window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[7]=[{"i":19120,"n":"חאביף, חננאל מאזמיר","k":"בעל מגדל חננאל","bt":"1720?","dt":"תקסג - יג אדר","dp":"אזמיר","b":"מחכמי איזמיר,תלמיד ר' יהודה אשכנזי,חיבר \"מגדל חננאל\" דרשות וחידושים על הרמב\"ם","s":"ארזי הלבנון; רוזניס-תורכיה-ה; פרוייקט השו\"ת","bk":[["מגדל חננאל","מפרשי רמב\"ם"],["מגדל חננאל [על רמב\"ם]",""]]},{"i":19121,"n":"חאביף, מנשה מאזמיר","dt":"תקכה - יב תמוז","dp":"אזמיר","b":"מחכמי אזמיר.","s":"רוזניס-תורכיה-ה"},{"i":19122,"n":"חאביף, מנשה מאזמיר - ב","dt":"תקמח - ב סיון","dp":"אזמיר","b":"רב באזמיר","s":"ארזי הלבנון; רוזניס-תורכיה-ה"},{"i":19123,"n":"חאגואל, דוד יעקב משלוניקי","k":"בעל פירוש להושענות","dt":"תרלט","dp":"שלוניקי","b":"מחכמי שלוניקי. חיבר פירוש להושענות מנהג ק\"ק סיציליא-תרכז.","s":"זכרון שלוניקי-141"},{"i":19124,"n":"חאגואל, יוסף ממרוקו","b":"מחכמי מרוקו, חתם על פס\"ד-תרטז, עם ר יצחק ן ואליד.","s":"מלכי רבנן"},{"i":19125,"n":"חאגואל, יעקב דוד משלוניקי","b":"מזכיר ביה\"ד בשלוניקי-תרף, ועסקן ציבורי, ממיסדי ה\"מזרחי\" בשלוניקי-תרעט.","s":"זכרון שלוניקי-213,217"},{"i":19126,"n":"חאגואל, סוליקא מטנג'יר","f":"פאדינא","dt":"תקצד","dp":"טנג'יר","b":"נהרגה עק\"ה.","s":"מלכי רבנן"},{"i":19127,"n":"חאגואל, שמואל משלוניקי","dt":"תרכז","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי-141"},{"i":19128,"n":"חאג'י יצחק אפנדי","dt":"תקצו","b":"מומר יהודה מקורב למלכות בקושטא.","s":"רוזניס-תורכיה-ו"},{"i":19129,"n":"חאגיו, יצחק מירושלים","dp":"ירושלים","b":"מחכמי איטליה צאצא למגורשי ספרד, עלה לירושלים בשנת שן. מוזכר בספר \"מאור עינים\" (פרק נו) שאשתו עברה אחר פטירתו לגור עם בנם בפיררה.","s":"גליס; רוזניס-תורכיה-ב"},{"i":19130,"n":"חאהן, אהרן מקליבלנד-ארה\"ב","k":"בעל קרבן אהרן","b":"מחכמי קליבלנד. חיבר ספרים באנגלית ובלשון אשכנז. ובהם \"עץ החיים\", \"עוקרי הרים\", \"יסודות המוסר של חכמי התלמוד\", ועוד.","s":"פין-כנסת ישראל"},{"i":19131,"n":"חאזיזה, יעקב מאלגיר","f":"דוד","bt":"תס","dt":"תקל - בערך","b":"רב בתלמסאן, נדרומא-אלגיר. נזכר בשטר-תקה.","s":"מלכי ישורון-חכמי אלגיר"},{"i":19132,"n":"חאזיזה, יצחק מאלגיר","dt":"תשטז","dp":"אלגיר","b":"רב בנדרומא-אלגיר. נהרג עק\"ה.","s":"מלכי ישורון-חכמי אלגיר"},{"i":19133,"n":"חאזיזה, יצחק ממרוקו","f":"אלעזר","b":"מחכמי אזמור-מרוקו. חתם על הסכמה-תרכב עם חכמי המגרב.","s":"ארזי הלבנון"},{"i":19134,"n":"חאזיזה, מכלוף מאלגיר","bt":"תרך","dt":"תרץ - בערך","b":"תלמיד ר חיים בלייח בתלמסאן. רב בטיג'ניף(=פאליקאו)-אלגיר. נזכר בהקמה ל\"שער כבוד ה'\" תונס תרסב.","s":"מלכי ישורון-חכמי אלגיר"},{"i":19135,"n":"חאזיזה, ראובן מאלגיר","dt":"תשיב","b":"רב ברוליזאן-אלגיר-תרעח.","s":"מלכי ישורון-חכמי אלגיר"},{"i":19136,"n":"חאטום, יצחק מירושלים","f":"שלמה","dt":"תרו-י - ד אלול","dp":"ירושלים","b":"מחכמי קושטא, עלה לירושלים. בשנת תרג הסכים על הספר \"דברי שלום\".","s":"גליס; גאון \"ירושלים\" ח."},{"i":19137,"n":"חאטום, שלמה בכור מקושטא","dt":"תקף - כז חשון","dp":"ירושלים","b":"מחכמי קושטא שר גדול ומקורב למלכות, עלה לירושלים וחתם-תקעט על שטר פרוזבול.","s":"אוצר הרבנים 18444; גליס; ארזי הלבנון; פרומקין-תח\"י"},{"i":19138,"n":"חאטום, שלמה מירושלים","k":"בעל לב האריה","dt":"תקסה - כז חשון","dp":"ירושלים","b":"עסקן מחכמי ירושלים.","s":"גאון-יהודי המזרח"},{"i":19139,"n":"חאטש, צבי הירש מקראקא","f":"ירחמיאל","k":"בעל שבתא דריגלא","b":"נכד ר יוסי מוינה ונינו של ר אביעזרי זליג מקורב, הו\"ל ספר זקנו \"נחלת צבי\". מקובל, דרשן, דיין בקרקא-תמ. חיבר גם \"דרך ישרה\", \"חמדת צבי\". לדעת אליקים המילזאני בספר ראבי\"ה - היה מהנוטים אחרי שבתי צבי.","s":"אוצר הרבנים 17289; פין-כנסת ישראל; שם הגדולים השלישי"},{"i":19140,"n":"חאליאן, שמואל משה מירושלים","b":"מחכמי ירושלים, חתם-תריד עם ר יונה סעדיה נבון על שטר משפחת פרנס.","s":"פרומקין-תח\"י"},{"i":19141,"n":"חאליגואה, יוסף משלוניקי","b":"מחכמי שלוניקי-שפ.","s":"זכרון שלוניקי"},{"i":19142,"n":"חאליגואה, משה מאדרינופול ושלונ","b":"דיין בשלוניקי-שמ, רב באדרינופול-שנב.","s":"רוזניס-תורכיה-ג; זכרון שלוניקי"},{"i":19143,"n":"חאליגולה, משה מירושלים","b":"מחכמי ירושלים-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":19144,"n":"חאליו, דוד","f":"שמואל חאליו","b":"מחכמי אלג'יר-שנת ר'","s":"אוצר הרבנים 4816"},{"i":19145,"n":"חאלילייו, שלמה משלוניקי","f":"חיים","k":"בעל אמר שלמה","b":"מחכמי שלוניקי.","s":"ארזי הלבנון"},{"i":19146,"n":"חאמי, אלעזר ממצרים","b":"מחכמי קהיר-שנה, חתם עם ר שמואל פודילא, ר משה יונה, ר יהודה חאמי, ועוד. אחיו - ר יהודה.","s":"ארזי הלבנון"},{"i":19147,"n":"חאמי, יהודה ממצרים","b":"מחכמי קהיר-של. אחיו - ר אלעזר.","s":"אוצר הרבנים 6929; ארזי הלבנון"},{"i":19148,"n":"חאנעס, ישראל ממינסק","bt":"תקעז","dt":"תרסה - י תשרי","b":"ר\"מ בביהמ\"ד במינסק.","s":"דור וחכמיו-א\"ש-ו"},{"i":19149,"n":"חאפדי, משה מתימן","b":"מחכמי חאפד-תימן בתחילת המאה ה-20.","s":"ארזי הלבנון"},{"i":19150,"n":"חאפיו, עוויז באקי מבוכרה","b":"רב בבוכרה. תלמיד ר יוסף מאמן בבוכרה.","s":"ארזי הלבנון"},{"i":19151,"n":"חאקו, אליהו - א","dt":"תקלו - יא תשרי","dp":"אזמיר","b":"מחכמי אזמיר.","s":"אוצר הרבנים 2109; רוזניס-תורכיה-ה"},{"i":19152,"n":"חאקו, אליהו מאזמיר ושלוניקי -ב","f":"יהודה מאזמיר","k":"בעל רוח אליהו","r":"חמיו של ר' ברזלי יעבץ","bt":"1700?","dt":"תקיד - יח טבת","b":"מגדולי חכמי שלוניקי, אזמיר. חיבר גם \"מצא חן\" ועוד, כמה מספריו שלא נדפסו היו בידי חתנו - ר ברזילי יעבץ מאזמיר.","s":"אוצר הרבנים 2110; פין-כנסת ישראל; ארזי הלבנון; רוזניס-תורכיה-ה; פרוייקט השו\"ת, ענייני שבתאי צבי בחלק מצבות רבני וחכמי איזמיר אות סט עמוד 144, קורות היהודים בתורקיה חלק ה' עמוד 63.","bk":[["רוח אליהו","מפרשי רמב\"ם"],["מצא חן","מפרשי רמב\"ם"]]},{"i":19153,"n":"חאקו, יהודה מאזמיר","dt":"תקצב","b":"מחכמי ורבני איזמיר. בנו - ר אליהו בעל \"רוח אליהו\".","s":"ארזי הלבנון"},{"i":19154,"n":"חאראשץ, אברהם מרדכי מלאמזיצא","b":"אב\"ד לאמזיצא-תרפט (אולי על מקום ר איסר יהודה מאלין שעבר לבריסק). כתב סמיכה ממנו לבחור גדליה הויזמן מלומזה.","s":"מתוך קטלוג"},{"i":19155,"n":"חאתים, אליהו מלאריסה","b":"רב בפטרץ, מראשי קהלת פליטי פטרץ וזייתון בלאריסה-תמה, יחד עם ר משה משען.","s":"רוזניס-תורכיה-ד,ה"},{"i":19156,"n":"חבה, אליה יהושע","dt":"תשלד","b":"מרבני בגדאד, דיין, עלה לא\"י, רב ראשי ברמת גן","s":"ארזי הלבנון"},{"i":19157,"n":"חבה, יצחק מירושלים","dt":"תשלא","b":"רב ומקובל בירושלים.","s":"ארזי הלבנון"},{"i":19158,"n":"חבה, שאול מירושלים","dt":"תשלא","b":"מחכמי ירושלים.","s":"ארזי הלבנון"},{"i":19159,"n":"חבוב, נתנאל משה מדמשק","k":"בעל קרבן נתנאל","bt":"תקצד-ט","bp":"דמשק","dt":"תרעז - ט שבט","dp":"ירושלים","b":"לאחר שנתייתם גדל אצל זקנו ר יצחק הכהן מסלתון טראב. תלמיד ר יעקב פרץ, ר אהרן יעקב, ר שלמה סוכרי ור מאיר משעאן. דיין בדמשק. למד עם ר אליהו מני בחברון, ונשא ונתן עם ר יצחק אבולעפיה. עלה לירושלים-תרסד ולמד קבלה עם ר חיים שאול דוויק ושאר מקובלים.","s":"גליס; אוצר הרבנים 16481; גאון-יהודי המזרח; ארזי הלבנון"},{"i":19160,"n":"חביב - משפחה","b":"משפחת רבנים יוצאי ספרד.","s":"גאון-יהודי המזרח"},{"i":19161,"n":"חביב הפייטן","f":"יצחק","b":"פייטן. חיבר סליחות במחזור טריפולי.","s":"פין-כנסת ישראל"},{"i":19162,"n":"חביב חיא בן שלמה אבן; בלוי משה יהודה","bt":"1912","dt":"ה'תשסג 2003","s":"היברובוקס","bk":[["ספר השולחן",""]]},{"i":19163,"n":"חביב ן, אברהם מאתונה","f":"יעקב משלוניקי","b":"רב ראשי באתונה-תרצה.","s":"אוצר הרבנים 416 א'"},{"i":19164,"n":"חביב ן, אברהם משלוניקי","dt":"תקם","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי-116"},{"i":19165,"n":"חביב ן, אברהם משלוניקי","f":"יעקב","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה. אחיו - ר רפאל - נספה בשואה.","s":"זכרון שלוניקי-214"},{"i":19166,"n":"חביב ן, בן ציון מאיר פסחיה","b":"תלמיד ר ג'יליבי בכור הלוי, בקי בתכונה ולימד את קרובו ר אברהם ן חביב. דיין באזמיר-תרסא.","s":"ארזי הלבנון; גאון-יהודי המזרח"},{"i":19167,"n":"חביב ן, ברוך מאלכסנדריה","dt":"שעו","b":"מחכמי אלכסנדריה-שמח.","s":"ארזי הלבנון; רוזניס-תורכיה-ג"},{"i":19168,"n":"חביב ן, חיים מעזה וירושלים","dt":"תקא","dp":"עזה","b":"מצאצאי ר לוי בן חביב, עבר לעזה ולימד שם תורה.","s":"גליס; אוצר הרבנים 5994; פרומקין-תח\"י; רוזניס-תורכיה-ד,ה"},{"i":19169,"n":"חביב ן, חיים מפורטוגל ופאס","f":"משה בן שם טוב","k":"בעל ספר הבתים","b":"מגדולי חכמי פורטוגל בדור הגירוש-רנז, מרביץ תורה בפאס-רס\"ה. קיבץ \"ספר הבתים\" ובו 3000 תשובות של הרשב\"א","s":"אוצר הרבנים 5993; ארזי הלבנון; מלכי רבנן; פין-כנסת ישראל; טולדנו-נר המערב"},{"i":19170,"n":"חביב ן, חיים משה מגליפולי","f":"שלמה בן שמעון","b":"רב בגליפולי, וגם זקנו ר שמעון היה רב בגליפולי. נזכר ב\"זכרנו לחיים\" לר רפאל חיים בנימין פרץ שהיה רב בגליפולי-תר.","s":"ארזי הלבנון"},{"i":19171,"n":"חביב ן, חיים משלוניקי","f":"רפאל","bt":"תרמב","bp":"שלוניקי","dt":"תש..","b":"נכד ר שמואל בעל \"אמר שמואל\". תלמיד ר חננאל ן ארדיט, ור שלמה ציון בביהמ\"ד \"בית יוסף\". חתן ר גבריאל אלמושנינו משלוניקי. מנהל הקדש חיימוג'ו קובו. רב ראשי בשלוניקי-תרפד על מקום ר בן ציון חי עוזיאל וממלא מקומו ר עמנואל ברודו, בלחץ המשכילים נתמנה הרב ד\"ר צבי הירש הנרי קורץ מוינה ור חיים הפך לסגנו ואחראי על הדיינים. הניח חבורים בכת\"י - ואבדו בשואה. נספה בשואה עם משפחתו - בנו גבריאל ובתו אסתר עלו לארץ לפני השואה.","s":"אוצר הרבנים 5995; זכרון שלוניקי-227; ארזי הלבנון"},{"i":19172,"n":"חביב ן, חיים רפאל משלוניקי","bt":"תקפב","bp":"שלוניקי","b":"היה רב בשלוניקי - בפועל כיהן כרב ראשי - לא רשמי, וייצג את הקהלה מול השלטונות.","s":"מתוך קטלוג"},{"i":19173,"n":"חביב ן, יהודה מספרד ומרוקו","b":"מגולי ספרד, רב באספי-מרוקו. חיבר או העתיק בכתב ידו ביאור על רש\"י לתורה בשנת רלד.","s":"ארזי הלבנון; מלכי רבנן"},{"i":19174,"n":"חביב ן, יעקב מאדרינופול","b":"רב באדרינופול-שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":19175,"n":"חביב ן, יעקב משלוניקי - ב","f":"רפאל","b":"דיין בשלוניקי-תרע. בנו - ר אברהם מאתונה.","s":"אוצר הרבנים 9629; זכרון שלוניקי-213"},{"i":19176,"n":"חביב ן, יצחק מירושלים","f":"משה-גט פשוט","dp":"ירושלים","b":"מחכמי ירושלים-תק.","s":"אוצר הרבנים 10652; פרומקין-תח\"י"},{"i":19177,"n":"חביב ן, יצחק משלוניקי","dt":"תם - כט תשרי","dp":"שלוניקי","b":"רב בשלוניקי. מתלמידיו: ר שלמה אמריליו. בניו: ר משה, ור מנחם - שעלו לירושלים.","s":"ארזי הלבנון; זכרון שלוניקי-54"},{"i":19178,"n":"חביב ן, ישי ג'יליבי משלוניקי","dt":"תקעא","dp":"שלוניקי","b":"מחכמי איזמיר, דיין-תקסו, רופא בשלוניקי.","s":"ארזי הלבנון; זכרון שלוניקי-100"},{"i":19179,"n":"חביב ן, ישראל מירושלים","f":"משה-גט פשוט","dp":"ירושלים","b":"מחכמי ירושלים-תק, נזכר ב\"משאת משה\".","s":"אוצר הרבנים 11927; ארזי הלבנון"},{"i":19180,"n":"חביב ן, מנחם מאישטיפי","b":"רב באישטיפי-שנות ה-ת'.","s":"רוזניס-תורכיה-ה"},{"i":19181,"n":"חביב ן, מנחם מירושלים","f":"יצחק משלוניקי","dt":"תקו","dp":"ירושלים","b":"נכדו של ר מנחם (שנשבה ונמכר לעבד - מתוך דרשות מהר\"ש אמריליו). רב באישטיפי (ליד שלוניקי)-תף, עלה לירושלים-תצז וכיהן כדיין אצל ר אליעזר בן יעקב נחום, ונמנה על ישיבת \"נוה שלום\". כתב הקדמה לספר \"בני יוסף\" לר יוסף בן שלמה יחיאל. נספד ע\"י ר ישראל יעקב אלגזיב\"שארית יעקב\", וע\"י ר משה אמריליו ב\"יד משה\". (לפי רוזניס עבר מירושלים לשלוניקי).","s":"גליס; אוצר הרבנים 13247; איטליה גירונדי-מ סד; גאון-יהודי המזרח; ארזי הלבנון; זכרון שלוניקי-85; פרומקין-תח\"י; רוזניס-תורכיה-ה"},{"i":19182,"n":"חביב ן, משה מירושלים - ב","f":"מנחם או יצחק","b":"מחכמי ירושלים בשנים תנג ותסא, ונזכר ב\"צרור הכסף\". ר אברהם גטניו שלח לו משלוניקי קונטרס בהלכות תרומות. יתכן שבנו הוא ר יצחק שנקבר לצד האחים ר נסים בעל \"אדמת קדש\" ור ישראל מאיר מזרחי בעל \"פרי האדמה\". (בארזי הלבנון חכם זה הוא בן ר יצחק).","s":"גליס; ארזי הלבנון"},{"i":19183,"n":"חביב ן, משה מספרד","b":"מחכמי ספרד בזמן הרא\"ש, ונזכר בתשובות הראש. רב בויליראל. הרב הראשון שנודע ממשפחת הרבנים - אבן חביב.","s":"ארזי הלבנון"},{"i":19184,"n":"חביב ן, משה מספרד וברושה","bp":"זאמורה-ספרד","b":"לאחר הגירוש עבר לתורכיה, רב בברוסה. חתנו - ר אברהם די גאון הלוי, והיה מחלוקת על ירושתו.","s":"רוזניס-תורכיה-א,ב"},{"i":19185,"n":"חביב ן, משה מפורטוגל","f":"שם טוב","k":"בעל דרכי נועם","bp":"ליסבון","b":"פילוסוף מחכמי ספרד או פורטוגל, וכ-10 שנים לפני הגירוש הגיע לנפולי-רמא, פולייא-איטליה. חיבר מ\"גלות ירושלים\", \"מחנה אלקים\", \"דרכי נועם\" ועוד. בנו - ר חיים שסידר ספר תשובות הרשב\"א - פאס-רסה.","s":"איטליה גירונדי-מ קב; אוצר הרבנים 14688; ארזי הלבנון; פין-כנסת ישראל"},{"i":19186,"n":"חביב ן, משה מקושטא","b":"דיין בקושטא-תרפא-תשטו. מכתב ממנו לר עובדיה יוסף.","s":"ארזי הלבנון"},{"i":19187,"n":"חביב ן, משה משלוניקי","f":"יצחק","bp":"שלוניקי","b":"נתייתם בילדותו מאביו הרב בשלוניקי. ותלמידו של אביו ר שלמה אמריליו בעל \"כרם שלמה\" קיבל על עצמו למלאת את מקומו עד שיגדל בנו, וכן היה. כיהן רב בשלוניקי-[תס..], על מקום אביו ותלמידו ר שלמה אמריליו. חתנו - ר משה ישראל בעל \"משאת משה\".","s":"ארזי הלבנון"},{"i":19188,"n":"חביב ן, רחמים מטריפולי","bt":"תקצ-ה","bp":"טריפולי","dt":"תרעה","b":"רב ודיין בטריפולי, ומלמד לתלמידים. ממלא מקום החכם באשי, ראש ישיבת ר מאיר כלפון. תמך בפתיחת בי\"ס שמשלב גם לימודי חול ואיטלקית. נזכר ב\"תעלומות לב\" ליוורנו תרלט.","s":"ארזי הלבנון; אוצר הרבנים 17744; מלכי חי\"ל-מרציאנו"},{"i":19189,"n":"חביב ן, רפאל מגליפולי","f":"שמעון מגליפולי","b":"דיין בגליפולי-תלג אצל אביו ר שמעון, ונזכר ב\"לב שלמה\" למהר\"ש הלוי, וב\"יד אהרן\". אגרת אליו מר משה די בושאל מרודוס, ועוד.","s":"ארזי הלבנון"},{"i":19190,"n":"חביב ן, רפאל משלוניקי","f":"שמואל","dt":"תרעח","b":"דיין מחכמי שלוניקי-תרס. בניו ר חביב, ר יעקב ור חיים שנספה עק\"ה בשואה.","s":"ארזי הלבנון; זכרון שלוניקי-191"},{"i":19191,"n":"חביב ן, רפאל משלוניקי","f":"יעקב","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה. אחיו ר אברהם - נספה בשואה.","s":"זכרון שלוניקי-214"},{"i":19192,"n":"חביב ן, שלום מטריפולי","bt":"תקל","dt":"תר","b":"רב וסופר בטריפולי. חתם בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":19193,"n":"חביב ן, שלמה","b":"נזכר בפסק בענין שבת-תצט וחתם עם ר יצחק בן יוסף-תקלח.","s":"ארזי הלבנון"},{"i":19194,"n":"חביב ן, שלמה הרופא משלוניקי","f":"דון שמואל בן שם טוב","dt":"רסד","b":"רופא בשלוניקי","s":"זכרון שלוניקי"},{"i":19195,"n":"חביב ן, שלמה מגליפולי","f":"שמעון מגליפולי","b":"בנו של רבה של גליפולי, ובנו ר חיים משה היה גם הוא רב בגליפולי.","s":"ארזי הלבנון"},{"i":19196,"n":"חביב ן, שלמה מטריפולי","dt":"תרצג","b":"רב בטריפולי. נזכר אצל גבריאל רוקח-1937.","s":"מלכי חי\"ל-מרציאנו"},{"i":19197,"n":"חביב ן, שלמה ממכנאס","b":"מחכמי מרוקו - כנראה מכנאס, העתיק שו\"ת ר יהודה טולדנו.","s":"מלכי רבנן"},{"i":19198,"n":"חביב ן, שמואל מירושלים","f":"שלמה","k":"בעל אמר שמואל","bt":"שצה","bp":"ירושלים","dt":"תנו - לפני","b":"מחכמי ירושלים. אחיו של ר משה. חיבר גם \"שבח נעורים\".","s":"ארזי הלבנון"},{"i":19199,"n":"חביב ן, שמואל ממצרים","k":"בעל מבקש ה' ?","b":"רב במצרים-תם. אחיו של ר משה מירושלים. נזכר ב\"גט פשוט\". אולי הוא המחבר \"מבקש ה'\".","s":"אוצר הרבנים 19173; גאון-יהודי המזרח"},{"i":19200,"n":"חביב ן, שמואל מספרד ושלוניקי","f":"שם טוב","bp":"קאסרישאשד-ספרד","dt":"רסד - יז אלול","dp":"שלוניקי","b":"רופא מספרד, לאחר הגירוש - מחכמי שלוניקי.","s":"עמנואל-שלוניקי"},{"i":19201,"n":"חביב ן, שמואל מפאס-מרוקו","f":"חיים","b":"רב בפאס-שנח-שסט ודיין עם ר ישועה בקיש, ר\"ש ן דנאן, ר וידאל הצרפתי, ר\"ש סירירו.","s":"אוצר הרבנים 19174; מלכי רבנן"},{"i":19202,"n":"חביב ן, שמואל משלוניקי","f":"חיים","k":"בעל אמר שמואל","bt":"תקעז","dt":"תרמז","dp":"שירון","b":"תלמיד ר אשר קובו בשלוניקי. חתן הדיין ר אברהם קובו. מחכמי שלוניקי, רב בשירון(=שיריס, סרס). חיבר שו\"ת וזכרונות בשם \"אמר שמואל\", בנו ר רפאל ונכדו שנפטר צעיר - ר שמואל ן חביב. חיבר \"שם משמואל\" אחרי פטירת הנכד ובו מתורת נכדו. נכדו גם - ר חיים - רבה של שלוניקי.","s":"ארזי הלבנון; זכרון שלוניקי-100,152"},{"i":19203,"n":"חביב ן, שמעון מברושה","b":"מחכמי ברוסה. אחיינו של ר משה ן חביב מברושה.","s":"רוזניס-תורכיה-א"},{"i":19204,"n":"חביב ן, שמעון מגליפולי","b":"רב בגליפולי-ת' ור ישי אלמולי על מקומו אחריו, יחד עם ר מאיר די בוטון בנו של בעל \"לחם משנה\". התכתב עם ר רפאל יהושע בנבנשתי בעל \"שדה יהושע\". תשובה ממנו ב\"צרור הכסף\" לר אברהם גטניו. נזכר ב\"זכרנו לחיים\" מר רפאל חיים בנימין פרץ שהיה רב בגליפולי כמאתיים שנה אח\"כ. בנו ר רפאל דיין אצל אביו, ור שלמה שבנו ר חיים היה רב בגליפולי.","s":"ארזי הלבנון"},{"i":19205,"n":"חביב ן, שמעון מצפת","b":"רב בצפת-תיט, השיב לר חיים בנבנישתי מאזמיר.","s":"רוזניס-תורכיה-ד"},{"i":19206,"n":"חביב ן, שמעון משלוניקי","b":"מגדולי חכמי שאלוניקי-תר\"כ","s":"אוצר הרבנים 19863"},{"i":19207,"n":"חביב ן, שמעון משלוניקי וונציה","bp":"שלוניקי","dt":"שעח - אחרי","b":"רב במונסטיר-שנז, ונציה-שסא. חתם על פסק הרמ\"ע בענין הכשר המקוה ברוויגו-שסו, ועם רבני ונציה-שסט עד דבר יעקב כהן שלום.","s":"ארזי הלבנון"},{"i":19208,"n":"חביב, אברהם מאיסטנקיואי וירושל","b":"מחכמי איסטנקיואי(=איסטאנקיואי)-תק, עלה לירושלים. חתנו - ר מצליח צורמני.","s":"רוזניס-תורכיה-ה"},{"i":19209,"n":"חביב, אברהם מבודון","f":"יקותיאל","b":"פקיד המושל התורכי בבודון-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":19210,"n":"חביב, אברהם מטריפולי - א","bt":"תף","dt":"תקס - בערך","b":"רב בטריפולי. חתם בפנקס בי\"ד טריפולי. סייע בהדפסת \"שיר השירים\" ביהודי ערבית - ליוורנו תקנא. נספד מאת ר יעקב רפאל מנשה מקושטא (האם המדובר באותו אדם?).","s":"מלכי חי\"ל-מרציאנו; רוזניס-תורכיה-ו"},{"i":19211,"n":"חביב, אברהם מטריפולי - ב","bt":"תרי","bp":"טריפולי","dt":"תרפג - יג ניסן","b":"רב בבנגזי, ראב\"ד בטריפולי, ומקובל, וכיהן כחכם באשי-תרמט על מקום ר חזקיה מראני. מחובבי ציון.","s":"ארזי הלבנון; אוצר הרבנים 416; מלכי חי\"ל-מרציאנו; אהלי שם"},{"i":19212,"n":"חביב, חיים בנימין מקושטא","b":"דיין בקושטא-תכה עם ר משה בנבנישתי ור משה גלנטי.","s":"רוזניס-תורכיה-ד"},{"i":19213,"n":"חביב, מסעוד מתונס","b":"מחכמי תונס, עלה לירושלים והיה מחכמי \"בית אל\". נזכר אצל ר משה זקן מאזוז ב\"סבר פנים\".","s":"ארזי הלבנון"},{"i":19214,"n":"חביבא, יוסף מספרד","k":"בעל נמוקי יוסף","b":"תלמיד ר חסדאי קרשקש השני. מגדולי הראשונים בספרד-קס, חיבר \"נמוקי יוסף\" על הרי\"ף.","s":"אוצר הרבנים 8305; פין-כנסת ישראל"},{"i":19215,"n":"חבילי, יצחק","b":"רב בשנת תי.","s":"אוצר הרבנים 10655; ארזי הלבנון"},{"i":19216,"n":"חביליו, אברהם הרופא משלוניקי","dt":"שנז - כח חשון","dp":"שלוניקי","b":"רופא בשלוניקי.","s":"זכרון שלוניקי; מלכי רבנן"},{"i":19217,"n":"חביליו, אלישע מירקדו מסרייבו","f":"שלמה","k":"בעל המון חוגג","bt":"תעט?","bp":"סרייבו","dt":"תקס?","dp":"סרייבו","b":"תלמיד ר דוד פארדו בעל שושנים לדוד. רב בסרייבו-תקמ, ליוורנו-איטליה-תקנג. חיבר \"המון חוגג\", \"פת לחם\", ועוד. הדפיס \"שפעת רביבים\" לרבו ר דוד פארדו-מהרד\"ף עם הוספות משלו.","s":"איטליה גירונדי-א כג; גאון-יהודי המזרח; ארזי הלבנון; אוצר הרבנים 2777; פין-כנסת ישראל; רוזניס-תורכיה-ה"},{"i":19218,"n":"חביליו, דוד מצפת","dt":"תכא - ט אב","dp":"אזמיר","b":"תלמידו של ר בנימין בן מאיר הלוי, עלה לירושלים עם רבו אך נאלצו לעזוב ועבר לצפת - עקב גזרות אבן פארוך, ר דוד היה בשליחות ירושלים ולפני שנת תך פגש בקושטא את ר דוד היכיני. החיד\"א שמע מזקני ירושלים שהיה לו מגיד. הספידו ר דוד הכהן בספר \"בן הא הא\", בנו ר יהודה כיהן כראב\"ד בחברון.","s":"גליס; אוצר הרבנים 4810; רוזניס-תורכיה-ג,ה; ארזי הלבנון; פרומקין-תח\"י; פין-כנסת ישראל"},{"i":19219,"n":"חביליו, יהודה מממצרים וחברון","f":"דוד מצפת ואזמיר","k":"בעל חבל בני יהודה","bt":"תיב","bp":"ירושלים","dt":"תנז - אחרי","dp":"אזמיר","b":"תלמיד ר אהרן בן חיים בעל \"קרבן אהרן\" ור אביגדור קסטילץ. היה רב בקהיר?, אלכסנדריה על מקום ר יהושע ננטוא (שלדברי רוזניס הודח בגלל נטיתו לשבתאות), ור יוסף בן בנימין הלוי על מקומו אחריו (לאחר שעלה לחברון). חברו של ר מרדכי הלוי בעל \"דרכי נועם\", בשליחות באזמיר. חיבר \"חבל בני יהודה\" שהודפס על ידי בנו מנטובה תנט, ו\"חלק בני יהודה\" ונציה תנו. עלה לחברון-תנד ונתמנה לאב\"ד וראש הרבנים. בנו - ר שמעון.","s":"גליס; אוצר הרבנים 6930; ארזי הלבנון; פין-כנסת ישראל; פרומקין-תח\"י; רוזניס-תורכיה-ד; תולדות הפוסקים, שא\"י"},{"i":19220,"n":"חביליו, יצחק הרופא","b":"מחכמי ירושלים, נזכר ב\"חרבות ירושלים\" כאחד הסובלים מפרעות אבן פארוך בשנת שפה.","s":"גליס"},{"i":19221,"n":"חביליו, שלמה שמעון (שמשון)","k":"בעל שבחי ירושלים","b":"מחכמי ירושלים בשנת תרכו. חיבר \"שבחי ירושלים\" ירושלים תרלב.","s":"גליס; אוצר 18899; ארזי הלבנון"},{"i":19222,"n":"חביליו, שמעון מחברון","f":"יהודה מחברון","k":"הו\"ל חבל בני יהודה","bp":"ירושלים","b":"נכד ר דוד חביליו. תלמיד ר אהרן ן חיים בעל \"קרבן אהרן\" ור אביגדור קשטליץ. מחכמי חברון, נדד בארצות המזרח, בשנת תנד באיטליה והדפיס את ספרי אביו. חיבר גם \"חלקת בני יהודה\".","s":"גליס; אוצר הרבנים 19864; איטליה גירונדי-ש כז; ארזי הלבנון; רוזניס-תורכיה-ד"},{"i":19223,"n":"חביליו, שמשון משלוניקי","dt":"שפא","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי; מלכי רבנן"},{"i":19224,"n":"חביני, יצחק משלוניקי","dt":"שעז - יד אלול","dp":"שלוניקי","b":"חזן מחכמי שלוניקי. מהרוגי דולייא-קאשטורינה - פולוג'י.","s":"עמנואל-שלוניקי"},{"i":19225,"n":"חבנסקי, אחיעזר","f":"גרשון מטשרנובל","s":"אוצר הרבנים 1901"},{"i":19226,"n":"חבנסקי, אחיעזר מאיר מטשאהן","f":"גרשון ברוך מקאמארין","b":"חתן ר מיכל סאמוט מלחוביץ-מחוז אוסטרהא. רב בטשאהן-ווהלין-תרע.","s":"אוצר הרבנים 1902; אהלי שם"},{"i":19227,"n":"חבנסקי, גרשון ברוך מקאמארין","f":"אחיעזר מטשרנוביל","bt":"תריז","b":"נכד ר גרשון מטשרנוביל. רב בקאמארין-פלך מינסק-תרמה. נסמך מאת: ר מרדכי דב מהורנסטיפל. בניו - ר זירא, ר אחיעזר מאיר משאהן.","s":"אוצר הרבנים 4453; אהלי שם"},{"i":19228,"n":"חבס, אליעזר יעקב מיאנישוק","bt":"תרי","bp":"יאנישוק","dt":"תרעט","dp":"יאנישוק","b":"ממיסדי ישיבת סלובודקה, וכולל הפרושים בקובנא. הלך ברגל מקובנא לברלין כדי להשפיע על הגביר החרדי ר עובדה להמן לתרום להפצת תורה - והכסף שקיבל שימש ליסוד שתי הישיבות, ועזר לר נתן צבי פינקל בסלובודקה, ולר יוסף יוזל הורביץ בלובטש ונוברדוק. חתנו ר נפתלי טרופ מראדין.","s":"ליטא; אנשי שם-אמריקה"},{"i":19229,"n":"חבס, ברכה","f":"ישראל","k":"בעל רחל - תרצד","bt":"1900","bp":"אליטא-ליטא","b":"עלתה לארץ בילדותה-1907. מורה פעילה ב\"החלוץ\" בפולין. פרסמה מאמרים וספרים רבים. בעלה דוד הכהן (שאתו חיברה את \"עשרים ימים בהודו\").","s":"ליטא"},{"i":19230,"n":"חבס, ישראל","f":"שמחה זיסל","bt":"1867","bp":"אליטא-ליטא","dt":"1939","dp":"תל אביב","b":"עסקן דתי ממשפחת היסו\"ד מוילנא. תלמיד ישיבת סלובודקה, וולוזין, תלמיד מובהק של הסבא מסלובודקא (ר נתן צבי פינקל). יסד חבת \"שפה ברורה\" לדיבור עברי ופעולה ציונית. עלה לארץ-1907 והתישב ביפו. יסד וערך את העתון החדרי \"היסוד\"-1931. פרסם מאמרים בעתוני התקופה. מעורי \"התרבות הישראלית\".","s":"ליטא"},{"i":19231,"n":"חבר, אברהם מחברון","bp":"ירושלים","dt":"תנא","dp":"סמוך לאלגיר","b":"מחכמי ירושלים, בשליחות חברון לצפון אפריקה, טבע בים ליד חופי אלגיר. אלמנתו הותרה מעיגון על ידי ר משה חביב ור אברהם הלוי בעל גינת ורדים, סיפר המעשה מופיע בשות גינת ורדים ח\"ב אהעז כלל ג סימן יו.","s":"גליס; פרומקין-תח\"י; רוזניס-תורכיה-ד; שא\"י"},{"i":19232,"n":"חבר, חיים מדמשק","f":"יצחק מדמשק","b":"תלמיד ר יעקב בירב בצפת. מחכמי צפת, רב קהלת הסיציליאנים בדמשק על מקום אביו, דיין בצפת-שיז עם ר משה טרני ור שם טוב ביבאס, חזר לדמשק.","s":"רוזניס-תורכיה-ב; פרומקין-תח\"י"},{"i":19233,"n":"חבר, יוסף מזעטל","f":"מרדכי","b":"ר\"מ בזעטל-ת\"ר","s":"אוצר הרבנים 8306"},{"i":19234,"n":"חבר, יעקב מהורדנא","b":"רב בהורדנא-תק\"ס","s":"אוצר הרבנים 9630"},{"i":19235,"n":"חבר, יצחק איזיק מסובאלק וסלו","f":"יעקב","k":"בעל בנין עולם","r":"רב בוולקוויסק, טיקטין, סובלאק, ראזאנאי","bt":"תקמז-ט","bp":"גרודנא","dt":"תריג - א כסלו","dp":"סובאלק","b":"תלמיד ר מנחם מנדל משקלוב-תלמיד הגר\"א. רב בפורוזובא, רוז'נוי, טיקטין, וילקוביסק, סובאלק. חיבר גם \"בית יצחק\", \"יד מצרים\", ועוד. בנו ר אהרן פונדיק מוילנא. לתולדותיו מאמר מאת ר נ\"ט לנדא - ב\"בית ועד לחכמים\" - נ\"י תרסג. הספד עליו ב\"אבל כבד\"-תריג לר חנוך זונדל מביאליסטוק.","s":"אוצר הרבנים 11168; ליטא; עיר וילנא ח\"א; פין-כנסת ישראל; שם הגדולים השלישי; ליפמן-קובנא; מוריה קובץ מה עמוד עז, ועו עמוד צה הערה 42; יומא דהילולא","bk":[["בית יצחק","מערכות"],["ברית יצחק - אדרא דמשכנא פרשת משפטים",""],["בית יצחק (הגר\"א חבר)",""],["אור תורה - מעלות התורה לרבי אברהם אחי הגר\"א נדפסו יחד",""],["באר יצחק - ליקוטי הגר\"א ואדרת אליהו להגר\"א",""],["בית יצחק - קבוע וספיקות, וברירה",""],["בית נאמן - עד אחד נאמן באיסורים",""],["בית עולמים - אידרא רבה",""],["בנין עולם - שו\"ת באבן העזר או\"ח ויו\"ד",""],["גנזי מרומים - מסכת אצילות",""],["זרוע נטויה - הגדה של פסח",""],["יד מצרים - הגדה של פסח",""],["מגן וצינה - מלחמת השם, וביאור בתורת הרמח\"ל",""],["סדר זמנים",""],["פתחי שערים - כתבי האריז\"ל",""],["דרושי הגרי\"א חבר - שיח יצחק",""],["הגדה של פסח - יד מצרים",""],["פתחי שערים",""],["בית נאמן","מערכות"],["סדר זמנים","מערכות"],["בנין עולם","שו\"ת - אחרונים"]],"e":"תקמ\"ט-תרי\"ג"},{"i":19236,"n":"חבר, יצחק מדמשק","b":"רופא, רב עדת הסיציליאנים בדמשק וראש ישיבה-רפא, ובנו - ר חיים על מקומו אחריו. (יש משערים שהיה גם בירושלים)","s":"אוצר הרבנים 10653; רוזניס-תורכיה-ב; פרומקין-תח\"י"},{"i":19237,"n":"חבר, ישועה מביירות","b":"גביר בביירות-לבנון-שנות ה-ש'. קרובו של ר חיים החבר.","s":"רוזניס-תורכיה-ג"},{"i":19238,"n":"חברב, אליהו מאוסטרהא","f":"מרדכי","bt":"תרכה","b":"רב בברוסילב(בוריסלב?)-תרמט, אוסטרהא-תרנב.","s":"אוצר הרבנים 2111; אהלי שם"},{"i":19239,"n":"חברון מלוב","f":"מרזוק","dt":"קנב","dp":"כפר רחיבאת-לוב","b":"רב בלוב. עליו ב\"גנזים\" תשכט.","s":"מלכי חי\"ל-מרציאנו"},{"i":19240,"n":"חברוני, אברהם משה","r":"ראש ישיבת חברון","bt":"תרסח","dt":"תשלה - ט תמוז","b":"מגדולי מרביצי התורה,ראש ישיבת חברון בירושלים-תרצ\"ו","s":"אוצר הרבנים 20191; היא שיחתי עמוד תתת","bk":[["משאת משה",""]]},{"i":19241,"n":"חבריא, דוד ממצרים","b":"מחכמי מצרים בזמן הרדב\"ז, מקהלת המערבים.","s":"רוזניס-תורכיה-א"},{"i":19242,"n":"חבריא, חיים ממצרים","k":"בעל חבר הקיני","b":"מחכמי קאהיר - שנות ה-ש', למד אצל ר' בצלאל אשכנזי בעל \"שיטה מקובצת\", חיבר פירוש \"חבר כהנים\" על הספרא.","s":"אוצר הרבנים 5997; ארזי הלבנון; פין-כנסת ישראל"},{"i":19243,"n":"חבשוש, יהודה מירושלים","f":"אברהם","dt":"תשד","dp":"ירושלים","b":"רב ודיין בעדה התימנית בירושלים. ראש ישיבת \"תורת משה\" על מקום ר שלום אלשיך. מקובל מחברי \"רחובות הנהר\", ראב\"ד העדה, ור יחיא עבאהל על מקומו אחריו-תשד.","s":"ארזי הלבנון"},{"i":19244,"n":"חבשוש, סלימן מתימן","f":"יחיא","k":"בעל אשכלת מרורות","b":"רב בתימן אחיו של ר חיים חבשוש. חיבר \"אשכלת מרורות והליכות שבא\" אודות התלאות שעברו על יהודי צנעא-תרסד בזמן מרד האימאם יחיא בשלטון התורכי.","s":"ארזי הלבנון"},{"i":19245,"n":"חבשוש, שלום מתימן","f":"יחיא","k":"בעל שושנת המלך","bt":"תקפה","bp":"צנעא","dt":"תרסה - אדר","dp":"צנעא","b":"תלמיד מרי יוסף קארה, ומרי יחיא בדיחי. עסק בצורפות לפרנסתו והיה מגדולי דורו. ראה הישיבה בצנעא על מקום רבו ר יחיא בדיחי עד שנסגרה בשנות הרעב-תרס. כיהן גם כדיין בצנעא. היה ממשיך דרכו של מהרי\"ץ בהלכה, וזאת למרות שהתפלל בנוסח שאמי. חיבר \"שושנת המלך\" בכת\"י, ונאלץ בגלל המחסור, למכרו לדאוד בן סלימאן עקבי. נפטר בזמן מצור התורכים על צנעא - שבו נספו גם יהודים רבים.","s":"ארזי הלבנון"},{"i":19246,"n":"חג' (חגי), יוסף ממצרים","b":"מחכמי מצרים-רפ - מקהלת המערבים, בזמן הרדב\"ז.","s":"רוזניס-תורכיה-א; טולדנו-נר המערב"},{"i":19247,"n":"חג'אג', אברהם","b":"רב בפאס-שצח.","s":"אוצר הרבנים 415; ארזי הלבנון"},{"i":19248,"n":"חג'אג', אברהם","k":"בעל זרעו של אברהם","r":"וי\"א תרם (אטלס עץ החיים ח\"י עמוד 196 ערך 452)","bt":"1810","dt":"תרמא","b":"אב\"ד בתונס-תרל. חתם עם ר שלום זרקא, ור סעדאני נטף על תשובה לחכמי ג'רבא-תרל.","s":"ארזי הלבנון; אוצר הרבנים 417; היברובוקס","bk":[["זרעו של אברהם",""]]},{"i":19249,"n":"חג'אג', אברהם - א","dt":"שכג - לפני","b":"ממגורשי ספרד,רב בפאס","s":"אוצר הרבנים 414; אלופי יעקב א-רעז"},{"i":19250,"n":"חג'אג', דוד אליהו","b":"רב ומ\"צ בגפצה(תונס)","s":"ארזי הלבנון"},{"i":19251,"n":"חג'אג', יוסף מאלגיר","f":"שאול","bt":"תץ","dt":"תקס - בערך","b":"רב בווהראן-אלגיר, וסופר, העתיק מחזור ווהראן.","s":"מלכי ישורון-חכמי אלגיר"},{"i":19252,"n":"חג'אג', כליפא מגריאן-לוב","f":"חמאני","bt":"תרו","bp":"גריאן-לוב","dt":"תרעג-ה","dp":"לוב","b":"רב, פייטן ורופא, והחזיק בספרי רפואות של הרמבם בכת\"י - וסירב למכרם בכל מחיר. היה נשיא היהודים במדינה והחזיק במבצר בעיר תיגרינא-ג'ריאן, היה ממשפחה של נשיאי היהודים באזור עד לכיבוש לוב בידי התורכים - וגם אח\"כ ברשיון מהתורכים. נזכר אצל ר משה סרוסי ב\"וישב משה\".","s":"אוצר הרבנים 12436; ארזי הלבנון; מלכי חי\"ל-מרציאנו; אהלי שם"},{"i":19253,"n":"חג'אג', נסים מטריפולי","dt":"תרצה","b":"רב בטריפולי. נזכר אצל גבריאל רוקח- בתוך לוח שנה-תרצז. נזכר גם ב\"התלמוד בתנ\"ך\"-ת\"א תשד לר שמואל בן הרוש","s":"מלכי חי\"ל-מרציאנו"},{"i":19254,"n":"חג'אג', עזוז מאלגיר","bt":"רך - בערך","dt":"רצ - בערך","b":"רב בביסקרא-אלגיר, ונזכר בשות ר שמעון בן הרשב\"ש.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":19255,"n":"חג'אג', שלמה מגפצה-תונס","f":"פרג'","b":"פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו.","s":"אוצר כתבי עת-לוין"},{"i":19256,"n":"חג'אג', שמעון מטריפולי","bt":"תרי","dt":"תרעה","b":"רב בטריפולי. נזכר ב\"התלמוד בתנ\"ך\"-ת\"א תשד.","s":"מלכי חי\"ל-מרציאנו"},{"i":19257,"n":"חגיז ישראל יעקב בן שמואל","f":"שמואל","k":"בעל עץ חיים","bt":"שפ-שפה","bp":"ליוורנו או פאס","dt":"תלד","dp":"קושטא","b":"אביו היה דרשן ידוע (לא ידוע היכן), בצעירותו היה באיטליה והיה תלמיד וחתן ר דוד קאריגל. בשנת תיח הגיע (או חזר) לירושלים לעמוד בראש ישיבת \"בית יעקב\" שהקימו הנדיבים אברהם ויעקב די ויגה. חתן ר דוד קריגל, ובזיוו\"ש חתן ר יונתן גלנטי ובנו שנולד הוא ר משה חגיז. היה ראש הרבנים בירושלים ומגדולי המתנגדים לשבתאי צבי. חיבר גם \"תחלת חכמה\", ועוד. חתנו ר משה ן חביב וישב אחריו על כסא הרבנות בירושלים. מתלמידיו ר נתן בן אלישע אשכנזי. - שנודע לימים כנתן העזתי. רוב חיבוריו אבדו.","s":"גליס; אוצר הרבנים 9627,12230; גאון-יהודי המזרח; פין-כנסת ישראל; פרומקין-תח\"י; רוזניס-תורכיה-ד,ה; היברובוקס; יומא דהילולא; וזה שער השמים עמוד 102","bk":[["הלכות קטנות","שו\"ת - אחרונים"],["הלכות קטנות (הלק\"ט)",""],["הלכות קטנות (שו\"ת)",""],["אורח מישור",""],["בית אהרן",""],["זכרון לבני ישראל",""],["עץ החיים",""],["קרבן מנחה",""],["תחלת חכמה",""],["עץ החיים – משניות",""],["אורח מישור","מחשבה ומוסר - אחרונים"],["זכרון לבני ישראל","מחשבה ומוסר - אחרונים"],["קרבן מנחה","מערכות"]],"e":"ש\"פ-תל\"ד"},{"i":19258,"n":"חגיז, אברהם מפאס","b":"מחכמי פאס, חתם-שצח עם ר שאול סירירו, ר שלמה ן דנאן, ר יוסף גיקטיליא, ועוד. אולי אחיו - ר שמואל בעל מבקש השם.","s":"מלכי רבנן; טולדנו-נר המערב"},{"i":19259,"n":"חגיז, יוסף משה מירושלים","b":"מחכמי ירושלים-סוף שנות ה-תק',","s":"פרומקין-תח\"י"},{"i":19260,"n":"חגיז, יעקב מירושלים","b":"רב בירושלים-תלה.","s":"רוזניס-תורכיה-ד"},{"i":19261,"n":"חגיז, יעקב מפאס","f":"שמואל בן יעקב בן שמו","dt":"שצה - יא כסלו","b":"מו\"ץ בפאס, חתם על פס\"ד עם ר חיים עוזיאל ור שלמה ן דנאן.","s":"מלכי רבנן; טולדנו-נר המערב"},{"i":19262,"n":"חגיז, יצחק מפאס","f":"שמואל","b":"רב בפאס-שמח, חתום על פסק דין והסכמה עם ר יוסף בן עמרם, יצחק אביזרדיל, יוסף אלמושנינו ועוד.","s":"אוצר הרבנים 10656; ארזי הלבנון; מלכי רבנן; טולדנו-נר המערב"},{"i":19263,"n":"חגיז, משה משלוניקי","b":"מחכמי שלוניקי-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":19264,"n":"חגיז, רפאל דוד מירושלים","b":"מחכמי ירושלים, חתם-תקצו על כתב שליחות חתנו - ר\"י חזן.","s":"אוצר הרבנים 17858; פרומקין-תח\"י; ארזי הלבנון"},{"i":19265,"n":"חגיז, רפאל שמואל מברושא","b":"רב בברושא-תלב.","s":"רוזניס-תורכיה-ד"},{"i":19266,"n":"חגיז, שלמה ממרוקו וירושלים","f":"שמואל?","dt":"שע - בערך","dp":"פאס","b":"מחכמי פאס, עלה לירושלים, וחזר לפאס. חיבר חדושים ונזכרו אצל ר שמואל ן דנאן ועוד.","s":"ארזי הלבנון; מלכי רבנן"},{"i":19267,"n":"חגיז, שמואל מפאס - הזקן","f":"אברהם?","dt":"של - בערך","b":"אולי הוא אחיו או בנו של ר אברהם מפאס. מחכמי פאס, חתם-שכד עם ר יצחק בן יוסף נהון, ור יהודה בן יצחק הכהן. חיבר ביאורים ונזכר בספר נכדו - \"מבקש השם\". מתלמידיו - ר שמואל ן דנאן. (יש בלבול בינו לבין נכדו)","s":"מלכי רבנן; פרומקין-תח\"י; טולדנו-נר המערב"},{"i":19268,"n":"חגיז, שמואל מפאס - הנכד","f":"יעקב בן שמואל","k":"בעל מבקש השם","bp":"פאס","dt":"שצג","dp":"ירושלים","b":"נכד(-אבי אמו) ר יהודה הכהן מפאס. רב וראש ישיבה בפאס, מתלמידיו ר סעדיה ן דנאן, עבר לטריפולי. הדפיס בונציה-שנו את ספריו, עלה לירושלים-שפ. חיבר גם \"דבר שמואל\" ונציה שנו, ועוד. אביו של ר יעקב בעל הלכות קטנות, נכדו - ר משה חגיז.","s":"גליס; אוצר הרבנים 19176; מלכי רבנן; גאון-יהודי המזרח; איטליה גירונדי-ש נח, פח; ארזי הלבנון; טולדנו-נר המערב"},{"i":19269,"n":"חדאד בורתה, משה מטריפולי","dt":"תרס - טז ניסן","dp":"צפת","b":"רב בטריפולי, והתפרנס מצורפות - בעל אישור מהשלטון לחתום על כלי זהב וכסף. יסד ישיבה ללימוד קבלה בשם \"דאר בורתא\", וליד הישיבה חברות בארגון תורה וחסד. עלה לארץ-תרנו והתישב בצפת.","s":"אוצר הרבנים 14691; מלכי חי\"ל-מרציאנו; ארזי הלבנון"},{"i":19270,"n":"חדאד בורתה, שלום מטריפולי","dt":"תשכב","b":"רב בטריפולי, ופעיל צבור, הו\"ל קונטרסים וחוברות ובהם \"זמרה ושמחה\" תשז, עתון \"דתנו\", דינים ומוסר בערבית יהודית. פיוט ממנו ב\"שאו זמרה\" ת\"א תשלב.","s":"מלכי חי\"ל-מרציאנו"},{"i":19271,"n":"חדאד חזקיה, דוד מגרבה וטריפול","f":"מעתוק","k":"בעל קרן לדוד ולזרעו","bt":"תרלה","bp":"ג'רבה","dt":"תשג - ח אייר","b":"חתן המקובל ר' משה עידאן. הגיע בנעוריו מג'רבה לטריפולי אל אחיו - ר יעקב. תלמיד ר סיסי הכהן, ור נסים נחום. דרשן, דיין בג'רבה, רב במטמטה-לוב, מצראתה-לוב, בן גאזי(=בנגזי)-לוב. נזכר ב\"ממלכת כהנים\" - \"פרח שושן\" ירושלים תשלז, ו\"המעלות לדוד\" גרבה תשח. חיבר \"קרן לדוד\" גרבה תשח.","s":"מלכי חי\"ל-מרציאנו; ארזי הלבנון"},{"i":19272,"n":"חדאד חזקיה, יעקב מגרבה וטריפול","f":"מעתוק","bt":"תרכה","bp":"ג'רבה","dt":"תרף","dp":"תונס","b":"רב בגרבה, טריפולי. יסד ביכ\"נ \"חדד עבובי\", הו\"ל \"תיקון השובבים\" ליוורנו תרנד. משורר וחיבר ספר פיוטים \"יינוב פי זמר\". נזכר ב\"המעלות לדוד\" ג'רבה תשח. אחיו של ר דוד.","s":"מלכי חי\"ל-מרציאנו"},{"i":19273,"n":"חדאד, אבא יהודה","dt":"כ חשון תרנ\"ח","b":"מחכמי ג'רבא","s":"ארזי הלבנון"},{"i":19274,"n":"חדאד, אבא שאול","k":"בעל ויגד שאול","dt":"תש","b":"חיבר \"ויגד שאול\" על התנ\"ך","s":"ארזי הלבנון"},{"i":19275,"n":"חדאד, אברהם מלוב","bt":"תק","bp":"כפר ידדר-לוב","dt":"תקע - בערך","b":"רב בלוב. נקבר בכפר ידדר-ליד מצארתה-לוב, ורבים עלו על קברו.","s":"מלכי חי\"ל-מרציאנו"},{"i":19276,"n":"חדאד, אהרן","b":"מחכמי קהילת אלחארה כבירה","s":"ארזי הלבנון"},{"i":19277,"n":"חדאד, אהרן","s":"ארזי הלבנון"},{"i":19278,"n":"חדאד, אליהו מג'רבה","k":"בעל חדות אליהו","bt":"תרסד","dt":"תשלה - טו אלול","dp":"ישראל","b":"דרשן, סופר בי\"ד בג'רבא, עלה לא\"י, חיבר \"חדות אליהו\". פרסם מאמרים ב\"הירח\" - ג'רבה תשח.","s":"ארזי הלבנון; אוצר כתבי עת-לוין"},{"i":19279,"n":"חדאד, בועז","k":"בעל ויאמר בועז","bt":"תרע","bp":"ג'רבא","dt":"תשנט - כו תשרי","b":"פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ.","s":"ארזי הלבנון; אוצר כתבי עת-לוין"},{"i":19280,"n":"חדאד, בן ציון מגרבה","f":"מרדכי","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה.","s":"אוצר כתבי עת-לוין"},{"i":19281,"n":"חדאד, בנימין מג'רבה","f":"לוי","k":"בעל אמרות טהורות","b":"שו\"ב מחכמי ג'רבא, חיבר \"אמרות טהורות\"","s":"ארזי הלבנון"},{"i":19282,"n":"חדאד, דוד יעיש","b":"דיין, מקובל, בעל מופת, מחכמי מועיציריה-חוגריה","s":"ארזי הלבנון"},{"i":19283,"n":"חדאד, ורגאני","k":"בעל רוח חיים","dp":"ט\"ו תשרי תשנ\"ח","b":"מחכמי ורבני ג'רבא, חיבר \"רוח חיים\"","s":"ארזי הלבנון"},{"i":19284,"n":"חדאד, חזקיה","k":"בעל מכתב לחזקיה","b":"מחכמי ג'רבא,עלה לירושלים,חיבר שו\"ת \"מכתב לחזקיה\"","s":"ארזי הלבנון"},{"i":19285,"n":"חדאד, יוסף","f":"נסים","b":"פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ.","s":"אוצר כתבי עת-לוין"},{"i":19286,"n":"חדאד, יעקב מצידון","b":"גביר בצידון-תל בערך, אחיו - הרופא ר אפרים חדאד מצידון.","s":"רוזניס-תורכיה-ד"},{"i":19287,"n":"חדאד, יצחק מגרבה - ב","f":"נסים","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה.","s":"אוצר כתבי עת-לוין"},{"i":19288,"n":"חדאד, יצחק מטריפולי","bt":"תק","dt":"תקע - בערך","b":"מחכמי טריפולי. נזכר בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":19289,"n":"חדאד, ישועה מג'רבה","k":"בעל ספר השעשועים","bt":"תרס","bp":"ג'רבא","dt":"תשכג - כג אדר","b":"מחכמי ג'רבא. פרסם מאמרים ב\"הירח\" - ג'רבה תשח.","s":"ארזי הלבנון; אוצר כתבי עת-לוין"},{"i":19290,"n":"חדאד, ישעיהו מגרבה","f":"אליהו","b":"פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו.","s":"אוצר כתבי עת-לוין"},{"i":19291,"n":"חדאד, כליפא ממלטה","bt":"תקצא","bp":"ווהראן","dt":"תרעא","dp":"מלטה","b":"רב באי מלטה, תונס, עלה לארץ-תרע, נסע לתונס ונפטר בדרכו במלטה.","s":"מלכי ישורון-חכמי אלגיר"},{"i":19292,"n":"חדאד, כמוס","f":"אליהו","k":"בעל חכם לב","bp":"ג'רבא","dt":"תרפו - א אדר","b":"תלמיד ר דוד כהן גישא בעל \"שירי דוד\". רב בג'רבא, מדנין (מרוקו או תונס). חיבר גם \"דבק טוב\" ועוד. פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו.","s":"ארזי הלבנון; אוצר כתבי עת-לוין","bk":[["חכם לב ועוד",""]]},{"i":19293,"n":"חדאד, מוסא מג'רבה","k":"בעל ברכת משה","bt":"תרסט","bp":"ג'רבא","dt":"תשנג - ה אב","dp":"ירושלים","b":"תלמיד ר מקיקץ שלי מג'רבא, ור רחמים חיותה חי הכהן. דיין ושו\"ב בג'רבא. חברם של ר מצליח מאזוז, ור רפאל כדיר צבאן. עלה לירושלים.","s":"ארזי הלבנון"},{"i":19294,"n":"חדאד, מכלוף מג'רבה","f":"כמוס מג'רבא","k":"בעל כרחם אב","b":"תלמיד ר יוסף ברבי. חיבר ספר מוסר ומשלים \"כרחם אב\" בערבית שהיה נפוץ מאוד בג'רבא.","s":"ארזי הלבנון"},{"i":19295,"n":"חדאד, מעתוק מג'רבה","dt":"תרלח","b":"רב בג'רבא. נעזר בגביר קאיד נסים שמאמה בעסק שעשו והתעשר והקים ישיבה.","s":"ארזי הלבנון"},{"i":19296,"n":"חדאד, מקיקץ ישראל מג'רבה","k":"בעל שאגת אריה ואריה","bp":"ג'רבא","dt":"תשם - יא תשרי","b":"תלמיד ר רחמים חי חויתא הכהן מג'רבא. רב בתיטאוין. עלה לארץ וכיהן כרב במושב בית הגדי. חיבר גם \"אשביע לחם\" ועוד.","s":"ארזי הלבנון","bk":[["שאגת אריה",""]]},{"i":19297,"n":"חדאד, משה הכהן מירושלים","dt":"תרנד - יב תמוז","dp":"ירושלים","b":"מחכמי ירושלים.","s":"גאון-יהודי המזרח"},{"i":19298,"n":"חדאד, משה מג'רבה","b":"רב בגג'רבא בזמן ר אהרן פרץ, נזכר אצל ר יצחק חדאד ב\"תולדות יצחק\", ונזכר אצל ר רחמים חורי ב\"שערי רחמים\".","s":"ארזי הלבנון"},{"i":19299,"n":"חדאד, משה מירושלים","b":"רב בירושלים-שנות ה-ר'-ש'.","s":"רוזניס-תורכיה-ב"},{"i":19300,"n":"חדאד, משה מתונס","f":"שלמה","b":"תלמיד ר שלמה דאנה בעל \"שלמי תודה\". רב בנאבל-תונס. עלה לארץ וכיהן כרב בחבל לכיש. חיבר ספר על שטרות - ג'רבא.","s":"ארזי הלבנון"},{"i":19301,"n":"חדאד, משה מתימן","b":"מחכמי צנעא במאה ה-18.","s":"ארזי הלבנון"},{"i":19302,"n":"חדאד, נסים מג'רבה","dt":"תרכח","dp":"ג'רבא","b":"דיין בג'רבא אצל ר מעתוק חדאד, נחשב למלומד בנסים.","s":"ארזי הלבנון"},{"i":19303,"n":"חדאד, סאסי נסים מג'רבה","k":"בעל חסדי ה'","b":"מחכמי ג'רבא, עלה לארץ. חיבר גם \"יראתך היא\".","s":"ארזי הלבנון"},{"i":19304,"n":"חדאד, עמוס","b":"פרסם מאמרים ב\"הירח\" - ג'רבה תשח.","s":"אוצר כתבי עת-לוין"},{"i":19305,"n":"חדאד, ציון מטריפולי","bt":"תרל","dt":"תש","b":"מחכמי טריפולי. הו\"ל ספרי קודש ובהם \"אלון בכות החדש\" ליוורנו תרעט, \"שאו זמרה\" תונס תרסב.","s":"מלכי חי\"ל-מרציאנו"},{"i":19306,"n":"חדאד, רחמים מג'רבה","f":"מעתוק","dt":"תרסא","b":"רב בג'רבא על מקום ר סאסי מעתוק הכהן יהונתן. תשובות ממנו בספרי ר משה זקן מאזוז מג'רבא.","s":"ארזי הלבנון"},{"i":19307,"n":"חדאד, שלום מג'רבה","f":"אהרן","b":"מחכמי ג'רבא. זקנו הגדול של ר דוד חדאד חזקיה בעל \"קרן לדוד\" מג'רבא. יסד בית כנסת שנקרא ע\"ש בג'רבא.","s":"ארזי הלבנון"},{"i":19308,"n":"חדאד, שמואל ממצרים","b":"מחכמי מצרים-רפ - מקהלת המערבים, בזמן הרדב\"ז.","s":"רוזניס-תורכיה-א"},{"i":19309,"n":"חדאד, שמעון מטריפולי","f":"עטיה","b":"רב ומלמד תורה בטריפולי, רב בזאויה-לוב. נזכר ב\"קונטרס אנשי השם\" לר שושן מזוז.","s":"מלכי חי\"ל-מרציאנו"},{"i":19310,"n":"חדה, דוד","b":"אב\"ד חדה בתימן, מקובל","s":"ארזי הלבנון"},{"i":19311,"n":"חדה, ישראל מתימן","dt":"תרצב - בערך","dp":"תימן","b":"רב בחדה-שרעב בתימן","s":"ארזי הלבנון"},{"i":19312,"n":"חדיד, שלמה מצידון","b":"רב בצידון-לבנון. חיבר ספר בקבלה וסגולות - בכת\"י.","s":"ארזי הלבנון"},{"i":19313,"n":"חדידה, אברהם","b":"חיבר פי' על הגדה ועל קוהלת ואסתר (מופיע אצל די רוסי - שהחזיק את חבוריו - בכת\"י).","s":"איטליה גירונדי-א עה"},{"i":19314,"n":"חדידה, אברהם מסופיה","b":"מראשי הקהלה הספרדית בסופיה - בדור שלאחר הגירוש.","s":"רוזניס-תורכיה-ב,ג"},{"i":19315,"n":"חדידה, יהודה מטיטואן-מרוקו - א","b":"מחכמי טיטואן, חתם בפס\"ד-תיד ונזכר ב\"משפט וצבי\".","s":"מלכי רבנן"},{"i":19316,"n":"חדידה, יהודה ממרוקו - ב","b":"מחכמי מרוקו, חתם על פס\"ד-תעד עם ר אלעזר בהלול.","s":"מלכי רבנן"},{"i":19317,"n":"חדידה, יצחק מצפת","b":"מתלמידי האר\"י.","s":"ארזי הלבנון"},{"i":19318,"n":"חדידה, ישועה","f":"יהודה","b":"חתום על שטר-תריח, ואביו חתום-תקפה.","s":"ארזי הלבנון"},{"i":19319,"n":"חדידה, פנחס משלוניקי","dt":"תקסט","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי-116"},{"i":19320,"n":"חדידה, ראובן מניקופול","b":"תלמיד ר חיים שבתי (=המהרח\"ש). מחכמי שלוניקי-שפה, רב בניקופול-שצט על מקום ר ציון ן שנג'י ור יצחק ביגא. חברו של ר ברוך קלעי.","s":"אוצר הרבנים 17699; ארזי הלבנון; זכרון שלוניקי; רוזניס-תורכיה-ג"},{"i":19321,"n":"חדידה, שלמה","b":"רב ק\"ק נוה שלום. נספד ע\"י בעל \"אזני יהושע\".","s":"איטליה גירונדי-ש טו"},{"i":19322,"n":"חדידה, שלמה (שמואל) מירושלים","dt":"תה - לפני","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לצפת ועבר לחברון. תלמיד מהרי\"ט. בשנת שעב נמנה על רבני קושטא. עבר לירושלים וחתם בשנת שפג על התקנה נגד הפירוד. מוזכר ב\"חרבות ירושלים\" כראש הקהלה בזמן פרעות אבן פארוך. תשובה אליו לירושלים בשו\"ת מהרי\"ט.","s":"גליס; אוצר הרבנים 18437; ארזי הלבנון; רוזניס-תורכיה-ג; פרומקין-תח\"י"},{"i":19323,"n":"חדיף, יוסף מלוב","bp":"בארדה(=בארצ'ה)-לוב","dt":"תשלט","dp":"ישראל","b":"רב בבארדה-לוב-תרפה עד תשה, חנך את ביה\"כ הראשון שם, עלה לארץ וכיהן כרב בביריה-ליד צפת.","s":"מלכי חי\"ל-מרציאנו"},{"i":19324,"n":"חדיקה, אברהם מתורכיה","f":"יהודה","b":"מחכמי תורכיה-ש', חיבור ממנו בכת\"י.","s":"אלופי יעקב א-רלט"},{"i":19325,"n":"חדש, ברוך יצחק מלנדוארווא","f":"אברהם אליעזר","bt":"תרכב","dt":"תרצא - כב אדר","b":"רב בלנדבורובה(=לאנדוואראווא)-פלך וילנא-תרמח. תלמיד ישיבת טלז, ר מאיר אטלס משאוועל, ר צבי יעקב מקלם. נסמך מאת: ר יצחק אלחנן מקובנא, ר יצחק מאיר מסלובודקא, ר יעקב חריף מוילנא.","s":"אוצר הרבנים 4212; אהלי שם"},{"i":19326,"n":"חדש, גרשון מפיוטר-פובלובסק","f":"ישראל יצחק","bt":"תרלב","b":"מו\"צ ושו\"ב בפיעטרופלוסק(=פיעטראפאוולאווסק)-סיביר.","s":"אוצר הרבנים 4408; אהלי שם"},{"i":19327,"n":"חדש, מאיר מירושלים","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא.","s":"אוצר כתבי עת-לוין"},{"i":19328,"n":"חדש, נח הלוי מארה\"ב","f":"יקותיאל מאיר","bt":"תרעג","bp":"קוזיאן-פלך וילנא","b":"תלמיד ישיבת וולוזין, מיר. נסמך מאת: ר אליעזר יהודה פינקל, הרב קופרשטוק, ר הניך אייגעש מוילנא, ר יצחק שוסטר מסוקולקא. בעל תואר עו\"ד ממכללת קולומביה-ארה\"ב. רב בקוזיאן-תרצב, ביכנ\"ס צא\"י ופא\"י בוילנא-תרצד, ניו יורק-תרצז. חבר אגודת הרבנים באמריקה, ותנועת פועלי אגודת ישראל בארה\"ב. חיבר ספר באנגלית בענין משפטי.","s":"אנשי שם-אמריקה"},{"i":19329,"n":"חדש, ראובן","dt":"תשג","b":"רב באלאשני","s":"אוצר הרבנים 17700"},{"i":19330,"n":"חדשה, שמואל מתימן","f":"דוד","bt":"[תרי-כ]","bp":"שרעב-תימן","b":"בנו של הראב\"ד של מחוז חדה בשרעב. דיין במחוז עם אחיו.","s":"ארזי הלבנון"},{"i":19331,"n":"חואינטיס, נסים מקושטא","bp":"קושטא","b":"תלמיד ר רפאל ביטראן מקושטא המזכירו ב\"זכור לטוב\".","s":"ארזי הלבנון"},{"i":19332,"n":"חואתי דמרי, אליהו","k":"בעל אחוה דעי","dt":"תשלד","b":"מחכמי ג'רבא, רב באלחאמה, עלה לבאר שבע, חיבר \"אחוה דעי\"","s":"ארזי הלבנון"},{"i":19333,"n":"חוברה, חיים מתימן","dt":"תשכב","b":"מגדולי חכמי תימן ומרביץ תורה בצנעא, עלה לארץ, דיין בירושלים, ראש ישיבת \"ענף חיים\".","s":"אוצר הרבנים 5998; ארזי הלבנון"},{"i":19334,"n":"חובש, אברהם מזאגרה","b":"דיין בזאגרה אצל ר גבריאל משה קריספין, יחד עם ר יצחק אסא.","s":"רוזניס-תורכיה-ו"},{"i":19335,"n":"חוגי עבודי, יחזקאל מבגדד","b":"מחכמי בגדד - שנות ה-תר', תלמיד ר שמעון אגסי.","s":"ארזי הלבנון"},{"i":19336,"n":"חוגי עבודי, סלמן מבגדד","r":"ראב\"ד העדה החרדית בי-ם","bt":"תרנד","bp":"בגדד","dt":"תשלג - כה אד\"א","dp":"ירושלים","b":"תלמיד \"בית זלכה\" אצל ר יהודה פתיה ור שמעון אגסי. ברח לבצרה כדי להמנע מגיוס לצבא התורכי יחד עם אלפי בחורים יהודים, וקבלו סיוע מהקהלה ומראשה ר יחזקאל ששון. ראש ישיבת \"תומכי תורה\" בבגדד, ורב ראשי בבבל. עלה לארץ-תשיא וכיהן כדיין בפתח תקוה וירושלים.","s":"ארזי הלבנון; אוצר הרבנים 16509"},{"i":19337,"n":"חודאדה","k":"ראה: חודארה","b":"ראש ישיבת ק\"ק \"איבורה\" בשלוניקי, חתם על הסכמות תלמוד תורה-שסח. נזכר ב\"קורא הדורות\" כראש ישיבה בק\"ק איבורה-קושטא.","s":"ארזי הלבנון; זכרון שלוניקי"},{"i":19338,"n":"חודאדה, אברהם מאזמיר","b":"רב באזמיר-תכו.","s":"רוזניס-תורכיה-ד"},{"i":19339,"n":"חודאדה, אברהם עובדיה מירושלים","b":"מראשי החברא קדישא בירושלים-תריד.","s":"פרומקין-תח\"י"},{"i":19340,"n":"חודארה, אברהם מבלגרד","b":"מחכמי בלגרד-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":19341,"n":"חודארה, אברהם מליפאנטו","b":"גביר מחכמי ליפאנטו-תלה.","s":"רוזניס-תורכיה-ד"},{"i":19342,"n":"חודארה, יוסף מטיריא","b":"רב בטיריא-ש'-ת' - בזמן ר גבריאל גליקו.","s":"רוזניס-תורכיה-ג"},{"i":19343,"n":"חודארה, יצחק","b":"מחכמי חברון, בשנת תקכג חתם על כתב בקשת עזרה.","s":"גליס"},{"i":19344,"n":"חודארה, שלמה משלוניקי","b":"ראש ישיבת ק\"ק \"איבורה\" בשלוניקי, חתם על הסכמות תלמוד תורה-שסח. נזכר ב\"קורא הדורות\" כראש ישיבה בק\"ק איבורה-קושטא.","s":"אוצר הרבנים 18438; ארזי הלבנון; זכרון שלוניקי; רוזניס-תורכיה-ג"},{"i":19345,"n":"חודובסקי, אברהם טוביה מניו זיל","bt":"תרכג","bp":"גנעזען-פלך פוזנא","b":"תלמיד ישיבת פוזנא, ביהמ\"ד לרבנים בברלין, ביהמ\"ד לרבנים בלונדון. רב בלסטר, בריסבון(=בריסבאנע), דונדין-ניו זילנד. מזכיר החברה \"היהודית האנגלית\".","s":"אוצר הרבנים 1096; אהלי שם"},{"i":19346,"n":"חודיפי, שלום מתימן","bp":"אחדוף-תימן","b":"רב באחדוף - מחוז חוגריה שבדרום תימן, במחצית השניה של המאה ה-19. הסמיך רבנים ושו\"בים.","s":"ארזי הלבנון"},{"i":19347,"n":"חודרוב, אברהם שמואל אבא מטלוסט","f":"פנחס","bt":"תרן","dt":"תשב","b":"רב בטלוסט על מקום אביו. נספה בשואה.","s":"וונדר-גליציה ח\"ג"},{"i":19348,"n":"חודרוב, חיים יהודה מאיר מטולנא","f":"דוד מטולנא","k":"אדמור מטולנא","b":"אדמו\"ר בטולנא-תר\"ל","s":"אוצר הרבנים 6357"},{"i":19349,"n":"חודרוב, יהושע אלעזר מקולומיאה","f":"משה יוסף","bt":"תקף","dt":"תרנה","b":"חתן ר חיים מקוסוב. דיין בקולומיאה וסירב לנהוג אדמורות.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 7657"},{"i":19350,"n":"חודרוב, מאיר","b":"רב-שנת תר\"נ","s":"אוצר הרבנים 12837"},{"i":19351,"n":"חודרוב, מנחם מנדל דוד מטולנא","f":"מרדכי מטולנא קולומיא","k":"אדמור מטולנא","bt":"תרמז","bp":"ויזניץ","dt":"תשם - יא אדר","b":"חתן דודו ר שמואל אברהם הגר מהורודנקה. רב בטשרנוביץ-תרסה. בשליחות באמריקה-תרפב והיגר לשם, אדמור מטולנא-ויזניץ באמריקה-תרצח על מקום אביו. חיבר \"במועדו\" ניו יורק תרצז, \"טו מאמרים\", ועוד.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 13460; אלפסי; אמריקה; אנשי שם-אמריקה"},{"i":19352,"n":"חודרוב, מרדכי מטולנא","f":"חיים יהודה מאיר מברד","k":"אדמור מטולנא-אמרי בר","bt":"תרכז","bp":"טולנא","dt":"תרצח - ב כסלו","b":"גדל אצל זקנו-אבי אמו ר דוד מטולנא. חתן ר ברוך הגר מויזניץ. אדמור בטולנא, בדעוויליע(=בידעוולע)-מרמאראש, בגאניטש-בוקובינה-תרנג, עבר לקולומיאה ושימש שם אדמור, בודפשט. היגר לניו יורק-תרצח ונקרא שם האדמור מטולנא-ויזניץ. הוציא לאור ספר חותנו \"אמרי ברוך\" תרעב עם הוספות ממנו. יסד את אגודת האדמורים ועמד בראשה. . הו\"ל ספר חותנו \"אמרי ברוך\" עם הקדמה ותוספות משלו. בנו ר מנחם מנדל בניו יורק. חתנו האדמור מנחם מנדל הגר מווישעווע. ?? לא באוצר ??","s":"וונדר-גליציה ח\"ג; אמריקה; אוצר הרבנים 13822; אלפסי; הונגריה; אנשי שם-אמריקה"},{"i":19353,"n":"חודרוב, משה","dt":"תשג","b":"רב בבוירוק","s":"אוצר הרבנים 14692"},{"i":19354,"n":"חודרוב, פנחס מזביא","f":"יהושע אלעזר","bt":"תר","dt":"תרן","b":"חתן ר ברוך מגורליץ. רבה של זביא. חתנו ר משולם שרגא הלפריין על מקומו אחריו.","s":"וונדר-גליציה ח\"ג"},{"i":19355,"n":"חודרוב, פנחס מטלוסט","f":"דוד","bt":"תרך","dt":"תרעה","b":"נקרא על שם סבו ר פנחס מקוריץ. חתן ר אברהם יהושע השל קצנלבויגן מטלוסט. רבה של טלוסט על מקום חותנו. פרסם מאמרים ב\"ועד חכמים\" - יזלוביץ (ועוד) תרנח.","s":"וונדר-גליציה ח\"ג; אוצר כתבי עת-לוין"},{"i":19356,"n":"חודרוב, פנחס מטרנוב","f":"שלום מנחם","bt":"תרס","dt":"תשג","b":"מצאצאי ר פנחס מקוריץ. רב בטרנוב. נספה בשואה. חיבר קונטרס \"זכרון פנחס\" - נדפס בסוף ספר \"אמרי פנחס\" לזקנו ר פנחס מקוריץ. תל אביב תשלד.","s":"וונדר-גליציה ח\"ג"},{"i":19357,"n":"חודרוב, שמואל דוב מפטריווא","f":"יהושע אלעזר אלתר","k":"אדמור מפטריווא","dt":"תרפט - יז תשרי","b":"נכד ר חיים מקוסוב בעל \"תורת חיים\". חתן האדמור מויזניץ ר ברוך הגר בעל \"אמרי ברוך\", אדמור חסידי ויזניץ בכפר פטריווה-מארמרוש והסביבה. לאחר פטירתו המשיכה האלמנה - בת האדמור - לקבל פתקאות והתנהגה כאדמורית. נספתה בשואה - אושוויץ תשד. (באוצר מופיע חתן ר חיים מקוסוב). שם אביו יהודה או יהושע.","s":"אוצר הרבנים 19490; טרנסילבניה; אלפסי"},{"i":19358,"n":"חודרוב, שניאור זלמן מברדיטשוב","f":"יוסף","b":"חתן ר משה מרזיסטשוב.","s":"וונדר-גליציה ח\"ו"},{"i":19359,"n":"חוולס, אברהם הלוי מצחינוואל","b":"הגיע לצחינוואל-גרוזיה ולימד תלמוד. נזכר במכתב ר מיכאל אלאשוילי מסוגונא בעל \"זבח ומנחה\".","s":"אהלי שם"},{"i":19360,"n":"חוולסון, דניאל","f":"אברהם","bt":"1819","bp":"וילנא","dt":"1911","b":"למד בברסלאו ולייפציג. מזרחן. חזר לרוסיה והתנצר והיה פרופ' לשפות עברית וסורית בפטרבורג. חיבר ספרים על ראשית הנצרות. והיה חוקר מדעי היהדות. יצחק כנגד עלילות הדם ברוסיה.","s":"ליטא"},{"i":19361,"n":"חווס, אליעזר יעקב","b":"רב ביאנישק","s":"אוצר הרבנים 2663"},{"i":19362,"n":"חוידנסקי, חיים יעקב מפוניבז","k":"בעל דרך המלך","b":"רב בפוניבז-תרע.","s":"אוצר הרבנים 6395; ליטא"},{"i":19363,"n":"חויז, משה מאוסציא","b":"רב באוסציא, תשובה אליו \"מנחת שי\".","s":"וונדר-גליציה ח\"ג"},{"i":19364,"n":"חולו, אברהם מירושלים","dt":"תצז - יא אדר","dp":"ירושלים","b":"רב ביוזיל-היסאר, עלה לירושלים?, נספד בספר \"שמע יעקב\" לר יעקב אלגזי,","s":"גליס; אוצר הרבנים 817; ארזי הלבנון; פרומקין-תח\"י; רוזניס-תורכיה-ה"},{"i":19365,"n":"חולו, אליהו מירושלים","b":"דיין בירושלים-תקי אצל ר יצחק רפפורט בעל \"בתי כהונה\". (היה גם בקושטא?)","s":"רוזניס-תורכיה-ה"},{"i":19366,"n":"חולו, יהודה שלמה משלוניקי","b":"דיין בשלוניקי-שסו.","s":"זכרון שלוניקי; רוזניס-תורכיה-ג"},{"i":19367,"n":"חולו, משה מירושלים","dt":"תקצב - יד אד\"ב","dp":"ירושלים","b":"מחכמי ירושלים.","s":"פרומקין-תח\"י"},{"i":19368,"n":"חולו, משה משלוניקי","dt":"רצח - כד חשון","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"עמנואל-שלוניקי"},{"i":19369,"n":"חומה, ברוך מארה\"ב","f":"אברהם אבא","k":"בעל מקור ברוך","bt":"1858","bp":"וואגאר-ליטא","dt":"1930","b":"הוסמך לרבנות ע\"י ר יצחק אלחנן ספקוטר. היגר לארה\"ב וכיהן כרב בשיקגו. עלה לארץ-תרן והתישב בעקרון והיה מנהל בי\"ס של הברון. עבר לירושלים ויסד חברה \"ת\"ת\" (תלמידי תשבי) שפעלה לחדוש הסנהדרין. חיבר גם \"חומת אש דת\" סט לואיס תרפז, ועוד. השתתף במילון אליעזר בן יהודה.","s":"ליטא"},{"i":19370,"n":"חוני המעגל","dt":"ג אייר"},{"i":19371,"n":"חוניו - מכת הדונמה","f":"עשמן באבה","b":"ראש כת הדונמה במאה ה-18.","s":"רוזניס-תורכיה-ד"},{"i":19372,"n":"חוניס, דוד אלכסנדר יעקב","f":"משה מרדכי","bt":"תרכא","b":"נסמך מאת: רי\"א איטינגא מלבוב, ר יוסף אפרתי מברדיטשוב. רב בקונסטנטין חדש-פודוליה-תרמח (ללא שכר) ובתרסא - עם שכר. חיבר \"פרי אס\"י\" - בכת\"י. חתנו - ר יוסף מרייהאראדאק-ווהלין.","s":"ארזי הלבנון; אוצר הרבנים 5091; אהלי שם"},{"i":19373,"n":"חונס, יצחק בר","f":"גדליהו","k":"בעל עורך המלים","bt":"1840","bp":"וילנא","dt":"1929","dp":"שיקגו","b":"תלמיד ר ולוולה שהיה מגיד בוילנא. בקי בלשון ודקדוק והיה מגיה בדפוס רש\"י פין, ובדפוס ראם. היגר לארה\"ב והתישב בשיקגו. חיבר קונקורנציה בשם \"עורך המלים והפתרונים\", \"ספר המלים\" - מילון תלמודי, ועוד.","s":"ליטא"},{"i":19374,"n":"חונס, שמעון משה בן גדליהו","k":"בעל תולדות הפוסקים","bp":"וילנא","b":"מגיה בדפוס בוארשא. חיבר תולדות הפוסקים. (אולי אחיו של ר יצחק בעל ספר המילים-ערוך הקצר."},{"i":19375,"n":"חוצין, משה","f":"צדקה חוצין","b":"גדול בתורה ובשיר","s":"אוצר הרבנים 14693"},{"i":19376,"n":"חוצין, משה מבבל","f":"צדקה","b":"פייטן ומשורר מחכמי בבל, מפיוטיו \"מלך גואל ומושיע\" שאומרים בחדש ניסן. נפטר בחיי אביו ונזכר ב\"צדקה ומשפט\"-תקע.","s":"ארזי הלבנון"},{"i":19377,"n":"חוצין, משה רפאל שלום מבגדד","b":"ראש ישיבה בבגדד. מתלמידיו ר צדקה חוצין השלישי, ר רפאל יצחק חיים שהיה לימים אב\"ד בבגדד.","s":"ארזי הלבנון"},{"i":19378,"n":"חוצין, צדקה מבגדד - ב","k":"בעל מקיץ נרדמים","dt":"תשכא - א אדר","dp":"ירושלים","b":"מחכמי בגדד, מצאצאי ר צדקה הראשון. לחם למען החינוך היהודי וכנגד המנסים לשנות, ועל כך נאסר, לאחר ששוחרר עלה לירושלים, בנה בית כנסת ובית מדרש, וכיהן כרבו, ר יעקב מוצאפי על מקומו אחריו.","s":"ארזי הלבנון","bk":[["מקיץ נרדמים",""]]},{"i":19379,"n":"חוצין, ראובן מבגדד","b":"רב בבגדד. חתם עם ר אליהו יהושע עובדיה על שטר.","s":"ארזי הלבנון"},{"i":19380,"n":"חוצין, רפאל ברוך מחברון","b":"מחכמי חברון בזמן ר אליהו מני. חתם עם 50 מחכמי חברון בתמיכה בר אליהו מני, וכנגד המתנגדים לו - והצליחו להסיר את המתנגדים ממעמדם ולהשיב את ר אליהו על כנו.","s":"ארזי הלבנון"},{"i":19381,"n":"חוצין, שלמה בכור מבגדד","bt":"תרג","bp":"בגדד","dt":"תרנג - ה תשרי","dp":"בגדד","b":"תלמיד ר עבדאללה סומך, מחכמי בגדד, פייטן, ומדפיס. הסכים עם רבו על \"סדרי טהרות\" לר גרשון חנוך העניך מראדזין. הו\"ל והדפיס \"אמרי ששון\" ובסופו מחדושיו שלו, מתורתו גם ב\"נופת צופים\" למהר\"ש תווינא. נספד ע\"י ה\"בן איש חי\".","s":"אוצר הרבנים 18693; ארזי הלבנון"},{"i":19382,"n":"חוצני, עזרא מירושלים","dt":"תשטז - ח סיון","dp":"ירושלים","b":"ר\"מ ב\"פורת יוסף\" בירושלים. מחכמי הקבלה. חתן ר עזרא הררי רפול.","s":"ארזי הלבנון"},{"i":19383,"n":"חור בנו של כלב ומרים הנביאה","dt":"טז תמוז"},{"i":19384,"n":"חורגין גרשון אברהם","dt":"ה'תרסג 1903","s":"היברובוקס","bk":[["אופקי מחשבה",""]]},{"i":19385,"n":"חורגין, פנחס מנ\"י","b":"פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן.","s":"אוצר כתבי עת-לוין"},{"i":19386,"n":"חורגל, אהרן דוד","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן.","s":"אוצר כתבי עת-לוין"},{"i":19387,"n":"חורונז'יצקי, שלמה","f":"ישראל","bt":"1877","bp":"שאוולי","dt":"1938","b":"עסקן ציבור ועו\"ד בפטרברוג. חבר בחברה להגנת זכויות היהודים ברוסיה. מקורב לחוגי \"פאלקס פארטיי\" מיסודו של דובנוב. עבר לקובנא. חבר במרכת הצויוני בליטא. חיבר ספר על שמות משפחה בישראל - בכת\"י.","s":"ליטא; ליפמן-קובנא"},{"i":19388,"n":"חורי, חויתו","k":"בעל חח ונזם","bt":"תרנד","dt":"תשמ","b":"מחכמי ג'רבא,עלה לא\"י,חיבר \"חח ונזם\"","s":"ארזי הלבנון"},{"i":19389,"n":"חורי, חיים מתונס וארץ ישראל","k":"בעל דרך החיים","r":"רב בגאבס, ואח\"כ בדיגת","bt":"תרמה","bp":"ג'רבא","dt":"תשיז - כה אייר","dp":"באר שבע","b":"רב ראשי בגאבס, לחם בהשכלה, ותרגם ספרי מוסר לערבית כמו \"פלא יועץ\", חיבר \"מצא חיים\" דרושים וחידושים. עלה לא\"י-תשטו. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ. מעורכי \"קרן דוד\" - גרבה תרעו, \"תורה מציון\" - ירושלים תרנה-תרסה.","s":"אוצר הרבנים 5999; ארזי הלבנון; אוצר כתבי עת-לוין; פניני עין חמד גליון 482","bk":[["דרך חיים - תנ\"ך וש\"ס",""],["חסד ואמת",""],["נפלאות גדולות",""],["מצא חיים, תשי\"ז, קבור בב\"ש",""]]},{"i":19390,"n":"חורי, יעקב מג'רבה","f":"רחמים","k":"בעל בני יעקב","bt":"תרכג","dt":"תרפט","b":"רב בגרבא-תרס. פרסם מאמרים ב\"המאסף\" בירושלים. בנו - ר מנחם.","s":"דור וחכמיו-א\"ש-ו","bk":[["בני יעקב לבושים",""]]},{"i":19391,"n":"חורי, מאיר מג'רבה","b":"פרסם מאמרים ב\"הירח\" - ג'רבה תשח.","s":"אוצר כתבי עת-לוין"},{"i":19392,"n":"חורי, מרדכי מהדיג'ת","b":"מחכמי הדיג'ת-ג'רבא-תר, ויחד עם ר נסים חדאד עמד לדין כנגד קהילת אלחארה-ג'רבא, ונזכר ב\"מעשה בית דין\".","s":"ארזי הלבנון"},{"i":19393,"n":"חורי, עטייה מג'רבה","k":"בעל נטע רבעי","dt":"תשלב","dp":"טבריה","b":"מחכמי ג'רבא, רב בתיטאוין. עלה לארץ. תלמיד המקובל ר מכלוף עידאן.","s":"ארזי הלבנון"},{"i":19394,"n":"חורי, רחמים מג'רבה - א","k":"בעל שערי רחמים","bt":"תץ","b":"תלמיד ר אהרן פרץ בעל \"בגדי אהרן\". מחכמי ג'רבא. אבי משפחת הרבנים הידועה. חיבר גם \"כסא רחמים\". בנו - ר מנחם בעל \"זרע האב\".","s":"ארזי הלבנון"},{"i":19395,"n":"חורי, שושן מדבדה","bt":"תקעד","b":"רב בדבדה, אלחאמה. אחיו של ר יצחק חורי.","s":"ארזי הלבנון"},{"i":19396,"n":"חורי, שלמה מג'רבה","k":"בעל חשק שלמה","bt":"תרן","dt":"תשב","dp":"ג'רבא","b":"מחכמי ג'רבא, וראש חברת \"אור תורה\".","s":"ארזי הלבנון"},{"i":19397,"n":"חורין, אהרן מאראד","f":"קלמן","k":"בעל עמק השוה-תקסג","bt":"תקכו","bp":"וייסקירכן","dt":"תרד - ט אלול","b":"תלמיד ה\"נודע ביהודה\" בפרג, ור ירמיה בן יצחק במטרסדורף. רב באראד-תקמט והגליל על מקום ר צבי סמניץ. היה מחלוקת בינו לר יצחק גריסהאבר מפאקש בענין כשרות דג ה\"שטירל\" שר יצחק אסרם ור אהרן התירם, ורוב רבני הונגריה פסקו לאיסור כנגדו. לאחר מכן חיבר \"עמק השווה\"-תקסג ובו יצא כנגד מנהגים שאין להם שורש, כגון כפרות וקמיעות, ור מרדכי בנעט עם עוד רבנים ראו בספר דברי כפירה ודנוהו לשריפה ואת קהילת אראד תבעו לפטר את הרב. בתגובה פרסם מאמר \"קנאת האמת\" בקובץ \"נוגה צדק\" תקעח, ובו התיר להשתמש בעוגב בתפילה גם בשבת ולמעשה הצטרף לדעת הריפורמים בגרמניה. בתגובה ארגן החת\"ס את גדולי הדור ובהם כאלה שבתחילה הגנו על ספרו \"עמק השווה\" - והחרימו אותו ואת ספריו וכינוהו - אח\"ר(=אהרן חוריני רבינר), ובספריו הבאים המשיך בדרכו ולמעשה הפך לרב הריפורמי-ניאולוגי הראשון בהונגריה, יחד עם יעקב שטינהארט. חיבר גם \"שריון קשקשים\" כנגד \"מקל נועם\" לר יצחק קריסהאבר מפאקש (שיצא נגדו), \"דבר בעתו\" - ובו עדיפות המצוות שבין אדם לחברו גם כלפי גוי על המצוות המעשיות, ועוד. פעל גם למען הקמת מרכז רוחני בירושלים, כנגד עלילת הדם בדמשק יחד עם לאוו ליפוט, חיסול הרוכלות בקרב היהודים והפנייתם למקצועות יצרניים.","s":"טרנסילבניה; אמריקה; הונגריה; פין-כנסת ישראל"},{"i":19398,"n":"חוריסט, נסים מגרבה","f":"פנחס","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה.","s":"אוצר כתבי עת-לוין"},{"i":19399,"n":"חורש, אברהם","f":"יהושע אליעזר עזרא","b":"מחכמי בגדאד","s":"ארזי הלבנון"},{"i":19400,"n":"חורש, אברהם יהושע","dt":"תרסב - שבט","dp":"בגדאד","b":"ראש השוחטים, חזן, דיין בבגדאד-תר\"א","s":"ארזי הלבנון"},{"i":19401,"n":"חורש, מאיר מבגדד","f":"מועלם יעקב","bt":"תרעא","bp":"בגדד","dt":"תשנז - כב תשרי","dp":"בני ברק","b":"מלמד מחכמי בגדד ומתלמידי \"בית זילכה\", תלמיד ר יהושע משה ור יעקב מוצפי. עלה לארץ-תשיא והתישב בירושלים, נס ציונה, רב ברמת גן.","s":"ארזי הלבנון"},{"i":19402,"n":"חושטט, יצחק מתאפילאלת","f":"משה","b":"מחכמי תאפילאלת-מרוקו - שנות ה-ר', נזכר ב\"יכין ובועז\".","s":"מלכי רבנן"},{"i":19403,"n":"חושיאל","f":"אלחנן","b":"אחד מארבעת השבויים. מחכמי העיר בארי באיטליה, מרביץ תורה בקירואן-תוניס-ד'תשס\"ו. אביו של רבינו חננאל.","s":"אוצר הרבנים 5799; פין-כנסת ישראל"},{"i":19404,"n":"חותא ן, שמואל מצפרו-מרוקו","dt":"תצב - יג אלול","b":"רב בצפרו-תסט, שו\"ב, דרשן ומעשה על הצדקה, תלמיד ר משה בן חמו. חתם עם ר ישועה בן חמו, ור מאיר די אבילא. חתם על פסקי דין רבים ב\"משפט וצדקה ביעקב\". ר יעקב ן צור ביקש את עזרתו-תסג, לעורר הצבור לבוא לעזרת חברי ההסגר בפאס. בנו - ר יצחק.","s":"ארזי הלבנון; מלכי רבנן"},{"i":19405,"n":"חותא, יצחק מצפרו-מרוקו","f":"שמואל","b":"מחכמי צפרו-מרוקו, חתם על פס\"ד-תפז עם ר יוסף הרוס. מכתב אליו מר מרדכי אצבאן.","s":"מלכי רבנן"},{"i":19406,"n":"חותא, שלמה ממרוקו","f":"יהושע","dt":"תרב - אחרי","b":"מחכמי צפרו-מרוקו, ספרא דדיינא-תקמז עד תרב.","s":"ארזי הלבנון; מלכי רבנן"},{"i":19407,"n":"חותר, דוד מתימן","f":"יחיא","bt":"תכז","bp":"צנעא","b":"ראב\"ד ורב ראשי בתימן-תפ\"ד","s":"ארזי הלבנון"},{"i":19408,"n":"חזוט, משה ממראקש","dp":"מראקש","b":"רב ומקובל במראקש, ונאמר עליו (ב\"מלכי רבנן\") שהיה לו גילוי אליהו.","s":"ארזי הלבנון; מלכי רבנן"},{"i":19409,"n":"חזיזה, יצחק מדמנאת-מרוקו","dt":"תרצה","b":"רב בדמנאת-מרוקו.","s":"ארזי הלבנון"},{"i":19410,"n":"חזן אליהו בכור בן יוסף רפאל","f":"יוסף רפאל","k":"בעל זכרון ירושלים","bt":"תרה-ח","bp":"אזמיר","dt":"תרסח - כא סיון","dp":"נא אמון","b":"עלה לירושלים עם זקנו ר חיים דוד חזן בשנת תרטו, הוסמך על ידו בשנת תרכה, חתנו של ר ישעיה ברדקי, סופר ומזכיר הקהילות בירושלים ואחר כך ראש בית הדין. בשליחות בצפון אפריקה, היה בטריפולי-תרלד והסכים שם על \"מזמרת הארץ\" לר פרג'י נעים, ונענה לבקשת יהודי טריפולי לכהן שם כרב בשנים תרלה-תרמח, על מקום ר חיים אדאדי, וקיבל אישור מקושטא לכהן כ\"חכם באשי\", רב באלכסנדריה-תרמט. חיבר \"זכרון ירושלים\" ליוורנו תרלד, בשנת תרמט רב באלכסנדריה על מקום ר משה פארדו. השתתף באסיפת רבנים בקראקא בענין עלילת דם. חיבר ספרים רבים חלקים נדפסו וחלקם בכתב יד. חיבר גם \"טוב לב\", \"תעלומות לב\", ועוד. הסכים על \"אהל יצחק\" - סטמר תרסג. פרסם מאמרים ב\"הפלס\" - ברלין תרסא-תרסה.","s":"גליס; ארזי הלבנון; אוצר הרבנים 2115; מלכי חי\"ל-מרציאנו; דור וחכמיו-א\"ש-ו; אוצר כתבי עת-לוין; אהלי שם; פרומקין-תח\"י; אוצר ישראל, תולדות היהודים באפריקה להירשברג, המעל\"ש, זכל\"ה יט; היברובוקס","bk":[["תעלומות לב (רא\"ח)",""],["תעלומות לב",""],["זכרון ירושלם",""],["נוה שלום",""]]},{"i":19411,"n":"חזן אליהו שמחה","r":"ראש ישיבת תורה ודעת","bt":"1906","dt":"ה'תשמב 1982","s":"היברובוקס; מוריה קובץ סה עמוד ב","bk":[["דברי אליהו",""],["דברי אליהו - ב\"ק, ב\"מ, ב\"ב, מכות, יבמות, קידושין, פסחים, ועל הרמב\"ם",""]]},{"i":19412,"n":"חזן ישראל משה בן אליעזר","f":"אליעזר","k":"בעל כרך של רומי","bt":"תקסח","bp":"אזמיר","dt":"תרכג-ח - טבת","dp":"צידון או ביירות","b":"עלה בילדותו-בגיל 3 עם אביו לירושלים. תלמיד זקנו ר רפאל יוסף בעל \"חקרי לב\". דיין-תרב אצל ר יעקב פינצי. בשנת תרד בשליחות באפריקה ואירופה, בשליחות באיטליה-תרח וכיהן כרב ברומא, קורפו-תריב או תריז, אלכסנדריה-תריז או תריט על מקום מהר\"ש חזן. חזר לירושלים ובשנת תרכג היה בביירות ונפטר שם. חיבר \"כרך של רומי\" ליוורנו תרלו, \"נחלה לישראל\", \"שארית הנחלה\"ועוד בדפוס ובכתב יד. חתם שמו - \"המשי\"ח\".","s":"גליס; אוצר הרבנים 12276,15520; ארזי הלבנון; פרומקין-תח\"י; היברובוקס","bk":[["כרך של רומי",""],["נחלה לישראל",""],["קדושת יום טוב",""],["קנאת ציון",""],["שארית הנחלה",""]]},{"i":19413,"n":"חזן רפאל יוסף בן חיים","bt":"1741","dt":"ה'תקפ 1820","s":"היברובוקס","bk":[["חקרי לב",""],["חקרי לב חלקים",""],["מערכי לב",""]]},{"i":19414,"n":"חזן, אברהם הלוי מירושלים","f":"נחמן מטולטשין","k":"בעל חכמה ותב","bt":"תרט","dt":"תרעח - כט כסלו","b":"חתן ר נתן טאטווסקי. מחשובי חסידי ברסלב. עלה לירושלים-תרנד, חזר לאומן-תרעד. חיבר גם \"חכמה ותבונה\", \"כוכבי אור\", ועוד. תלמידו ר לוי יצחק בנדר.","s":"אלפסי; מצבת בנו בהר הזיתים, אוצרות גליון 204","bk":[["אבני\"ה ברזל - סיפורים מר' נחמן מברסלב",""],["ביאור הליקוטים - לקוטי מוהר\"ן",""],["כוכבי אור",""]]},{"i":19415,"n":"חזן, אברהם הפייטן","f":"יעקב","b":"פייטן ופיוטים ממנו במחזור קושטא.","s":"אלופי יעקב א-שיט"},{"i":19416,"n":"חזן, אברהם הרופא הקראי","f":"יעקב","b":"תלמיד ר שבתי בן מלכיאל הכהן. מגדולי חכמי הקראים. חיבר ספרים לקראים.","s":"אלופי יעקב א-שכה"},{"i":19417,"n":"חזן, אברהם יצחק מקושטא","b":"רב בקושטא-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":19418,"n":"חזן, אברהם מאלגיר","f":"ראובן","bt":"תרך","dt":"תרץ - בערך","b":"רב בתייארת-אלגיר. תשובה ממנו בענין טחינת חיטים לפסח ב\"קול צעקת הרועים\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":19419,"n":"חזן, אברהם מאלגיר וירושלים","f":"מכלוף","bp":"תייארת-אלגיר","b":"רב במרוקו, צרפת, עלה לירושלים וכיהן כרבה של משטרת ישראל.","s":"מלכי ישורון-חכמי אלגיר"},{"i":19420,"n":"חזן, אברהם מגירונדי","f":"יצחק בן משה","b":"מחכמי ספרד, פייטן ומפיוטיו במחזורי ספרד וקושטא.","s":"ארזי הלבנון; אלופי יעקב א-שכא; מלכי רבנן"},{"i":19421,"n":"חזן, אברהם מירושלים","b":"פרסם מאמרים ב\"תורה אור\" - ירושלים תשה.","s":"אוצר כתבי עת-לוין"},{"i":19422,"n":"חזן, אברהם מלובלין","k":"בעל חבורי הלקט","dt":"שעב","b":"מחכמי לובלין","s":"אוצר הרבנים 422"},{"i":19423,"n":"חזן, אברהם מספרד ושלוניקי","k":"בעל אחות קטנה?","dp":"שלוניקי","b":"תלמיד וחתן ר יוסף טאיטצק. רב בשלוניקי. בנו - ר יוסף. החזיק עם בנו בכתבי רבו וחותנו ר יוסף טאיטצק ומסרם לר יהודה טאיטצק שהדפיסם בשם \"שארית יהודה\".","s":"אוצר הרבנים 420; ארזי הלבנון; אלופי יעקב א-שך; זכרון שלוניקי; מלכי רבנן; פין-כנסת ישראל; רוזניס-תורכיה-ב; פרומקין-תח\"י"},{"i":19424,"n":"חזן, אברהם מספרד ושלוניקי","k":"בעל אחות קטנה","dt":"רצה - טז חשון","dp":"שלוניקי","b":"מחכמי אנדלוסיה בזמן הגירוש, רב בשלוניקי ומחותמי \"ההסכמות\", אבי משפחת חזן. מחבר הפיוט \"אחות קטנה\" (וי\"א שהמחבר הוא ר אברהם יצחקי או ר אברהם טאויל). נזכר בספרי חכמי דורו. בנו - ר שלמה על מקומו אחריו.","s":"אוצר הרבנים 418; ארזי הלבנון; אלופי יעקב א-שך; זכרון שלוניקי; מלכי רבנן; פין-כנסת ישראל"},{"i":19425,"n":"חזן, אברהם מפרג","dt":"שעו - ג ניסן","b":"מחכמי פרג","s":"אוצר הרבנים 419"},{"i":19426,"n":"חזן, אברהם מקרמניץ","f":"יהודה","k":"בעל חבורי לקט","b":"חיבר פירוש לנביאים בלשון אשכנז - נדפס בלובלין שנג, ופירוש לסליחות - פרג שסח.","s":"איטליה גירונדי-א נח; אלופי יעקב א-רלח"},{"i":19427,"n":"חזן, אברהם משלוניקי - הנכד","f":"שלמה","dt":"שעג - לפני","b":"משורר, רב בשלוניקי - של-שעג. חברו של ר שלמה הלוי הבחור שהביא תשובה ממנו.","s":"אוצר הרבנים 421; זכרון שלוניקי; מלכי רבנן; רוזניס-תורכיה-ג"},{"i":19428,"n":"חזן, אהרן ג'יליבי מאזמיר","f":"יוסף","dt":"תרצא - א ניסן","dp":"אזמיר","b":"משכיל, מראשי הקהלה באזמיר, הו\"ל העתון \"לה איספיראנסה\".","s":"גאון-יהודי המזרח"},{"i":19429,"n":"חזן, אליהו יצחק","k":"בעל ידי אליהו","bp":"בגדאד","b":"רב בהונג קונג-תרס\"ו, שנחאי-תר\"ף, עלה לא\"י-תר\"ץ, חיבר \"ידי אליהו\"","s":"ארזי הלבנון"},{"i":19430,"n":"חזן, אליהו מאזמיר","b":"רב באיזמיר","s":"אוצר הרבנים 2116"},{"i":19431,"n":"חזן, אליהו מליטא","b":"פרסם מאמרים ב\"היכל התורה\" - מיר-נוברדוק תרצה, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה.","s":"אוצר כתבי עת-לוין"},{"i":19432,"n":"חזן, אליהו ממונטריאול","b":"פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב, \"המתיבתא\" - נ\"י תשג, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר.","s":"אוצר כתבי עת-לוין"},{"i":19433,"n":"חזן, אליהו רחמים מאזמיר","f":"רפאל יוסף","k":"בעל ארח משפט","dt":"תר","dp":"אזמיר","b":"רב באזמיר. חיבר \"אורח משפט\" שלוניקי תריח, \"ארח מישור\", \"אבן המקח\" ועוד. תשובות ממנו מופיעות בספרו של אביו \"חקרי לב\". בניו - ר משה ישראל חזן שהיה ראבד נא אמון במצרים, ר דניאל. חתנו - ר יצחק בכר קורי, ונכדו ר יהודה בכר קורי.","s":"גליס; אוצר 2311 הרבנים, ארזי הלבנון; מצבות חכמי אזמיר בסוף ספר עניני שץ לפריימן"},{"i":19434,"n":"חזן, אליעזר מאזמיר וירושלים","f":"רפאל יוסף","k":"בעל עמודי ארזים,מראשוני בעלי התוספות","bt":"תקמו","bp":"אזמיר","dt":"תקפג - ח אב","dp":"ירושלים","b":"מקובל, עלה לא\"י-תקע\"א, חיבר \"עמודי ארזים\", הניח כתבים רבים. נספד בספר \"מראה הגדול\", וב\"תהלה לדוד\" ו\"כסא שלמה\". ?? לא באוצר ??","s":"גליס; אוצר הרבנים 2502; ארזי הלבנון; מפתח ההספדים, המעל\"ש; אוצר הרבנים 2500","bk":[["עמודי הארזים [על יראים]",""]]},{"i":19435,"n":"חזן, אליעזר ממראקש","b":"מחכמי מראקש, חתם על פס\"ד-תקט, עלה לירושלים. הניח נימוקים וליקוטי דינים - בכת\"י. בנו - ר שלמה בעל \"שלחן הזהב\".","s":"מלכי רבנן"},{"i":19436,"n":"חזן, אלעזר ממראקש","b":"רב במראקש-מרוקו, חתם-תקפז עם ר דוד צבאח, ור משה רוזיליו בעל קול מבשר.","s":"מתוך קטלוג"},{"i":19437,"n":"חזן, בן ציון מרדכי (נחום)","bt":"תרלז","bp":"בגדאד","dt":"תשיב - יב חשון","dp":"ירושלים","b":"שם המשפחה במקור נחום. תלמיד ר שמואל אברהם מג'לד, ר יוסף חיים בעל \"בן איש חי\". עלה לארץ-תרסא, תלמיד ר שאול דוויק, ר אברהם עדס, ר יום טוב ידיד הלוי. ממיסדי ישיבת \"פורת יוסף\" בשליחות ה\"בן איש חי\" ובתרומת הגביר יוסף אברהם שלום מכלכתא, השתתף בהקמת ישיבת \"שושנים לדוד\", \"מעין גנים\". הו\"ל מספרי רבו ה\"בן איש חי\".","s":"ארזי הלבנון; גאון-יהודי המזרח"},{"i":19438,"n":"חזן, בנימין","b":"מובא בספר החזיונות לר' חיים ויטאל","s":"ארזי הלבנון"},{"i":19439,"n":"חזן, ברוך משלוניקי","b":"מחכמי שלוניקי-שנות ה-ש'.","s":"רוזניס-תורכיה-ג"},{"i":19440,"n":"חזן, גרשון","f":"רפאל יוסף","dt":"תקעד","s":"ארזי הלבנון"},{"i":19441,"n":"חזן, דוד חיים מירושלים ואזמיר","f":"חיים","k":"בעל חוזה דוד","bt":"תע","bp":"ירושלים","dt":"תקח - לפני","dp":"ירושלים","b":"רב בירושלים. בשליחות באשכנז-תפה, בהיותו בהמבורג שינו תקנה בענין מכירת ספרים לכבודו. חיבר ספר \"חוזה דוד\" אמשטרדם תפד. וכן \"אגן הסהר\" שלוניקי תקי, \"קהילת בן דוד\" שלוניקי תקח. בספרו מספר כי בהגיעו לוינה נאסר בטעות שהחליפוהו באדם אחר, והקהלה עשתה רבות לשחרורו, בהיותו אסיר חיבר את ספרו על אבות וקראו \"דוד במצודה\", חזר לירושלים לפני תקי. יסד דפוס באזמיר עם ר יונה אשכנזי מקושטא, והיה גם המגיה בדפוס ובנו ר יהודה על מקומו אחריו בדפוס. החיד\"א למד בישיבתו בירושלים ומביא דברים רבים בשמו. בנו - ר חיים בן יוסף בעל \"עין יוסף\",","s":"גליס; אוצר הרבנים 4811; גאון-יהודי המזרח; ארזי הלבנון; פין-כנסת ישראל; פרומקין-תח\"י; רוזניס-תורכיה-ה; יערי ארשת א,"},{"i":19442,"n":"חזן, דוד חיים ממצרים","b":"מרבני נא אמון-תרכ\"א","s":"אוצר הרבנים 5115"},{"i":19443,"n":"חזן, דוד מירושלים","b":"ראשון לציון בירושלים","s":"אוצר הרבנים 4812"},{"i":19444,"n":"חזן, דוד שלמה מירושלים","bp":"ירושלים","dt":"תרץ - כה כסלו","dp":"ירושלים","b":"מורה בביה\"ס כי\"ח בירושלים, פעיל בועד הקהלה הספרדית.","s":"גאון-יהודי המזרח"},{"i":19445,"n":"חזן, דניאל מאזמיר","f":"אליהו רחמים","b":"מחכמי איזמיר","s":"ארזי הלבנון"},{"i":19446,"n":"חזן, חיים אריה","f":"משה מצעהלים","k":"בעל קוסמוגרפיה","bt":"1860","bp":"אמדור-פלך גרודנא","dt":"1941","dp":"וילנא","b":"מנהל החדר המתוקן \"לתורה ולתעודה\" בגרודנא. עבר לוילנא ולימד בגימנסיה של כהן. מורה למתמטיקה בגימנסיה של ד\"ר י. אפשטין. פרסם מחקרים בעברית ולועזית נגד תורת היחסות של אינשטין. נספה בשואה כשהוא עטור בטלית ותפלין.","s":"ליטא"},{"i":19447,"n":"חזן, חיים דוד מירושלים","f":"רפאל יוסף","k":"בעל יטב לב","bt":"תקנא","bp":"אזמיר","dt":"תרכא-ט - ה שבט","dp":"ירושלים","b":"אביו היה ה\"ראשון לציון\" בעל \"חקרי לב\", בשנת תקעא הלך לקושטא להדפיס את ספרו של אביו ונשאר שם שלושים שנה. בשנת תר נתמנה לרבה של אזמיר, חזר לירושלים-תרטו והתמנה ל\"ראשון לציון\"-תרכא על מקום ר נסים אבולעפיה, חיבר \"נדיב לב\" שלוניקי תרכב, \"ייטב לב\" אזמיר תרכה, \"תורת זבח\" על הלכות שחיטה, ועוד. לפי ר יעקב ספיר היה מצאצאי בעל ר אפרים בעל שער אפרים.","s":"גליס; אוצר הרבנים 6292; ברוורמן-אנשי שם; פין-כנסת ישראל; גאון-יהודי המזרח; ארזי הלבנון; פרומקין-תח\"י; פין-קריה נאמנה; תדהר י,","bk":[["נדיב לב, הראשון לציון",""]]},{"i":19448,"n":"חזן, חיים יוסף מאזמיר","f":"יוסף","b":"מרבני אזמיר-תקך. אביו של ר יוסף רפאל הראשון לציון","s":"אוצר הרבנים 6374; רוזניס-תורכיה-ה"},{"i":19449,"n":"חזן, חיים מירושלים","f":"יוסף בן אליהו","k":"בעל שנות חיים","dt":"תסה-עב","dp":"מיר (ליטא)","b":"מחכמי אזמיר, עלה לירושלים-תס, בשליחות בפולין יחד עם ר אברהם רוויגו. נפטר במהלך שליחותו השניה ברוסיה-פולין. חיבר \"שנות חיים\" ונציה תנג. אביו של ר דוד בעל \"חזה דוד\" וזקנו של בעל \"חקרי לב\".","s":"גליס; אוצר הרבנים 6000; פין-כנסת ישראל; פרומקין-תח\"י; ארזי הלבנון; רוזניס-תורכיה-ד; שא\"י"},{"i":19450,"n":"חזן, יהודה","f":"יעקב","b":"תלמיד ר מאיר מבית מאיר - ושירים ממנו בספר הלכות בדיקת הריאה לכבוד רבו.","s":"איטליה גירונדי-י לא"},{"i":19451,"n":"חזן, יהודה מאזמיר","dt":"תקי - יז סיון","dp":"אזמיר","b":"רב באזמיר-שנות ה-ת'.","s":"רוזניס-תורכיה-ה"},{"i":19452,"n":"חזן, יהודה מאזמיר","f":"דוד חיים","dt":"תקכה - ה אב","dp":"אזמיר","b":"מחכמי אזמיר. מדפיס-תקט על מקום אביו.","s":"רוזניס-תורכיה-ה"},{"i":19453,"n":"חזן, יהודה משלוניקי","f":"אברהם","dt":"רצג - ז כסלו","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"עמנואל-שלוניקי"},{"i":19454,"n":"חזן, יוסף חיים מאזמיר","dt":"תקמב - א אב","dp":"אזמיר","b":"דיין באזמיר-תקלד עם ר שלמה ן עזרא ור יצחק בילמונטי. התכתב עם ר אליקים גטניו משלוניקי. נתמנה ע\"י ר חיים דוד אבולעפיה לרב אחריו יחד עם ר רפאל יצחק די מאיו והיה מחלוקת על כך.","s":"רוזניס-תורכיה-ה"},{"i":19455,"n":"חזן, יוסף מאזמיר וירושלים","f":"אליהו","k":"בעל עין יוסף","r":"מרבני איזמיר","bt":"שעה או שפ","bp":"אזמיר או שלוניקי","dt":"תנח-ס","dp":"ירושלים","b":"מחכמי אזמיר, עלה לארץ-תן. איבד את ראייתו אך חזרה אליו בדרך נס ולזכר זה קרא לכל ספריו בשם \"עין\". מספריו \"עין יוסף\" אזמיר תלה ועוד. חתם-תנה על כתב שליחות ר משה ששפורטש הממוען לר בנימין הכהן בריגיו. עלה לירושלים-תן. אצל רוזניס - בניו - ר יוסף, ר כלב, ר חיים בעל \"שנות חיים\", ונכדו ר חיים דוד בעל \"ישרי לב\" מתלמידיו - ר אברהם ישראל זאבי בעל \"אורים גדולים\". לפי תח\"י היה מחכמי ישיבת \"יפאר ענוים\" אך הדבר לא מסתדר עם השנה).","s":"גליס; אוצר הרבנים 8309; גאון-יהודי המזרח; פין-כנסת ישראל; פרומקין-תח\"י; רוזניס-תורכיה-ד; מוריה קובץ קיא שנה כ גליונות א - ב עמודים כג - כד","bk":[["עין יהוסף - בבא קמא, בבא מציעא, ושבועות",""],["עין יוסף - דרושים וביאורים על התורה עד פ' משפטים",""]]},{"i":19456,"n":"חזן, יוסף מירושלים","k":"בעל עץ חיים","b":"רב-שנת ת\"ס (האם הוא בעל \"עין יוסף?)","s":"אוצר הרבנים 8309 א'"},{"i":19457,"n":"חזן, יוסף מירושלים","b":"מחכמי ישיבת \"יפאר ענוים\" בירושלים-שנות ה-תק'.","s":"רוזניס-תורכיה-ה"},{"i":19458,"n":"חזן, יוסף ממצרים","b":"רב במצרים-שנות ה-ת' בזמן ר מרדכי הלוי בעל \"גינת ורדים\".","s":"רוזניס-תורכיה-ד"},{"i":19459,"n":"חזן, יוסף משלוניקי","f":"אברהם","dt":"שפב - כ שבט","dp":"שלוניקי","b":"נכד ר יוסף טאיטצק. דיין בשלוניקי. החזיק בכתבי זקנו ומסרם לקרובו ר יהודה טאיטצק שהדפיסם בשם \"שארית יהודה\".","s":"זכרון שלוניקי; מלכי רבנן; רוזניס-תורכיה-ב"},{"i":19460,"n":"חזן, יוסף רפאל מאזמיר וירושלים","f":"חיים יוסף","k":"חק\"ל - בעל חקרי לב","r":"קובץ בית אהרן וישראל קו' י עמוד ז","bt":"תקא","bp":"אזמיר","dt":"תקפא - כג חשון","dp":"ירושלים","b":"תלמיד ר יצחק אלבעלי. מחכמי ישיבת ר חיים אבולעפיה באזמיר ורב באזמיר-תקן, נכדו של ר דוד חזן בעל \"חזה דוד\" ושל ר יוסף חזן. חתן הגביר ר דניאל פלאג'י - אחיו של ר חיים פלאג'י הזקן. דיין אצל ר חיים בן דוד אבולעפיה בעל \"נשמת חיים\" באזמיר, עם חבריו ר חיים שלמה ן עזרא בעל \"יד שלמה\", ר רפאל יצחק מאייו בעל \"שרשי הים\". בשנת תקעז עלה לחברון ונתקבל לראבד, בשנת תקעח התמנה ל\"ראשון לציון\" על מקום ר יעקב קוראל. בניו - ר בכור חיים שנפטר צעיר-תקנא, ר רחמים אליהו מחכמי אזמיר, ר אליעזר שעלה עם אביו לירושלים, ר גרשון שנפטר צעיר ואחיו ר אליהו חלץ לאשתו-תקעד, ר יצחק רב באזמיר וחתן דודו המלי\"ץ (=ר מרדכי הלוי), ר חיים דוד שהיה רשל\"צ בירושלים, ובן בתו החבי\"ף (ר חיים בן יעקב פלאג'י). לאחר שחלה נוסף לו השם רפאל ומאז חתם שמו יר\"ח.","s":"גליס; אוצר הרבנים 8976,17881; גאון-יהודי המזרח; ארזי הלבנון; רוזניס-תורכיה-ה; אוצר הרבנים 8976; ראה ערך חקרי לב","bk":[["חקרי לב (חק\"ל)",""],["מערכי לב (אור היר\"ח)",""],["חקרי לב",""],["חקרי לב – שו\"ת",""],["מערכי לב – דרוש",""]]},{"i":19461,"n":"חזן, יחיאל מאזמיר","b":"מדפיס באזמיר אצל ר דוד חזן-תצג.","s":"רוזניס-תורכיה-ה"},{"i":19462,"n":"חזן, יעקב אלישע מקאסטוריא","b":"רב בקאסטוריא-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":19463,"n":"חזן, יעקב מירושלים","dt":"תקסב - כט כסלו","dp":"ירושלים","b":"מחכמי ירושלים בשנת תקיח, בישיבת \"בית אברהם\" - ישיבת אברהם מיוחס. בשליחות עם ר יום טוב אלגזי בשנת תקל, בשנת תקלג חתם על כתב שליחות ר אלעזר בן שאנג'י. אחיו - ר אליעזר. (אצל פרומקין תאריך פטירתו - תקמד - ולדבריו יש חכם נוסף בשם זה והוא שפגש את החיד\"א יחד עם ר יו\"ט אלגזי ונפטר אחרי תקנב).","s":"גליס; אוצר הרבנים 9631; פרומקין-תח\"י; רוזניס-תורכיה-ה; בניהו \"ספר החידא\""},{"i":19464,"n":"חזן, יצחק","f":"רפאל יוסף","dt":"תרטו","dp":"אזמיר","b":"חתן דודו ר מרדכי הלוי - המלי\"ץ. אחיו ר רחמים אליהו בעל חקרי לב, ובן אחותו - החבי\"ף. מתורתו בספרי רבני דורו ומשפחתו. בנו - ר ראובן - חיבר דרוש שנדפס ב\"ברך את אברהם\".","s":"ארזי הלבנון"},{"i":19465,"n":"חזן, יצחק דוד","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה.","s":"אוצר כתבי עת-לוין"},{"i":19466,"n":"חזן, יצחק יוסף מלוביטש","f":"צבי הירש מפלאצק","b":"רב בביהמ\"ד בלוביטש ובעל ספריה גדולה. פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן, \"תורה מציון\" - ירושלים תרנה-תרסה. מכתביו הדפיס הנצי\"ב את הספר רנה של תורה (והקדיש לו עותק מספרו).","s":"אוצר כתבי עת-לוין"},{"i":19467,"n":"חזן, יצחק מאדריאנופול ומגניסיה","bp":"שלוניקי","b":"מחכמי אדריאנופול, רב במגניסיאה-שטו, ור משה עונקיירא על מקומו אחריו.","s":"אוצר הרבנים 10658; ארזי הלבנון; רוזניס-תורכיה-ב,ג"},{"i":19468,"n":"חזן, יצחק ממרוקו","f":"מאיר מאלמנצוריא","k":"בעל יחוה דעת","r":"רב ופוסק - רב בקזבלנקה","bt":"תרעט","bp":"אלמנצוריא-דרעא","dt":"תשן - א אייר","dp":"ירושלים","b":"נכד ר יצחק אבטן ממרוקו. תלמיד ר ידידיה טולידנו ממכנאס. רב באלמנצוריה (מחוז דרעא) על מקום אביו, ואחראי על גטין וקדושין בכל המחוז מטעם רבני מכנאש. רב באגדיר(=אגאדיר)-מרוקו-תשד, קזבלנקה-תשד, עלה לארץ-תשכז וכיהן כדיין בחיפה, ירושלים. חיבר \"כה לחי\", \"ליצחק ריח\".","s":"ארזי הלבנון; יומא דהילולא","bk":[["יחוה דעת",""],["חכמת יצחק",""],["ריח הגט (שו\"ת)",""]],"e":"תרע\"ט-תש\"נ","rb":"קזבלנקה","co":{"a":"33.533333,-7.583333","b":"30.680637,-6.383617"}},{"i":19469,"n":"חזן, יצחק משלוניקי","b":"דיין בשלוניקי-תרס.","s":"זכרון שלוניקי-191"},{"i":19470,"n":"חזן, יצחק משלוניקי","b":"מחכמי שלוניקי-שנות ה-ש'.","s":"רוזניס-תורכיה-ג"},{"i":19471,"n":"חזן, ישראל מקאשטוריאה","b":"דיין בקאשטוריאה-תע עם ר אברהם בנבנישתי ור מנחם בן חיים הכהן.","s":"רוזניס-תורכיה-ד"},{"i":19472,"n":"חזן, כלב מאזמיר","f":"יוסף","b":"תלמיד ר יוסף טרני המהרי\"ט. דיין אצל בעל \"כנסת הגדולה\".","s":"ארזי הלבנון; רוזניס-תורכיה-ד"},{"i":19473,"n":"חזן, כמוס מלוב","bt":"תרך","dt":"תרץ - בערך","b":"רב בזאוויה-לוב-תרנג עד תרעד. מתלמידיו - ר משה בלולו.","s":"מלכי חי\"ל-מרציאנו"},{"i":19474,"n":"חזן, מאיר ממרוקו","b":"רב במרוקו. אביו של ר יצחק בעל \"יחוה דעת\".","s":"ארזי הלבנון"},{"i":19475,"n":"חזן, מיכאל מסרייבו","b":"גביר בסרייבו-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":19476,"n":"חזן, מכלוף מירושלים","b":"מראשי עדת המערבים בירושלים-תרע. חתם עם ר נחמן בטיטו. בנו - ר אברהם?","s":"מתוך קטלוג"},{"i":19477,"n":"חזן, מסעוד ממרוקו","b":"מחכמי מרוקו-שנות ה-ת'.","s":"מלכי רבנן"},{"i":19478,"n":"חזן, מרדכי","b":"רב במוסלוב-תק\"פ","s":"אוצר הרבנים 13823"},{"i":19479,"n":"חזן, משה","f":"מתתיהו","b":"נזכר בכת\"י בשם הנשיא ר משה במדינת פרלס.","s":"פרומקין-תח\"י"},{"i":19480,"n":"חזן, משה מבלגרד","b":"דיין בבלגרד-תקמח, יחד עם ר חיים שלמה עמאר, ור יהודה בן חיים הכהן.","s":"רוזניס-תורכיה-ה"},{"i":19481,"n":"חזן, משה מגוריציאה","f":"יעקב חי","b":"רב בגוריציאה-תקמז.","s":"מתוך כת\"י"},{"i":19482,"n":"חזן, מתתיה ממונסטיר","b":"דיין-תקנא אצל ר שמואל קלדרון עם ר שבתי בן יהושע קמחי.","s":"רוזניס-תורכיה-ה"},{"i":19483,"n":"חזן, מתתיהו משלוניקי","b":"מחכמי שלוניקי-תקם, חתם על שטר בוררות בין בני ר יצחק מולכו וגבאי הקהל-תקם.","s":"ארזי הלבנון"},{"i":19484,"n":"חזן, נסים עזרא כצ'ורי מבבל","k":"בעל חובת הארץ","dt":"תשלב - כא אלול","dp":"ירושלים","b":"תלמיד ר שלמה לניאדו. מחכמי בבל, ביקר בירושלים-תרפז וחזר לבגדד, ועלה לירושלים-תשט, וכיהן כרב בית הכנסת אהל רחל\" בירושלים. העלה ספריה גדולה מבגדד ונידבה לישיבת \"אהבת שלום\". מצאצאי הפייטן ר עבדאללה בן כצ'יר חנין ונכדו של ר סלימאן בן עבדאללה חנין. חיבר גם \"מעשה נסים\" פירוש על \"זבחי צדק\" לר עבדאללה סומך.","s":"ארזי הלבנון"},{"i":19485,"n":"חזן, סלימאן ממכנאס","b":"מחכמי מכנאס, חתם-תקט על פס\"ד עם ר ישועה בן יוסף.","s":"מלכי רבנן"},{"i":19486,"n":"חזן, צבי הירש מפלאצק","f":"שמריל","b":"חזן בפלאצק. בנו - ר יצחק יוסף מלוביטש.","s":"מתוך קטלוג"},{"i":19487,"n":"חזן, שלום ממרוקו","dt":"תשנז - כא סיון","b":"רב באימדידנת-מרוקו, עלה לישראל וכיהן כרב במושב \"בית שקמה\", ובאשקלון.","s":"ארזי הלבנון"},{"i":19488,"n":"חזן, שלמה מאלגיר צפת ויפו","b":"רב באלגיר, עלה לארץ - תקס-תרי, והתישב בצפת. רב לעדת המערבים ביפו-תרי. (אולי בלבול עם בעל \"שלחן הזהב\").","s":"אוצר הרבנים 18442; ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":19489,"n":"חזן, שלמה ממרוקו וצפת ירושלים","f":"אליעזר","k":"בעל שלחן הזהב","bt":"תרטו-ז","bp":"מרוקו","dt":"תרמו","dp":"צידון","b":"מחכמי מראקש-מרוקו, עלה לירושלים (וי\"א בגיל שלש עם הוריו), אב\"ד ביפו עד תרלב, עבר לירושלים-תרלב וכיהן כאב\"ד, ראב\"ד בצפת. נסע להדפיס ספרו בקושטא ונפטר בדרכו. חיבר גם \"שלחן הזהב\", \"שלחן מלכים\".","s":"גליס; אוצר הרבנים 18443; גאון-יהודי המזרח; ארזי הלבנון"},{"i":19490,"n":"חזן, שלמה מספרד וצפת","f":"אברהם","k":"בעל קינה על כד אנוסי","bp":"ספרד","b":"מאנוסי ספרד, חזר ליהדות, נדד בטריפולי, צידון, חלב, רב בצפת והסכים עם המבי\"ט. נשלח ע\"י ר יעקב בירב אל הרלב\"ח בירושלים לקבל הסכמתו לחדוש הסמיכה (גם הוא וגם הרלב\"ח נחטפו כילדים בפורטוגל ע\"י הנוצרים וחזרו ליהדות), ונזכר בשו\"ת הרלב\"ח. חיבר קינה על כ\"ד אנוסים שנהרגו עק\"ה בפיזרו - שטז.","s":"גליס; אוצר הרבנים 18439; גאון-יהודי המזרח; ארזי הלבנון; רוזניס-תורכיה-ב; פרומקין-תח\"י"},{"i":19491,"n":"חזן, שלמה מצפת","f":"דוד","b":"מחכמי ירושלים. בשליחות-תקלז קהלת צפת באיטליה עד שנת תקמד.","s":"רוזניס-תורכיה-ה"},{"i":19492,"n":"חזן, שלמה משלוניקי","f":"אברהם","dt":"שלא - כז תשרי","dp":"שלוניקי","b":"שתדלן ורב בק\"ק סיציליה בשלוניקי-של על מקום אביו. נספד ע\"י ר סעדיה לונגו, ור משה אלמושנינו. מבניו: ר אברהם.","s":"אוצר הרבנים 18440; ארזי הלבנון; זכרון שלוניקי; מלכי רבנן; רוזניס-תורכיה-ג"},{"i":19493,"n":"חזן, שמואל מאזמיר","b":"מגדולי רבני אזמיר","s":"אוצר הרבנים 19179"},{"i":19494,"n":"חזן, שמואל מאלגיר","bt":"של","dt":"ת - בערך","b":"מחכמי אלגיר ונזכר בשו\"ת ר שלמה צרור.","s":"מלכי ישורון-חכמי אלגיר"},{"i":19495,"n":"חזן, שמואל מטריפולי","f":"שלמה","bt":"שף","dt":"תס - בערך","b":"רב ודיין בטריפולי. חתם על תעודה בענין אברהם קרדוזו החשוד בשבתאות.","s":"מלכי חי\"ל-מרציאנו"},{"i":19496,"n":"חזנוביץ, דוד מברנוביץ","dt":"תשג","b":"מרביץ תורה בברנוביץ","s":"אוצר הרבנים 4813"},{"i":19497,"n":"חזנוביץ, יהודה ליב מוילנא","dt":"תרסו","b":"מו\"צ בווילנה","s":"אוצר הרבנים 7275"},{"i":19498,"n":"חזנוביץ, יוסף","bt":"1844","bp":"גוניונדז-ליטא","dt":"1919","dp":"יקטרינוסלב","b":"מיסד הספריה הלאומית בירושלים. רופא, חובב ציון וחבר ב\"בני משה\". ביקר בארץ-1890 עם ר שמואל מוהליבר והחל לאסוף ספרים עבור הספריה הלאומית. שלח 10,000 ספרים לירושלים-1896 שנמסרו לספרית \"מדרש אברבנל\" שהפכה בהמשך לספריה הלאומית.","s":"ליטא"},{"i":19499,"n":"חזנוביץ, ליאון (כתריאל שו\"ב)","k":"בעל החורבן היהודי","bt":"1882","bp":"שירווינט","dt":"1925","dp":"וולחוביצי-צ'כיה","b":"פעיל ב\"חובבי ציון\", נאסר ועבר לגליציה. עורך ה\"אידישער ארבייטער\" בקראקא, ולבוב. היגר לארגנטינה-1909 וערך שם את \"ברויט און עהרע\" ומתח ביקורת על שיטת ההתישבות של יק\"א. גורש ע\"י השלטונות עבר לקנדה ולוינה, בזמן מלחה\"ע ה-I עבר להאג ויסד את \"אידישע ארבייטער קארבעספאנדענץ\", עבר ללונדון, ארה\"ב וערך את \"די צייט\". חיבר ספרים בגרמנית ובהם על הפרעות ביהודי פולין-1918. ובאידיש.","s":"ליטא"},{"i":19500,"n":"חזק, ברוך","k":"בעל סדרי עבור שנים","b":"מגדולי רבני מצרים","s":"אוצר הרבנים 4088"},{"i":19501,"n":"חזק, יעקב ישראל מפדובה","f":"אברהם","b":"מחכמי פדובה, מבני החבורה של הרמח\"ל.","s":"פרומקין-תח\"י"},{"i":19502,"n":"חזק, יעקב רפאל חזקיה","bt":"תמט","dt":"תקמב - טו אב","dp":"פדובה","b":"רב ודיין בפדובה-תקמ אחרי ר ישעיה בסאן ור ישעיהו רומאנין. תלמיד ר מרדכי באסן מוירונה, ותלמיד הרמח\"ל בפדובה. מתלמידיו בפדובה - ר שבתי אהרן חיים מדיני, ר עזריאל אלאטינו, ר יהודה טודרוס, ור מאיר טריאסטי. חיבר ספר כללים על הש\"ס, תשובות והגהות. היה חברו של ר אברהם שמו (הרא\"ש) בעל \"זרע אברהם\", והחיד\"א העריכו מאוד וביקשו שיברכנו.","s":"איטליה גירונדי-י לה; אוצר הרבנים 9632,17871; פין-כנסת ישראל"},{"i":19503,"n":"חזק, שמואל יהודה מטריקאלה","b":"רב בטריקאלה-שצג.","s":"רוזניס-תורכיה-ג"},{"i":19504,"n":"חז\"ק-פאסיג, אברהם יצחק מזלוטשו","b":"רב ורופא מומחה,רב בזלאטשוב-תפ\"ד,פרנס ועד דד\"א,ביאברוב","s":"אוצר הרבנים 1221"},{"i":19505,"n":"חזקוני, אברהם מקראקא","f":"חזקיהו","k":"בעל זאת חוקת התורה","bt":"שפז","b":"רב ומקובל בקראקא. תלמיד התוי\"ט, ר ארנ\"ן פואה, והרמ\"ז נב\"ת. חיבר \"זאת חוקת התורה\", \"שתי ידות\" אמשטרדם, \"זרע יעקב\". בנו ר יעקב הדפיס ספרי אביו.","s":"איטליה גירונדי-א א; אוצר הרבנים 423; פין-כנסת ישראל"},{"i":19506,"n":"חזקיה","b":"רב בשורה-קווקז-תר\"נ","s":"אוצר הרבנים 5800"},{"i":19507,"n":"חזקיה אברהם הכהן מירושלים","dt":"תקצג - יד סיון","dp":"ירושלים","b":"נכדו של ר יצחק הכהן רפפורט בעל \"בתי כהונה\". דיין בירושלים אצל הר\"ש סוזין, וחתום אתו על שטר-תקפו, חתם על כתבי שליחות בשנים תקפט ותקץ.","s":"גליס; אוצר הרבנים 5811; פרומקין-תח\"י; ארזי הלבנון; ירושלים לזכר לונץ, זכלה יא, שא\"י"},{"i":19508,"n":"חזקיה אברהם הלוי","f":"אברהם מקושטא","b":"אביו היה החכם באשי הראשון בקושטא. (ואולי הוא שמו של ר אברהם הלוי עצמו ולא של בנו)","s":"רוזניס-תורכיה-ו"},{"i":19509,"n":"חזקיה אברהם הלוי מקושטא"},{"i":19510,"n":"חזקיה אברהם מאלכסנדריה","f":"שלמה אליעזר","b":"דיין באלכסנדריה אצל ר נתן עמרם. חתם-תרכז עם ר יעקב יוסף תורגמן.","s":"מתוך קטלוג"},{"i":19511,"n":"חזקיה דבאזלה","b":"בשליחות צפת וירושלים בצרפת-תנט. (אולי היה מירושלים ואולי מצרפת).","s":"פרומקין-תח\"י"},{"i":19512,"n":"חזקיה רפאל הכהן מקושטא","b":"דיין בקושטא, וממונה על איסור והיתר, חתם-תקצד על בקשת עזרה עבור קהלת איזנימיט עם ר חיים משה פריסקו ור אליעזר די טולידו.","s":"מתוך קטלוג"},{"i":19513,"n":"חזקיה רפאל יוסף הכהן","b":"דיין בח'אסקוי(טורקיה)-תקס\"ו","s":"ארזי הלבנון"},{"i":19514,"n":"חזקיה שם טוב משלוניקי","b":"דיין בשלוניקי-תרג.","s":"זכרון שלוניקי-140"},{"i":19515,"n":"חזקיה שמואל משה הלוי מאיטליה","b":"רב בפוסאנו-פיימונטי-איטליה. נספד בדרך שיר - בכת\"י.","s":"מתוך קטלוג"},{"i":19516,"n":"חזקיטו, ברוך עוזיאל מפיררה","k":"הו\"ל מעיני הישועה","b":"מחכמי איטליה, רב בפיררה-שטו, חי בזמן מהר\"ם פאדובא. הו\"ל \"מעיני הישועה\" לר\"י אברבנל עם תולדות חייו כפי ששמעם מבנו - ר יוסף אברבנל מפיררה.","s":"אוצר הרבנים 4232; ארזי הלבנון; פין-כנסת ישראל"},{"i":19517,"n":"חזקיטו, יהודה ממצרים","b":"רב במצרים-רפז ולפי רוזניס בשנות ה-ת'.","s":"אוצר הרבנים 6932; רוזניס-תורכיה-ד"},{"i":19518,"n":"חטאב, יוסף","b":"פרסם מאמרים ב\"הירח\" - ג'רבה תשח.","s":"אוצר כתבי עת-לוין"},{"i":19519,"n":"חטאב, מעתוק מג'רבה","f":"כליפא","k":"בעל אורה ושמחה","bp":"ג'רבא","dt":"תרפו - יח כסלו","b":"תלמיד ר דוד גינשא. רב בכפר גרדאן. חיבר גם \"ששון ויקר\" ו\"שמחה וששון\" בכת\"י.","s":"ארזי הלבנון"},{"i":19520,"n":"חטובסקי, יואל מרמיגולה","f":"ישראל עוזר","bt":"תרכא","b":"תלמיד ישיבת וולוזין, ר יצחק אלחנן בקובנא. רב ברעמיגלא(=רמיגולא)-פלך קובנא-תרנא. נסמך מאת: ר יצחק אלחנן, הנצי\"ב, ר יוסף רוזין מסלונים, ר רפאל שפירא מוולוזין.","s":"אוצר הרבנים 7836; ליטא; אהלי שם"},{"i":19521,"n":"חטים - חוטים - משפחה וקהלה","b":"משפחה שמוצאה בעיר חוצים(=הוצים) שעל נהר הדניסטר.","s":"רוזניס-תורכיה-ה"},{"i":19522,"n":"חטר","f":"שלמה","b":"מחכמי תימן,רב בדמאר בתקופת ר' זכריה הרופא,עסק במחשבה ופילוסופיה,חיבר סראג' אלעקול\"-נר השכלים וכן ספרי שו\"ת","s":"ארזי הלבנון"},{"i":19523,"n":"חי, יצחק משה","b":"מגדולי חכמי איטליה,מרביץ תורה בפירארו-תק\"כ","s":"אוצר הרבנים 11446"},{"i":19524,"n":"חיאל, אליעזר","b":"דומ\"צ ברימאנוב","s":"אוצר הרבנים 2503"},{"i":19525,"n":"חיאל, יצחק נפתלי מרימנוב","f":"מרדכי","bt":"תר","dt":"תרעה","b":"רב ברימנוב-תרע על מקום אביו.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 11459"},{"i":19526,"n":"חיאל, מרדכי","f":"אליעזר חיאל","b":"דומ\"צ ברומאנוב-תר\"ל","s":"אוצר הרבנים 14190"},{"i":19527,"n":"חידאירי, שלמה מתורכיה","b":"מחכמי תורכיה בזמן מהר\"ם פאודבה.","s":"ארזי הלבנון"},{"i":19528,"n":"חיוג, אברהם","b":"נזכר ב\"מנחת שי\" ספר שחיבר (על המסורה?).","s":"אלופי יעקב א-רסב"},{"i":19529,"n":"חיוג, אפרים","k":"בעל מקרא קדש","b":"רב-שנת תק\"ס","s":"אוצר הרבנים 3029"},{"i":19530,"n":"חיוואן, שלמה מקושטא","f":"אברהם מפורטוגל","k":"בעל יריעות שלמה","b":"רב בקושטא-שכ, בן למשפחה ממגורשי פורטוגל.","s":"ארזי הלבנון"},{"i":19531,"n":"חיון, אברהם מירושלים","k":"בעל הגהות שלמי צבור","bp":"בוסניה","dt":"תקס-ח - יב טבת","dp":"אזמיר","b":"עלה לירושלים תקיח, מראשי ישיבת \"דמשק אליעזר\", השיג על החיד\"א שענה לו בספרו. בשנת תקל יצא לשנתיים בשליחות, בשליחות קהילת ירושלים בשלוניקי-תקן, בשליחות חברון-תקנח. הגיה והדפיס ספר \"שלמי צבור\" דיני תפלה לר ישראל אלגזי עם הערות בשם \"שלמי חגיגה\". חיבר ספר \"תורת השלמים\" (נדפס ב\"לדוד אמת\" לר ישראל יעקב אלגזי ליוורנו תקנו). חיבר גם \"קשר גורל\" ובו מוכיח כי ר יוסף קארו לא חיבר את הספר המיוחס לו \"מגיד מישרים\".","s":"גליס; אוצר הרבנים 426; פרומקין-תח\"י; ארזי הלבנון; רוזניס-תורכיה-ו; אור השמש, יהב\"י, אוסף אלישר,   הספידו ר חיים אברהם אישטרומשה בספרו \"בן אברהם\" וכן ר רפאל יוסף חזן (\"מערכי לב\" דרוש פ\"ט).","bk":[["תורת השלמים",""]]},{"i":19532,"n":"חיון, אברהם מירושלים","f":"שלמה","b":"מחכמי ירושלים-שסח, מצאצאי ר יוסף חיון מחבר \"מילי דאבות\", הדפיס את ספר זקנו בונציה שס. סבו ר משה היה רבה האחרון של ליסבון. עלה לירושלים בשנת שה.","s":"גליס; אוצר הרבנים 425; אלופי יעקב א-קכה; פרומקין-תח\"י; הקדמת הספר \"מלי דאבות\"."},{"i":19533,"n":"חיון, אברהם מפורטוגל וקושטא","f":"נסים (משה)","k":"בעל אמרות טהורות","b":"תלמיד קרובו ר יוסף דון בעל \"מילי דאבות\". מחכמי ליסבון, לאחר הגירוש רב בקושטא-רנז, חיבר \"אמרות טהורות\".","s":"אוצר הרבנים 424; ארזי הלבנון; אלופי יעקב א-קסט; פין-כנסת ישראל"},{"i":19534,"n":"חיון, אליהו מתורכיה","b":"מחכמי תורכיה-תקסו. פגש את ר מרדכי סוזין, מביא מתורת המלי\"ץ. חיבר \"פנקס הכללים\" בכת\"י.","s":"מתוך קטלוג"},{"i":19535,"n":"חיון, גדליה מאדרינופול","b":"רב בקהלת פורטוגזים באדרינופול-שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":19536,"n":"חיון, גדליה מירושלים","k":"בעל מדרש תלפיות?","bt":"תמג (באו' תן)","bp":"קושטא","dt":"תקי-א - ה אב","dp":"ירושלים","b":"תלמיד ר חיים אלפנדרי, נשא ונתן עם ר יהודה רוזניס, מקובל, עלה לירושלים, בשליחות קהילת חברון בתורכיה, יסד את בית המדרש המקובלים \"בית אל\" בירושלים. חתום על תקנות והסכמות עם גדולי ירושלים וביחוד עם ר יצחק רפפורט בעל \"בתי כהונה\" ור משה מזרחי בעל \"אדמת קודש\". הסכים על ספר זה ועל הספר \"פרי האדמה\" בשנת תקז, והתמנה ל\"ראשון לציון\" בשנת תקז. נספד בספר \"קידש ידיד\" ובספר \"קול יעקב\" לר יעקב שאול. הסכים על \"פרי האדמה\"-תקז, \"ראשון לציון\"-תקז.","s":"גליס; אוצר הרבנים 4333; גאון-יהודי המזרח; ארזי הלבנון; רוזניס-תורכיה-ה; ירושלים א,"},{"i":19537,"n":"חיון, גדליה משלוניקי - קושטא","dt":"שכט - אחרי","b":"חתן מהרשד\"ם? רב בשלוניקי-של, קושטא?. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא.","s":"זכרון שלוניקי; רוזניס-תורכיה-ב"},{"i":19538,"n":"חיון, דוד מאלגיר - א","bt":"שי","dt":"שפ - בערך","b":"רב באלגיר. נזכר בשו\"ת שלמה צרור.","s":"מלכי ישורון-חכמי אלגיר"},{"i":19539,"n":"חיון, דוד מאלגיר - ב","b":"רב בתייארת-תרפה. שאלה ממנו לר רפאל אנקאווא ונזכר ב\"תועפות ראם\".","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":19540,"n":"חיון, זבולון מטריפולי","f":"שבתי","bt":"תקך","dt":"תקף - בערך","b":"רב בטריפולי. נזכר בפנקס בי\"ד טריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":19541,"n":"חיון, חייא (הארוך) מסרייבו","b":"חתן ר שמואל אלמולי. מחכמי סרייבו-תמח, פעל לגרש את החכם צבי מסרייבו אולי יהודי העיר דאגו להשאיר את החכם צבי כרבם. לאחר מיכן כיהן כדיין אצל ר יצחק צבי אשכנזי. קרובו של נחמיה חייא חיון (ויש שהחליפו ביניהם).","s":"רוזניס-תורכיה-ד"},{"i":19542,"n":"חיון, חיים משה מצפת","f":"עובדיה אהרן מירושלים","dp":"צפת","b":"בשנת תנט בשליחות ירושלים בשלוניקי, בשנת תסד חתם על כתב שליחות של ר אברהם רויגו ור חיים חזן. בשנת תעג חתם על מכתב לר יצחק למפרונטי מטעם קהילת צפת, היה חברו של ר אברהם יצחקי, וחתנו של מוהר\"י חגיז. מתשובותיו בספרי חכמי דורו ובהם \"זרע אברהם\", \"גינת ורדים\" ו\"מטה יוסף\". בסוף ימיו רב בצפת. בשנת תסה התמנה \"ראשון לציון\" לאחר פטירת ר משה בן חביב.","s":"גליס; ארזי הלבנון; רוזניס-תורכיה-ד; שא\"י, בן צבי מחקרים, ספר צפת מאמר סימונסון ובן צבי."},{"i":19543,"n":"חיון, יוסף מאלגיר","f":"משה","bt":"תק - בערך","dt":"תקע - בערך","b":"רב ומשורר באלגיר. פיוט ממנו ב\"רינה וישועה\", וחיבר גם קינות לתשעה באב.","s":"מלכי ישורון-חכמי אלגיר"},{"i":19544,"n":"חיון, יוסף מפורטוגל","f":"אברהם בן נסים","k":"בעל מילי דאבות","dt":"רנו-רע","dp":"קושטא","b":"רב בליסבון-פורטוגל, יצא לקושטא לפני הגירוש. חיבר פירוש לאבות - ונציה - ובסוף תולדות המחבר מאת נכדו ר אברהם חיון. תלמידו - ר יוסף יעקב - כתב עליו בספרו \"אור החיים\". תשובות ממנו לרבים מחכמי דורו. בנו - ר משה מליסבון.","s":"איטליה גירונדי-י קנז; אוצר הרבנים 8311; פין-כנסת ישראל; פרומקין-תח\"י"},{"i":19545,"n":"חיון, יעקב מאלגיר","bt":"תרסד","bp":"למדייא","b":"רב בסעידא-אלגיר. עורך ומגיה ספר \"מכשירי מילה\" - ליוורנו תרפט.","s":"מלכי ישורון-חכמי אלגיר"},{"i":19546,"n":"חיון, יעקב מצפת","b":"בשליחות-תרלז קהלת צפת בארצות ערב והודו.","s":"מתוך קטלוג; יערי"},{"i":19547,"n":"חיון, יצחק בעל הנס מפורטוגל","b":"רב בפורטוגל לפני הגירוש. היה חסיד ופועל ישועות בזמן עצירת גשמים יחד עם חבירו - ר יצחק אבוהב.","s":"אוצר הרבנים 10661; גאון-יהודי המזרח; ארזי הלבנון"},{"i":19548,"n":"חיון, יצחק משלוניקי","b":"מחכמי שלוניקי. חתן מהרשד\"ם, ואביו של ר שמואל בעל \"בני שמואל\". נפטר צעיר.","s":"זכרון שלוניקי"},{"i":19549,"n":"חיון, מאיר משלוניקי","b":"רב ודיין בשלוניקי-שן.","s":"זכרון שלוניקי; רוזניס-תורכיה-ג"},{"i":19550,"n":"חיון, מימון","b":"נזכר באוצר המכתבים.","s":"ארזי הלבנון"},{"i":19551,"n":"חיון, מסעוד מטריפולי","bt":"תקי","dt":"תקף - בערך","b":"שו\"ב בטריפולי, ומספרים כי החיד\"א רצה לפוסלו על שבודק את הסכין בראיה - עד שפגשו וקיבל את הסכמת החיד\"א (נזכר ב\"לקדושים אשר בארץ\").","s":"מלכי חי\"ל-מרציאנו"},{"i":19552,"n":"חיון, מסעוד מטריפולי - הזקן","b":"ספרא דדיינא בטריפולי. חתם בפנקס בי\"ד בטריפולי.","s":"מלכי חי\"ל-מרציאנו"},{"i":19553,"n":"חיון, משה מאלגיר","bt":"שך - בערך","dt":"ת - בערך","b":"תלמיד ישיבת אלגיר אצל ר שלמה דוראן - המכנהו \"לנבון וחכם תלמידנו\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":19554,"n":"חיון, משה מירושלים","f":"אהרן עובדיה מירושלים","b":"חתן ר ישראל יעקב חגיז, וגיסו של ר משה. מתשובותיו ב\"זרע אברהם\" ו\"גנת ורדים\". רב בירושלים, צפת. בשליחות ירושלים-תנט.","s":"אוצר הרבנים 14696; גאון-יהודי המזרח; ארזי הלבנון; פרומקין-תח\"י; רוזניס-תורכיה-ה"},{"i":19555,"n":"חיון, משה מליסבון","f":"יוסף","b":"רבה האחרון של ליסבון לפני הגירוש, בנו ר אברהם.","s":"אוצר הרבנים 14695; ארזי הלבנון"},{"i":19556,"n":"חיון, משה ממראקש","f":"מוסא","b":"מחכמי מראקש.","s":"מלכי רבנן"},{"i":19557,"n":"חיון, משה מצפת","b":"רב בצפת-תע בערך, דיינים אצלו ר יוסף ביבאס, ר יצחק נחמיאש.","s":"רוזניס-תורכיה-ה"},{"i":19558,"n":"חיון, משה מתורכיה","f":"אליהו","b":"נכד ר משה יום טוב. מחכמי תורכיה אחרי תקף. חברו של ר נסים מדיני. הניח חבור בכת\"י.","s":"מתוך קטלוג"},{"i":19559,"n":"חיון, נחמיה חייא מסרייבו","f":"משה","k":"בעל דברי נחמיה","bt":"תי - בערך","bp":"סרייבו","dt":"תץ","dp":"תונס","b":"עלה לצפת עם הוריו ולמד בישיבות המקובלים בצפת ובחברון, חזר לסרייבו ונטה לשבתאות., עבר לבלגרד-תמג, אוילונה ונלקח בשבי במלחמה עם ונציה ונפדה, עבר לשלוניק והתחבר לדונמא, רב באישקופיה, עבר לליוורנו, התישב בשכם עם משפחתו-תנח, עבר לאזמיר-תסב וניסה להדפיס שם את ספרו \"עז לאלקים\". חתן ר יוסף ביבאס. בשליחות במצרים והפך לתומך בש\"ץ, והיה מחלוקת כנגדו ואף חרם, והוא חיבר ספרים כנגד כדי להצדיק עצמו. החרם הוסר בקושטא-תפח בהוראת הוזיר שהתערב בהשפעת הגביר רפאל מאנילה שתמך בחיון. ישב בירושלים וגורש משם-תסט, עבר למצרים, ליוורנו וניסה להדפיס את ספרו \"מהמנותא דכלא\", עבר לונציה והדפיס את ספרו \"רזא דיהודא\"-תעא, הגיע לפרג וישב שם כשנה וחיבר את \"דברי נחמיא\", הדפיסו בברלין-תעב, עבר לאמשטרדם ונתמך בידי חכמי הספרדים ובראשם ר שלמה אאיליון, אולם חכמי האשכנזים יצאו נגדו והחרימוהו, ונגרמה מחלוקת בקהלה על כך, עבר לקושטא ושלוניקי וניסה להתיר את החרם במשך כ-3 שנים, התקרב לגביר אברהם סאמאנון והגביר רפאל מאנילה שפעלו לטובתו אצל הוזיר שאילץ את רבני קושטא (ר יהודה רוזניס, ר שמואל הלוי ור יוסף בן ישעיה טרני) להתיר את החרם. עבר לוינה, התחתן עם נוצריה במורביה ועבר עמה לאמשטרדם והדפיס את \"הקולות יחדלון\" אך הסתכסך עם תומכו ר שלמה אאיליון, ועבר לברלין, פרג (שם ריחמו עליו אשת ר יונתן איבשיץ ודאגו למזונותיו), עבר לצפון אפריקה ומת שם. קרובו של ר חייא חיון מסרייבו. נינו המיר את דתו-תצג.","s":"גאון-יהודי המזרח; רוזניס-תורכיה-ד"},{"i":19560,"n":"חיון, נסים עזרא מירושלים","b":"מחכמי ירושלים-תרלה, ועסקן ציבור. החזיק בכתה\"י \"שיטה מקובצת\" יחד עם חברו ר יצחק מפרג.","s":"אוצר הרבנים 16062; גאון-יהודי המזרח; ארזי הלבנון"},{"i":19561,"n":"חיון, עובדיה אהרן מתונס וירוש","f":"אברהם (דוד?)","k":"בעל מחנה אהרן","bt":"תמו","bp":"תונס","b":"מחכמי תונס, עלה לירושלים-תמו (באוצר תכ), דיין אצל ר משה גלנטי-המג\"ן. חתם עם חכמי העיר בשנים תמז - תנה. חיבר \"מחנה אהרן\" ליוורנו תקנה. חיבר פירוש על הזהר בשם \"דרכי נעם\". בנו ר משה חיון שהיה חתנו ר יעקב חגיז. ראב\"ד בצפת-תסה.","s":"גליס; אוצר 16548,1566; גאון-יהודי המזרח; ארזי הלבנון; פרומקין-תח\"י; רוזניס-תורכיה-ד,ה"},{"i":19562,"n":"חיון, עובדיה ממונסטיר","b":"רב במונאסטיר-שנות ה-תק', עם ר יצחק פיסו ור שבתי קמחי.","s":"רוזניס-תורכיה-ה"},{"i":19563,"n":"חיון, עזרא מסרייבו","b":"מחכמי סרייבו (=שאריי בוסניה), בזמן ר מצליח מאג'אנון.","s":"ארזי הלבנון; רוזניס-תורכיה-ג"},{"i":19564,"n":"חיון, שבתי מטריפולי","bt":"תף","dt":"תקן - בערך","b":"רב בטריפולי. מתלמידיו - ר אברהם כלפון המזכירו ב\"מעשה צדיקים\" - בכת\"י.","s":"מלכי חי\"ל-מרציאנו"},{"i":19565,"n":"חיון, שלמה ממרוקו","dt":"תאפיללת-מרוקו","b":"תלמיד ר יעקב אביחצירה, וחברו של בנו ר מסעוד. חתם עם ר יעקב בן מסעוד-תקיח. שלח פס\"ד לר ידידיה מונסונייגו שהסכים עמו.","s":"ארזי הלבנון; מלכי רבנן"},{"i":19566,"n":"חיון, שלמה מקושטא","f":"אברהם חיון","b":"מגדולי חכמי קושטא-ש\"כ","s":"אוצר הרבנים 18445"},{"i":19567,"n":"חיון, שלמה מתונס","b":"מחכמי תונס-תרלח, ונזכר ב\"משפט הירושה\".","s":"ארזי הלבנון"},{"i":19568,"n":"חיות - משפחה","b":"לפי המסורת נטלו אבות המשפחה אבנים מבית הכנסת שלהם במרסיל שבצרפת והשקיעום בביכ\"נ אלטנוי בפרג. ולכן נקראו אלטשולר","s":"וונדר-גליציה ח\"ו"},{"i":19569,"n":"חיות יצחק בן אברהם","bt":"1538","dt":"ה'שע 1610","s":"היברובוקס","bk":[["דרשה לליל שמורים",""],["פחד יצחק",""],["פני יצחק",""],["שיח יצחק",""]]},{"i":19570,"n":"חיות יצחק בן יעקב","bt":"1640","dt":"ה'תפו 1726","s":"היברובוקס","bk":[["זרע יצחק",""]]},{"i":19571,"n":"חיות, אברהם","b":"שנת ת\"י","s":"אוצר הרבנים 427"},{"i":19572,"n":"חיות, אברהם","f":"יצחק חיות","k":"בעל הולך תמים","b":"שנת שצ\"ד","s":"אוצר הרבנים 429; פין-כנסת ישראל"},{"i":19573,"n":"חיות, אברהם מפרובאנס","b":"רב בפרובאנס-שי. בנו ר יצחק בעל \"פני יצחק\", ר שמואל שיננא שנפטר בחיי אביו.","s":"אוצר הרבנים 428; %"},{"i":19574,"n":"חיות, אהרן","b":"פרסם מאמר ב\"שילה\" - ירושלים תשה - אודות ר שמואל סלנט.","s":"אוצר כתבי עת-לוין"},{"i":19575,"n":"חיות, אליעזר חיים","f":"יצחק","b":"חתנו ר יעקב הורביץ. ונכדו ר ישעיה מאיטליה בעל \"בית הלוי\". לפי \"עיר וילנא\" היה בנו של בעל \"פני יצחק\" ולפי אוצר הרבנים ר יצחק בן אליעזר.","s":"אוצר הרבנים 2653"},{"i":19576,"n":"חיות, אליעזר מנימרוב וברודי","f":"יצחק","dt":"תקכז","b":"חתן ר מרדכי סגל מקוצק. רב בנמירוב, פשוורסק, שטערוויץ, ברודי.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 2506"},{"i":19577,"n":"חיות, אליעזר מקראקא - א","f":"יצחק חיות","dt":"שפג - כז סיון","b":"מגדולי חכמי קרקא","s":"אוצר הרבנים 2505"},{"i":19578,"n":"חיות, אלעזר (ריינס)","b":"מצאצאי מהריץ חיות. חתנו - ר מרדכי שלמה אולמן מבריסל.","s":"החת\"ס ותלמידיו"},{"i":19579,"n":"חיות, אפרים מלייפניק","f":"אברהם","k":"בעל אשל אברהם","b":"חתן ר יצחק כהנא רפפורט למילפניק. רב בליפניק, יצא בשליחות עצמו-תקעז לאיטליה תוניס וצרפת למען הדפסת חיבוריו. חיבר \"אשל אברהם\" ליוורנו תקעט, ועוד. עלה לירושלים-תקפב, עבר לקושטא-תקפז.","s":"וונדר-גליציה ח\"ג; פין-כנסת ישראל"},{"i":19580,"n":"חיות, אריה ליב מסאנוק","f":"ברוך","bt":"תרלד","b":"רב בסאנוק-תרסה.","s":"וונדר-גליציה ח\"ב; אוצר הרבנים 3300; אהלי שם"},{"i":19581,"n":"חיות, אשר שמחה מזאלין","b":"רבה של זאלין.","s":"וונדר-גליציה ח\"ב"},{"i":19582,"n":"חיות, בנימין זאב וולף מוארפלט","bt":"תקכח","dt":"תרז - כב חשון","b":"תלמיד החת\"ס, ור לוי פולק מטריטש. רב בשטמפען, לאקנבך, וארפלאטה-תקע, חתנו - ר משה גולד על מקומו שם.","s":"אוצר הרבנים 3831; החת\"ס ותלמידיו"},{"i":19583,"n":"חיות, בריש מבריסק","k":"ארבע חיות - כינויו","b":"מגדולי חכמי בריסק. אחיו: ר ליבוש מבארקי, ר הירש, ור וולף - ונקראו לגודל צדקתם \"ארבע החיות\" (שמותיהם היו שמות חיות - הירש-צבי, ליבוש-אריה, בעריש-דב, וולף-זאב).","s":"אוצר הרבנים 3978; הגדול ממינסק"},{"i":19584,"n":"חיות, גרשון מניקלשבורג","dt":"תקמט - טו אדר","dp":"ניקלשבורג","b":"מקובל, איש מופת, רב בהוציפלץ(=האציפלאץ), מטרסדורף, רב המדינה בניקלשבורג-תקלט.","s":"אוצר הרבנים 4410; פין-כנסת ישראל"},{"i":19585,"n":"חיות, וולף מבריסק","k":"ארבע חיות - כינויו","b":"מגדולי חכמי בריסק. אחיו: ר ליבוש חיות מבארקי, ר בריש, ור הירש - ונקראו לגודל צדקתם \"ארבע החיות\" (שמותיהם היו שמות חיות - הירש-צבי, ליבוש-אריה, בעריש-דב, וולף-זאב).","s":"אוצר הרבנים 5386; הגדול ממינסק"},{"i":19586,"n":"חיות, חיים מלבוב","f":"צבי הירש מזולקווא","b":"חתן ר ישעיה ליב הורביץ. מחכמי לבוב.","s":"מצבות קדש-לבוב"},{"i":19587,"n":"חיות, יהודה ליב מפרוסטיץ","b":"מרביץ תורה בפרוסטיץ-שס\"ג","s":"אוצר הרבנים 7276"},{"i":19588,"n":"חיות, יואל מלמברג","f":"ד\"ר יוסף","bt":"תרע","bp":"למברג","dt":"תשמה","dp":"דטרויט","b":"חזן ומלחין. עלה לארץ-תרצג, עבר לארה\"ב-תרצח. נשיא האגודה למוסיקה יהודית - צופר.","s":"וונדר-גליציה ח\"ו"},{"i":19589,"n":"חיות, יוסף מלבוב","f":"אברהם","k":"בעל בן פורת יוסף","dt":"תמה - י אדר","dp":"לבוב","b":"דרשן, ראב\"ד בלבוב. חתם-תלה עם ר יהודה אברהם הלוי.","s":"אוצר הרבנים 8312; מצבות קדש-לבוב; בובר-לבוב"},{"i":19590,"n":"חיות, יעקב","f":"מנחם מאניש מפרג","b":"רב-שנת ת\"כ","s":"אוצר הרבנים 9633"},{"i":19591,"n":"חיות, יעקב","f":"מנחם מאניש מוילנא","b":"נכד בעל \"פני יצחק\". בנו ר יצחק בעל \"זרע יצחק\". אודותיו ב\"אגרת קץ חי\" דרוהוביטש תרמו.","s":"ליטא"},{"i":19592,"n":"חיות, יעקב יצחק","f":"אליעזר חיות","b":"רב-שנת ת\"י","s":"אוצר הרבנים 10162"},{"i":19593,"n":"חיות, יעקב קופל מברודי","f":"יצחק חיות","dt":"תקמב - ז סיון","b":"מקובל,רב בבראדי","s":"אוצר הרבנים 10301"},{"i":19594,"n":"חיות, יצחק","f":"אליעזר חיות","b":"מקובל,פרנס דד\"א-תק\"נ,עלה לא\"י. בנו ר מאיר חיות.","s":"אוצר הרבנים 10665"},{"i":19595,"n":"חיות, יצחק איזיק חזק","b":"מתורתו בספר \"ברכת טוב\".","s":"איטליה גירונדי-א יג"},{"i":19596,"n":"חיות, יצחק מאונסדורף","b":"ראש הקהל באונסדורף. חתניו: ר יחזקאל הלוי מאונסדורף בעל \"תורת יחזקאל\", ר ישראל פאלבר ובזיוו\"ש ר אהרן שפיץ מפרוסטיץ-טרנטשין.","s":"גרינוולד-סלובקיה והונגריה"},{"i":19597,"n":"חיות, יצחק מבוסק ופרג","f":"אברהם","k":"בעל פחד יצחק","bt":"רצח","bp":"פוזנא","dt":"שמה-שע -יא תמוז","b":"מגדולי דורו. גיסו של המהר\"ל (שנשא את אחותו). רב בלבוב, קראקא, בוסק-שכח, פרג-שמד, פרוסטיץ. חיבר קינה על חורבן ק\"ק פוזנא. ועל אחיו ר שמואל שיננא. חיבר \"פחד יצחק\" לובלין שלג, \"פני יצחק\" קראקא שנא. בניו ר מנחם מאניש אלטשולר - מרבניה הראשונים של וילנא, ר אליעזר, ר אברהם. (יש אומרים שנפטר - שע).","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 10662; איטליה גירונדי-י סד; עיר וילנא ח\"א; בית העלמין בוילנא-קלויזנר; פין-כנסת ישראל; בובר-לבוב; מבוא לספר פני יצחק \\ אפי רברבי, תוספת להמודיע יז אלול תשעג עמודים כב - כה; מבוא לספר, תוספת להמודיע יז אלול תשעג עמודים כב - כה","bk":[["מטעמי יצחק (כת\"י)",""],["פחד יצחק – אגדות חז\"ל",""],["קרית ארבע - עה\"ת (כת\"י)",""],["שיח יצחק – דיני פסח",""],["פני יצחק אפי רברבי – הלכות",""]]},{"i":19598,"n":"חיות, יצחק מברוד - א","f":"מאיר","bp":"טיסמניץ","dt":"תקסח","b":"חתן ר נתן נטע אב\"ד ברודי. רב בברודי.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 10665 א'"},{"i":19599,"n":"חיות, יצחק מסקוליע הנכד","f":"יעקב או צבי הירש","k":"בעל זרע יצחק","bt":"ת או תכ","dt":"תפו - כז אלול","b":"נכד (או מצאצאי) ר יצחק חיות מפרג בעל \"אפי רברבי\". תלמיד ר השל מקראקא. חתן ר ידידיה גד מקאליש. רב בסקוליא, ועמד בראש ישיבה. נלחם בשבתאים. רב בדרוהוביטש. חיבר \"זרע יצחק\" פפד\"א תצב ויצא לאור ע\"י בנו - ר אליעזר. אמר שמקבל על עצמו שעד עשרה דורות מזרעו כשיבואו להשתטח על קברו - יוושעו.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 10663; פין-כנסת ישראל; בובר-לבוב; פין-קריה נאמנה"},{"i":19600,"n":"חיות, ליב מבריסק ובאדקי","k":"ארבע חיות - כינויו","b":"מחכמי בריסק, רב בבאדקי-תקע. אחיו: ר הירש פרילוקר, ר בריש, ור וולף חיות - ונקראו לגודל צדקתם \"ארבע החיות\" (שמותיהם היו שמות חיות - הירש-צבי, ליבוש-אריה, בעריש-דב, וולף-זאב).","s":"אוצר הרבנים 12513; הגדול ממינסק"},{"i":19601,"n":"חיות, מאיר מברוד","f":"מנחם מאנוש","dt":"תריד","b":"איש מסחר ובעל בנק מחכמי ברודי-תקס, עקב עסקיו שהה כמחצית מזמנו באיטליה. חתן ר חיים ברנשטין","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 12839"},{"i":19602,"n":"חיות, מאיר מטיסמניץ","f":"אליעזר חיות","b":"חתן ר מרדכי מטיסמניץ. רב בטיסמניץ-תק\"מ. בנו - ר יצחק.","s":"אוצר הרבנים 12840"},{"i":19603,"n":"חיות, מאיר מטיסמניץ","f":"יצחק","b":"חי בזמן הבעשט. חתן ר שמואל הלוי מטיסמניץ. רב בטיסמניץ על מקום חותנו.","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 12838; אהלי שם"},{"i":19604,"n":"חיות, מנחם מאנוש מברודי","f":"יצחק","dt":"תקצב","b":"גביר מחכמי ברודי. חתן ר זאב וולף ברנשטין. היה סוחר באיטליה וממנו נסתעפה משפחת חיות שם. נספד ב\"איתן האזרחי\".","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 13345"},{"i":19605,"n":"חיות, מנחם מאניש","f":"יצחק בן אברהם","dt":"שעז - בערך","b":"אב\"ד וילנא.","s":"בובר-לבוב; %"},{"i":19606,"n":"חיות, מרדכי מאונסדורף","f":"משה","b":"רב באונסדורף-תק\"ע","s":"אוצר הרבנים 13824"},{"i":19607,"n":"חיות, מרדכי מקראקא","b":"מחכמי קראקא-תרנו עמד להוציא לאור \"פסקי חלה\" לרשבא, \"משפטי הנדוי\" לר\"ד ן יחיא.","s":"וונדר-גליצה ח\"ב"},{"i":19608,"n":"חיות, עקיבא שלום מדובובה","k":"בעל נשמת חיה","bt":"תקעה","bp":"טולצ'ין-פודוליה","dt":"תרכח","b":"מצאצאי ר יצחק חיות בעל \"זרע יצחק\". בהיותו בטולצ'ין היה ממתנגדי החסידות ובשל מחלוקת עם האדמו\"ר מסוואראן אף נאלץ לברוח לברודי, עבר לאורהיוב-תרז, לבוב, בהמשך התקרב לר דוד מטולנה והתמנה לרב בדובובא. חיבר גם \"התרגשות הנפש\" (בעילום שמו), \"יסוד דתנו\" (הספר נעלם ויתכן שכלל לא נדפס), הניח כתבים רבים וחתנו ר בנימין הורביץ הו\"ל מכתביו \"סידור עקבי שלום\", ותכנן להדפיס גם \"נחלת שבעה\". מאמר לזכרו ב\"בית המדרש - קראקא תרמח.","s":"אוצר כתבי עת-לוין; אסף-נאחז בסבך"},{"i":19609,"n":"חיות, פנחס","f":"מנחם מאניש אלטשולר","b":"נכד בעל \"פני יצחק\". מצאצאיו בעל המצודות.","s":"ליטא"},{"i":19610,"n":"חיות, פתחיה מספרד ופרג","b":"ממגורשי ספרד,רב בפרג-ר\"פ","s":"אוצר הרבנים 17085"},{"i":19611,"n":"חיות, צבי הירש מדרוהוביטש","f":"דוד","k":"בעל תפארת צבי","bt":"תקצח","bp":"דרוהוביטש","dt":"תרע","b":"חיבר \"תפארת צבי\" דרוהוביטש תרמח.","s":"וונדר-גליציה ח\"ב"},{"i":19612,"n":"חיות, צבי הירש מזולקווא","f":"מאיר","k":"בעל עטרת צבי","r":"נולד בשנת התרי\"ט 1859, נפטר בווינה בשנת התר\"פ 1919. מחכמי גליציה. גדול הדור, פוסק ומקובל. מאות רבנים נועצו בו בענייני הלכה. התפרסם כאחד מגדולי רבני פולין. בשנת 1906 נבחר לאב בית דין בקראקוב ונחשב בפועל רבה הראשי של העיר. כתב למעלה מ-100 ספרים בהלכה, באגדה ובקבלה. בימי חייו הודפסו 20 מחיבוריו והשאר נותר בכתב יד שעם הזמן הובאו בחלקם לדפוס. מחיבוריו: \"אתוון דאורייתא\", \"בית האוצר\", \"אוצרות יוסף\", גליוני הש\"ס לתלמוד הבבלי והירושלמי, \"חושן יוסף\" ועוד. היתה לו יד בקבלה, ובדרכו הייחודית הוא מוצא לכל רעיון בתורת הקבלה מקור בתלמוד וכך הוא מאחד את כל חלקי התורה, הלכה, אגדה וסוד ליחידה אחת לשמה.","bt":"תקסו","bp":"ברודי","dt":"תרטז - ל תשרי","dp":"למברג","b":"תלמיד ר אפרים זלמן מרגליות. בקי בשפות ומדעים, חתן הנגיד ר שלמה פשיבוגרסקי. רב בזולקווא-תקפח, קאליש-תריב, וחזר לזולקווא-תריד, קראקא. חיבר \"עטרת צבי\", \"תורת נביאים\" זולקווא תקצו, ועוד. מאמר ממנו ב\"פליטת סופרים\" - וילנא תרכג. מבניו: ר חיים מלבוב-חתנו של ר ישעיה ליב הורביץ, ר שלמה מברוד, ר יצחק מברוד.","s":"וונדר-גליציה ח\"ב; איטליה גירונדי-צ ה; אוצר הרבנים 17290; אוצר כתבי עת-לוין; פין-כנסת ישראל; מצבות קדש-לבוב; ברוורמן-אנשי שם; בובר-זולקוא; בובר-לבוב; חכמת ישראל באירופה עמוד 165, מבשר ואומר ל' תשרי תשעג; ראה ערך מהר\"ץ חיות; היברובוקס","bk":[["מהר\"ץ חיות – הגהות",""],["משפט ההוראה",""],["תורת הנביאים אלה המצוות",""],["אגרת בקרת",""],["אמרי בינה",""],["דרכי הוראה",""],["דרכי משה",""],["מאמר משפט ההוראה",""],["מבוא התלמוד",""],["מטבע הברכות",""],["מנחת קנאות",""],["שאלות ותשובות מוהר\"ץ",""],["תורת נביאים",""],["תפארת למשה",""]]},{"i":19613,"n":"חיות, צבי פרץ מוינה","f":"שלמה","k":"בעל פירוש מסכת משקין","bt":"תרלז","bp":"ברודי","dt":"תרפז","dp":"וינה","b":"דוקטור באוניברסיטת וינה, ומוסמך בבית המדרש לרבנים שם. סירב לרבנות דרוהוביטש. עסק בהוראה בפירנצה. רבה של טריאסט-תרעב. רבה של וינה-תרעח, ובשליחות מספר פעמים. חיבר \"פירוש מסכת משקין\" לרבנו שלמה בן יתום - ברלין תרע, ועוד. ספרים שונים נכתבו עליו.","s":"וונדר-גליציה ח\"ב"},{"i":19614,"n":"חיות, שאול מברוד","f":"יצחק","k":"בעל אוצר בדויי השם","bt":"תרמד","bp":"ברודי","dt":"תרצה","b":"ספרן בספריית קהילת וינה. חיבר \"אוצר בדויי השם\" וינה תרצג.","s":"וונדר-גליציה ח\"ב"},{"i":19615,"n":"חיות, שלמה מברוד","f":"צבי הירש מזולקווא","bt":"תקצה","bp":"זולקווא","dt":"תרנז","dp":"למברג","b":"דיין בברודי-תרמו.","s":"וונדר-גליציה ח\"ב"},{"i":19616,"n":"חיות, שמואל","f":"אברהם","dt":"שנא - יג טבת","b":"אחיו של ר יצחק בעל \"פני יצחק\". נפטר צעיר בחיי אביו.","s":"ליטא"},{"i":19617,"n":"חיות, שמואל דוד מוילנא וירושלי","dp":"ירושלים","b":"מחכמי ירושלים-שנות ה-תק'-תר'.","s":"פרומקין-תח\"י"},{"i":19618,"n":"חיות, שמואל מלבוב","f":"יוסף","dt":"תכד - ח אייר","dp":"לבוב","b":"ש\"ץ מחכמי לבוב. נהרג עק\"ה.","s":"מצבות קדש-לבוב; בובר-לבוב"},{"i":19619,"n":"חיות, שמשון מהורדנא","f":"מנחם מאניש אלטשולר","dt":"תטו - יח אב","dp":"בלגרד","b":"נכד בעל \"פני יצחק\". מחכמי קראקא, הורדנא. נזכר ב\"אור חדש\". נפטר בנסיעה בבלגרד, וספריו נמכרו ומהם הגיעו לר שמחה הכהן בעל ספר השמות.","s":"אוצר הרבנים 20071; ליטא; רחובות עיר הורדנא-הורביץ"},{"i":19620,"n":"חיות-אלטשולר, מנחם מאניש","f":"יצחק","k":"בעל זמירות שבת","bt":"שכ","bp":"פרג","dt":"שצז - ה-ח אייר","dp":"וילנא","b":"הגיע מפרג וכיהן כרב בטורבין, שידלוב, וילנא-שעז על מקום ר אברהם הלוי סגל (לוריא?). תשובה אליו ב\"חוט השני\" לר חיים יאיר בכרך, וחידוש ממנו אצל ר זלמן מרגלית ב\"שער אפרים\". הסכים על \"עץ שתול\" - ונציא שעח. חתם בלובלין-שעז לפני השל\"ה. הסכים על \"המגיד - צאינה וראינה\" לר יעקב אשכנזי מפרג-שפג. חיבר פירוש על חידת אבן עזרא בכת\"י, ועוד. נזכר בשו\"ת \"שער אפרים\". חיבר \"קבלת שבת\"-לובלין עם הסכמת המהרש\"א שתיקן לאמר אחד השירים בלובלין. מבניו: ר יעקב אביו של ר יצחק בעל \"זרע יצחק\", ר פנחס, ר שמשון (או שמעון) מהורדנא (שנפטר בבלגרד), ר יוסף יוזפא - חתן ר משה נשיא א\"י. חתנו ר יוסף בן משה הורביץ. (אולי גם ר יצחק מרגליות מיאברוב).","s":"וונדר-גליציה ח\"ג; אוצר הרבנים 13344; איטליה גירונדי-נ ט; עיר וילנא ח\"א; בית העלמין בוילנא-קלויזנר; רחובות עיר הורדנא-הורביץ; פין-קריה נאמנה; בובר-לבוב; %; מבוא לס' פני יצחק אפי רברבי מעמוד 3","bk":[["סדר קבלת שבת",""]]},{"i":19621,"n":"חיותה סופר, ישועה רחמים מג'רבה","f":"חנינא הכהן","k":"בעל שמחת כהן","bt":"תרסא","bp":"ג'רבא","dt":"תשיט - י שבט","dp":"מושב ברכיה","b":"דיין בג'רבא על מקום ר ציון הכהן, תלמיד ישיבת ר יצחק חורי, וישיבת ר אליעזר - ולימים עמד בראשה, ותלמיד ר משה כלפון הכהן. עלה לארץ-תשיד וכיהן כרב במושב ברכיה. מצאצאי ר מרדכי הכהן שהיה דיין אצל ר אהרן פרץ מג'רבא. מתלמידיו ר מצליח מאזוז הי\"ד שהקים את ישיבת \"כסא רחמים\" ע\"ש רבו והזכירו בספרו, ור רפאל כדיר צבאן, שהיה ראש הישיבה על מקומו. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ, \"הירח\" - ג'רבה תשח, \"מקבציאל\" - גרבה תרצה, \"קרן דוד\" - גרבה תרעו, \"תקפו של נס\".","s":"אוצר הרבנים 17744 א'; ארזי הלבנון; אוצר כתבי עת-לוין"},{"i":19622,"n":"חייא אהרן הלוי מירושלים","f":"אליהו","b":"מחכמי ירושלים, חתם-תקיד על שטר התקשרות עם ר שלום מזרחי שרעבי, החיד\"א ועוד מחכמי ירושלים.","s":"רוזניס-תורכיה-ה"},{"i":19623,"n":"חייא הפייטן","f":"יוסי","b":"חיבר סליחות ובהם \"יחד עשיר ואביון\" הנמצא במחזור אויניון.","s":"פין-כנסת ישראל"},{"i":19624,"n":"חייא הרופא מצפת","k":"בעל מעשי חייא","bt":"שי","bp":"צפת - כנראה","dt":"שעז או שעח","dp":"צפת","b":"תלמיד ר שלמה סאגיש, ולפי עדות ר עמנואל אבוהב היה גם תלמיד ר יוסף קארו. נסמך לפני שנת שנט על ידי ר יעקב בירב השני יחד עם עוד ששה חכמים, והוא חתום עמם על מחוייבות שלא להסמיך אחרים אלא על דעתו של ר יעקב בירב, למד קבלה אצל ר חיים ויטאל, דיין בבית דינו של ר משה גלנטי, עבר לטבריה לפני שנת שמז לחדש בה את הישיבה ולעמוד בראש הרבנות, לאחר מכן בשליחות לתורכיה, אב\"ד בירושלים-שסז. חזר לצפת-שעב והסכים על ספר \"באר שבע\" לר ישכר איילנבורג, בין תלמידיו בקבלה ר בנימין הלוי. כמה מתשובותיו בספר \"מעשה חייא\" על ידי בנו ר מאיר רופא.","s":"גליס; אוצר הרבנים 6611; פרומקין-תח\"י; פין-כנסת ישראל; ארזי הלבנון; ירושלים ט, די\"י בתוגרמא ג, בניהו \"קובץ על יד\" ה; ארשת ב.","bk":[["מעשה חייא [עהש\"ס ושו\"ת]",""]]},{"i":19625,"n":"חייא מאיר מונציה ופטרץ","f":"דוד","b":"מרבני ונציה, מרביץ תורה בליפאנטו, רב בפטרס(=פטרץ)-יוון-רפח של העדה הסיציליאנית, מתלמידיו ר שמואל קלעי מארטא.","s":"אוצר הרבנים 6610; ארזי הלבנון; פין-כנסת ישראל"},{"i":19626,"n":"חייא מליפאנטו","f":"אברהם","b":"רב בליפאנטו-שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":19627,"n":"חייא מפדובה","b":"מחכמי איטליה בזמן הרדב\"ז","s":"ארזי הלבנון"},{"i":19628,"n":"חייט, אברהם מטריביטש","f":"ראובן","k":"בעל קורות העתים","b":"רב בניקלשבורג. חיבר \"קורות העתים\" - ברלין תקסא - ובו גם תולדות רבני אוסטריה.","s":"איטליה גירונדי-א פא; פין-כנסת ישראל"},{"i":19629,"n":"חייט, אריה דב מבוסטון","f":"ישראל איסר חיים","k":"בעל אוצר הרעיון והמח","bt":"תרנג","bp":"אוטיאן-ליטא","b":"תלמיד ישיבת כנסת בית יצחק אצל ר ברוך ליבוביץ, ישיבת פוניבז, מיר. חתן ר יהושע מרדכי קלצקין מראסיין. נסמך מאת: ר ברוך בר מסלובודקא, ר יצחק רבינוביץ מפוניבז, ר מאיר שמחה הכהן בעל \"אור שמח\". רב בליבוי-לעטלנד-תרפד, היגר לארה\"ב וכיהן כרב בלונג-ברנטש-ניו גרסי-תרפד, בוסטון-תרצב. חיבר \"אוצר הרעיון והמחשבה\".","s":"אמריקה; אנשי שם-אמריקה"},{"i":19630,"n":"חייט, ברוך מוילנא","f":"משה","b":"מחכמי בימ\"ד על שם הגר\"א, והיה ממיסדי הישיבה שם, יחד עם חבריו ר יהושע חייט, ור מאיר בן אריה שטעמפעווער.","s":"עיר וילנא ח\"א"},{"i":19631,"n":"חייט, דוד משלוניקי - הזקן","k":"איל רב דיל וידוי","dt":"תקס - בערך","dp":"שלוניקי","b":"רב בשלוניקי. נתפרסם על ציוויו שמי שישתטח על קברו צריך להקדים ולהתוודות על חטאיו כלפי חבריו - ומכאן כינויו. נזכר אצל ר אברהם גטניו.","s":"זכרון שלוניקי-105"},{"i":19632,"n":"חייט, דוד משלוניקי - הנכד","bp":"שלוניקי","dt":"תרטז - כא סיון","dp":"ירושלים","b":"מקובל מחכמי שלוניקי, עלה לירושלים-תר.","s":"גליס; אוצר הרבנים 4814; ארזי הלבנון; זכרון שלוניקי-139; פרומקין-תח\"י"},{"i":19633,"n":"חייט, חיים עוזר מניו יורק","b":"דיין אצל ר משה פינשטיין בניו יורק.","s":"מתוך קטלוג"},{"i":19634,"n":"חייט, יהודה מספרד ואיטליה","f":"יעקב","k":"בעל מנחת יהודה","dt":"רסח - בערך","b":"מגדולי מקובלי ספרד,בגירוש ספרד עבר לפורטוגל, פאס, עזב בגלל הרעב-רנג, הגיע לאחר יסורים ומות אשתו לונציה, רב במנטובה. חיבר \"מנחת יהודה\" על \"מערכת האלקות\" לרבינו פרץ, חיבר גם ספר דקדוק.","s":"איטליה גירונדי-י קנה; אוצר הרבנים 6934; ארזי הלבנון; מלכי רבנן; פין-כנסת ישראל"},{"i":19635,"n":"חייט, יהושע מוילנא","b":"מחכמי בימ\"ד על שם הגר\"א, והיה ממיסדי הישיבה שם, יחד עם חבריו ר ברוך חייט, ור מאיר בן אריה שטעמפעווער.","s":"עיר וילנא ח\"א"},{"i":19636,"n":"חייט, יעקב","b":"מקובל-שנת ת\"ל","s":"אוצר הרבנים 9634"},{"i":19637,"n":"חייט, יצחק","b":"חסיד חב\"ד. לתולדותיו ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד.","s":"אוצר כתבי עת-לוין"},{"i":19638,"n":"חייט, יצחק מאיר מפומפיאן","dt":"תש..","b":"רבה האחרון של פומפיאן. נספה בשואה.","s":"ליטא"},{"i":19639,"n":"חייט, ישראל איסר חיים","b":"שד\"ר ישיבת סלובודקא ור\"מ במינסק. בנו - ר דב אריה מארה\"ב.","s":"אנשי שם-אמריקה"},{"i":19640,"n":"חייט, רפאל אברהם מכלוף","b":"מחכמי ירושלים, בשנת תקצו חתם על מנוי ר יונה נבון כ\"ראשון לציון\", בשנת תקצו בשליחות במרוקו, בשנים תרג - תרה חתם על כמה מסמכים בירושלים.","s":"גליס"},{"i":19641,"n":"חייטין, משה מבארזנא","f":"זאב","k":"בעל נעם מגדים","b":"רב בברזנה-פלך צרניגוב-תרס. חתנו - ר יעקב אהרן הנדלוב מבאחמאטש.","s":"אוצר הרבנים 14697; אהלי שם"},{"i":19642,"n":"חיים","k":"ר' חיים הקדוש","b":"עק\"ה-שנת ר\"כ","s":"אוצר הרבנים 6132"},{"i":19643,"n":"חיים","f":"חיים","dp":"עזה","b":"מצאצאי ר לוי בן חביב, מוזכר בהקדמת ר ישראל נגארה בספרו \"מימי ישראל\".","s":"גליס; ירושלים ט, קוה\"ד"},{"i":19644,"n":"חיים","f":"בנימין","b":"חתנו - ר דוד הלפרין מאוסטרהא.","s":"אוסטרהא ס"},{"i":19645,"n":"חיים","f":"משה מקופנהגן","b":"בנו - ר שלמה זלמן מזאבלודוב.","s":"ברוורמן-אנשי שם"},{"i":19646,"n":"חיים","f":"יצחק מסקידל","b":"בנו - ר צבי הירש.","s":"ברוורמן-אנשי שם"},{"i":19647,"n":"חיים אבא מסערעד","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא.","s":"אוצר כתבי עת-לוין"},{"i":19648,"n":"חיים אביגדור הכהן מאדרינופול","f":"משה","k":"בעל פרי עץ הדר","bp":"קושטא","b":"תלמיד ר אליעזר נחום, לאחר שנתייתם עבר עם קרובו ר אברהם בן שמואל אביגדור בעל \"זכור לאברהם\" לקושטא, גדל בביתו של ר משה הכהן בעל \"כהונת עולם\" ולמד אתו בישיבת ר חיים קמחי. עלה לארץ ולמד בישיבה בצפת, עבר למצרים וישב בבית הגביר ר אברהם מוספיא, ברח לשלוניקי, נדד עד אמשטרדם ונתמך על ידי ר יוסף הכהן די אזיבידו ועוד, היה בלאריסה, עלה עם ר חיים אבולעפיה לטבריה-תק, בשליחות טבריה לאיטליה-תקב, אשכנז ואמשטרדם. היה במשא ומתן הלכתי עם ר משה מורפורגו אבד אנקונה, חיבר \"פרי עץ חיים\" אמשטרדם תקב.","s":"גליס; אוצר הרבנים 6197; ארזי הלבנון; רוזניס-תורכיה-ה"},{"i":19649,"n":"חיים אברהם הכהן משלוניקי","dt":"תכא - יב תשרי","b":"מחכמי שלוניקי.","s":"רוזניס-תורכיה-ד"},{"i":19650,"n":"חיים אברהם מוינה","k":"נכד הרש\"ל","b":"רב בווינה","s":"אוצר הרבנים 6198"},{"i":19651,"n":"חיים אברהם מספרד","b":"מחכמי ספרד,ראש ישיבה","s":"ארזי הלבנון"},{"i":19652,"n":"חיים אברהם מקושטא","f":"שלום","b":"אב\"ד בקושטא-תקעח.","s":"ארזי הלבנון; רוזניס-תורכיה-ו"},{"i":19653,"n":"חיים אברהם ראובן מוידסלאב","b":"תלמיד ר מנחם מנדל מקוצק.","s":"אלפסי"},{"i":19654,"n":"חיים אברהם שאול מאזמיר וירושלי","dt":"תקנז - כא אב","dp":"ירושלים","b":"גביר מחכמי אזמיר, עלה לירושלים.","s":"גליס; גאון-יהודי המזרח; פרומקין-תח\"י; רוזניס-תורכיה-ה; ירושלים א,"},{"i":19655,"n":"חיים אהרן מקיטוב וירושלים","f":"אברהם גרשון קיטובר","dt":"תקלג - כג ניסן","dp":"טבריה","b":"עמד בראש העדה בירושלים לאחר פטירת אביו, בשנת תקכג חתם על בקשת עזרה לקהילת מיץ, בשנת תקכח בשליחות הקהלה. בסוף ימיו עבר לטבריה.","s":"גליס; אוצר הרבנים 6213; פרומקין-תח\"י; ירושלים ב, אור כי טוב"},{"i":19656,"n":"חיים אורי פיבש הלוי","b":"מראשי הקהלה בצפת, חתם-תקץ על אגרת.","s":"פרומקין-תח\"י"},{"i":19657,"n":"חיים אליהו הלוי מירושלים","b":"מרבני ירושלים-תר\"ע","s":"אוצר הרבנים 6228"},{"i":19658,"n":"חיים אליהו הלוי מירושלים","k":"הו\"ל תורת נזיר","dt":"תקף - אחרי","b":"מחכמי ירושלים. נכד ר אברהם מוטאל, והדפיס את ספרו \"תורת נזיר\" עם הגהות ממנו - שלוניקי תקף.","s":"גליס; אוצר הרבנים 6227; גאון-יהודי המזרח; פרומקין-תח\"י"},{"i":19659,"n":"חיים אלעזר הלוי מירושלים","b":"בשנת תרא שליח ירושלים באדרינופול, ובטיריא בשנת תרו. מכתב שלו פורסם (בניהו סורא ג).","s":"גליס; שא\"י"},{"i":19660,"n":"חיים אפרים מנמירוב","b":"רב בנמירוב-תרע\"ז","s":"אוצר הרבנים 6244"},{"i":19661,"n":"חיים אריה ליב מזאלודק","b":"רב בזאלודק, הסכים-תרלב על \"אבן שלמה\" לר שמואל מלצן."},{"i":19662,"n":"חיים אריה ממעזא-באנד","b":"רב במעזא-באנד-תרס, יהודי הכפר עברו במשך הזמן למארוש-ואשארהי הסמוכה.","s":"אוצר הרבנים 6246; טרנסילבניה"},{"i":19663,"n":"חיים אשר","dt":"תרא - יב ניסן","s":"אוצר הרבנים 6253"},{"i":19664,"n":"חיים בכור הכהן מסמאקוף ירושלים","dt":"תרטו - טז אב","dp":"ירושלים","b":"מחכמי סמאקוף, עלה לירושלים.","s":"פרומקין-תח\"י"},{"i":19665,"n":"חיים בן בצלאל","r":"אב\"ד פרידבורג","bt":"1530","dt":"ה'שמח 1588","s":"היברובוקס; המבשר - קהילות גליון 235 עמוד 4, תוספת להמודיע כג שבט תשעד עמוד ל","bk":[["אגרת הטיול",""],["החיים",""],["ספר החיים",""]]},{"i":19666,"n":"חיים בעל התוספות","f":"יוסי","b":"מבעלי התוספות בזמן רבנו תם. חיבר תוספות למסכת זבחים.","s":"פין-כנסת ישראל"},{"i":19667,"n":"חיים בעריש הכהן מירושלים","f":"יעקב","k":"בעל טוב מאוד","b":"מחכמי ירושלים."},{"i":19668,"n":"חיים ברוך מלענטשנא","f":"יחיאל צבי מראציאנזש","k":"בעל ברכת חיים","b":"מצאצאי בעל מגיני שלמה. תלמיד ר יחזקאל מקוזמיר - שהיה קורא לו \"האתרוג שלי\". אב\"ד לענטשנא.","s":"אוצר הרבנים 6265; אלפסי"},{"i":19669,"n":"חיים ברוך מקאשטוריה","bp":"אישקופיה","b":"רב באישקופיה(=איסקוב)-שנות ה-ש', היה מחלוקת כנגדו ועבר לכהן כרב בקאשטוריה. מתורתו ב\"בני שמואל\" לר שמואל חיון.","s":"רוזניס-תורכיה-ג"},{"i":19670,"n":"חיים ג'יליבי בכור הלוי","f":"נסים רפאל מאזמיר","bt":"תקעה","bp":"אזמיר","dt":"תרסח - כב אלול","dp":"אזמיר","b":"מחכמי אזמיר, עסק ברפואה ובקבלה מעשית. רופאה של אמו של השולטן עבד אל עזיז. בנו - ר אליהו מאזמיר וירושלים.","s":"גאון-יהודי המזרח"},{"i":19671,"n":"חיים גרשון הכהן מקושטא","dt":"תרך - טו אייר","b":"חכם באשי בקושטא-תר\"ד","s":"ארזי הלבנון"},{"i":19672,"n":"חיים דב הרופא מפרוסיה","k":"ד\"ר ברנרד","b":"פרופסור לרפואה,רופא ארמון מלך פרוסיה,חזר בתשובה,פועל ישועות","s":"אוצר הרבנים 6280"},{"i":19673,"n":"חיים דב מחורוסטקוב","b":"רב בחורוסטקוב. הספד המהרש\"ק עליו ב\"עין דמעה\"-תקצד.","s":"וונדר-גליציה ח\"ו"},{"i":19674,"n":"חיים דב מסאספאלו","b":"רב בסאספאלו-תר\"ס","s":"אוצר הרבנים 6279"},{"i":19675,"n":"חיים דוד אליהו מארץ ישראל","f":"נתן נטע","b":"ממונה \"כולל רייסין\"-תרטו. חתם על כתב הסמכה לר אברהם מסלונים להיות הממונה על איסוף הכספים לכולל.","s":"אלפסי"},{"i":19676,"n":"חיים דוד הקטן מצפת וטבריה","f":"יעקב יהודה","dt":"תקצז - כד טבת","dp":"צפת","b":"תלמיד ר מנחם מנדל מויטבסק ור אברהם מקאליסק. מנהיג חסידי רייסין בטבריה על מקום ר צבי מהארקי וממונה על כולל רוסיה בצפת. בשליחות חסידי רייסין בחו\"ל. נספה ברעש בצפת.","s":"גליס; אלפסי; קורות העתים."},{"i":19677,"n":"חיים דוד הרופא מוידין","f":"גבריאל","b":"ראש החברה קדישא בוידין-תקכא.","s":"רוזניס-תורכיה-ה"},{"i":19678,"n":"חיים דוד מדפיס מזולקוא","b":"מדפיס באמשטרדם. מצאצאי ר אורי פיבש הלוי מאמשטרדם, נקרא ע\"י מלך פולין יאן סאבייסקי לבוא מאמשטרדם לזולקוא וליסד שם את הדפוס היהודי הראשון בפולין.","s":"פין-כנסת ישראל"},{"i":19679,"n":"חיים דוד משלוניקי","b":"מגדולי חכמי שלוניקי-ש\"ס","s":"אוצר הרבנים 6285"},{"i":19680,"n":"חיים דוד משלוניקי","f":"דוד חיים","dt":"תיט - ה אלול","dp":"שלוניקי","b":"אולי נכד ר חיים שבתי. מחכמי שלוניקי. נהרג כנראה ע\"י יהודי.","s":"עמנואל-שלוניקי"},{"i":19681,"n":"חיים דוד שלמה מנואוידואהר","f":"יוסף","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה.","s":"אוצר כתבי עת-לוין"},{"i":19682,"n":"חיים דניאל הלוי מירושלים","dt":"תקצד - כח כסלו","dp":"ירושלים","b":"רב בירושלים. חתם-תקצג על קבלת עדות ביפו, חתם-תרי בדבר משפחת אמזלג ונזכר ב\"זכרונות קדומים\".","s":"פרומקין-תח\"י"},{"i":19683,"n":"חיים החבר מצפת","f":"יצחק","bp":"דמשק","b":"עלה לצפת ולמד אצל ר יעקב בירב, בשנת שא היה מחכמי צפת, לאחר פטירת אביו שהיה ראש ישיבה בדמשק עבר לדמשק למלא מקום אביו. בשנת שיז היה בצפת וחתם עם המבי\"ט על תעודה, חתם-שלא על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא. מופיע בשו\"ת חכמי דורו. נמנה על 25 הרבנים שהכתירו את ר יעקב בירב כמוסמך הראוי להסמיך אחרים.","s":"גליס; פין-כנסת ישראל; רוזניס-תורכיה-ב; אלגי, אור החיים, ירושלים ט, כנסת ישראל ועוד"},{"i":19684,"n":"חיים הכהן חריף מדינוביץ","f":"שלמה חריף מזמברוזא","b":"רב בדיינוביץ-תק\"י,בועד הרבנים בפטרסבורג","s":"אוצר הרבנים 6003"},{"i":19685,"n":"חיים הכהן מאוסטרהא","f":"נפתלי-פירות גינוסר","b":"רב באוסטרהא-תצ","s":"אוצר הרבנים 6030; ברוורמן-אנשי שם"},{"i":19686,"n":"חיים הכהן מאזמיר","b":"מחכמי איזמיר,חתן ר' אליהו הכהן האתמרי","s":"ארזי הלבנון"},{"i":19687,"n":"חיים הכהן מבלגרד","b":"רב בבלגרד-תנב, עם ר דוד רוסו.","s":"רוזניס-תורכיה-ד"},{"i":19688,"n":"חיים הכהן מבלגרד","f":"שלמה","b":"מראשי קהלת בלגרד-תקכא בזמן שלא כיהן רב שם.","s":"רוזניס-תורכיה-ה"},{"i":19689,"n":"חיים הכהן מג'רבה וטריפולי","f":"שלמה","k":"בעל נאוה קודש","bt":"תקפז","bp":"ג'רבא","dt":"תרסה - כה סיון","dp":"טריפולי","b":"תלמיד מוהרש\"ך, אב\"ד טריפולי-תרלד על מקום ר אברהם אדאדי שעלה לארץ. מקובל. חיבר \"נאוה קודש\" פירוש על שיר השירים, \"מצוות המלך\", ועוד ספרים רבים.","s":"אוצר הרבנים 6027; ארזי הלבנון; מלכי חי\"ל-מרציאנו"},{"i":19690,"n":"חיים הכהן מוילנא","f":"יונה מוילנא","b":"חתן ר אריה בן ר שמעון הגדול פרגר מוילנא. אביו של אברהם דב לבנזון (אד\"ם הכהן).","s":"עיר וילנא ח\"ב"},{"i":19691,"n":"חיים הכהן מחברון","b":"מחכמי חברון-תכ\"א","s":"ארזי הלבנון"},{"i":19692,"n":"חיים הכהן מחברון","k":"בעל מים חיים","b":"רב בחברון. חיבר \"מים חיים\" - תקטז.","s":"רוזניס-תורכיה-ה"},{"i":19693,"n":"חיים הכהן מירושלים","f":"אברהם","k":"בעל עץ חיים וענפיו","b":"חיבר ספר על בית מושב זקנים בירושלים."},{"i":19694,"n":"חיים הכהן מירושלים","b":"מחכמי ישיבת \"בית אל\" בירושלים-תקיח.","s":"רוזניס-תורכיה-ה"},{"i":19695,"n":"חיים הכהן מלבוב","f":"שמואל כהנא","b":"רב בלבוב-תק\"א","s":"אוצר הרבנים 6026"},{"i":19696,"n":"חיים הכהן מלובלין","f":"נפתלי כץ","dt":"תנח - יח ניסן","b":"חתן ר יחיאל לוריא. רב בלובלין והמדינה","s":"אוצר הרבנים 6024; ברוורמן-אנשי שם"},{"i":19697,"n":"חיים הכהן מליוורנו צפת וחלב","f":"אברהם","k":"בעל תורת חכם","bt":"שמה","bp":"מצרים","dt":"תטו","dp":"ליוורנו","b":"עלה לצפת ולמד קבלה אצל ר חיים ויטאל. רב בחלב-שלט על מקום ר מרדכי אשכנזי הכהן. בדרך לונציא נשדדו ממנו רוב ספריו. חיבר \"תורת חכם\" ונציה תיד, \"מקור חיים\"על שו\"ע, וספרים נוספים בדפוס ובכתב יד. החיד\"א מספר כי הספר \"מגדל דוד\" שנדפס על ידי ר דוד לידא אמשטרדם תס הוא של ר חיים הכהן וכפי שרומז ר דוד לידא בהקדמתו לספר \"נחל נובע ממקור חיים כהנא רבא\". נסע לאיטליה להדפיס את ספריו ושם נפטר. היה במחלוקת עם ר נפתלי בעל \"עמק המלך\". חיבר קינה \"קול ברמה נשמע\". (התאריכים לא מסתדרים - לפי רוזנס עבר מצפת לחלב בשנת שלט - אולי יש עירוב של שני רבנים).","s":"אוצר הרבנים 6023,5897; גליס; ארזי הלבנון; פין-כנסת ישראל; תולדות הפוסקים, די\"י בתוגרמא."},{"i":19698,"n":"חיים הכהן ממכנאס - א","f":"אברהם","b":"מחכמי מכנאס-שנות ה-ש'.","s":"מלכי רבנן"},{"i":19699,"n":"חיים הכהן ממכנאס - ב","f":"אברהם","b":"מחכמי מכנאס-שנות ה-ת'.","s":"מלכי רבנן"},{"i":19700,"n":"חיים הכהן ממרוקו","f":"שלום","b":"רב במרוקו-תרנא.","s":"מתוך קטלוג"},{"i":19701,"n":"חיים הכהן מסמרגן","b":"רב בסמרגן","s":"אוצר הרבנים 6035"},{"i":19702,"n":"חיים הכהן מפאקראי וצפת","b":"רב בפאקראי, נמנה בין העולים הפרושים עם ר מנחם מנדל משקלוב לצפת.","s":"פרומקין-תח\"י"},{"i":19703,"n":"חיים הכהן מפינסק","b":"תלמיד ר אהרן הגדול מקרלין, ובעקבותיו הגיע למגיד ממזריטש, ששלח לו מכתב.","s":"אלפסי"},{"i":19704,"n":"חיים הכהן מפרג","f":"יצחק כץ","k":"ופפד\"מ","dt":"שצה","b":"נכד המהר\"ל-אבי אמו. רב בניקלשבורג, פרג, פפד\"מ-שפח על מקום ר פתחיה, פוזנא-שצ. אחיו של ר נפתלי כץ מלובלין.","s":"אוצר הרבנים 6028; רבני פרנקפורט"},{"i":19705,"n":"חיים הכהן מצרפת","f":"חננאל","b":"מבעלי התוספות-ד'תתקנ. אבי זקנו של ר משה מקוצי בעל הסמ\"ג.","s":"אוצר הרבנים 6021; פין-כנסת ישראל"},{"i":19706,"n":"חיים הכהן מקאשטוריאה","b":"רב בקאשטוריאה-תע. בנו - ר מנחם - דיין בקאשטוריאה.","s":"רוזניס-תורכיה-ד"},{"i":19707,"n":"חיים הכהן מקלוש","f":"יוסף","bt":"תקב","dt":"תקף","b":"מחכמי קלוש. אחיו של בעל הקצות.","s":"וונדר-גליציה ח\"ג"},{"i":19708,"n":"חיים הכהן משלוניקי - א","f":"שלמה - מהרש\"ך","dt":"שצז - כה סיון","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי; מלכי רבנן"},{"i":19709,"n":"חיים הכהן משלוניקי - ב","dt":"תיט - כו אב","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי-53; מלכי רבנן"},{"i":19710,"n":"חיים הכהן פאקראייער מוילנא","b":"גביר מראשי קהלת וילנא יחד עם ר אריה ליב פעסעלעס.","s":"פרומקין-תח\"י"},{"i":19711,"n":"חיים הלוי אלעסקר מגיד מרובנא","f":"שמואל","b":"תלמיד המגיד ממזריטש. רב באוסטרהא, רובנא. נזכר ע\"י הצל\"ח, ואחיו בעל חדושי הרז\"ה. הסכים ב\"הלכה פסוקה\".","s":"אלפסי"},{"i":19712,"n":"חיים הלוי מאדרינופול","b":"דיין באדרינופול, חתם-תקעה עם ר יהושע גירון ור מרדכי בנבנישתי.","s":"רוזניס-תורכיה-ו"},{"i":19713,"n":"חיים הלוי מאזמיר ?? לבדוק מי ז","f":"שלמה","k":"בעל שיר ושבחה - כת\"י","b":"מחכמי אזמיר-תרן. חיבר \"שבח לאל\" על תהלים, \"חיים בחסד\" על נביאים, \"מוסר אב\" על פרקי אבות, ועוד.","s":"מתוך קטלוג"},{"i":19714,"n":"חיים הלוי מבולגריה","dt":"תריז - ב שבט","b":"מגדולי חכמי בולגריה","s":"אוצר הרבנים 6040"},{"i":19715,"n":"חיים הלוי מברזדנוב","f":"אברהם הלוי","b":"רב בברזדוב-תר\"ע","s":"אוצר הרבנים 6042"},{"i":19716,"n":"חיים הלוי מחברון","b":"מחכמי חברון וגזבר הקהלה בשנים תקמח - תקץ, חתום על אגרות משנת תקנב - תקץ, בשנת תקץ מונה בנו יוסף לעוזרו וממלא מקומו.","s":"גליס; רוזניס-תורכיה-ה; \"התור\" תרפט יט וכא, ירושלים א ג-ד, ציון תרצג, שריד ופליט"},{"i":19717,"n":"חיים הלוי מחלב","b":"רב ודיין בחלב-תקע\"ד","s":"ארזי הלבנון"},{"i":19718,"n":"חיים הלוי מטבריה","f":"שלמה מוידז","b":"מחכמי טבריה. כינה עצמו משרת האדמו\"ר ר אברהם מקאליסק. אולי הוא ר חיים הלוי שהיה בשליחות ונזכר אצל בעל התניא.","s":"אלפסי"},{"i":19719,"n":"חיים הלוי מיברוב ולבוב","b":"ראב\"ד ומו\"צ בלבוב וראש מדינה בגליל לבוב. חתם-תסד על תקנות הקהלה. חתנו - ר חיים בן יקותיאל זיסקינד כץ מיברוב ולבוב.","s":"בובר-זולקוא"},{"i":19720,"n":"חיים הלוי מירושלים","dt":"תרח - יז אלול","b":"מגדולי חכמי הספרדים בירושלים,דיין","s":"אוצר הרבנים 6041"},{"i":19721,"n":"חיים הלוי מירמליניץ","f":"יוסף הלוי","b":"רב ביארמליניץ","s":"אוצר הרבנים 6044"},{"i":19722,"n":"חיים הלוי מלבוב","f":"משה","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה.","s":"מצבות קדש-לבוב; בובר-לבוב"},{"i":19723,"n":"חיים הלוי ממצרים","b":"רב הכולל במצרים - שנות ה-ת'. חיבר ספר להגן על הרמב\"ם מטענות בעל \"חוות יאיר\" בענין הלכה למשה מסיני.","s":"אוצר הרבנים 6043; פין-כנסת ישראל"},{"i":19724,"n":"חיים הלוי מסופיה","b":"גביר בסופיה?-שנות ה-תק'. נספד מאת אחיינו - ר ראובן בן יעקב מסופיה.","s":"רוזניס-תורכיה-ה"},{"i":19725,"n":"חיים הלוי מקובנא","f":"אברהם מקרוז'","dt":"תרכח","b":"דיין בקובנא.","s":"שם הגדולים השלישי"},{"i":19726,"n":"חיים הלוי משלוניקי","b":"מחכמי שלוניקי-שץ, תלמיד ר שלמה ן מאיור.","s":"זכרון שלוניקי"},{"i":19727,"n":"חיים הלוי משלוניקי","f":"שמואל","dt":"רפז","dp":"שלוניקי","b":"מחכמי שלוניקי. אחיו - ר יוסף.","s":"עמנואל-שלוניקי"},{"i":19728,"n":"חיים הנקדן","f":"שניאור","b":"מחכמי הדקדוק. חיבר ספר על המסורה - ה'נב.","s":"פין-כנסת ישראל"},{"i":19729,"n":"חיים הפייטן","f":"יקר","b":"חיבר פיוט \"חבוש פאר ציון מלך עליון\".","s":"פין-כנסת ישראל"},{"i":19730,"n":"חיים הפייטן","f":"מכיר","b":"פייטן - שנות ה-ק'. תלמיד מהר\"ם בן ברוך ונזכר בספרו, נזכר גם ב\"אור זרוע\". חיבר קינה על גזרת מינכן-ה'מה - \"אנא אלקי... ה' צבאות גואלם\".","s":"פין-כנסת ישראל"},{"i":19731,"n":"חיים הפייטן","f":"שלמה","b":"חיבר \"חולי נפי לדינך וגורי\".","s":"פין-כנסת ישראל"},{"i":19732,"n":"חיים וועלוויל פסח'ס מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז.","s":"עיר וילנא ח\"א"},{"i":19733,"n":"חיים זאב וולף מאסמינא","f":"יצחק","k":"בעל דברי חיים","dt":"תרמג","dp":"ירושלים?","b":"עלה לירושלים. חיבר \"דברי חיים\" איידקוהנן(=איידטקוהנען) תרלג, בהסכמת המלבים ועוד.","s":"גליס"},{"i":19734,"n":"חיים זאב וולף מיאווארזנא","b":"אב\"ד יאווארזנא. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט - ובהם תשובה הלכתית לר שלום איזנבורג מקשנוב.","s":"אוצר כתבי עת-לוין"},{"i":19735,"n":"חיים זאלודקער","dt":"תקפא - י שבט","b":"חתן ר ישעיה באקשטר. בניו: הגביר ר ליפעלי איועניצער, ר אברהם פה טהור.","s":"עיר וילנא ח\"א"},{"i":19736,"n":"חיים זליגמן מגאשלר","dt":"תמו","b":"אב\"ד גאשלר. בנו - ר שמואל קצנשטין מאלטונא.","s":"דוקס-אוה למושב-ב"},{"i":19737,"n":"חיים זלמן ממיר","b":"רב במיר-תר\"נ","s":"אוצר הרבנים 6316"},{"i":19738,"n":"חיים חייקא מאוסטרהא","f":"מרדכי","dt":"תקלא - טז טבת","dp":"אוסטרהא","b":"מחכמי אוסטרהא, מיושבי הקלויז הגדולה. הסכים על \"מפלגי ראובן\". מבניו: ר אליהו אשר מאוסטרהא, ר שמואל.","s":"אוסטרהא קל"},{"i":19739,"n":"חיים חייקל מזמושט","f":"אהרן מטרניגרד","k":"בעל צרור החיים","dt":"תקל - לפני","b":"רב בזאמוטש-תקי. חיבר \"צרור החיים\" ונדפס ע\"י אחיו ר יצחק - ברלין תקל.","s":"אוצר הרבנים 6327; פין-כנסת ישראל"},{"i":19740,"n":"חיים חיקא בן אהרן","bt":"1730","dt":"ה'תקכד 1764","s":"היברובוקס","bk":[["צרור החיים",""]]},{"i":19741,"n":"חיים חריף מקשאנוב","dt":"תקמז","b":"רב בקשאנוב.","s":"וונדר-גליציה ח\"ב; אוצר הרבנים 6002"},{"i":19742,"n":"חיים טורדוס מסידרוקאפסי","dt":"שפא - ז אב","dp":"שלוניקי","b":"מחכמי סידרוסקאפסי-ליד שלוניקי.","s":"עמנואל-שלוניקי"},{"i":19743,"n":"חיים טשערהייער","b":"תלמיד חבר להגר\"א.","s":"ברוורמן-אנשי שם"},{"i":19744,"n":"חיים יהודה אליעזר מאזמיר","k":"בעל שמחת יהודה","dt":"תקמ - ד-יד אלול","b":"מחכמי איזמיר,מרביץ תורה,חיבר שו\"ת \"שמחת יהודה\". (באוצר הרבנים נרשם תאריך פטירתו - ה אלול תקמט). בנו - ר יהושע אברהם יהודה.","s":"אוצר הרבנים 6354; ארזי הלבנון; רוזניס-תורכיה-ה; הקדמה לפתח הדביר החדש הערה 42","bk":[["שמחת יאודה – שו\"ת,",""]]},{"i":19745,"n":"חיים יהודה הלוי מירושלים","b":"מחכמי ירושלים, בשנת תקמב חתם על כתב שליחות ר רפאל בן רובי.","s":"גליס; ארזי הלבנון; פרומקין-תח\"י; רוזניס-תורכיה-ה; ירושלים ו, תחי"},{"i":19746,"n":"חיים יהודה מירושלים","k":"בעל ותתפלל חנה","dt":"תרנז - יז תשרי","b":"מיקירי ירושלים","s":"אוצר הרבנים 6332"},{"i":19747,"n":"חיים יהודה מצפת","f":"שמחה","b":"מחכמי צפת, חתם בשנת תקנא על כתב שליחות ר חיים מודעי.","s":"גליס; ירושלים לזכר לונץ."},{"i":19748,"n":"חיים יהודה משלוניקי","b":"חתן ותלמיד ר שלמה אמריליו בעל \"כרם שלמה\". מחכמי שאלוניקי. תשובות ממנו ב\"עוללות הכרם\", \"זרע אברהם\". מתלמידיו - ר שלמה עבדאלה.","s":"אוצר הרבנים 6333; פין-כנסת ישראל"},{"i":19749,"n":"חיים יהושע הכהן מלאזדיי","f":"ראובן","b":"רב בלאזדיי על מקום ר צבי הירש כהנא.","s":"ליטא"},{"i":19750,"n":"חיים יהושע הכהן מקמניץ","f":"ראובן","dt":"תרמ - יא שבט","dp":"בריסק","b":"רב בביאליסטוק, קמניץ. נזכר ב\"שאילת שמואל\" לר שמואל אביגדור מקרלין.","s":"אוצר הרבנים 6359; ברוורמן-אנשי שם"},{"i":19751,"n":"חיים יהושע מגליכוב","dt":"תרלז","b":"מגדולי תלמידי ר ה\"צמח צדק\" שמינהו שליח לפדיון שבויים, נתפס בזמן שניסה להציל ילדי קנטוניסטים ושוחרר במאמצי רבו שכינהו \"רעי כאח לי\".","s":"אלפסי"},{"i":19752,"n":"חיים יובעלירער מוילנא","b":"ממיסדי ותומכי ישיבת מייליס בוילנא.","s":"עיר וילנא ח\"א"},{"i":19753,"n":"חיים יוסף ברוך מחברון","b":"מחכמי חברון, בשנת תקכג חתום על בקשת עזרה.","s":"גליס"},{"i":19754,"n":"חיים יוסף מאמציסלב","f":"אברהם שמחה","b":"מו\"צ באמציסלב-תרכ. (בספר נחלת אבות מסופר שאליו עבר בלחישה נוסח הקמיע המיוחד של דודו זקנו ר חיים מוולוזין).","s":"אוצר הרבנים 6368"},{"i":19755,"n":"חיים יוסף מבלגרד","f":"מאיר","b":"דיין בבלגרד-תח - תמח, יחד עם ר שמואל בן משה לארידו (לדירי) ור יצחק ברוך עדניא.","s":"רוזניס-תורכיה-ד"},{"i":19756,"n":"חיים יחזקאל מטשנגר","k":"חיים יחזקאל מסריזשוב","b":"רב בטשענגער-תק\"נ","s":"אוצר הרבנים 6386"},{"i":19757,"n":"חיים יחיאל בארנשטיין ב\"ר שמואל הלוי","bt":"תרה","dt":"תרפח","s":"שבת בשבתו גליון 1523","bk":[["חשבון תקופות ומולדות",""],["מחלקת רב סעדיה גאון ובן מאיר - בקביעת שנות ד\"א תרפ\"ב - תרפ\"ד, פרק מקורות סדר העבור בישראל",""]]},{"i":19758,"n":"חיים יחיאל מרוסיה","f":"פנחס מקוריץ","b":"רב ברוסיה. חתם על היתר מאה רבנים - תרלח."},{"i":19759,"n":"חיים יעקב אליהו מאזמיר","b":"מדפיס באזמיר-תקסו.","s":"רוזניס-תורכיה-ה"},{"i":19760,"n":"חיים יעקב הלוי מדובניצה","b":"רב בדובניצה-תקס בערך.","s":"רוזניס-תורכיה-ה"},{"i":19761,"n":"חיים יעקב הלוי מקיוסטנדיל וסופ","f":"משה","dt":"תקסח - בערך","b":"רב בקיוסטנדיל, סופיה-תקסז ור רחמים אברהם וינטורא על מקומו אחריו.","s":"רוזניס-תורכיה-ו"},{"i":19762,"n":"חיים יעקב מצפת","f":"יעקב דוד","k":"בעל צרור החיים","bt":"תס","bp":"אזמיר או אדרינופול","b":"מחכמי אזמיר, למד אצל ר חיים אבולעפיה בעל \"עץ החיים\" ואצל ר חיים אלפנדרי בקושטא, עלה בעקבות רבו לצפת-לפני תעז. בשנת תעז בשליחות צפת לערי המערב, בשנת תעח היה בתונס ואלגיר. לאחר מכן בשליחות לספרד ואשכנז ביחד עם ר מאיר שיגורא, ושוב בצפון אפריקה, תשובות רבות השיב במהלך שנותיו בשליחות. חיבר \"צרור החיים\" אמשטרדם תצח, \"סמא דחיי\" אמשטרדם תצט. (אצל יערי ורוזניס נרשם בטעות? - תלמיד ר חיים אלפנדרי).","s":"גליס; אוצר הרבנים 6388; פין-כנסת ישראל; ארזי הלבנון; אלגי, בן צבי בספר צפת, שא\"י"},{"i":19763,"n":"חיים יצחק (ירוחם) מטימבורג","b":"רב בטימבורג, לימנוב. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז.","s":"וונדר-גליציה ח\"ו; אוצר כתבי עת-לוין"},{"i":19764,"n":"חיים יצחק הפייטן","b":"חיבר פיוט \"חי ה' וברוך צורי\".","s":"פין-כנסת ישראל"},{"i":19765,"n":"חיים יצחק מליפוביץ וצפת","b":"מראשי הקהלה בצפת, חתם-תקץ על אגרת.","s":"פרומקין-תח\"י"},{"i":19766,"n":"חיים יצחק שלום מלאריסה","b":"גביר בלאריסה-שנות ה-תק', תמך בחכמים ובהדפסת ספריהם, והחזיק ישיבה בשלוניקי בראשות ר יצחק ן שנג'י.","s":"רוזניס-תורכיה-ה"},{"i":19767,"n":"חיים ישועה מאיטליה","b":"מחכמי איטליה-ת\"ר","s":"אוצר הרבנים 6443"},{"i":19768,"n":"חיים ישעיהו הכהן מירושלים","k":"בעל מסגרת השלחן","dt":"ה שבט","b":"רב בראחוב,ויסאקי-תר\"נ,עלה לירושלים","s":"אוצר הרבנים 6441"},{"i":19769,"n":"חיים ישראל משיניבה","b":"רב בשיניבה - תשובה אליו במהר\"י הכהן.","s":"וונדר-גליציה ח\"ו"},{"i":19770,"n":"חיים יששכר משצריץ","f":"צבי","dt":"תרלג","b":"רב בשצריץ 47 שנה.","s":"וונדר-גליציה ח\"ו"},{"i":19771,"n":"חיים ליב מטרבובלא","dt":"תקנח - יב אייר","b":"רב בטרעבוולא","s":"אוצר הרבנים 6447"},{"i":19772,"n":"חיים ליב מלודז","f":"אהרן","b":"פרסם מאמרים ב\"קול תורה\" - וארשא תרסח.","s":"אוצר כתבי עת-לוין"},{"i":19773,"n":"חיים ליבוש מלפטין","f":"יוסף","b":"רב בלפטין-תר\"ע","s":"אוצר הרבנים 6449"},{"i":19774,"n":"חיים מאוסטרהא","f":"משה שלום מאוסטרהא","dt":"תקיד - יב תשרי","dp":"אוסטרהא","b":"פרנס באוסטרהא בשתי הח\"ק. גם אביו לפניו היה פרנס באוסטרהא. בנו ר יצחק.","s":"אוסטרהא צא"},{"i":19775,"n":"חיים מאוסטרהא","f":"יוסף אפרים מאוסטרהא","dt":"תקכג - יח חשון","dp":"אוסטרהא","b":"נכד ר נפתלי הרץ-אחיו של בעל \"משחת אהרן\" בן ר יואל פיבש מאוסטרהא. פרנס באוסטרהא יחד עם אביו. נפטר בחיי אביו.","s":"אוסטרהא קיב"},{"i":19776,"n":"חיים מאוסטרהא","f":"יעקב ישראל בן עוזר","dt":"תקמז - כח אייר","dp":"אוסטהרא","b":"פרנס באוסטרהא-תקכח. חברו של ר ברוך ממזבוז שישב אז באוסטרהא ולמדו ביחד. בנו ר אריה ליב.","s":"אוסטרהא קנז"},{"i":19777,"n":"חיים מאוסטרהא","f":"נחמן","k":"חיים פעטשניק","b":"מו\"צ ודיין באוסטרהא אצל ר חיים רפפורט בעל \"מים חיים\". הסכים על \"סדר עבודה ומורה דרך\" יחד עם ר חיים רפפרוט - סלאויטא תקצו.","s":"אוסטרהא רנה"},{"i":19778,"n":"חיים מאור הגולה","f":"נסים","k":"בעל עץ חיים","b":"מגדולי הראשונים","s":"אוצר הרבנים 6057; פין-כנסת ישראל"},{"i":19779,"n":"חיים מאיר משדה לבן","b":"תלמיד ר יהודה ליב הסבא משפולא. בנו ר שמשון אהרן.","s":"אלפסי"},{"i":19780,"n":"חיים מאלגיר","bt":"שי","dt":"שפ - בערך","b":"מחכמי וארגלאן(=וארגלא)-במדבר הסהרה ליד גרדאייא-אלגיר. שאלה ממנו לרשב\"ץ ב\"חוט המשולש\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":19781,"n":"חיים מאר\"ץ","f":"ברכאל","b":"חכם קדמון הנזכר אצל ר ששת הרופא בן יפת מחלב-ה'ן.","s":"ארזי הלבנון"},{"i":19782,"n":"חיים מבוברויסק","f":"שמריהו","b":"רב בבוברויסק. הסכים על דרך הישרים ל מרדכי צבי מנבי."},{"i":19783,"n":"חיים מבלמשוב","b":"רב בבלאמאשוב-תמ\"ז","s":"אוצר הרבנים 5828"},{"i":19784,"n":"חיים מבלשביץ","dt":"תרכט - בערך","b":"תלמיד מהרי\"א מזידיטשוב. רב בבלשביץ.","s":"וונדר-גליציה ח\"ו"},{"i":19785,"n":"חיים מברלין","f":"ר\"ש מלנצבורג","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב.","s":"תולדות אנשי השם-לנדסהוט"},{"i":19786,"n":"חיים מברצלונה","f":"שלמה","b":"תלמיד הרשב\"א-שכ\"ו,חיבר ספר \"השולחן\" הלכות ברכות ותפילה","s":"ארזי הלבנון"},{"i":19787,"n":"חיים מגומבין","k":"אבי המגן אברהם","b":"רב בגומבין(=גאמבין)-שנת ת'","s":"אוצר הרבנים 5829"},{"i":19788,"n":"חיים מגיד מוילנא","f":"שלמה זלמן מוילנא","bp":"וילנא","dt":"תקנה - כו טבת","dp":"וילנא","b":"רב בוילנא. חברו של הגר\"א ונשלח ע\"י ומטעם ועידת הרבנים בוילנא-תקנו לערי ליטא ורייסן לפעול כנגד התפשטות החסידות. נספד ב\"אפיקי יהודה\". ב\"יהדות ליטא נרשם תאריך פטירתו - תקסד).","s":"אוצר הרבנים 5972; ליטא; עיר וילנא ח\"א; בית העלמין בוילנא-קלויזנר"},{"i":19789,"n":"חיים מגלוגא","dt":"תק - כא ניסן","b":"מרביץ תורה ודיין בהנובר","s":"אוצר הרבנים 5937"},{"i":19790,"n":"חיים מדמשק וצפת","f":"יצחק החבר","k":"ר' חיים החבר","b":"עלה לצפת-ש\"א,רב בדמשק,חזר לצפת-שי\"ז","s":"אוצר הרבנים 5996"},{"i":19791,"n":"חיים מדמשק וצפת","f":"שלמה עמרם","k":"בעל מטעם המלך","bp":"צפת","b":"בגיל שבע עבר לדמשק ולמד בישיבה לבית פרחי, חזר לצפת והיה סופר הקהלה, מקורב לשר חיים פרחי בעכו. חיבר \"מטעם המלך\" נא אמון תרסח. בשנת תקיז בשליחות בתורכיה, בשנת תקע חתם על כתב שליחות ר אברהם בן המון.","s":"גליס; ירושלים לזכר לונץ, שא\"י, מחקרים ומקורות לבן צבי"},{"i":19792,"n":"חיים מדרוהוביטש","f":"קלונימוס קלמן","b":"דיין בדרוהוביטש.","s":"וונדר-גליציה ח\"ו"},{"i":19793,"n":"חיים מדרויע","b":"רב בדרויע-תקל\"ז","s":"אוצר הרבנים 5830"},{"i":19794,"n":"חיים מדרעא-מרוקו","b":"מקובל,ממערב הפנימי בדרעא-ת\"ס","s":"אוצר הרבנים 5832"},{"i":19795,"n":"חיים מדרעא-מרוקו וצפת","bp":"דרעא","b":"מקובל מחכמי מרוקו, עלה לצפת בזמן ר חיים ויטאל. נחשב למגיד עתידות ושזכה לגילוי אליהו.","s":"מלכי רבנן; טולדנו-נר המערב"},{"i":19796,"n":"חיים מהאזנפוט","f":"שמעון","b":"גביר בהאזנפוט-תקס. בנו - שמריהו מהאזנפוט. חתניו - ר דב בן שלמה מהאזנפוט, ר פנחס אייכל מהאזנפוט.","s":"אובצינסקי-קורלנד"},{"i":19797,"n":"חיים מהורדנא","dt":"תקיד - כב תמוז","dp":"הורדנא","b":"מחכמי הורדנא","s":"פרידנשטין - הורדנא"},{"i":19798,"n":"חיים מהורדנקא","b":"חתן ר איצק הארידענקיר. גביר מחכמי הורדנקא. חתנו (בזיוו\"ר) ר מאיר מרגליות בעל מאיר נתיבים.","s":"אוסטרהא קסז"},{"i":19799,"n":"חיים מהליטש","dt":"תרכט - בערך","b":"רב בהליטש. תושבה אליו \"האלף לך שלמה\".","s":"וונדר-גליציה ח\"ו"},{"i":19800,"n":"חיים מהמבורג","f":"יוסף מיכל","k":"בעל אור החיים","bt":"תקנב","bp":"המבורג","dt":"תרה","dp":"המבורג","b":"תלמיד וחתן ר אליעזר לאזי ברלין בעל \"משנת דרבי אליעזר\". מחכמי המבורג, בעל ספריה גדולה, חיבר רשימת ספרים בשם \"תולדות מחברי הספרים\", ונדפסה מאת שטינשנידר בשם \"אוצרות החיים\", עם תולדות ר חיים מיכל לצונץ. ספריו נמכרו לספריית אוקספורד ולמוזיאום הבריטי. חיבר מאמר על הפייטנים ונדפס ע\"י גיסו ר יצחק ברלין - הנובר 1839.","s":"דוקס-אוה למושב-ב; פין-כנסת ישראל"},{"i":19801,"n":"חיים מהמבורג וברלין","f":"ר\"א","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט, אך לאחר מכן היה בראש מתנגדיו עד שעזב לפפד\"מ.","s":"תולדות אנשי השם-לנדסהוט"},{"i":19802,"n":"חיים מהראשקה","b":"דומ\"צ בהראשקה-תר\"ל","s":"אוצר הרבנים 5834"},{"i":19803,"n":"חיים מואשאן","b":"רב בוואשאן-תק\"ס","s":"אוצר הרבנים 5838"},{"i":19804,"n":"חיים מווידז-ליטא","k":"בעל גן יה","b":"מקובל, רב בווידז-ליטא-תקס.","s":"אוצר הרבנים 5839; ליטא; פין-כנסת ישראל"},{"i":19805,"n":"חיים מוולוזין","f":"יצחק מוולוזין","k":"בעל נפש החיים","r":"אב\"ד ור\"מ בוולוז'ין","bt":"תקט","dt":"תקפא - יד סיון","dp":"וולוזין","b":"תלמיד ר אריה ליב בעל \"שאגת אריה\", ר רפאל הכהן בעל \"תורת יקותיאל\", הגר\"א. חתן ר אריה ליב גינצבורג מוילנא(=ליב כתבן). מייסד ישיבת וולוזין, רב בוילקומיר על מקום ר שלמה הלוי-תלמיד הגר\"א, וולוזין והקים שם ישיבת \"עץ חיים\"-תקסד. מגדולי הפוסקים בדורו. בניו: ר יצחק על מקומו אחריו, ר יוסף. חתניו ר הלל בן שמחה מגרודנא, ר מרדכי, וב\"אהלי שם\" מופיע גם ר משה הכהן (אבי משפחת כהנא-שפירא) כחתנו. מתורתו ב\"תבונה\" - ירושלים תשא-תשח.","s":"אוצר הרבנים 5924; ליטא; אוצר כתבי עת-לוין; פין-כנסת ישראל; פניני עין חמד גליון 484; יומא דהילולא","bk":[["חוט המשולש","שו\"ת - אחרונים"],["נפש החיים",""],["חוט המשולש - שו\"ת",""],["כתר ראש - הנהגות",""],["נפש החיים - מוסר",""],["רוח חיים - אבות",""],["תשובות רבינו חיים מוואלוזין (שו\"ת)",""],["רוח חיים",""],["חוט המשולש ח\"א",""],["נפש החיים","מחשבה ומוסר - אחרונים"]],"e":"תק\"ט-תקפ\"א"},{"i":19806,"n":"חיים מויטקאוא","b":"רב בוויטקאווא-תק\"פ","s":"אוצר הרבנים 5837"},{"i":19807,"n":"חיים מויטקוב","b":"חסיד חוליוב. רב בויטקוב-תרכט.","s":"וונדר-גליציה ח\"ו"},{"i":19808,"n":"חיים מוילנא","f":"משה (שמאי)","b":"דיין בוילנא, חתם-תי עם בעל הש\"ך, ר שלמה הלוי ר נפתלי הרץ בן מאיר רייך.","s":"פין-קריה נאמנה"},{"i":19809,"n":"חיים מוילנא","f":"יחיאל","b":"דיין בוילנא, חתם-תקיא עם ר מרדכי בן משה.","s":"פין-קריה נאמנה"},{"i":19810,"n":"חיים מוילנא","f":"אליעזר פיבש","b":"גביר מראשי קהלת וילנא, חתם-תץ בפנקס הקהלה, נדב ספר תורה-תצד.","s":"פין-קריה נאמנה"},{"i":19811,"n":"חיים מוילנא","f":"יונה","dt":"תקנד - טו אלול","dp":"וילנא","b":"מחכמי וילנא בזמן הגר\"א.","s":"פין-קריה נאמנה"},{"i":19812,"n":"חיים מוישטיניץ-ליטא","dt":"תרלה","b":"רב בוישטיניץ על מקום ר חיים וסרצוג.","s":"ליטא"},{"i":19813,"n":"חיים מוריגלאן-מרוקו","b":"שאלה ממנו לריב\"ש.","s":"טולדנו-נר המערב"},{"i":19814,"n":"חיים מורמייזא","f":"יהודה ליואי הזקן","k":"הזקן","b":"גדול חכמי אשכנז,רב בוורמייזא וראש מדינת אשכנז-ש\"י, בניו: ר יעקב, ר העלמן (תלמידי המהרש\"ל), ר בצלאל, ונכדו - המהר\"ל מפרג.","s":"אוצר הרבנים 5983; בית העלמין בוילנא-קלויזנר"},{"i":19815,"n":"חיים מורמייזא","f":"סיני בן בצלאל מפרג","b":"בן אחיו של המהר\"ל מפרג. רב בקעלן ומדינת ביהם-תכ. בנו - ר יהודה ליב עשקלש(7367), חתנו - ר טודרוס.","s":"אוצר הרבנים 5984; ברוין-אנשי מופת"},{"i":19816,"n":"חיים מזולקוא","f":"אורי","b":"עשיר,רב בזלקווא-תק\"ל","s":"אוצר הרבנים 5841"},{"i":19817,"n":"חיים מזולקוא","f":"אהרן","b":"מחכמי זולקוא, חתם-תסד על תקנת הקהלה.","s":"בובר-זולקוא"},{"i":19818,"n":"חיים מזולקוא","f":"דוד מאוסטרהא","dp":"זולקוא","b":"מחכמי זולקוא.","s":"בובר-זולקוא"},{"i":19819,"n":"חיים מזיטל","f":"נפתלי הרץ מנוברדוק","b":"רב בזיטל","s":"אוצר הרבנים 5842; מרקוביץ-נוברדוק"},{"i":19820,"n":"חיים מזלטופול","b":"אב\"ד זלטופול.","s":"ברוורמן-אנשי שם"},{"i":19821,"n":"חיים מזעלווע","b":"מקובל,רב בזעלווע,סעליב-תק\"ע","s":"אוצר הרבנים 5843"},{"i":19822,"n":"חיים מחאזדש","b":"רב בחאזדש-תק\"ע","s":"אוצר הרבנים 5844"},{"i":19823,"n":"חיים מחברון","f":"יהודה ליב מנחם מנדל","b":"מראשוני חסידי חב\"ד בחברון. (ראה גם: ר משה חיים מחברון)","s":"אלפסי"},{"i":19824,"n":"חיים מחמלניק","b":"אב\"ד חמלניק-בשנות התק'. בנו ר דוד מאוסטרהא - נפטר תקסב, חתנו - ר שלמה זלמן זוסמן מאוסטרהא.","s":"אוסטרהא קצד,רלז"},{"i":19825,"n":"חיים מחמלניק","b":"גביר בחמלניק שבנה בכספו את ביהכ\"נ הגדולה בחמלניק ונקראת על שמו. חתנו ר שלמה זלמן הכהן זוסמן מאוסטרהא.","s":"אוסטרהא רלז"},{"i":19826,"n":"חיים מטבריה","f":"מנחם","b":"בשליחות קהילת החסידים בטבריה בטיקטין-תקמו.","s":"אלפסי"},{"i":19827,"n":"חיים מטולדו","f":"שמואל או דוד","k":"בעל צרור החיים","bt":"נ","bp":"טוליטולה","dt":"ק","dp":"טוליטולה","b":"תלמיד הרשב\"א, רב בטולידו-ס. חיבר \"צרור החיים\" ו\"צרור הכסף\"","s":"אוצר הרבנים 5944; ארזי הלבנון; פין-כנסת ישראל"},{"i":19828,"n":"חיים מטולטשין","dt":"תח - יא תמוז","b":"עק\"ה,ראב\"ד בטולטשין","s":"אוצר הרבנים 5846"},{"i":19829,"n":"חיים מטשערניגוב","b":"רב בטשערניגוב-תר\"נ","s":"אוצר הרבנים 5845"},{"i":19830,"n":"חיים מטשרנוביץ","f":"שלמה","dt":"תקעג-ז","dp":"צפת","b":"אב\"ד במוהליב, בוטשאן, קישינוב, טשרנוביץ וגליל בוקובינה, עלה לארץ בשיירת תקלז או סמוך לכך.","s":"אלפסי; פרומקין-תח\"י"},{"i":19831,"n":"חיים מיאנובה","dt":"תרכו","b":"רב ביאנובה,דיין בוורשה","s":"אוצר הרבנים 5831"},{"i":19832,"n":"חיים מינינה וירושלים","f":"יהודה","dt":"תסד","b":"בשנת תכג היה דיין בעיר ינינה(=יאנינה) ביון, (ולפי רוזניס רב הכולל) אחר כך עלה לירושלים, נזכר בשות \"זרע אברהם\" כדיין. היה תלמידו וחתנו של ר שלמה אמריליו בעל \"כרם שלמה\". מתשובותיו בספרי חכמי דורו וביניהם \"כרם שלמה\" לחותנו, \"זרע אברהם\" לר אברהם יצחקי ו\"סם חיים\" לר חיים עשהאל. נפטר צעיר בחיי חותנו.","s":"גליס; אוצר הרבנים 6020; פרומקין-תח\"י; שה\"ג, כנסת ישראל; רוזניס-תורכיה-ד"},{"i":19833,"n":"חיים מירושלים","k":"בעל תוצאות חיים","b":"עלה לירושלים-תק\"ל","s":"אוצר הרבנים 5847"},{"i":19834,"n":"חיים מלבוב","f":"יחיאל מיכל הקדוש","b":"דיין בלבוב, חתם-תקכב עם ר ישכר בער איגרא, ר יחיאל מיכל בריסקר, חתם-תקכו על פסק דין. הסכים על \"כנסת המשנה\".","s":"אוצר הרבנים 5848; בובר-לבוב"},{"i":19835,"n":"חיים מלבוב","f":"מרדכי","dt":"תכד - כ סיון","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה.","s":"מצבות קדש-לבוב"},{"i":19836,"n":"חיים מלבוב","f":"ברוך","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה.","s":"מצבות קדש-לבוב; בובר-לבוב"},{"i":19837,"n":"חיים מלובלין","b":"רב בלובלין-תק\"י","s":"אוצר הרבנים 5849"},{"i":19838,"n":"חיים מלובלין","f":"שמואל","dt":"תסו - י שבט","dp":"לובלין","b":"חתן הגביר ר בנימין וולף הלפרין (המכונה ר\"א ר\"ל). מחכמי לובלין. בנו - הגביר ר אברהם ר חיימש - פרנס ועד ארבע ארצות.","s":"לקורות היהודים בלובלין"},{"i":19839,"n":"חיים מלובלין","f":"בנימין וולף או שמואל","dt":"תסז","dp":"לובלין","b":"מחכמי לובלין. אחיהם של ר נפתלי הירש אב\"ד לובלין, ר אליעזר, ר משה. בניו: ר אברהם פרנס בלובלין, ר שמואל מקוצק, ר יעקב, חתניו: ר\"מ אב\"ד זלחוב, ר פנחס מקוריוו.","s":"לקורות היהודים בלובלין"},{"i":19840,"n":"חיים מליניץ","b":"תלמיד הבעשט. מגיד מישרים בליניץ.","s":"אלפסי"},{"i":19841,"n":"חיים מלעסלא","f":"יואל","k":"חיים בר\"י מלעסלא","bt":"תקנג","dt":"תרה","b":"דיין בלעסלא-תקעג, אב\"ד בבירנבוים, שווערן-מחוז פוזנא. הסכים על \"זבחי רצון\" - קרוטושין תרה.","s":"מתוך קטלוג"},{"i":19842,"n":"חיים ממינקוביץ","k":"אדמור ממינקוביץ","b":"חתן ר שמואל אשכנזי-חתנו של ר יצחק מאיר מזינקוב. אדמור במינקוביץ.","s":"אלפסי"},{"i":19843,"n":"חיים מנדל מפייטירטה","b":"רב ומו\"צ בפייטירטה-תר\"ע","s":"אוצר הרבנים 6476"},{"i":19844,"n":"חיים מנחם מן מוינה ופרג","f":"יצחק","b":"תלמיד בעל מטה משה. חתן ר בנימין אהרן סלניק בעל משאת בנימין ונזכר בספרו. מגדולי חכמי דורו, ר\"מ בפרג, רב בוינה ומדינת אסטרייך-שצז על מקום ר ליב רופא (זקנו של בעל עטרת זקנים). תשובה ממנו בשו\"ת ב\"ח החדשות, הסכים על ש\"ל לשו\"ע. בניו ר נתן נטע מקראקא, - אולי ישראל יצחק, חתנו - ר יצחק מוינה. (יש אומרים שבנו גם ר משה מלבוב - שנפטר תטו). (יש שהחליפו בינו ובין ר מנחם מנדל אוירבך בעל עטרת זקנים).","s":"אוצר הרבנים 6477,13268; בובר-לבוב"},{"i":19845,"n":"חיים מנחם מקושטא","b":"תלמיד ר אליעזר די טולידו, ערך והו\"ל ספר רבו \"משנת רבי אליעזר\"-תריג.","s":"רוזניס-תורכיה-ו"},{"i":19846,"n":"חיים מניישטט","f":"משה","b":"מגדולי חכמי אשכנז,רב בנוישטט-ד'תתק\"פ","s":"אוצר הרבנים 6075 א'"},{"i":19847,"n":"חיים מסאסמקין","b":"רב בסאסמקין(=סאסמקן)-קורלנד.","s":"אובצינסקי-קורלנד"},{"i":19848,"n":"חיים מסופיה","f":"עזרא","b":"גביר בסופיה-תקן, תמך ברבנים ובהדפסת ספרים.","s":"רוזניס-תורכיה-ה"},{"i":19849,"n":"חיים מסטנוב","f":"שלמה זלמן","dt":"תקסה - כו טבת","b":"מקובל,דרשן,רב בסמילוביץ,מגיד בווילנה","s":"אוצר הרבנים 6017"},{"i":19850,"n":"חיים מסטנוב","f":"יוסף מיאמפלי(=ימפולא","k":"אדמור מסטנוב","dt":"תר - ז אייר","b":"נגד המגיד מזלוטשוב. חתן דודו ר דוד מסטעפין. אדמו\"ר בסטאנוב(=סטנוב)-תקפ.","s":"אוצר הרבנים 6089; אלפסי"},{"i":19851,"n":"חיים מסלוצק","dt":"תקצז - ד סיון","b":"רב בסלוצק","s":"אוצר הרבנים 5851"},{"i":19852,"n":"חיים מסמרגן","b":"רב בגליל סמרגן","s":"אוצר הרבנים 5850"},{"i":19853,"n":"חיים מסעוד ממצרים","b":"רב בקהיר-תעו, חיבר דרשות בכת\"י.","s":"מתוך קטלוג"},{"i":19854,"n":"חיים מסעלץ","f":"חנניה","b":"מחכמי סעלץ ומקורב לגדול ממינסק (בשבתו כרב בסעלץ). נקרא בשם \"חריפי פומפדיתא\" יחד עם חברו ר יצחק שרה לאה'ס.","s":"הגדול ממינסק"},{"i":19855,"n":"חיים מסעלץ","f":"מנחם מאניש","b":"רב בסעלץ על מקום אביו. בסוף שנות ה-תק-תר. חיבר כת\"י על חושן משפט.","s":"מתוך קטלוג"},{"i":19856,"n":"חיים מספרד","f":"יעקב","b":"מחכמי ספרד בזמן הרמ\"ה,ממתנגדי ספרי הרמב\"ם","s":"ארזי הלבנון"},{"i":19857,"n":"חיים מפאשטוב","b":"רב בפאשטוב-ליד שוינציאן.","s":"ברוורמן-אנשי שם"},{"i":19858,"n":"חיים מפוזנא (ליפשיץ?)","f":"צבי","k":"בעל סם חיים","b":"דרשן בפוזנא. חיבר \"סם חיים\" - אמשטרדם תנב. (אולי בנו - ר אריה ליב ליפשיץ מדעסוי).","s":"פין-כנסת ישראל"},{"i":19859,"n":"חיים מפוסוואל","f":"אברהם שלמה מפומפיאן","b":"רב בפאסוואל-תקס. אחיו - ר אברהם אבלי מפוסוואל ווילנא.","s":"אוצר הרבנים 5852; שם הגדולים השלישי"},{"i":19860,"n":"חיים מפיליפופולי","b":"רב בפיליפופולי-שפד.","s":"רוזניס-תורכיה-ג"},{"i":19861,"n":"חיים מפינסק","dt":"תקצז - כב אדר","b":"בעל חסד,רב בפינסק, עלה לצפת. (ראה גם ר חיים בן אהרן בעל מנחת אהרן מבריסק - כנראה יש בלבול בין שני רבנים האחד עלה לצפת והשני נפטר בבריסק).","s":"אוצר הרבנים 5855"},{"i":19862,"n":"חיים מפינסק וצפת","f":"אביגדור הכהן","dt":"תקצד","b":"חותנו של ר אברהם אייזנשטיין, עלה עם חתנו בשנת תקפג לצפת, ומונה לחבר בית הדין של קהילת הפרושים. הספידו ר מנחם מנדל מקמניץ בספרו \"קורות העתים\".","s":"גליס; פרומקין-תח\"י; מגדולי ירושלים."},{"i":19863,"n":"חיים מפיסטין","f":"שמואל","b":"רב בפיסטין.","s":"וונדר-גליציה ח\"ו"},{"i":19864,"n":"חיים מפלונסק","b":"תלמיד ר מנחם מנדל מקוצק.","s":"אלפסי"},{"i":19865,"n":"חיים מפרשבורג","dt":"תקלה - כו סיון","b":"דיין בפרשבורג","s":"אוצר הרבנים 5853"},{"i":19866,"n":"חיים מציטוביאן","f":"שמחה","k":"בעל רצון יראים","bp":"ראסיין","b":"מחכמי ציטוביאן."},{"i":19867,"n":"חיים מציפר","dt":"תקפג - כב תשרי","b":"רב בציפר","s":"אוצר הרבנים 5854"},{"i":19868,"n":"חיים מקאוולי ולבוב","f":"משה משלם","b":"מנהיג בועד ארבע ארצות, חתם-תמז ביריד ירוסלב.","s":"בובר-לבוב"},{"i":19869,"n":"חיים מקאסטלאן","b":"תלמיד החת\"ס. רב בקסטלאן-תקץ.","s":"החת\"ס ותלמידיו"},{"i":19870,"n":"חיים מקולומיא","f":"יהושע","dt":"תלג - ט אדר","dp":"לבוב","b":"חתן ר צבי הירש ממזריטש. מראשי ועד דד\"א, רב בקולומייא(=קאלימייא), ר\"מ בלבוב. נזכר ב\"אמונת שמואל\". הסכים על \"לב אריה\"-תלד. בניו - ר אפרים פישל מקולומייא, ר צבי הירש מברזאן ודרוהוביטש.","s":"אוצר הרבנים 5859; מצבות קדש-לבוב; בובר-לבוב"},{"i":19871,"n":"חיים מקומורנא ולבוב","dt":"תעג - אחרי","b":"חתן ר\"י ר מייקש. דיין בלבוב (חוץ לעיר), חתם-תמו בפנקס הקהלה, על פסק דין-תמז, ועוד.","s":"אוצר הרבנים 6141; בובר-לבוב"},{"i":19872,"n":"חיים מקוסוב","dt":"תרלא?","dp":"חיפה","b":"עלה לצפת בשנת תרלג?, נטמן סמוך למערת ר אבדימי דמן חיפה, ובנו ר משה הקים אוהל על קברו.","s":"גליס"},{"i":19873,"n":"חיים מקוסטולאני","b":"רב בקוסטולאני-תק\"פ","s":"אוצר הרבנים 5857"},{"i":19874,"n":"חיים מקושטא","f":"דוד","b":"רב בקושטא-שנות ה-תק' (בזמן ר אליהו פאלומבו).","s":"רוזניס-תורכיה-ה"},{"i":19875,"n":"חיים מקיוסטנדיל","f":"משה","b":"דיין בקיוסטנדיל-תקנו אצל ר יצחק שמואל חרבון, יחד עם ר ציון קובו.","s":"רוזניס-תורכיה-ו"},{"i":19876,"n":"חיים מקמניץ","b":"רב בקמניץ, ובנו ר יוסף ואחריו נכדו ר צבי הירש על מקומו אחריו.","s":"ברוורמן-אנשי שם"},{"i":19877,"n":"חיים מקמפינא וואנדסבק","dt":"תקה - יד אד\"ב","dp":"אלטונא","b":"אב\"ד קעמפען(=קעמפינא), מו\"ץ בואנדסבק.","s":"אוצר הרבנים 5835; דוקס-אוה למושב-ב"},{"i":19878,"n":"חיים מקראקא","k":"בעל מגן אברהם","dt":"תנט - ט תשרי","dp":"קראקא","s":"צונץ-קראקא"},{"i":19879,"n":"חיים מקרוסנא","dt":"תקנג - א-ה אב","dp":"מוהילוב","b":"תלמיד הבעשט, בידידות עם ר פנחס מקוריץ. נפטר בדרכו לארץ. מתורתו \"תורת החסידים הראשונים\".","s":"אוצר הרבנים 6151; אלפסי"},{"i":19880,"n":"חיים מקריפטש","b":"שו\"ב בקריפטש על מקום חותנו ר שלמה - תשובה אליו בשו\"מ.","s":"וונדר-גליציה ח\"ו"},{"i":19881,"n":"חיים מקרסטיר","dt":"תקמא - ל תשרי","b":"רב בקרסטור(=קרסטיר)","s":"אוצר הרבנים 5856"},{"i":19882,"n":"חיים מרדכי מגלינא","b":"רב בגלינא-תרלג.","s":"וונדר-גליציה ח\"ו"},{"i":19883,"n":"חיים מרקיטנא","dt":"תרנט","b":"רב ברקיטנא-תרי\"ט","s":"אוצר הרבנים 5860"},{"i":19884,"n":"חיים משגוביא-ספרד","k":"ר' חיים הארוך","b":"מחכמי שגוביא(ספרד)","s":"ארזי הלבנון"},{"i":19885,"n":"חיים משה הכהן מסעליש","dt":"תריז - יא כסלו","b":"נכד ר יאיר הכהן - רבה הראשון של סעליש. רב בסעליש על מקום ר אליעזר ליפמן שטיין, ור שמואל קליין על מקומו אחריו-תרך.","s":"אוצר הרבנים 6500; גרינוולד-סלובקיה והונגריה"},{"i":19886,"n":"חיים משה הלוי מקודון","b":"רבה האחרון של קודון-יון עד שנת תמה, אז חרבה הקהלה בכיבוש ונציה.","s":"רוזניס-תורכיה-ד"},{"i":19887,"n":"חיים משה מאזמיר","dt":"תקלה - כב שבט","dp":"אזמיר","b":"מחכמי אזמיר.","s":"רוזניס-תורכיה-ה"},{"i":19888,"n":"חיים משה מחווראשץ וקריינק","b":"חתן ר חיים-אביו של ר נתן בעל אבן בחן. מ\"מ ומו\"צ בחווראשץ(=חאראשץ?), קריינק."},{"i":19889,"n":"חיים משה מסטעפין","f":"דוד מסטעפין","dt":"כז תשרי","b":"רב בברזנא, ומגיד מישרים בגריידונג.","s":"אלפסי"},{"i":19890,"n":"חיים משלוניקי","f":"יוסף","dt":"תרן","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי-152"},{"i":19891,"n":"חיים משלוניקי","f":"אליה","b":"מחכמי שלוניקי-שנות ה-ת', עלה לארץ. מתורתו ב\"סם חיי\" לר בנימין עשאל.","s":"רוזניס-תורכיה-ד"},{"i":19892,"n":"חיים משערשוב","b":"חתן ר אשר שארשוב. רב בשארשוב.","s":"ברוורמן-אנשי שם"},{"i":19893,"n":"חיים משצצין","k":"המגיד משצוצין","b":"דרשן,רב בשצוצין","s":"אוצר הרבנים 6190"},{"i":19894,"n":"חיים משקלוב וחברון (מוסייב)","b":"מראשוני חסידי חב\"ד בחברון. (ראה גם: ר משה חיים מחברון)","s":"אלפסי"},{"i":19895,"n":"חיים משקלוב וירושלים","f":"משה","dt":"תקצט - א תמוז","dp":"ירושלים","b":"השוחט הראשון לעדת האשכנזים בירושלים.","s":"פרומקין-תח\"י"},{"i":19896,"n":"חיים ן, אברהם הספרדי","f":"יהודה","k":"בעל ספר על הכנת הזהב","b":"מחכמי ספרד-כב. חיבר ספר על הכנת הזהב, וחיבור על המסורה - שניהם בכת\"י. (ברשימת הכומר די רוסי).","s":"איטליה גירונדי-א סא; אלופי יעקב א-רמ; פין-כנסת ישראל"},{"i":19897,"n":"חיים ן, אברהם מחברון","f":"אהרן - בעל קרבן אהרן","bp":"מצרים","dt":"תך - בערך","dp":"מונסטיר-בסרביה","b":"שליח כולל חברון-שץ. רב במצרים. אחיו - ר דוד מירושלים.","s":"אוצר הרבנים 276, 630; רוזניס-תורכיה-ד"},{"i":19898,"n":"חיים ן, אברהם מקושטא","f":"שם טוב","b":"מחכמי קושטא, מוצאו ממשפחה מיוצאי ספרד. חתם על תשובת הרא\"ם עם חבריו על מינוי ר שאלתיאל הנגיד קהייא. ואולי הוא ר אברהם בן שם טוב הרופא שחיבר ספר רפואה בכת\"י.","s":"אלופי יעקב א-ת; רוזניס-תורכיה-ב"},{"i":19899,"n":"חיים ן, אהרן מחברון","f":"דוד בן אהרן","bt":"שץ","bp":"חברון","dt":"תמח - יב תמוז","dp":"אזמיר","b":"נכד ר אהרן ן חיים בעל \"קרבן אהרן\" ונכד(-אבי אמו) ר אליעזר ן ארחא. דיין בחברון. אירח בביתו של שבתי צבי בהיותו בדרכו בשליחות ירושלים למצרים. בשליחות-תלה חברון באזמיר וכיהן שם כדיין, רב בכיאו(=כיאוס)-תלה, אזמיר (יחד עם ר שלמה הלוי). פסק שלו בספר \"דרכי נעם\", נשא ונתן עם ר חיים אלפנדרי כמובא בספר \"מוצל מאש\" שבסוף ספר \"אש דת\", החליף מכתבים עם ר אברהם אמיגו ועוד. חיבר פירוש על \"עין יעקב\". תשובותיו נמצאות בספרים \"לב שלמה\" לר שלמה בן אהרן הלוי, ב\"כנסת הגדולה\" ועוד. נספה ברעש באזמיר או כיאוס. (אצל גליס נזכר שחיבר קרבן אהרן - וכנראה הכוונה לזקנו).","s":"גליס; אוצר הרבנים 1569; ארזי הלבנון; מוריה 24-ז-ט; פין-כנסת ישראל; רוזניס-תורכיה-ד,ה"},{"i":19900,"n":"חיים ן, אהרן מפאס וירושלים","f":"אברהם בן שמואל","k":"בעל קרבן אהרן","bt":"שד-כ","bp":"פאס","dt":"שצב","dp":"ירושלים או ונציה","b":"תלמיד ר יוסף אלמושנינו, מגדולי חכמי דורו. רב בפאס-שס, דיין אצל ר וידאל הצרפתי, סבב במזרח-שסו, עבר במצרים וכתב בה את רוב חבוריו, ונציה, הסכים שם על ספר \"צידה לדרך\" ונתמנה רב הספרדים שם, עלה לירושלים-שצ, צפת. חיבר גם \"לב אהרן\", ועוד. תשובות ממנו בשו\"ת ר יצחק אלגזי מכיאו, ופסקיו הובאו בספרי חכמי דודו ובמיוחד \"משפטי צדק\" לר מאיר בן שם טוב מלמד, \"כנסת הגדולה\" ועוד. חיבר ספר \"תורת כהנים\" ונציה שמט, \"לב אהרן\" ונציה שמט, ועוד. יש הטוענים כי נפטר בונציה ולא בירושלים. בניו: ר דוד, ר אברהם.","s":"גליס; אוצר הרבנים 1567; גאון-יהודי המזרח; ארזי הלבנון; מוריה 24-ז-ט; מלכי רבנן; פין-כנסת ישראל; רוזניס-תורכיה-ג; פרומקין-תח\"י; רוזניס-תורכיה-ד"},{"i":19901,"n":"חיים ן, ברוך מקושטא - א","b":"אחיו של ר אליהו-מהראנ\"ח. מגדולי הרבנים בקושטא, בתקופת המהרי\"ט, נקרא להיות דיין באיזמיר - ממונה על דיני ממונות (לצדו של ר חיים בנבנישתי הממונה על איסור והיתר) - אך סירב. נזכר ב\"פני משה\", ו\"לחם סתרים\".","s":"אוצר הרבנים 4086; ארזי הלבנון; אלופי יעקב א-תרן; פין-כנסת ישראל; רוזניס-תורכיה-ג,ד"},{"i":19902,"n":"חיים ן, ברוך מקושטא - ב","b":"דיין ביה\"ד האשכנזי בקושטא-תי.","s":"רוזניס-תורכיה-ד"},{"i":19903,"n":"חיים ן, דוד אהרן מחברון","b":"מגדולי חברון-תקצ\"ט","s":"ארזי הלבנון"},{"i":19904,"n":"חיים ן, דוד מירושלים","f":"אהרן - בעל קרבן אהרן","bp":"פאס","dp":"ירושלים","b":"מחכמי ירושלים. אביו בעל \"קרבן אהרן\" עלה לירושלים מפאס-שץ, עם שני בניו ר אברהם ור דוד. אחיו - ר אברהם מחברון. לפי רוזניס היה נכדו של ר אהרן ן חיים.","s":"גליס; אוצר הרבנים 4815; ארזי הלבנון; רוזניס-תורכיה-ד"},{"i":19905,"n":"חיים ן, חיים מדמשק","b":"גביר מחכמי דמשק, תמך בר ישראל נג'ארה. בנו - ר אברהם - נספד מאת ר ישראל נג'ארה.","s":"ארזי הלבנון; רוזניס-תורכיה-ג"},{"i":19906,"n":"חיים ן, יוסף מאלגיר","bt":"תקצט","dt":"תרפז","b":"רב ודיין ורוליזאן-אלגיר.","s":"מלכי ישורון-חכמי אלגיר"},{"i":19907,"n":"חיים ן, יעקב ממראקש - א","b":"מו\"ץ במראקש, חתם על פס\"ד-תסט ונזכר ב\"משפט וצבי\".","s":"מלכי רבנן"},{"i":19908,"n":"חיים ן, יעקב ממראקש - ב","b":"מו\"ץ במראקש, חתם על פס\"ד-תרמח עם ר שלמה אסבאג.","s":"מלכי רבנן"},{"i":19909,"n":"חיים ן, יצחק ממרוקו","f":"שלמה","b":"מחכמי מרוקו - שנות ה-ת'?, מתלמידיו - ר אלעזר בהלול שהביא ממנו בספרו.","s":"מלכי רבנן"},{"i":19910,"n":"חיים ן, יצחק מצפת","b":"מחכמי צפת-ש\"כ","s":"אוצר הרבנים 10667"},{"i":19911,"n":"חיים ן, יצחק משלוניקי וירושלים","b":"מחכמי שלוניקי, דמשק, עלה לירושלים-רנא.","s":"אוצר הרבנים 10654; ארזי הלבנון"},{"i":19912,"n":"חיים ן, לוי אברהם הכהן","k":"בעל לוית חן","bp":"וילפראנס-צרפת","dt":"ה'עה - בערך","dp":"ארלי-צרפת","b":"מגדולי החכמים, חוקר, מהנדס, תוכן, סופר ומחבר, רב בצרפת-ד'תתק\"פ, היה במונטפלייר, נרבונה. זקנו של הרלבג. היה מחלוקת כנגדו בגלל דעותיו ובין מתנגדיו - הרשב\"א.","s":"אוצר הרבנים 12462; גאון-יהודי המזרח"},{"i":19913,"n":"חיים ן, מרדכי מאלגיר","bt":"תרי","dt":"תרף","b":"רב במסתגאנם-תרן, תמושנת-אלגיר-תרסה.","s":"מלכי ישורון-חכמי אלגיר"},{"i":19914,"n":"חיים ן, שלמה","f":"יצחק","b":"נזכר בתשובה-תנה.","s":"ארזי הלבנון"},{"i":19915,"n":"חיים ן, שלמה מאדרינופול","b":"רב באדרינופול-שנות ה-ר'.","s":"רוזניס-תורכיה-ב"},{"i":19916,"n":"חיים ן, שלמה מאלגיר","f":"חיים","k":"בעל שבח תודה","bt":"[תקע]","dt":"תרל - בערך","b":"כנראה מחכמי והראן-אלג'יר. חיבר ספר \"שבח תודה\" והוא שירים ופיוטים ליום פורים קטן - לזכר הצלת הקהלה-תקץ.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":19917,"n":"חיים ן, שלמה ממרוקו","dt":"תרפט - כה תשרי","dp":"מראקש","b":"מקובל ואב\"ד במראקש.","s":"ארזי הלבנון"},{"i":19918,"n":"חיים ן, שמואל","b":"החכם השלם בפאס","s":"אוצר הרבנים 19181"},{"i":19919,"n":"חיים נחמן (נחום) פרנס מוילנא","f":"משה פרץ מדובנא","dt":"תריד - ח ניסן","dp":"וילנא?","b":"מצאצאי ר חיים רפפורט מלבוב. חתן ר אפרים זלמן מרגליות מברודי, ובזיוו\"ש חתן ר ליבעלי ר בערש, וגיסו של ר יחזקאל לנדא מוילנא. גביר פרנס וגבאי צ\"ג בוילנא. חתם על כתבים שונים של הקהלה ועל הסכמות שונות. מתורתו ב\"קונטרס אחרון ל\"שאגת אריה\". ממקבלי פניו של מונטיפיורי בוילנא. בניו: ר אברהם פרנס, ר אליהו מפולוצק. חתניו: ר לוי זקהיים, ר אהרן משה פדובה בעל \"ביאורי הרא\"ם\". דודו - ר אברהם אריה מלויצק.","s":"אוצר הרבנים 6517; עיר וילנא ח\"א; שם הגדולים השלישי"},{"i":19920,"n":"חיים נטע","dt":"תרלט - כח כסלו","b":"רב בראזדיל","s":"אוצר הרבנים 6519"},{"i":19921,"n":"חיים נסים הכהן מירושלים","dt":"תקנו - יח אייר","dp":"ירושלים","b":"מחכמי ירושלים בזמן ר יום טוב אלגזי, ונזכר ב\"תבואות הארץ\", בשנת תקלז חתם על תקנת העזבונות, בשנת תקל על מכתב עזרה לקהלה, ועל מכתב שליחות ר יום טוב אלגזי ור יעקב חזן, על כתב שליחות ר אברהם ריוח-תקלא.","s":"גליס; אוצר הרבנים 6523; פרומקין-תח\"י; רוזניס-תורכיה-ה; ירושלים לזכר לונץ, תחי"},{"i":19922,"n":"חיים נסים מניש","b":"דיין מחכמי ניש-תקן בערך.","s":"רוזניס-תורכיה-ה"},{"i":19923,"n":"חיים נתן מדלטין","b":"רב בדלטין-תרן.","s":"וונדר-גליציה ח\"ו"},{"i":19924,"n":"חיים סגל מוירונה","f":"אליעזר","b":"רב בוירונה בזמן ר\"מ בסאן תשובה ממנו ב\"פלגי מים\" בענין המקוה ברוויגו.","s":"איטליה גירונדי-ח יד"},{"i":19925,"n":"חיים סנדר מנישוויעז","b":"רב בנישוויעז","s":"אוצר הרבנים 6533"},{"i":19926,"n":"חיים עובדיה מאדרינופול","b":"רב קהלת גרוש קשטיליה באדרינופול - בדור שאחר הגירוש וקרובו ר יעקב עובדיה על מקומו אחריו. (ראה גם: חיים עובדיה די בושאל).","s":"רוזניס-תורכיה-ב,ג"},{"i":19927,"n":"חיים עובדיה מאדרינופול","b":"מראשי קהלת אדרינופול, חתם-תקצה על בקשת עזרה לקהלה מקהלת רוסג'וק לאחר השריפה עם הרבנים ר יוסף בכמוהר\"ר מרדכי ור יקיר אשטרוק גירון, ועם משה אלפאסה, נסים יוסף פיזה, אהרן רודריג ויהודה בן יצחק.","s":"רוזניס-תורכיה-ו"},{"i":19928,"n":"חיים עוזר הכהן מקרמניץ","f":"משה","k":"בעל באר מים חיים","b":"תלמיד הקלויז בברוד. מגיש מישרים בעיר חדש. חיבר גם \"מקור החכמה\", \"נחל אשכול\".","s":"אלפסי"},{"i":19929,"n":"חיים עוזר מברוד","f":"משה הכהן","k":"בעל נחל אשכול","bt":"תקכ","bp":"קרמניץ","dt":"תקף","b":"רב בברודי. חיבר \"נחל אשכול\" ברין תקסט, \"מקור החכמה\" וארשא תקעה, ועוד.","s":"וונדר-גליציה ח\"ב"},{"i":19930,"n":"חיים עמרם מצפת","b":"סופר קהלת צפת-תקט. נזכר ב\"עין משפט\", ו\"בית דין של שלמה\".","s":"רוזניס-תורכיה-ה"},{"i":19931,"n":"חיים פיבל מבומססלא","f":"דוד זכריה מנדלן","k":"בעל ביאור לתרגום","dt":"תה","b":"חתן השל\"ה. רב בבומסלא-ש\"פ,קומויא","s":"אוצר הרבנים 6540; פרומקין-תח\"י"},{"i":19932,"n":"חיים פיבל מקמניץ","f":"שמשון מבריסק","dt":"תקצה - כו-ח אב","b":"תלמיד החוזה מלובלין, היהודי הקדוש מפשיסחא, ור שמחה בונם מפשיסחא. גביר מחכמי וארשא, ומחשובי החסידים שם. השפיע על בעל חדושי הרי\"ם וקרבו לחסידות פשיסחא.","s":"אוצר הרבנים 6541; אלפסי"},{"i":19933,"n":"חיים פלטיאל","f":"(ברוך)","b":"מגדולי הראשונים, פוסק, פייטן, מרביץ תורה במגדנבורג-שנת ה'ן' - בזמן ר מאיר בן ברוך. חיבר פיוט למתן תורה ועוד.","s":"אוצר הרבנים 6543; פין-כנסת ישראל"},{"i":19934,"n":"חיים פנחס הכהן מירושלים","k":"בעל ניב הלולים","bp":"ירושלים","b":"מחכמי ירושלים."},{"i":19935,"n":"חיים פרץ מקושטא ומצרים","dt":"תיד","dp":"קושטא","b":"ג'יליבי במצרים-תיג על מקום ר אברהם אלכולי. נהרג עם המשנה למלך במצרים בידי השולטן בקושטא.","s":"רוזניס-תורכיה-ד"},{"i":19936,"n":"חיים צבי הירש מווהנילוב","b":"רב בוווהנילוב - תשובה אליו \"בית שלמה\"-תרג.","s":"וונדר-גליציה ח\"ו"},{"i":19937,"n":"חיים צבי מטאוויאן","f":"מאיר","b":"אב\"ד טאוויאן-פלך קובנא."},{"i":19938,"n":"חיים צבי מקאליש","b":"רב בזאוואכיסט,קאליש-ת\"ר","s":"אוצר הרבנים 6546"},{"i":19939,"n":"חיים צבי מקרמניץ","b":"מו\"צ בקרמניץ-תק\"ע","s":"אוצר הרבנים 6545"},{"i":19940,"n":"חיים קאפיקש מאוסטרהא","dt":"קכז - י אייר","dp":"אוסטרהא","b":"דיין באוסטרהא בזמן ר אברהם משלם זלמן שהספידו בספרו \"דברי רב משלם\".","s":"אוסטרהא קיט"},{"i":19941,"n":"חיים ר טויבי'עס מוילנא","dt":"תרל - לפני","b":"מו\"צ בוילנא בזמן כהונת ר יחזקאל לנדא כראב\"ד.","s":"עיר וילנא ח\"א"},{"i":19942,"n":"חיים רבי מעשיל","b":"רב בלובלין. בנו ר שמשון מטרניגרד. ונינו ר יהושע השל מאפטא.","s":"אוצר הרבנים 6077,6506"},{"i":19943,"n":"חיים רפאל אברהם מירושלים","f":"אשר","dt":"תקלב - יח אב","dp":"ירושלים","b":"מקובל מחכמי ירושלים, ראש ישיבת \"יפאר ענוים\" בירושלים-תקיח, בשנת תצד בשליחות בקושטא, הדפיס שם \"שערי קדושה\" לר חיים ויטאל מתוך כתב יד שמצא במצרים בשנת תצד.היה בשליחות במצרים ובאירופה עם ר יצחק זרחיה אזולאי. בשנת תקב היה בבורדו, בתקג בליוורנו, בתקד בטורינו, ובתקט שוב בירושלים, משפחת פראנקו מאטליה נדברו ליסוד ישיבה בירושלים בשם \"יפאר ענוים\", והעמידו את ר חיים בראשה. בשל הצרות נמלט עם הרבה מבני הקהילה למצרים. חתם על תקנות שונות בירושלים ובכללם תקנת הרווקים. הסכים על ספר \"שער יוסף\". נבחר ל\"ראשון לציון\" לאחר פטירת ר מיוחס בכר שמואל.","s":"גליס; אוצר הרבנים 6574,17844; פין-כנסת ישראל; גאון-יהודי המזרח; ארזי הלבנון; פרומקין-תח\"י; א.י. כץ ספונות ט, הראשונים לציון, בניהו ספר החידא ועוד."},{"i":19944,"n":"חיים רפאל ברוך מניש","b":"דיין מחכמי ניש-תקן בערך.","s":"רוזניס-תורכיה-ה"},{"i":19945,"n":"חיים רפאל הלוי מבוסניה וירושלי","f":"אברהם","dt":"תקנד - כה אלול","dp":"ירושלים","b":"מחכמי בוסניה, עלה לירושלים.","s":"פרומקין-תח\"י"},{"i":19946,"n":"חיים רפאל מאילוקסט","b":"שו\"ב באילוקסט-תקצה על מקום ר שלמה ויליזער ור אלימלך בן אריה על מקומו אחריו.","s":"אובצינסקי-קורלנד"},{"i":19947,"n":"חיים שבתי","f":"שבתי","k":"בעל תורת חיים,מהרח\"ש","bt":"שטו - לפני","bp":"שלוניקי","dt":"תז - יג ניסן","dp":"שלוניקי","b":"תלמיד ר אהרן ששון. מרביץ תורה, דיין, ראש ישיבת \"שלום\"-שעה, רב ראשי בשלוניקי-שצט-ת על מקום ר יעקב רוביו, ולצדו היו רבני הכולל: ר אשר ן ארדוט, ר אברהם מוטאל, ור מרדכי קלעי. חיבר שו\"ת \"תורת חיים\". מתלמידיו: ר עזריה יהושע אשכנזי מאזמיר, ר אליהו אלפנדרי בעל \"אליהו רבא\", ר אהרן קופינו מקושטא, ר שלמה אביוב מאישקופיה, ר עזריאל בן מאיר סגל מבלגרד, ר יהושע חנדלי מצפת, ר יעקב טרשה ור משה הכהן מרודוס. בניו: ר יוסף, ר דוד, ר שבתי, ר משה-על מקומו אחריו. השיב לשאלות ממקומות רבים ובהם מברזיל.","s":"אוצר הרבנים 6577; ארזי הלבנון; זכרון שלוניקי; מלכי רבנן; פין-כנסת ישראל; יומא דהילולא","bk":[["תורת חיים [מהרח\"ש]","שו\"ת - אחרונים"],["תורת חיים [שו\"ת] (מהרח\"ש)",""],["מהרח\"ש, שו\"ת תורת חיים",""],["מהרח\"ש",""],["תורת חיים",""]],"e":"שי\"ז~-ת\"ז"},{"i":19948,"n":"חיים שבתי צבי מירושלים","dt":"תרל - כד תמוז","dp":"ירושלים","b":"מחכמי ירושלים.","s":"פרומקין-תח\"י"},{"i":19949,"n":"חיים שטמפי מפרשבורג","f":"יחיאל מיכל משטאמפן","k":"חיים מיכל'ס","dt":"תקלא - כו סיון","dp":"פרשבורג","b":"גביר אמיד ודיין בפרשבורג. חתנו - ר אפרים אפגער מפרשבורג. אחיו - ר קלמן.","s":"פרשבורג-וינגרטן; אבני בית היוצר-וייס; שטמפן - הרצוג"},{"i":19950,"n":"חיים שלום הכהן ממודנא","b":"רב במודנא-תקסט. היה מעורב במחלוקת בענין גילוח בחול המועד יחד עם ר דוד זינצהיים ור ישמעאל הכהן ממודנא.","s":"מתוך קטלוג"},{"i":19951,"n":"חיים שלום מירושלים","f":"בנימין מעלי הכהן","b":"דיין,שד\"ר ירושלים לקושטא-ת\"פ,שד\"ר למצרים,חיבר ביאור לרמב\"ם","s":"ארזי הלבנון"},{"i":19952,"n":"חיים שלום מקושטא","b":"גביר מחכמי קושטא-ש'. סייע בהדפסת ספרים.","s":"רוזניס-תורכיה-ב"},{"i":19953,"n":"חיים שלמה הלוי מירושלים","dt":"תקצה? - כסלו","dp":"ירושלים","b":"מחכמי ירושלים. חתם-תרב בהסכמה על דפוס בק, הגכים על \"תפלת ישראל\"-תרב. (התאריכים לא מסתדרים - ראה גם: ר חיים דוד שלמה הלוי, ור שלמה הלוי).","s":"פרומקין-תח\"י"},{"i":19954,"n":"חיים שלמה זלמן מממיר","b":"מצאצאי ר דוד ממיר. רב במיר. בנו - ר בצלאל נפתלי ברסלר מסעלץ.","s":"ברוורמן-אנשי שם"},{"i":19955,"n":"חיים שמואל הלוי מירושלים ויון","k":"בעל אור החשמל","bp":"ירושלים","b":"מחכמי ירושלים, בשליחות ביון, ובשנת תרטו התמנה לרב ביאנינה (יון). חתם-תקפו עם חכמי צפת על כתב שליחות ר מסעוד פינטו?","s":"גליס; ארזי הלבנון; שריד ופליט, שא\"י"},{"i":19956,"n":"חיים שמואל מאזמיר","b":"דיין באזמיר, חתם-תרכח על שטר עם ר ישעיה יוסף פונטרימולי.","s":"מתוך קטלוג"},{"i":19957,"n":"חיים שמואל מקושטא","b":"תלמיד ר רפאל יעקב אסא, ר מיכאל אשכנזי, דיין בקושטא-תקסו אצל ר אליהו פאלומבו. (יתכן שהוא שנקרא אצל רוזניס גם שמואל חיים והיה אב\"ד בקושטא במגרש חאסקיואי?)","s":"רוזניס-תורכיה-ו"},{"i":19958,"n":"חיים שמחה משטאבין","b":"רב בטשאבין(=שטאבין). חתנו - ר משה גרשון מובשוביץ מדובראווא.","s":"אוצר הרבנים 6597; אהלי שם"},{"i":19959,"n":"חיים שמעון דב מסמילוביץ","f":"אריה ליב","k":"בעל שבעים תמרים","b":"רב בסמילוביץ, חארקי-תרכב.","s":"אוצר הרבנים 6598א"},{"i":19960,"n":"חיים שמש מוילנא","f":"יהודה ליב","dt":"תקנה - יג תשרי","dp":"וילנא","b":"מחכמי וילנא, בשליחות הקהלה באשכנז ופגש את ר יונתן איבשיץ בהמבורג.","s":"פין-קריה נאמנה"},{"i":19961,"n":"חיים ששון משלוניקי","dt":"שעז - יד אלול","dp":"שלוניקי","b":"נהרג עק\"ה בהריגת פולוג'י?","s":"מולכו-שלוניקי-ג; עמנואל-שלוניקי"},{"i":19962,"n":"חיים, אליהו עבדאלה מבגדד","f":"משה חיים עבדאלה","bt":"תקסג","dt":"תריט - ז אלול","dp":"בגדד","b":"אביו של ה\"בן איש חי\". מקובל, בעל חסד, דרשן בבגדד על מקום אביו, ומראשי הקהלה.","s":"אוצר הרבנים 2170; ארזי הלבנון"},{"i":19963,"n":"חיים, אליעזר","b":"רב בטהראן","s":"ארזי הלבנון"},{"i":19964,"n":"חיים, אנג'יל משלוניקי","f":"חיים","k":"בעל עץ חיים","dt":"תצג - ז אדר","dp":"שאלוניקי","b":"מחכמי שלוניקי. חיבר דרשות והספדים וטעמי מצוות בשם \"עץ חיים\".","s":"ארזי הלבנון; זכרון שלוניקי-70"},{"i":19965,"n":"חיים, דוד מבגדד ורמת גן","f":"יעקב","dt":"תשמב","dp":"רמת גן","b":"נכד ה\"בן איש חי\", דרש במקומו בארבע שבתות בשנה, פוסק, הוציא לאור מכתבי סבו, עלה לא\"י-תשל\"ב(דרך אנגליה)","s":"ארזי הלבנון"},{"i":19966,"n":"חיים, דוד משלוניקי","f":"משה חיים משלוניקי","dt":"תקה","dp":"שלוניקי","b":"גביר בשלוניקי. בנו של הרב הכולל.","s":"זכרון שלוניקי-93"},{"i":19967,"n":"חיים, יוסף שלום מבגדד וחברון","f":"עבדאלה בן משה חיים","bp":"בגדד","dt":"תרנז","dp":"דמשק","b":"עלה עם אביו לירושלים, פעיל צבור, משגיח על קופת כוללות חברון-תריד, היה במחלוקת בעניני הכוללות, נאלץ לברוח בגלל הלשנה והתישב בדמשק. בן דודו של ה\"בן איש חי\".","s":"גאון-יהודי המזרח"},{"i":19968,"n":"חיים, יעקב מבגדד","f":"יוסף חיים-בן איש חי","k":"בעל קול יעקב","bt":"תרכא","b":"מקובל, רב בבגדד-תרע על מקום אביו. הו\"ל את ספרי אביו.","s":"אוצר הרבנים 9363; אהלי שם"},{"i":19969,"n":"חיים, משה מבגדד - הנכד","f":"אליהו","bt":"תקצח","bp":"בגדד","dt":"תרסב - כב תמוז","b":"אחיו של ה\"בן איש חי\". מוהל מחכמי בגדד, ובנו ר בנימין המשיך אחריו. תשובה ממנו בשו\"ת ר אליהו מני - בכת\"י.","s":"ארזי הלבנון"},{"i":19970,"n":"חיים, משה עבדאלה מבגדד - הזקן","f":"חיים בן משה עבדאללה","bt":"תקי או תקטז","dt":"תקצז-ט","b":"זקנו של ה\"בן איש חי\", הגיע מבצרה לבגדד לשמש כרב, והעמיד תלמידים הרבה. הנהיג שמנהגם יהיה כדברי החיד\"א וייחשב לרבם המובהק. מתלמידיו - ר דוד נאוי בעל \"יחי ראובן\", ר אליהו יהושע עובדיה בעל \"שיחת דקלים\", ר יעקב יוסף הרופא, ור עבדאללה סומך בעל \"זבחי צדק\". תלמידו ר ראובן נאווי כיהן כראש הדיינים אצלו. מתורתו בספר נכדו \"רב פעלים\" ושם מסופר כי הוא תיקן את ענין התפלין בבגדד שהיה שם מנהג טעות ותקנו.","s":"אוצר הרבנים 15383; ארזי הלבנון"},{"i":19971,"n":"חיים, נסים מבגדד","f":"אליהו בן משה חיים","dt":"תקץ - ניסן","b":"אחיו של הבן איש חי. מחכמי בגדד.","s":"ארזי הלבנון"},{"i":19972,"n":"חיים, רפאל אברהם מכלוף מירושלי","b":"מחכמי ירושלים. הסכים על \"דברי שלום\" ירושלים תרג. חתם-תקצו על כתב מינוי ר יונה נבון. (נקרא בטעות חייאט במקום חיים).","s":"ארזי הלבנון; פרומקין-תח\"י"},{"i":19973,"n":"חיימוביץ, איתמר מזאלוזיץ","dt":"תשג","b":"רב בזאלוזיץ","s":"אוצר הרבנים 3633"},{"i":19974,"n":"חיימוביץ, אלחנן דוב משיקגו","bt":"תרל","dt":"תרצב - טז טבת","b":"רב בשיקאגו-תרס\"ז","s":"אוצר הרבנים 2025"},{"i":19975,"n":"חיימוביץ, אריה ליב משיקגו","dt":"תשכז","b":"רב בשיקאגו","s":"אוצר הרבנים 3298"},{"i":19976,"n":"חיימוביץ, חיים יהודה מסערעקופ","f":"סעדיה הלוי","b":"רב בסערעקופ."},{"i":19977,"n":"חיימוביץ, ישראל ליב ממיטאוי","f":"אליעזר אלתר","bt":"תקפט","dt":"תרמא - כז כסלו","b":"לאחר שנתייתם גדל אצל זקנו(-אבי אמו) ר שמואל כץ. מחכמי וילק, בזיוו\"ש חתן ר יעקב בנדטמן מבויסק בעל \"זכרון יעקב\" - שהזכירו בספרו. רב במיטאוי-תרכב. חתניו - ר ליב שוחט מזאגר.","s":"אובצינסקי-קורלנד"},{"i":19978,"n":"חיימוף רבין, חזקיה הכהן מבוכרה","f":"יצחק חיים","bt":"תרלב","bp":"בוכרה","dt":"תשה - טו טבת","dp":"ירושלים","b":"רבה של בוכארה על מקום אביו-תרנו, עלה לארץ-ניסן תרעא, חזר לבוכרה-תרעב, אחיו נרצחו במהפכה-תרעז, ברח לאפגניסטן-תרץ, עלה לארץ-ניסן וכיהן כרבה של העדה הבוכרים בירושלים.","s":"אוצר הרבנים 5821; גאון-יהודי המזרח; ארזי הלבנון"},{"i":19979,"n":"חיימוף, יהודה ארי מירושלים","b":"רבה של העדה הבוכרית בירושלים,למד בישיבת \"פורת יוסף\",תלמיד ר' יוסף ידיד הלוי,דיין-תש\"ז,מגיד בישיבת הערב \"מגדל דוד\"","s":"ארזי הלבנון"},{"i":19980,"n":"חיימוף, שמחה מבוכרה","dt":"תרצו - שמחת תור","dp":"ירושלים","b":"מחכמי בוכרה, עלה לירושלים, תלמיד ר יוסף ידיד הלוי. שו\"ב בירושלים. נפטר צעיר.","s":"ארזי הלבנון"},{"i":19981,"n":"חיימזון, משה חיים מלונדון","f":"נתן","bt":"תרכד","b":"מו\"צ בלונדון-תרסד.","s":"אוצר הרבנים 15391; אהלי שם"},{"i":19982,"n":"חיינא, יצחק מירושלים","b":"מחכמי ירושלים, נזכר במכתב הנוסע האלמוני משנת רפב.","s":"גליס; רוזניס-תורכיה-ב; פרומקין-תח\"י"},{"i":19983,"n":"חיינא, שמואל ממצרים","b":"מחכמי מצרים בדור שלאחר הרדב\"ז.","s":"רוזניס-תורכיה-ב"},{"i":19984,"n":"חייקא","b":"רב בהארובאשוב-ש\"ל","s":"אוצר הרבנים 6614"},{"i":19985,"n":"חייקין, דובער מרדכי","f":"שמואל מדוברובנא","k":"בעל מאמר מרדכי -כת\"י","bt":"תרכג","bp":"ויטבסק","b":"נכד-אבי אמו ר חיים אריסקער משקלוב מצאצאי ר ליב-חתן המהר\"ל. תלמיד ר אברהם עטינקוף מניעזין וויטבסק. רב בקאבאק דפלאצק-פלך ויטבסק-תרנג. נסמך מאת: ר אברהם עטינקוף, ר יצחק אלחנן מקובנא, ר אלעזר ברכהן מפלאצק, ר צבי הירש רבינוביץ מקובנא. חיבר גם \"מיני תרגמיא\" על אגדות חז\"ל - בכת\"י.","s":"אוצר הרבנים 4628; אהלי שם"},{"i":19986,"n":"חייקין, ישראל שרגא מפטרבורג","b":"שו\"ב בפטרבורג כ-50 שנה. בנו - ר משה אביגדור מלונדון.","s":"אהלי שם"},{"i":19987,"n":"חייקין, משה אביגדור מלונדון","f":"ישראל שרגא מפטרבורג","k":"בעל התנצלות היהודים","bt":"תרח או תריב","bp":"שקלוב","dt":"תרפח","dp":"תל אביב","b":"מצאצאי ר חיים חייקל מאמדור, ור אביגדור מראזינאי-אביו של ר שמואל אביגדור מוילנא. חתן ר שלמה זלמן פינסקר מחרסון. נסמך מאת: ר יצחק אלחנן מקובנא, ר אברהם שמואל דיסקין, ר יקותיאל זלמן לנדא מפטרבורג. רב בפאריס-תרמד, רוסטוב-תרמח, שפילד-אנגליה-תרנב, לונדון-תרסב. בשנת תרפו עלה לתל אביב. חיבר ספרים באנגלית בהסכמת ר נפתלי אדלר, חיבר ספר על עלילות הדם בשם \"התנצלות היהודים\", \"תשועת ישראל\".","s":"גליס; אוצר הרבנים 15232; אהלי שם; דור וחכמיו-א\"ש-ו; שם הגדולים השלישי"},{"i":19988,"n":"חייקין, צבי הירש","dt":"תרמג","dp":"ירושלים","b":"חסיד חב\"ד. כתב מכתבים-1876 אל ר לוי יצחק (שניאורסון?) ובו סיפר ששמע על חזרתו בתשובה של ר משה מליאובה (בנו המומר של בעל התניא), עלה לארץ עם בנו ר יואל מאיר.","s":"אסף-נאחז בסבך"},{"i":19989,"n":"חייקין, שמעון מנשה מסלוצק חברו","f":"משה","bt":"תקמז","bp":"שקלוב","dt":"תרנג","dp":"חברון","b":"חסיד ר דובער מליובאויטש. עלה לארץ עם העליה החבדית הראשונה-תקעט התישב בצפת ועבר לחברון-תקפג, מראשוני חסידי חבד בארץ ישראל. ושימש כרב קהילת חבד בחברון קרוב לשבעים שנה. בשנת תקצט חתם על האגרת למונטיפיורי. נפטר בגיל מאה ושש עשרה שנה. חתנו - ר אהרן מאיר בן ברוך בנדט בן ר אליהו קאליקולר.","s":"גליס; אוצר הרבנים 19972; אלפסי"},{"i":19990,"n":"חילו, יצחק מספרד וירושלים","f":"יוסף","k":"בעל שבילי ירושלים?","bp":"ארגון (ספרד)","b":"מחכמי לארידה-ארגון-ספרד וידוע כמקובל, עלה לירושלים-צג(1333), וכתב מכתבים לאביו וחבריו בספרד. יש הטוענים שחיבר \"שבילי ירושלים\" אך לדעת ג. שלום ולדעת איש שלום ב\"תרביץ\" תרצה המדובר בזיוף. בשנים פה-פח העתיק כתב יד חשוב בקבלה (נמצא בספריית פירנצי).","s":"גליס; אוצר 10666; ארזי הלבנון"},{"i":19991,"n":"חימי, יחיא מסאלי","f":"פנחס","b":"רב בסאלי-שנות ה-תק'. חיבר חדושים על הש\"ס.","s":"מלכי רבנן"},{"i":19992,"n":"חכים הפייטן","b":"פייטן מחכמי וורמייזא. חיבר סליחה \"איה קנאת וגבורתך\". אולי הוא שנהרג עק\"ה עם בניו בוורמייזא-ד'תתנו, והיה גם חכים בשנת ה'ן ונזכר ב\"אור זרוע\".","s":"פין-כנסת ישראל"},{"i":19993,"n":"חכים, חסדאי בכור","b":"מחכמי ורבני איזמיר","s":"ארזי הלבנון"},{"i":19994,"n":"חכים, יוסף הלוי מקושטא","b":"מדפיס בקושטא, אולי קרובו או יורשו של המדפיס - ר יצחק אלחכים.","s":"רוזניס-תורכיה-ב"},{"i":19995,"n":"חכים, יוסף יהודה מצפת","dt":"תרנו - יח כסלו","b":"ראש רבני צפת. חתם על כתב שליחות-תרכז ר יצחק מזרחי, ועל שליחות ר יעקב חיון-תרלז.","s":"אוצר הרבנים 8821"},{"i":19996,"n":"חכים, משה מירושלים","b":"מחכמי ירושלים, סבל מאבן פארוך בשנת שפה.","s":"גליס"},{"i":19997,"n":"חכים, רפאל שלמה מקהיר","k":"בעל קשר אמיץ","b":"מלמד עברית בקהיר. חיבר \"קשר אמיץ\" - הלכות שחיטה, קהיר תשז."},{"i":19998,"n":"חכים, שלמה מאזמיר","k":"בעל כסא שלמה","bt":"1770?","dt":"תקצח - יט סיון","b":"רב באזמיר. ותיקן תקנות רבות. מתורתו בספרי חכמי דורו ובהם ר חיים פלאג'י שגם הספדיו. חיבר גם \"מלאכת שלמה\".","s":"אוצר הרבנים 18446; ארזי הלבנון; ראה ערך מלאכת שלמה; קובץ בית אהרן וישראל קו' י' עמ ז'","bk":[["כסא שלמה",""],["מלאכת שלמה","מפרשי רמב\"ם"],["מלאכת שלמה [על רמב\"ם]",""],["כסא שלמה - דרוש",""],["מלאכת שלמה – רמב\"ם",""]]},{"i":19999,"n":"חכים, שלמה רפאל מצפת","f":"יוסף יהודה","dt":"תרסח - א אב","b":"רב בצפת. נזכר ב\"המאסף\".","s":"אוצר הרבנים 18894; ארזי הלבנון"},{"i":20000,"n":"חכים, שמואל מאזמיר","b":"רב באזמיר-תקפז עם ר דוד אמאדו, ר יצחק נבארו ור שלמה בכר,","s":"רוזניס-תורכיה-ו"},{"i":20001,"n":"חכים, שמואל מאלגיר","b":"תלמיד ר אברהם בן נתן הספרדי - בכללי העיבור. דיין בברשך, תנס-אלגיר (לא תוניס), בזמן הריב\"ש והרשב\"ץ, והתכתב עמם. עזב את ברשך בגלל מחלוקת עם ר שמואל חלאיו בברשך (שהתלונן על ר שמואל חכים במכתבו לרשב\"ץ, ובו מתלונן כי הרב חכים מסרב ללמדו עניני המולד והלוח שלמד אצל ר אברהם בן נתן - ונזכר בתשב\"ץ). כנראה הגיע לתורכיה להדפיס את שו\"ת הריב\"ש והשתקע שם.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":20002,"n":"חכים, שמריה משלוניקי","b":"מגדולי חכמי שלוניקי-שפ.","s":"אוצר הרבנים 20014; ארזי הלבנון"},{"i":20003,"n":"חכם ן, שמואל הלוי","k":"ראה: חקאן","dt":"רצו","b":"מגדולי חכמי ספרד בתקופת הגירוש,פוסק,מרביץ תורה בא לשלוניקי","s":"אוצר הרבנים 19182; רוזניס-תורכיה-א,ב"},{"i":20004,"n":"חכם צבי, אפרים","f":"נתן אשכנזי מברוד","bt":"תנ","dt":"תקלח - י שבט","b":"רב בברוד","s":"אוצר הרבנים 3030"},{"i":20005,"n":"חכם שמעון בן אליהו","f":"אליהו","bt":"תרג","bp":"בוכרה","dt":"תרע","dp":"ירושלים","b":"מחכמי בוכרה, עלה לירושלים-תרל, והיה מנהיג העדה הבוכרית בירושלים. תרגם ספרים לפרסית יהודית ובהם התנ\"ך, והו\"ל ספרים בפרסית יהודית מתוך כתבי יד.","s":"גליס; גאון-יהודי המזרח; ארזי הלבנון; היברובוקס","bk":[["חוקת הפסח כולל לימוד כל חדש ניסן בשפת פרסי",""]]},{"i":20006,"n":"חכם, אברהם מירושלים","f":"עזריה","bp":"סננדג'(סינה)","dt":"תשכה - א אלול","dp":"ירושלים","b":"רב בכרמנשה-תרע\"ב, ירושלים-תרצ\"ו, ראש ישיבת \"מגן אברהם\"","s":"ארזי הלבנון"},{"i":20007,"n":"חכם, פנחס מפרס","f":"שמעון","k":"בעל זכר צדיק","b":"רב בפרס.","s":"ארזי הלבנון"},{"i":20008,"n":"חכם, שם טוב מאלקוליעא","b":"רב באללקוליעא בזמן הריב\"ש והשיב לו בספרו.","s":"ארזי הלבנון"},{"i":20009,"n":"חכמדס, קלמן","dt":"תשג","b":"רב בקאטוביץ","s":"אוצר הרבנים 17630"},{"i":20010,"n":"חכמון ן, ישמעאל מאיטליה","b":"מגדולי חכמי איטליה-ת\"פ","s":"אוצר הרבנים 11642"},{"i":20011,"n":"חכמון ן, ישמעאל מטריפולי","bt":"רס","dt":"של - בערך","b":"מחכמי טריפולי. מתורתו ב\"קונטרס חדושים על הרמב\"ם מגאונים קדמונים\" בתוך \"מעשה רוקח\" ונציה תקב.","s":"מלכי חי\"ל-מרציאנו"},{"i":20012,"n":"חכמון ן, ישראל מטריפולי","b":"רב בטריפולי. חדושים ממנו בקונטרס חדושים על הרמבם מגאונים קדמונים - תקב.","s":"ארזי הלבנון"},{"i":20013,"n":"חכמון, יצחק מלוב - \"דיבורא\"","bt":"תרל","dt":"תש - בערך","b":"מו\"ץ במצראתה.","s":"מלכי חי\"ל-מרציאנו"},{"i":20014,"n":"חכמון, עמאר מטריפולי","dt":"תנט","b":"דיין בטריפולי, מראשוני הדיינים הידועים משם. נזכר ב\"ימות עולם\"-בכת\"י לר אברהם כלפון.","s":"מלכי חי\"ל-מרציאנו"},{"i":20015,"n":"\"חכמי לוניל היו בשנות ד'תתקנ","bk":[["חכמי לוניל [ראה נספח ח]",""]]},{"i":20016,"n":"חכמי לוניל המופיעים ברשב\"\"א היו בשנות ה'נ.\"","dt":"ד'תתקנ","b":"ר\"י הזקן נקרא גם על שם מקומו: ר\"י הזקן מדנפירא. החידושים שנדפסו עמ\"ס קידושין בגליון ש\"ס וילנא תחת השם \"תוס' ר\"י הזקן\", אינם ממנו (ידיעות נכבדות [בתחילת קובץ הערות] של ר' אלחנן וסרמן), וראה ערך רבי אברהם מן ההר בהערה. על משפחתו, ראה נספח ט.","bk":[["ר\"י הזקן (ר\"י, ריב\"ש)",""]]},{"i":20017,"n":"חכמי פרובינציא","bt":"1250","dt":"ה'קי 1350","s":"היברובוקס","bk":[["חכמי פרובינציא",""]]},{"i":20018,"n":"חכמי שווילי, ישראל","f":"יעקב","bt":"תרכו","bp":"אחיסקא-קווקז","b":"עלה עם הוריו לירושלים, פעל להקמת שכונות בירושלים.","s":"גאון-יהודי המזרח"},{"i":20019,"n":"חכמישוילי, יעקב יוסף","dt":"תרנב","dp":"ירושלים","b":"רב בחיסקא (קוקז), עלה לירושלים בשנת תרכז, והיה מראשי עדת הגורג'ים בירושלים.","s":"גליס; אוצר 9938"},{"i":20020,"n":"חלאוה, אברהם מירושלים ואיטליה","f":"יצחק","k":"בעל מנחת אברהם","bt":"תריח","bp":"ירושלים","dt":"תרפד - יט אדר","dp":"מרסיליה","b":"מחכמי ירושלים, בשליחות בפרס, מרוקו ותונס, עבר לליוורנו. חיבר ספר \"מנחת אברהם\" (ליוורנו תרסא).","s":"גליס; יהב\"י, שא\"י.","bk":[["מנחת אברהם",""]]},{"i":20021,"n":"חלאוה, אברהם ממכנאס","f":"יצחק","b":"מחכמי מכנאס, חתם על שטר-תקי עם ר יהושע בירדוגו. אולי הוא שחתם בפאס-תקה עם ר שלמה עטייה ור שלמה הכהן. בנו - ר משה.","s":"מלכי רבנן; טולדנו-נר המערב"},{"i":20022,"n":"חלאוה, אברהם ממכנאס - ב","f":"יוסף בן משה ממכנאס","b":"מצאצאי ר אברהם הראשון. מחכמי מכנאס, בשליחות בלונדון-תקפה ונתקבל שם לרב העדה הספרדית. חיבר הקדמה ופיוטים ל\"קול יעקב\" - לונדון תרד.","s":"ארזי הלבנון; מלכי רבנן; טולדנו-נר המערב"},{"i":20023,"n":"חלאוה, אברהם ממכנאס - הזקן","b":"מקובל, מחכמי מכנאס- שנות ה-ש'-ת'.","s":"ארזי הלבנון; מלכי רבנן"},{"i":20024,"n":"חלאוה, אברהם ממרוקו","b":"רב במוגאדור-מרוקו-שנות ה-ת'.","s":"מלכי רבנן"},{"i":20025,"n":"חלאוה, אהרן מירושלים","f":"משה","dt":"תריט - א כסלו","dp":"ירושלים","b":"מרביץ תורה, מרבני ירושלים.","s":"גליס; אוצר הרבנים 1570; גאון-יהודי המזרח; ארזי הלבנון"},{"i":20026,"n":"חלאוה, אהרן ממכנאס","f":"משה הקדוש","k":"בעל פה לאדם","b":"מחכמי מכנאס-מרוקו. הו\"ל ספר אביו \"פה לאדם\".","s":"מלכי רבנן"},{"i":20027,"n":"חלאוה, חיים ממכנאס","f":"יוסף","b":"דיין במכנאס, הסכים על \"קול יעקב\"-תריב עם אחיו ר משה, שירים ממנו ב\"קול יעקב\".","s":"ארזי הלבנון; מלכי רבנן"},{"i":20028,"n":"חלאוה, יהודה","f":"משה (מהר\"ם חלאוה)","k":"בעל אמרי שפר","b":"רב בטורטושה,חיבר \"אמרי שפר\"","s":"ארזי הלבנון"},{"i":20029,"n":"חלאוה, יהודה מאלגיר","bt":"רפ","dt":"שס - בערך","b":"מרבני אלג'יריה, מורה הוראה ותשובה מנו בשו\"ת נפך לר אברהם ן טוואה - בכת\"י.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":20030,"n":"חלאוה, יהודה ממרוקו","b":"מגדולי חכמי מרוקו","s":"אוצר הרבנים 6935"},{"i":20031,"n":"חלאוה, יוסף ממכנאס","f":"משה","k":"בעל וילקט יוסף","b":"מחכמי מכנאס, חתם על הסכמה-תקץ. חיבר ספר דרשות \"וילקט יוסף\". בניו: ר אברהם מלונדון, ר משה ור חיים.","s":"אוצר הרבנים 8315; מלכי רבנן"},{"i":20032,"n":"חלאוה, יוסף נסים","b":"ראה גם: יוסף חלאוה ממכנאס.","s":"מתוך קטלוג"},{"i":20033,"n":"חלאוה, יצחק ממרוקו","b":"מחכמי מרוקו בזמן ר אליהו הצרפתי שהתכתב עמו.","s":"מלכי רבנן"},{"i":20034,"n":"חלאוה, משה מירושלים","f":"יעקב","b":"הסכים על זהרי חמה-תח, (במפתח ההסכמות מזכירו כר משה בן יעקב מחלב).","s":"ארזי הלבנון; פרומקין-תח\"י"},{"i":20035,"n":"חלאוה, משה ממכנאס - א","f":"אברהם?","dt":"תקנג - ז-יז אב","b":"נכד ר אברהם חלאוה (ולדעת טולדנו-נר המערב היה בנו). מחכמי מכנאס. בנו - ר יוסף בעל \"וילקט יוסף\" הביא מתורתו בספרו. דרשות וחדושים ממנו משנת תק בערך אולי מטבריה (האם זה אותו הרב?)","s":"אוצר הרבנים 14699; מלכי רבנן; טולדנו-נר המערב"},{"i":20036,"n":"חלאוה, משה ממכנאס - ב","f":"יוסף","b":"רב במכנאס-תרב והסכים על \"קול יעקב\" לר יעקב בירדוגו יחד עם אחיו ר חיים.","s":"ארזי הלבנון; מלכי רבנן"},{"i":20037,"n":"חלאוה, משה ממרוקו","f":"יוסף בן משה?","k":"בעל פה לאדם","dt":"תקפו - תשרי","b":"רב ומשורר בכפר אזרו-מרוקו. ולדעת טולדנו-נר המערב היה רב במכנאס והיה אחיו של ר אברהם שהיה רב בלונדון. קובץ משיריו נדפס בשם \"פה לאדם\" - תריג. נהרג עק\"ה ע\"י שודדים. בנו - ר אהרן מירושלים הו\"ל מכתביו.","s":"גאון-יהודי המזרח; מלכי רבנן; טולדנו-נר המערב"},{"i":20038,"n":"חלאוה, משה מספרד","f":"דוד מקנגי","b":"חברו של הריב\"ש. תלמיד הרשב\"א ובנו בברצלונה, וכן רבינו פרץ הכהן והר\"ן. מחכמי טורטושא-ספרד-קנט - אך לא כיהן ברבנות. היה מעורב במחלוקת על רבנות צרפת בין ר מתתיהו בן יוחנן ור אושעיא ונזכר בשו\"ת הריב\"ש. בנו ר יהודה בעל \"אמרי שפר\". חיבר חדושים לש\"ס.","s":"ארזי הלבנון"},{"i":20039,"n":"חלאוה, משה מספרד ופאס","dt":"רפו - לפני","b":"תלמיד ר שמואל בלאנסי בספרד יחד עם חברו ר יוסף עוזיאל, לאחר הגירוש הגיע לפאס, לימד תורה והניח תלמידים רבים. היה מעורב במחלוקת על הנפיחה. נזכר ב\"יכין ובועז\".","s":"אוצר הרבנים 14698; מלכי רבנן"},{"i":20040,"n":"חלאוה, סמחון (שמעון) ממכנאס","f":"שלמה","k":"בעל צו לצו","bt":"תקצב","bp":"מכנאס","dt":"תרס","b":"עבר ממרוקו לאלגיר וכיהן כרב בווהראן-אלגיר. חיבר גם \"חכמה ודעת\". תשובות ממנו ב\"כרם חמר\".","s":"ארזי הלבנון; מלכי רבנן; מלכי ישורון-חכמי אלגיר"},{"i":20041,"n":"חלאוה, שלמה ממכנאס-מרוקו","b":"רב במכנאס-תקן. חיבר קינות על הרדיפות במכנאס-תקן, חיבר שירים לכבוד ר אליהו הצרפתי ובנו ר ישראל יעקב הצרפתי.","s":"אוצר הרבנים 18447; מלכי רבנן; ארזי הלבנון"},{"i":20042,"n":"חלאוה, שמואל ממרוקו","dp":"מרוקו","b":"מחכמי מכנאס וראש ישיבה.","s":"ארזי הלבנון"},{"i":20043,"n":"חלאווה, חנניה ממרוקו","dp":"מזגיתה","b":"מצדיקי מרוקו,שד\"ר מא\"י שטבע בנהר","s":"ארזי הלבנון"},{"i":20044,"n":"חלאיו, דוד מאלגיר","f":"שמואל","bt":"קן","dt":"רך - בערך","b":"תלמיד הרשב\"ץ. רב וספרא דדיינא בברשך-אלגיר על מקום אביו, ומלמד תורה, רב במיליאנא-אלגיר. לבקשתו חיבר הרשב\"ץ לפיוט \"ברוך אשר אשש\" לר יוסף ן אביתור (מחזור מנהג מגורשי ספרד באלגיר).","s":"מלכי ישורון-חכמי אלגיר"},{"i":20045,"n":"חלאיו, יצחק מאלגיר","f":"דוד","bt":"קץ","dt":"רס - בערך","b":"רב בברשך-אלגיר על מקום אביו וזקנו, מיליאנא על מקום אביו. בתשובה אליו כותב הרשב\"ש כנגד אנשים לא ראויים העוסקים בקבלה. כנראה שהוא הרב שעזב את ברשך ללא הסכמת הקהל הנזכר בשו\"ת הרשב\"ש.","s":"מלכי ישורון-חכמי אלגיר"},{"i":20046,"n":"חלאיו, שמואל מספרד ואלגיר","f":"דוד","bt":"קך","bp":"מיורקה","dt":"ר","b":"תלמיד ר צמח-אבי הרשב\"ץ. רב במיורקה, עבר לאלגיר-קן. מגדולי חכמי אלגיר. חברו של הרשב\"ץ, ונזכר גם בשו\"ת הריב\"ש.","s":"אוצר הרבנים 19183; מלכי ישורון-חכמי אלגיר"},{"i":20047,"n":"חלאק, עזרא מחלב","dt":"תרסד","b":"מחכמי חלב.","s":"ארזי הלבנון"},{"i":20048,"n":"חלב, אברהם מויריאה","b":"מראשי קהלת ויריאה-שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":20049,"n":"חלובי, משה","f":"יעקב","b":"מחכמי ירושלים, בשנת תו חתם על תקנת המסים.","s":"גליס"},{"i":20050,"n":"חלול, אברהם מיוזיל-היסאר","b":"מראשי קהלת יוזיל-היסאר-ליד אזמיר-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":20051,"n":"חלומניץ, אליהו מקעלין","b":"רב במסטיץ-תקסב.","s":"מתוך קטלוג"},{"i":20052,"n":"חלופוביץ, אברהם שרגא מקמנסקיא","f":"צבי דב","bt":"תרלה","b":"רב בקמנסקה(=קאמענסקאיע)-פלך יקטרינסלב-תרס.","s":"אוצר הרבנים 1431; אהלי שם"},{"i":20053,"n":"חליבוי, משה מקושטא","f":"שלמה","b":"מדפיס בקושטא-רעט עם ר יוסף ישראל צרפתי.","s":"רוזניס-תורכיה-א"},{"i":20054,"n":"חליגאוה, חיים מקוצ'ין","f":"יוסף","b":"ראש קהלת \"בני ישראל\" בקוצ'ין-הודו. הו\"ל הגדת בומבי-תרו והגדת פונה-תרלד.","s":"מתוך קטלוג"},{"i":20055,"n":"חלימי, אברהם מאלגיר","f":"בנימין בן כלפאלה","k":"בעל ימי אברהם","bt":"תקצ","bp":"קצמטינא","dt":"תרן - בערך","b":"נינו של ר מסעוד זנביב (זרביב). דיין, דרשן ומרביץ תורה בקצמטינא. חיבר גם \"זכות אבות\" ירושלים תרן, \"ויגד לאברהם\", \"והוכח אברהם\", ועוד. חתן ר' שמעון זרביב. בנו - ר סידי פרג' הו\"ל את ספריו וחיבר הקדמה לספרו \"ימי אברהם\".","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר; מלכי ישורון עמוד 124","bk":[["הוכח אברהם",""],["זכות אבות",""],["יגד לאברהם",""],["ימי אברהם",""],["קנה אברהם",""]]},{"i":20056,"n":"חלימי, דניאל מאלגיר ובאר שבע","f":"שלמה","bt":"תרעה","dt":"תשמט","b":"רבה האחרון של גילמא-אלגיר, רב באוויניון-צרפת, עלה לא\"י , רב בבאר שבע","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":20057,"n":"חלימי, כליפא מאלגיר","bt":"תקף","dt":"תרס - בערך","b":"רב בקצמטינא. נזכר ברשימה בתחילת \"ארץ טוב\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":20058,"n":"חלימי, פרג' מאלגיר","f":"אברהם","k":"בעל אורות החיים","bt":"תרלו","dt":"תשיז","b":"רב בקצמטינא. ביקר בארץ ושב לאלגיר. הו\"ל ספרי אביו וחיבר הקדמה ל\"חיי אברהם\". חיבר גם \"לא אמות כי אחיה\" ג'רבא תשך, ועוד.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":20059,"n":"חליף, שלמה מפורטוגל ושלוניקי","b":"מאנוסי פורטוגל, הגיע לשלוניקי - שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":20060,"n":"חלמי, סאסי מאלגיר","b":"רב בקצמטינא-רס, והעתיק את ספר הזוהר ועוד.","s":"מלכי ישורון-חכמי אלגיר"},{"i":20061,"n":"חלמיש, ישעיה מירושלים","b":"חתם-תרצו כעד על הלואה לצורך רכישת בנין ישיבת חברון בירושלים. פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו.","s":"אוצר כתבי עת-לוין"},{"i":20062,"n":"חלפוני, זכריה","f":"שלום","k":"ר' יוחנן מזרחי","b":"מגדולי חכמי תימן, גדול פרשני המשנה והתלמוד בתימן-ש\"כ-שצ\"ה, חי במחוז רדאע, חיבר פירוש \"מזרחי\" לש\"ס","s":"ארזי הלבנון"},{"i":20063,"n":"חלפין, משה","b":"לדעת האדמור הריי\"צ זהו חותמו של ר משה אב\"ד פוזנא, י\"א שהוא גביר מברלין, וי\"א שהוא מחכמי שקלוב. (קובץ על יד, יא ושם נזכר משהחלפין בן צייטליס.","s":"מתוך קטלוג; אור ישראל מונסי כרך לד"},{"i":20064,"n":"חלפן דוד","bt":"1848","dt":"ה'תרצ 1930","s":"היברובוקס","bk":[["ילקוט דוד",""]]},{"i":20065,"n":"חלפן, אבא מרי מאיטליה ופרג","f":"אליהו","dt":"שמו - ח אלול","dp":"פרג","b":"נכד ר אבא מרי מספרד ואיטליה, עבר מאיטליה לפרג והיה מגדולי חכמי פרג. בנו ר אליהו חלפן הרופא אביו של ר יצחק מוינה.","s":"אוצר הרבנים 59; אלופי יעקב א-יז; פין-כנסת ישראל"},{"i":20066,"n":"חלפן, אבא מרי מספרד ואיטליה","bp":"ספרד","b":"לאחר הגירוש עבר לאיטליה. אבי משפחת חלפן באיטליה. מבניו: ר אליהו. נכדו ר אבא מרי מפרג.","s":"ארזי הלבנון; אלופי יעקב א-טז"},{"i":20067,"n":"חלפן, אברהם מתתיהו מאודסה","k":"בעל אמרים אמת","b":"רב באודסה. חיבר הספד בשם \"אמרים אמת\"-אודסה תרסא."},{"i":20068,"n":"חלפן, אליהו הרופא מוינה","f":"אבא מארי","bt":"שכא","bp":"פרג","dt":"שפד","b":"רופא מחכמי וינה-שנח.","s":"אלופי יעקב א-תקפט; פין-כנסת ישראל"},{"i":20069,"n":"חלפן, אליהו חיים מטלז","dt":"תש-א","b":"מצאצאי ר חיים מוולוזין. רב בטלז. בניו: ר משה מקליבלנד, ר פנחס מטלז, ר אפרים. נספה בשואה.","s":"אוצר הרבנים 2265; אנשי שם-אמריקה"},{"i":20070,"n":"חלפן, אליעזר מפרג","f":"אור שרגא חלפן","b":"דיין,דרשן בפרג","s":"אוצר הרבנים 2501"},{"i":20071,"n":"חלפן, דוד הלוי מבוצאץ","k":"בעל ילקוט דוד","b":"חיבר \"ילקוט דוד\" פשמישל תרפז.","s":"וונדר-גליציה ח\"ב"},{"i":20072,"n":"חלפן, יוסף מברודי","f":"אור שרגא פייבוש","b":"דיין בברודי-תק\"ג","s":"אוצר הרבנים 8316"},{"i":20073,"n":"חלפן, יחזקאל (יחיאל) הי\"ד","f":"אליהו בן אבא מארי","b":"בנו - ר יצחק מוינה.","s":"%"},{"i":20074,"n":"חלפן, משה מארה\"ב","f":"אליהו חיים הי\"ד","bt":"תרסה","bp":"טלז","b":"תלמיד ישיבות טלז, פוניבז. נסמך מאת ר\"ל רובין מוילקומיר. רב בליטא, הגיע לארה\"ב-תרצח (אביו ואחיו נשארו בליטא נספו בשואה), רב בקליבלנד, מזכיר ישיבת טלז בקליבלנד. חתן ר חיים יעקב ישראל ברגר מקליבלנד בעל \"אהבת ישראל\".","s":"אנשי שם-אמריקה"},{"i":20075,"n":"חלפן, מתתיהו מארגנטינה","bp":"יליזבטגרד-רוסיה","b":"תלמיד ישיבות ליטא, ביהמ\"ד לרבנים בפאריס. רב הכולל במושבות יק\"א בארגנטינה, רב בבואנס-איירס-תרע.","s":"אוצר הרבנים 15779; אהלי שם"},{"i":20076,"n":"חלפן, עקיבא מוילנא","f":"אליהו","k":"בעל דבר שמואל","b":"מחכמי וילנא. חיבר \"דבר שמואל\" ביאליסטוק תקעד - ובו דברים בשם נפתלי הרץ ויזל, משה מנדלסון, ועוד, עם הסכמות ר נחום ריבקינד שתדלן מפטרבורג, ר מרדכי חן טוב משיסלביץ, ועוד.","s":"עיר וילנא ח\"ב"},{"i":20077,"n":"חלפן, פנחס מטלז","f":"אליהו חיים מטלז","dt":"תש-א","b":"ר\"מ בישיבה קטנה-מכינה בטלז. נספה בשואה.","s":"אוצר הרבנים 16909; אנשי שם-אמריקה"},{"i":20078,"n":"חלפן-דילמדיגו, אליהו מנחם מונצ","f":"אבא מארי דלמדיגו","k":"בעל ביאור לתורה","b":"נכד מהרי\"ק (=ר יוסף קולון). תלמיד ר יוסף שרגא, רב רופא ומקובל בונציה-שי בזמן מור\"ס. בזמן המחלוקת בענין הדפסת ספרי קבלה היה מהמתנגדים עם חברו מהר\"ם פאדובה. תשובה ממנו בספר רבו, ומובא בשו\"ת הרמ\"א. בנו - ר יחיאל חלפן אביו של ר יצחק מוינה אביהם של ר חיים מנחם, ור יחיאל - ומהם כמה משפחות מיוחסות בישראל. נזכר באגרת ר שלמה מולכו - שסיפר שהיה בעיר עוד רופא ר יעקב מונטינו והיה מחלוקת בינו לבין ר אליהו חלפן ור שלמה ניסה לעשות שלום ביניהם וכו'.","s":"איטליה גירונדי-א לו; אלופי יעקב א-תקפט; פין-כנסת ישראל"},{"i":20079,"n":"חלפן-ליפשיץ, משה מוארשא","dt":"תקצא - חשון","b":"תלמיד המגיד מקוזניץ והחוזה מלובלין. גביר מראשי הקהלה בוארשא. חתניו - ר יצחק מאיר אלתר בעל \"חדושי הרי\"ם\", ר מנחם מנדל מקוצק. חתם בשם - \"משה ליפשיץ\".","s":"אלפסי"},{"i":20080,"n":"חלפתא, מאיר ממצרים","b":"תלמיד ר חייא רופא מצפת. מחכמי צפת, רב במצרים-תיב. בנו - ר שלמה - נפטר בחיי אביו.","s":"רוזניס-תורכיה-ד"},{"i":20081,"n":"חלפתן, מרדכי","b":"מחכמי ירושלים, בשנת רמא הזכירו ר משולם מוולטרא כאחד הדיינים בירושלים.","s":"גליס"},{"i":20082,"n":"חלפתן, רחב\"ס","f":"יעקב","b":"מחכמי ירושלים, מוזכר במכתב ר משולם מוולטרא כאחד מדייני הקהלה בשנת רמב.","s":"גליס; מסע משולם מוולטרא."},{"i":20083,"n":"חמדאן, משלה מפרס","b":"רב בטהרן-פרס, נזכר ב\"מעשה אבות\".","s":"ארזי הלבנון"},{"i":20084,"n":"חמדי, דוד מתימן","f":"ישע הלוי","k":"אלואל - בעל הקצר והמ","b":"מגאוני תימן, חיבר פירוש מדרשי על התורה בשם \"אולוגיז אלמגני\"(הקצר המספיק), \"אלגאמע\"(המאסף)דרשן, פוסק, פילוסוף, משורר-שנת ק\"נ","s":"ארזי הלבנון"},{"i":20085,"n":"חמדי, לוי מצנעא-תימן","f":"ישועה","bt":"תרכא","bp":"צנעא","dt":"תרף - כ סיון","dp":"ירושלים","b":"מחכמי תימן, עלה לירושלים-תרנה והיה סופר סת\"ם. נחשב לצדיק וכתב קמיעות ורבים באו לקבל את ברכתו.","s":"ארזי הלבנון; אוצר הרבנים 12458"},{"i":20086,"n":"חמדי, שלום הלוי","k":"ר' שלום חמדי הזקן","dt":"תרעג - ב תשרי","b":"מגדולי חכמי התימנים","s":"אוצר הרבנים 18149"},{"i":20087,"n":"חמו ן, אברהם מאלגיר","bt":"תקס","dt":"תרל","b":"רב באלגיר, עלה לארץ - אחרי תקץ והתישב בכפר פקיעין.","s":"מלכי ישורון-חכמי אלגיר"},{"i":20088,"n":"חמו ן, אברהם מדבדו-מרוקו","b":"מחכמי דבדו-תרי.","s":"מלכי רבנן"},{"i":20089,"n":"חמו ן, אברהם ממרוקו","b":"רב בדבדו(=צפארו)-מרוקו-תקעט, אחיו - ר משה.","s":"מלכי רבנן"},{"i":20090,"n":"חמו ן, אהרן מאלגיר","b":"רב במיליאנה-אלגיר, ועמד בקשר מכתבים עם ר יוסף משאש.","s":"מלכי ישורון-חכמי אלגיר"},{"i":20091,"n":"חמו ן, דוד מצפרו-מרוקו","b":"מחכמי צפרו-מרוקו בזמן היעב\"ץ.","s":"מלכי רבנן"},{"i":20092,"n":"חמו ן, חיים מדבדו ופאס","bp":"דבדו","dp":"פאס","b":"מו\"צ בכפר זא, דרשן, מחכמי פאס-שנות ה-תר'.","s":"ארזי הלבנון; מלכי רבנן"},{"i":20093,"n":"חמו ן, יוסף מאלגיר","bt":"תקע","dt":"תרל - בערך","b":"רב וסופר בתלמסאן. חתם בשנים תרי-תרך.","s":"מלכי ישורון-חכמי אלגיר"},{"i":20094,"n":"חמו ן, יוסף ממרוקו","f":"אהרן","b":"רב בדבדו-מרוקו, חתם-תרכז עם ר משה בן יהודה הכהן סקלי.","s":"מתוך קטלוג"},{"i":20095,"n":"חמו ן, יחיא מפאס","f":"אברהם","b":"מו\"ץ בפאס, חתם על ההסכמה בענין הנפיחה-רפו, עבר דרך וריגלאן (עיר של קראים) לונציה והיה שם מגיה בהוצאת ה\"טור\"-נדפס שלד.","s":"מלכי רבנן"},{"i":20096,"n":"חמו ן, יעקב מדבדו-מרוקו","f":"משה","b":"מחכמי דבדו-מרוקו-שנות ה-תק'.","s":"מלכי רבנן"},{"i":20097,"n":"חמו ן, ישועה מאלגיר","k":"בעל קול רינה וישועה","dt":"תש - בערך","b":"רב בתלמסאן, בעל עבאס, ועוד. הו\"ל \"קול רינה וישועה\" - גרבה תרו. תרגם לערבית יהודית \"בן אדמה\" בנוסח יהודי בלידא, ובנוסח יהודי תלמסאן. עסק בכתיבת קמיעות והיה מחלוקת כנגדו עד שנאלץ לעזוב את תלמסאן - ר יוסף משאש תיווך בינו לבין מתנגדיו.","s":"מלכי ישורון-חכמי אלגיר"},{"i":20098,"n":"חמו ן, ישועה מצפרו-מרוקו","f":"משה","dt":"תק","b":"רב בצפרו(=דבדו,דברו) על מקום אביו, היה חותם עם ר שמואל בן חותא, חתם על פס\"ד-תע. התכתב עם ר יהודה ן עטר. (מסר את כתביו לבנו ר משה שנהרג ובנותיו מסרו את הכתבים לגניזה - ואבדו).","s":"ארזי הלבנון; מלכי רבנן"},{"i":20099,"n":"חמו ן, מימון מצפרו-מרוקו","b":"מחכמי צפרו-מרוקו. אביו של ר משה ן חמו.","s":"ארזי הלבנון; מלכי רבנן"},{"i":20100,"n":"חמו ן, משה מצפרו","f":"שמואל","b":"מחכמי צפרו(=דבדו)-מרוקו-תקלד, וישב אצל אביו ולמד ואביו פרנסו. פסק דין של רבני פאס ומקנאס לפוטרו ממס.","s":"ארזי הלבנון; מלכי רבנן"},{"i":20101,"n":"חמו ן, משה מצפרו-מרוקו - הזקן","f":"מימון","dt":"תסא-ז - כא אלול","b":"רב בצפרו(=דברו)-מרוקו בזמן ר יהודה ן עטר, ר וידאל הצרפתי. חיבר פירוש לתורה. נזכר ב\"משפט וצדקה ביעקב\". היה מעורב במחלוקת בין ר יעקב ן צור לר שמואל אזאווי. בניו - ר מימון ו ישועה על מקומו אחריו.","s":"ארזי הלבנון; מלכי רבנן"},{"i":20102,"n":"חמו ן, משה מצפרו-מרוקו - הנכד","f":"משה","dt":"תקי-א","b":"רב בצפרו(=צפארו)-מרוקו, והיה מחלוקת עם ר יוסף עטייה ואנשים מהקהל שרצו לסלקו, ורבני פאס התערבו לטובתו, ובקשו מחכמי צפרו שידריכוהו בדרך אבותיו הקדושים עד שיהיה הענף דומה לשורש. נהרג עק\"ה ע\"י ערבים.","s":"ארזי הלבנון; מלכי רבנן"},{"i":20103,"n":"חמו ן, סלימן ממרוקו","f":"דוד","b":"רב במרוקו-תפו וחתם אז עם ר יוסף מלכא. נזכר ב\"משפט וצדקה\".","s":"ארזי הלבנון"},{"i":20104,"n":"חמו ן, רפאל ממרוקו","f":"מכלוף","b":"מחכמי צפרו - בשנות ה-תר', נספד ע\"י תלמידו ר יוסף בן נאיים בעל \"מלכי רבנן\".","s":"ארזי הלבנון"},{"i":20105,"n":"חמו ן, שלם מפאס","b":"סופר שטרות בפאס-תריג.","s":"מלכי רבנן"},{"i":20106,"n":"חמו ן, שלמה יעקב ממרוקו","b":"חתם עם ר יוסף אלחדד הכהן על כתב סמיכה לשו\"ב ר ישעיה סבעוני.","s":"מתוך קטלוג"},{"i":20107,"n":"חמו ן, שמואל מצפרו-מרוקו","b":"מחכמי צפרו-מרוקו-שנות ה-ת'. בנו - ר יעקב.","s":"ארזי הלבנון; מלכי רבנן"},{"i":20108,"n":"חמודות, יאיר מנ\"י","b":"פרסם מאמרים ב\"הלבנון\" - סטמר תרפח.","s":"אוצר כתבי עת-לוין"},{"i":20109,"n":"חמוי, אברהם","b":"מקובל-תרל\"ט","s":"אוצר הרבנים 432"},{"i":20110,"n":"חמוי, אברהם","f":"רפאל","k":"בעל אביעה חידות","bp":"חלב","b":"עבר לקושטא, ליוורנו, חיבר ספרים רבים ביניהם \"אביעה חידות\" ו\"האח נפשנו\"","s":"ארזי הלבנון; גאון-יהודי המזרח"},{"i":20111,"n":"חמוי, אברהם שלום חי רפאל","f":"רפאל","k":"בעל זמן בית דין","b":"מחכמי מרשיליא.","s":"אוצר הרבנים 1388; גאון-יהודי המזרח"},{"i":20112,"n":"חמוי, אליהו מחלב","f":"עזרא","k":"בעל פה אליהו","bt":"תקצו","dt":"תרעו - א תשרי","dp":"חלב","b":"חתן ר יצחק סוויד. אב\"ד בחלב(=אליפו)-תרס, מרביץ תורה, חיבר \"פה אליהו\", חיבר פיוטים.","s":"אוצר הרבנים 2112; גאון-יהודי המזרח; ארזי הלבנון; אהלי שם"},{"i":20113,"n":"חמוי, אלעזר","b":"מגדולי רבני מצרים-ש\"ס","s":"אוצר הרבנים 2871"},{"i":20114,"n":"חמוי, בנימין מירושלים","f":"משה","k":"בעל אמתחת בנימין","bt":"תרד-תרך","bp":"ירושלים","dt":"תרפב - כח שבט","dp":"חיפה","b":"אביו מראשי עדת המערבים, בשליחות במרוקו לפני שנת תרלח, בשנת תרלח שליח בתורכיה, רב ביינישאר, נתמנה לרב בלריסה, חזר לירושלים, יצא לשליחות ושימש כרב בבלגרד, ובקשטיריה-תרמז. בשנת תרמט היה בחיפה. חיבר \"אמתחת בנימין\" ירושלים תרלז, ועוד בכתב יד.","s":"גליס; ארזי הלבנון; אוצר הרבנים 3698; גאון-יהודי המזרח; יהב\"י, שא\"י","bk":[["אמתחת בנימין",""]]},{"i":20115,"n":"חמוי, יוסף חיים מאלגיר","b":"רב בסוק אראץ-אלגיר-תרף. הסכים על \"גביע יוסף\" לר יוסף בן הרוש - סוסה תרפז.","s":"מלכי ישורון-חכמי אלגיר"},{"i":20116,"n":"חמוי, מנשה מטבריה","f":"עזרא","k":"בעל זכרון ירושלים","dt":"תרצא - א אדר","dp":"טבריה","b":"מחכמי טבריה. בשליחות טבריה באלגיר-תרלב וסירבו שם לעזור לו עד שהגיע ר אליהו מאני מחברון וסייע בעדו. נציג הקהלה היהודית בעירית טבריה-תרמב. בשליחות בתונס וטריפולי-תרסב. בנו ר נסים - מחכמי טבריה.","s":"אוצר הרבנים 13627 א'; ארזי הלבנון"},{"i":20117,"n":"חמוי, משה הכהן מחלב","dt":"תרסה - טו תמוז","b":"מרביץ תורה בארם צובה","s":"אוצר הרבנים 14701"},{"i":20118,"n":"חמוי, משה מחיפה","f":"בנימין","bt":"תרמז","bp":"קשטוריאה","dt":"תשלד - ב שבט","b":"רב בחיפה, בשליחות בתורכיה ובדרכו נתבקש לרבנות רודוס - אך סירב לרבנות לבקשת אביו.","s":"אוצר הרבנים 14703; גאון-יהודי המזרח"},{"i":20119,"n":"חמוי, משה מירושלים","bt":"תקפח","dt":"תרס - א תשרי","dp":"ירושלים","b":"מחכמי ירושלים, בנו ר בנימין.","s":"ארזי הלבנון; אוצר הרבנים 14702"},{"i":20120,"n":"חמוי, עזרא מחלב","f":"יצחק","bt":"תרך","bp":"חלב","dt":"תשו - כח טבת","dp":"ירושלים","b":"רב בחלב, עלה לירושלים-תרצה. תלמיד ר אברהם חיים עדס. מתלמידיו ר שלמה לניאדו ראש ישיבת פורת יוסף, ור יהודה אצלאן עטיה. רוב חדושיו אבדו, ומתורתו בספר חתנו ר יעקב אלמליח \"וישא יעקב\".","s":"אוצר הרבנים 16567; ארזי הלבנון; אהלי שם"},{"i":20121,"n":"חמוי, שבתי הכהן ביצ'ה מחלב","f":"משה","b":"מחכמי חלב. הו\"ל-תרסו תרגום מגילת אסתר לערבית מאת ר יוסף אלשמסא.","s":"ארזי הלבנון"},{"i":20122,"n":"חמוי, שלמה רפאל מצפת","b":"מחכמי צפת-תר, בשליחות הקהלה.","s":"מתוך קטלוג"},{"i":20123,"n":"חמוי, שמעון מחלב","b":"מחכמי חלב-תקפח, וחתם אז עם חכמי חלב על שטר מסירת משכון.","s":"ארזי הלבנון"},{"i":20124,"n":"חמוץ, יוסף","k":"בעל יודעי בינה","b":"מגדולי המקובלים בדורו-שנת ת'","s":"אוצר הרבנים 8317"},{"i":20125,"n":"חמיאל חיים יצחק בן אפרים","bt":"1917","dt":"ה'תשעא 2011","s":"היברובוקס","bk":[["מאסף לעניני חינוך והוראה",""]]},{"i":20126,"n":"חמידס, אלכסנדר זוסיא","k":"בעל קול נהי","b":"רב בוינה-תרן. חיבר \"קול נהי\" פרזעמישל תרנה.","s":"וונדר-גליציה ח\"ב"},{"i":20127,"n":"חמידס, אפרים מבקשביץ","dt":"תשב","b":"נכד ר משה חמדיש. חתן ר יצחק תאומים מקריסנפולי. אב\"ד בקשביץ-תרמה. חתנו ר צבי הכהן שורץ על מקומו אחריו. נספה בשואה.","s":"וונדר-גליציה ח\"ב; אוצר הרבנים 3032; אהלי שם"},{"i":20128,"n":"חמידס, גיטל אסתר מטיסמניץ","f":"מרדכי רולר מחודרוב","b":"אם משפחת חמידס. בניה - ר שמשון חמידס מזלוזיץ ור דב בר חמידס מקולומיאה. כתבה את אגרת היוחסין של המשפחה.","s":"וונדר-גליציה ח\"ב"},{"i":20129,"n":"חמידס, דב בר מקולומיאה","b":"חתן ר חיים שמחה וילר מלמברג. רב בקולומיאה.","s":"וונדר-גליציה ח\"ב"},{"i":20130,"n":"חמידס, חיים צבי מקופיטשיניץ","b":"שו\"ב ורב בקופיטשיניץ-תרלה.","s":"וונדר-גליציה ח\"ו"},{"i":20131,"n":"חמידס, יאיר מבילגרוד","b":"רב בבליגרוד.","s":"וונדר-גליציה ח\"ב"},{"i":20132,"n":"חמידס, יהושע השל רבינוביץ-מרק'","f":"מרדכי ראש מדינה","bt":"תנ","bp":"טיסמניץ","dt":"תקיא","b":"נקרא מרקוביץ ורבינוביץ. חתן נכדת ר שניאור ראב\"ד רישא ועבר לשם. בזיוו\"ש חתן ר יחזקאל סגל לנדא מטורנא.","s":"וונדר-גליציה ח\"ו"},{"i":20133,"n":"חמידס, ישראל מסטרי","f":"מרדכי ראש מדינה","b":"רב בסטרי. אביו של ר בנימין וולף.","s":"וונדר-גליציה ח\"ו"},{"i":20134,"n":"חמידס, מרדכי דוד מטבריה","b":"מצאצאי החכם צבי. מחכמי טבריה.","s":"מתוך קטלוג"},{"i":20135,"n":"חמידס, מרדכי ראש מדינה","f":"משה מטיסמניץ","b":"נכד ר שכנא מלובלין ומהרש\"ל. חתן ר שמואל בב\"ר אברהם ר\"מ. בניו - ר יצחק איזיק, יהושע מרקוביץ (ע\"ש אביו מרדכי) רבינוביץ (על היותו חתן הרב), ר שמואל מטיסמניץ, ר אברהם מגרוחוב, ר ישראל מסטרי.","s":"וונדר-גליציה ח\"ו"},{"i":20136,"n":"חמידס, משה מחלב","dt":"תרסה - טו תמוז","dp":"חלב","b":"חתן ר ישראל אשכנזי מטיסמניץ. רב-שנת תר. נכדו - ר אפרים סגל מבקשביץ.","s":"ארזי הלבנון; אוצר הרבנים 14700; אהלי שם"},{"i":20137,"n":"חמידס, קלמן מאלסק","b":"עלה לירושלים וכיהן כרב בב\"ד מחזיקי הדת. תשובה אליו - \"שביבי אש\"-תרעא.","s":"וונדר-גליציה ח\"ו"},{"i":20138,"n":"חמידס, קלמן קלונימוס מאלסק","b":"רב באלעסק-תרס, קטוביץ. נספה בשואה.","s":"וונדר-גליציה ח\"ב"},{"i":20139,"n":"חמידס, שאלתיאל איזיק משטשריץ","b":"פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא.","s":"אוצר כתבי עת-לוין"},{"i":20140,"n":"חמידס, שמואל מטיסמניץ","f":"מרדכי ראש מדינה","dt":"תקיא-ג","b":"חתן ר אביגדור מרגליות מחנטשין. רב בטיסמניץ. בניו - ר אלעזר, ר שלמה זלמן מרישא, ר בנימין זאב וולף מסטרי, ר שלום סאמעליר מטיסמניץ.","s":"וונדר-גליציה ח\"ב,ח\"ו"},{"i":20141,"n":"חמידס, שמעון מזלוזיץ","bt":"תקסט","dt":"תרלב","dp":"זלוזיץ","b":"תלמיד המהרש\"ק - והספידו בברודי. רב בסטרי-תר, זלוזיץ-תרכט.","s":"וונדר-גליציה ח\"ב; אוצר הרבנים 20070"},{"i":20142,"n":"חמידס-איטינגא, אברהם מטיסמניץ","f":"מרדכי חמידס מטיסמניץ","dt":"תקכה","b":"חתן ר חיים יהודה ליב איטינגא - ונקרא גם בשמו - איטינגא. רב בגרוחוב(=חורחוב),ראב\"ד בלבוב-תצט, ראש מדינה בטיסמניץ-תקיט. בנו - ר יהודה ליב איטינגא, ר דב בריש. בניו - ר יהודה ליב איטינגא מטישויץ, ר יוסף - חתן ר מנחם מנדל מרגליות, ר שמואל?, ונכדו ר מרדכי-ראש מדינה בטיסמניץ. חתנו - ר ישראל בן מנחם מנדל שטנגן-מרגליות (לפי אוצר הרבנים ר ישראל היה חתנו של ר אברהם). מצאצאיו - ר אברהם מטיסמניץ. ראב\"ד ור\"מ בלבוב, חתם-תצט על פס\"ד עם ר נתן נטע סגל בן זלמן, ר מנחם מנדל בן ברוך, ר חיים רפפורט ועוד. חתם-תקי עם ר נתן נטע בן יקותיאל ור פנחס בן יעקב קצנלנבוגן.","s":"וונדר-גליציה ח\"ו; אוצר הרבנים 651,177; בובר-לבוב"},{"i":20143,"n":"חמיץ, יוסף מאיטליה","f":"יהודה","k":"בעל דרך אמת","b":"מחכמי איטליה, תלמידו של ר יהודה אריה ממודנא ונסמך על ידו, למד באוניברסיטת פאדובה וקיבל תואר דוקטור לרפואה, ור יהודה אריה הוציא לכבודו ספר \"בליל חמיץ\" ונציה שפד. למד קבלה אצל ר אהרן ברכיה די מודנא בניגוד לדעתו של רבו ר יהודה אריה, ועל כך חיבר ר יהודה אריה את ספריו \"ארי נוהם\" ו\"בן דוד\". החל לחבר ספר \"אור נוגה\" ואת השלמתו מסר לר משה זכות, והוא עלה לירושלים בשנת תיח, חיבר \"דרך אמת\" ונציה תכג, ועוד. ר יהודה אריה חיבר קינה למותו של תלמידו ר יוסף.","s":"גליס; פין-כנסת ישראל; ברנשטיין \"הצופה לבית ישראל\", תשבי \"ספונות\" א."},{"i":20144,"n":"חמיץ, שמואל","b":"מחכמי ירושלים, בין הסובלים בשנת שפה מפרעות אבן פארוך.","s":"גליס"},{"i":20145,"n":"חמצי, אברהם אלברט מרודוס","bt":"תרנו","bp":"רודוס","b":"מלחין. עבר לאזמיר, רודוס.","s":"גאון-יהודי המזרח"},{"i":20146,"n":"חמצי, חיים יהושע אלעזר הכהן","k":"בעל כה תברכו","bt":"ה'תקנה (בערך)","dt":"תרמא - כו אד\"ב","b":"רב באזמיר, רב ור\"מ בחיפה.","s":"אוצר הרבנים 6361; גאון-יהודי המזרח","bk":[["ולבש הכהן [עה\"ת ועהש\"ס]",""]]},{"i":20147,"n":"חמצי, יוסף הכהן מאזמיר","b":"גביר באזמיר או שלוניקי, תמך בהדפסת ספרו של ר יוסף רפאל חזן \"חקרי לב\" על אבן העזר.","s":"רוזניס-תורכיה-ה"},{"i":20148,"n":"חמצי, שמואל הכהן מאזמיר","b":"מחכמי אזמיר, אחיו של ר חיים יהושע אלעזר מאזמיר. נזכר בהקדמת הפרד\"ס ל\"אמר יוסף\" שלוניקי תקצא.","s":"ארזי הלבנון"},{"i":20149,"n":"חמרון, יצחק ממרוקו","b":"מחכמי מרוקו-שנות ה-ת'. נהרג עק\"ה.","s":"מלכי רבנן"},{"i":20150,"n":"חן (גרציאני), שאלתיאל מספרד","b":"רב ופייטן בספרד בזמן קרובו הריב\"ש, ולמדו יחד אצל הר\"ן. רב בפרגה-ספרד, ברצלונה-קלה על מקום הר\"ן. חיבר פירוש לתורה.","s":"ארזי הלבנון"},{"i":20151,"n":"חן טוב, גרשון מביאליסטוק","k":"בעל מנחה חדשה","bp":"סויסלאץ","dt":"תרלג - א שבט","b":"תלמיד ר אלכסנדר זיסקינד הרכבי מנוברדוק. מחכמי ביאליסטוק. (באוצר הרבנים - נפטר ב-תרך).","s":"אוצר הרבנים 4409; מרקוביץ-נוברדוק"},{"i":20152,"n":"חן טוב, מרדכי","b":"רב בשוויסלץ-תק\"ע","s":"אוצר הרבנים 13825"},{"i":20153,"n":"חן, אברהם דוד משנדובה","k":"בעל תשובת חן","b":"אב\"ד שנדובה. עורך \"דבר בעתו\" - וארשא תרצט, \"כנסת ישראל\" - וילנא תרץ.","s":"אוצר כתבי עת-לוין"},{"i":20154,"n":"חן, אברהם יהודה מנובוזיבקוב","f":"חיים דוד צבי מצרניגו","k":"בעל במלכות היהדות","bt":"תרמא","dt":"תשיח - י תשרי","b":"רב בנובוזיבקוב-פלך צרניגוב-תרסט, דנציג, פאריס, עלה לירושלים. נסמך מאת: הרב מהורנסטיפל, ר יחזקאל לישפיץ בעל \"המדרש והמעשה\". מתורתו ב\"דברי טעם\" לר אריה ליב האפט מקאנטאפ.","s":"אוצר הרבנים 433; אהלי שם"},{"i":20155,"n":"חן, אברהם מפרובנס","f":"שלמה","b":"מחכמי פרובנס-קן. חיבר ספר רפואה על חולי הקדחת.","s":"אלופי יעקב א-רנז"},{"i":20156,"n":"חן, אלחנן מפירייטין","b":"נכד ר פרץ מצערניגוב. רב בפירייטין.","s":"אהלי שם"},{"i":20157,"n":"חן, אליעזר יהודה מוארשא","b":"פרסם מאמרים ב\"דבר בעתו\" - וארשא תרצט.","s":"אוצר כתבי עת-לוין"},{"i":20158,"n":"חן, חיים דוד צבי מצרניגוב וירו","f":"פרץ בישענקויצער","bt":"תרו","dt":"תרפו","dp":"ירושלים","b":"ממשפחת חסידי חב\"ד. רב בצרניגוב-תרלה, עלה לירושלים בשנת תרפו. בניו - ר מנחם מנדל מניעזין, ר אברהם מנובוזיבקוב.","s":"גליס; אוצר 5207; אהלי שם"},{"i":20159,"n":"חן, יהודה","f":"עמנואל","b":"מחכמי קנדיה(כרתים) בזמן המהריב\"ל","s":"ארזי הלבנון"},{"i":20160,"n":"חן, יחזקאל מוארשא","b":"אחיו של ר אברהם דוד בעל \"תשובת חן\". הו\"ל \"דבר בעתו\" - וארשא תרצט.","s":"אוצר כתבי עת-לוין"},{"i":20161,"n":"חן, מנחם מנדל מניעזין","f":"חיים דוד צבי מצרניגו","bt":"תרלט","b":"ממשפחת חסידי חב\"ד. רב בניעזין-פלך צרניגוב-תרסז וראש ישיבת חב\"ד בעירו שהוקמה בידי ר לוי יצחק שניאורסון-נכד בעל התניא.","s":"אוצר הרבנים 13461; אהלי שם"},{"i":20162,"n":"חן, עמנואל","b":"מגדולי חכמי קנדיה-ר\"פ","s":"אוצר הרבנים 16747"},{"i":20163,"n":"חן, פרץ בישענקויצר מצערניגוב","b":"תלמיד ר דב בר מליובאויטש, חתנו ר מנחם מנדל הצמח צדק ובנו ר שמואל. עסקן מחשובי חסידי חב\"ד.","s":"אוצר הרבנים 17067; אלפסי"},{"i":20164,"n":"חן-שאלתיאל, עמנואל גראסיא","b":"רב בקושטא-לאחר הגירוש.","s":"רוזניס-תורכיה-א"},{"i":20165,"n":"חנדלי, אברהם","dt":"תקיד - טז אלול","dp":"ירושלים","b":"מחכמי ירושלים.","s":"גליס; פרומקין-תח\"י"},{"i":20166,"n":"חנדלי, אברהם משלוניקי","dt":"תקכג","dp":"שלוניקי","b":"גביר בשלוניקי.","s":"זכרון שלוניקי-93"},{"i":20167,"n":"חנדלי, אליהו הרופא מקושטא","b":"רופא בקושטא-שנות ה-ש'-ת'.","s":"רוזניס-תורכיה-ג"},{"i":20168,"n":"חנדלי, אליהו מקושטא","bt":"שלוניקי","b":"נכד(-אבי אמו) ר אליהו קובו. מחכמי קושטא-שנות ה-תק', הדפיס את ספר זקנו \"שני מאורות הגדולים\". רב בלאריסה על מקום ר יצחק פרנסיס ולצדו ר אברהם פילוסוף ור שמואל בן יצחק משען.","s":"רוזניס-תורכיה-ה"},{"i":20169,"n":"חנדלי, אסתר קיירה","dt":"שס - טו ניסן","dp":"קושטא","b":"אשת הרופא ר אליהו חנדלי, מקורבת למלכות ולסולטנית באפפא אשת השולטן מוראד השני. סייעה רבות ליהודים, סייע לר שמואל שולם בהוצאת ספר יוחסין. נהרגה ע\"י מתנגדיה יחד עם שלשה מבניה.","s":"פין-כנסת ישראל; רוזניס-תורכיה-ג"},{"i":20170,"n":"חנדלי, יהודה הרופא משלוניקי","b":"רופא בשלוניקי - שנות ה-שס בערך, עבר לקושטא.","s":"זכרון שלוניקי; רוזניס-תורכיה-ג"},{"i":20171,"n":"חנדלי, יהודה משלוניקי","b":"תלמיד ר מרדכי קלעי. מחכמי שלוניקי-שנות ה-ת', עבר לקושטא, מקורב למלכות.","s":"רוזניס-תורכיה-ד,ה"},{"i":20172,"n":"חנדלי, יהושע משלוניקי וירושלים","f":"יוסף מאישקופיה","k":"בעל פני יהושע","bp":"איסקופיא","dt":"שפא - אחרי","dp":"ירושלים","b":"אביו ר יוסף היה רב של איסקופיא, תלמיד ר חיים שבתי בשלוניקי, מחכמי שלוניקי. חיבר \"פני יהושע\" ונדפס בתוך \"אדרת אליהו\" (לר אליהו קובו) אמשטרדם תעה. ועוד. שות ממנו בספרי חכמי דורו. בשנת שפא עלה לצפת ואחר כך לירושלים.","s":"גליס; אוצר הרבנים 7561; זכרון שלוניקי; פין-כנסת ישראל; רוזניס-תורכיה-ג; פרומקין-תח\"י; \"ירושלים\" ט."},{"i":20173,"n":"חנדלי, יוסף מלאריסה","b":"מראשי קהלת לאריסה-תמח.","s":"רוזניס-תורכיה-ד"},{"i":20174,"n":"חנדלי, יוסף משלוניקי ואישקופיה","bp":"שלוניקי","dt":"שעז","dp":"ירושלים","b":"מחכמי שלוניקי, אביו של ר יהושע חנדלי, ותלמידו של ר שאלתיאל חפץ, חברו של ר דוד קונפורטו (זקנו של בעל \"קורא הדורות\"), לימד תורה בעיר אישקופיא, היה ראש הרבנים בשלוניקי והקים בה ישיבה, בסוף ימיו עלה לירושלים.","s":"גליס; זכרון שלוניקי; רוזניס-תורכיה-ג"},{"i":20175,"n":"חנדלי, יצחק הרופא משלוניקי","b":"רופא בשלוניקי-שנות ה-ש'-ת'.","s":"רוזניס-תורכיה-ג"},{"i":20176,"n":"חנדלי, יצחק מאזמיר","b":"שליח צבור בקהלת פורטוגל באזמיר-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":20177,"n":"חנה לייב מסעלץ","b":"מחכמי סעלץ בזמן כהונת הגדול ממינסק.","s":"הגדול ממינסק"},{"i":20178,"n":"חנוך הכהן","f":"טוביה","k":"בעל יסוד אמונה","dt":"תר - כח טבת","b":"מצאצאי ר משה משדה לבן, ור צבי הירש מזוריק. מראשוני החסידים בפולין המרכזית. תלמיד המגיד מזלוטשוב, ר משולם זושא מאניפולי, החוזה מלובלין והמגיד מקוזניץ. חיבר \"יסוד אמונה ומדת ענוה\"","s":"אלפסי"},{"i":20179,"n":"חנוך הכהן מירושלים","dt":"תרכא - כא","dp":"ירושלים","b":"מחכמי ירושלים.","s":"פרומקין-תח\"י"},{"i":20180,"n":"חנוך הנדיל הכהן מקיטוב","b":"חתן ר שמואל-חתנו של ר נחמיה פיבל, וגיסו של ר יעקב קאפיל חסיד מקולומיא. תלמיד ר מנחם מנדל מקוסוב. ממונה על השובי\"ם מטעם רבו בכל אזור השפעתו.","s":"אלפסי"},{"i":20181,"n":"חנוך הנדל (מנוח) מלבוב","f":"שמריה","k":"בעל מנוח הלבבות","dt":"שעא - א תשרי","dp":"לבוב","b":"תלמיד המהרש\"ל. מחכמי לבוב. סידר גט בוינה יחד עם ר יהושע ואלק בעל הסמ\"ע. חיבר גם \"חכמת מנוח\", ועוד ספרים רבים.","s":"אוצר הרבנים 6664,13192; מצבות קדש-לבוב לד; בובר-לבוב; פין-קריה נאמנה"},{"i":20182,"n":"חנוך הניך מאיר מסאסוב ורצקי","dt":"תשד","b":"רב בסאסוב-וורצקי","s":"אוצר הרבנים 6676"},{"i":20183,"n":"חנוך הניך מאלסק","k":"בעל לב שמח","dt":"תרמד - ל אב","b":"רב ואדמו\"ר באלעסק","s":"אוצר הרבנים 6628"},{"i":20184,"n":"חנוך הניך מבלזיץ","b":"רב בבלזיץ-ת\"כ","s":"אוצר הרבנים 6629"},{"i":20185,"n":"חנוך הניך מגניזן","f":"אברהם","k":"בעל ויכוח יוסף והשבט","bp":"גנעזין","b":"דרשן בקראקא, נמלט לאשכנז בגזירות תח, רב באיטינגן, דיין ודרשן בפוזנא-תכב. הסכים על \"נחלת צבי\". בנו - ר יהודה ליב ונכדו - ר חנוך בן יהודה משנייטך הו\"ל מכתבי זקנו \"חנוך בית יהודה\" - פפד\"ם תסח.","s":"אוצר הרבנים 6639; פין-כנסת ישראל"},{"i":20186,"n":"חנוך הניך מזגירש","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה.","s":"אוצר כתבי עת-לוין"},{"i":20187,"n":"חנוך הניך מזולקוא","f":"יאסקי","b":"מחכמי זולקוא, חתם-תמח על חרם בזולקוא יחד עם ר הלל בעל \"בית הלל\", ועל בחירת ראשי הקהל-תמו.","s":"בובר-זולקוא"},{"i":20188,"n":"חנוך הניך מזולקווא","k":"ר חנוך העניך מזלקווא","b":"חתן ר בצלאל מוכסן מזולקוא. גביר מראשי קהלת זולקוא. בנו - ר נפתלי הרץ מזולקוא, ר יוסף רבי הנכס. חתניו - ר יוסף בנימין זאב בעל \"אור יקרות\", ר אורי, ר יהודה ליב הלוי. ניסה יחד עם גיסו - ר נתן - לשכנע את ר יעקב עמדן-יעב\"ץ להתישב בזולקוא וללמוד בבית המדרש שלהם.","s":"אוצר הרבנים 6643; בובר-זולקוא"},{"i":20189,"n":"חנוך הניך מקאלווריה","f":"יהודה מוילנא - יסו\"ד","k":"בעל משפחת החנוכי","b":"איש מופת, רב בקאלוואריע(=קאלוואריה), זאבלודאווי(=זאבלודוב)-תקע. בניו ר זליג מירושלים, ר אליעזר פרוזינר מולקוביסק. חתנו ר יהושע השל בכרך. גיסו - ר שמואל - רבה האחרון של וילנא.","s":"אוצר הרבנים 6630; ברוורמן-אנשי שם; ליפמן-קובנא"},{"i":20190,"n":"חנוך הניך משידלוב וזולקוא","b":"מחכמי זולקוא, חתם-תנד על תקנת הקהלה, ובשנת תנא חתם על איסור הישיבה בעיר על ר מאיר כץ מקאליש בגלל שחרחר ריב ומדנים בעדה.","s":"בובר-זולקוא"},{"i":20191,"n":"חנוך הניך משנייטוק","f":"יהודה ליב","k":"בעל חינוך בית יהודה","b":"רב בשנייטוק-תסח, דרשן בקראקא. בנו - ר ליב בעל \"ראשית בכורים\". חתנו - ר משה פרנקפורטר.","s":"אוצר הרבנים 6641; דוקס-אוה למושב"},{"i":20192,"n":"חנוך הענכש מפוזנא","b":"אב\"ד פוזנא-סוף שנות ה-ש'. בנו - ר יהודה ליב על מקומו אחריו?. נספד מאת ר אברהם רפפורט בספרו \"איתן האזרחי\".","s":"בובר-לבוב"},{"i":20193,"n":"חנוך זונדל מביאליסטוק","f":"יוסף","k":"בעל ענף יוסף","dt":"ה'תרכ-תרכח","dp":"ביאליסטוק","b":"מחכמי ביאליסטוק. חיבר \"עץ יוסף\", ו\"ענף יוסף\" על המדרשים.","s":"פין-כנסת ישראל; ברוורמן-אנשי שם","bk":[["עץ יוסף",""],["ענף יוסף",""]]},{"i":20194,"n":"חנוך זונדל מוילקוביסק","b":"רב בווילקובישק-ת\"פ","s":"אוצר הרבנים 6667"},{"i":20195,"n":"חנוך זונדל מלובלין","k":"בעל כוכבי נגה","b":"מחכמי לובלין. חיבר \"כוכבי נגה\" אלקסניץ תקכט.","s":"לקורות היהודים בלובלין"},{"i":20196,"n":"חנוך זונדל מצפת","f":"נפתלי דב","bp":"מרמרוש","dp":"צפת","b":"למד אצל ר מנחם מנדל שטרן רבה של סיגט, בשנת תקפב התמנה לרב של וישאוה. בשנת תרז עלה לצפת והתמנה שם לרב. (נזכר בשות \"בית שלמה\")","s":"גליס; אוצר הרבנים 6666; גרינולד סיני קנה-קנו, מספרות ישראל בהונגריה, בשער ספר."},{"i":20197,"n":"חנוך זונדל מצפת וירושלים","f":"צבי הירש","b":"בשנת תקפג בשליחות באירופה מטעם קהלות צפת וירושלים, לאחר מכן בשליחות באמריקה ובזמן שהותו שם נוסדה חברת \"תרומת הקודש\" לגיוס תרומות לארץ ישראל. מחכמי צפת, בשליחות באמריקה-תקצב והקים חברת \"תרומת הקודש\", ובהיותו שם כיהן כדיין בענין מחלוקת בק\"ק \"שארית ישראל\". אחד מחכמי הגויים ויליאם ל. ראי שחיבר ספר דקדוק לשון עברי ביקש ממנו הסכמה לספרו וקיבלה. (ישנו רב בצפת חנוך זינדל פאנעל - והוא חי מאוחר יותר).","s":"גליס; אמריקה; שא\"י"},{"i":20198,"n":"חנוך מוילנא","f":"יעקב קופל הקדוש","b":"חתם-תלב על קיום צוואת ר משה ריבקש בעל באר הגולה.","s":"פין-קריה נאמנה"},{"i":20199,"n":"חנוך מזולקוא","f":"יקותיאל","b":"מחכמי זולקוא, חתם-שפו על תקנה בזולקוא.","s":"בובר-זולקוא"},{"i":20200,"n":"חנוך מירושלים","b":"מחכמי ירושלים-תח בערך. נספד ב\"איתן האזרחי\" לר אברהם רפפורט.","s":"פרומקין-תח\"י; בובר-לבוב"},{"i":20201,"n":"חנוך מלבוב","f":"מרדכי","dt":"תע - כט טבת","dp":"לבוב","b":"מרביץ תורה, ר\"מ בלבוב-תלו כ-40 שנה.","s":"אוצר הרבנים 6631; מצבות קדש-לבוב; בובר-לבוב"},{"i":20202,"n":"חנוך מספרד","f":"משה בר חנוך","b":"מראשוני חכמי התורה בספרד,קרוב למלכות,מרביץ תורה בקורדובה-ד'תש\"נ","s":"אוצר הרבנים 6649"},{"i":20203,"n":"חנוך מספרד","f":"משה","dt":"ד'תשעה","b":"מחכמי ספרד הקדומים, רב בקורדובה על מקום אביו, ורב ראשי בספרד המוסלמית, נשבה יחד עם אביו והובא לקורדובה בספרד, אביו היה ראשון גדולי התורה בספרד, בין תלמידי ר' חנוך היה ר שמואל הנגיד. ר חנוך נפטר כמה ימים לאחר שנשברה הבימה בשמחת תורה כאשר עלה לחתן תורה ביחד עם רבים.","s":"ארזי הלבנון; פין-כנסת ישראל"},{"i":20204,"n":"חנוך משאריגרד","b":"רב בשאריגרד-תר\"ס","s":"אוצר הרבנים 6633"},{"i":20205,"n":"חנוכה, משה","b":"מגדולי חכמי אשכנז-ר\"כ","s":"אוצר הרבנים 14704"},{"i":20206,"n":"חנוכה, נסים","b":"מחכמי ארץ ישראל, בשנת תריד בשליחות בפרס.","s":"גליס"},{"i":20207,"n":"חנוכה, נסים מטבריה","b":"מחכמי טבריה, בשליחות בבגדד ופרס-תריד.","s":"ארזי הלבנון"},{"i":20208,"n":"חנון, יצחק מאלגיר","bt":"תרכד","dt":"תשח","b":"דיין באלגיר. הסכים על הדפסת מחזור אלגיר - ליוורנו תרצז.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":20209,"n":"חנון, משה מספרד","b":"מגדולי חכמי ספרד בזמן הגירוש-רנב, עבר לפטרוס-יון-רנב.","s":"אוצר הרבנים 14705; ארזי הלבנון"},{"i":20210,"n":"חנוניה החסיד מירושלים","b":"מחכמי ירושלים. נזכר בתשובות הגאונים.","s":"פין-כנסת ישראל"},{"i":20211,"n":"חנט, שמואל משלוניקי","b":"רב בשלוניקי-רפ בערך.","s":"רוזניס-תורכיה-א"},{"i":20212,"n":"חניאל, אליהו מאזמיר","f":"דוד","dt":"תקמא - כו אייר","dp":"אזמיר","b":"מחכמי אזמיר.","s":"רוזניס-תורכיה-ה"},{"i":20213,"n":"חנין הלוי מסופיה","f":"אליה","b":"רב בסופיה-סוף שנות ה-ש'.","s":"רוזניס-תורכיה-ג"},{"i":20214,"n":"חנין מאדרינופול","f":"הין","b":"רב באדרינופול - בדור שאחר הגירוש.","s":"רוזניס-תורכיה-ב"},{"i":20215,"n":"חנין מטריקולה","f":"פרחיה","b":"רב קהלת סיציליה בטריקולה - בדור שלאחר הגירוש. בנו - ר משה מטריקולה.","s":"רוזניס-תורכיה-ב"},{"i":20216,"n":"חנין, אהרן מאלגיר","bt":"שך","dt":"שץ","b":"תלמיד הרשב\"ץ - ונזכר ב\"חוט המשולש\". חיבר פיוט לספר \"תפארת ישראל\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":20217,"n":"חנין, יהודה ממרוקו ואלגיר","f":"יעקב","k":"בעל ספר האור","bt":"רף - בערך","bp":"תארודאנת(מרוקו)","dt":"שן - בערך","b":"מקובל, בא ממרוקו, רב באלגיר, לימד קבלה לתלמידים. חיבר \"ספר האור\", פירוש על ספר המצוות לרמב\"ם בדרך פשט וסוד, ועוד. דודו של ר יעקב איפרגן בעל \"פרח שושן\". יש פיוט מר יהודה ן חנין נדפס ב\"תפארת ישראל\" - ונציה ואולי הוא נכדו.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":20218,"n":"חנין, מכלוף מאלגיר","bt":"ק - בערך","dt":"קץ - בערך","b":"רב במסתגאנם והיה \"זקן הקהל\" - (במשך השנים הפך התואר \"זקן הקהל\" ל\"מוקאדם\" - נגיד). בקשר מכתבים עם הריב\"ש והרשב\"ץ - ונזכר בתשבץ.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":20219,"n":"חנין, משה מפדובה","f":"פרחיה","b":"רב בונציה, פדובה. תשובה אליו לונציה ממהרם פדובה.","s":"איטליה גירונדי-מ ח"},{"i":20220,"n":"חנין, משה מפטרץ","b":"רב בפטרץ-שנות ה-ש'.","s":"רוזניס-תורכיה-ב"},{"i":20221,"n":"חנין, נחמן מונציה","f":"שבתי","k":"בעל פירוש לתורה","b":"מגדולי חכמי איטליה, רב בונציה-ת' בזמן בעל \"כלי חמדה\". מתשובותיו בספרי חכמי דורו. תשובה ממנו בשות ר מנחם מריקנטי - בנוגע לבעלי חנויות בפיררה. נזכר בהקדמת \"כלי יקר\" להרש\"ל. חיבר פירוש לתורה - בכת\"י.","s":"אוצר הרבנים 16010; איטליה גירונדי-נ ו,ז"},{"i":20222,"n":"חנינא ליפא מחמלניק","k":"ליפסון","b":"תלמיד הבעשט. מחותן עם ר אפרים בעל \"דגל מחנה אפרים\". בנו ר אריה ליב ליפסון מליטין. מתורתו ב\"משנת חסידים\".","s":"אלפסי"},{"i":20223,"n":"חנינאי כהנא גאון","f":"רב אברהם גאון","b":"גאון פומבדיתא ד'תקמ\"ב-תקמ\"ה,בגלל סכסוך עם ראש הגולה הורד מכיסאו","s":"ארזי הלבנון"},{"i":20224,"n":"חנינאי כהנא גאון סורא","f":"רב הונא","b":"גאון סורא-ד'תשכ\"ט-תשל\"ד,גידל ציפורניו מתוך ציפיה לעבוד ככהן בביהמ\"ק,תלמיד רב יהודאי גאון","s":"ארזי הלבנון"},{"i":20225,"n":"חנינה הכהן מג'רבה","b":"רב בג'רבה-תר\"ס","s":"אוצר הרבנים 6694"},{"i":20226,"n":"חנליש, אברהם מנחם מניס מפלשטין","b":"רבה של פלטשין-תרלו. בנו ר יהושע על מקומו אחריו.","s":"וונדר-גליציה ח\"ב,ח\"ו"},{"i":20227,"n":"חנליש, אליהו","k":"בעל יד אליהו","b":"רב בשנת תר\"מ","s":"אוצר הרבנים 2114"},{"i":20228,"n":"חנליש, יהודה ליב","f":"מאיר מטנהויזן","k":"בעל ויגש יהודה","r":"מתלמידי הרמ\"א וראש ישיבה בלובלין","dt":"שנו - כא שבט","b":"מגדולי חכמי אשכנז","s":"אוצר הרבנים 7278; מוריה קובץ לט עמודים מו - נ","bk":[["ויגש יהודה – הגהות מהרל\"ח - טור",""]]},{"i":20229,"n":"חנליש, יהושע מפלטשין","f":"אברהם מנחם מניס","dt":"תרצד - בערך","b":"רבה של פלטשין-תרפב. תשובה אליו - שושנים לדוד.","s":"וונדר-גליציה ח\"ב,ח\"ו"},{"i":20230,"n":"חנן (חאני), יעקב משלוניקי","dt":"תקיז","dp":"שלוניקי","b":"רופא בשלוניקי.","s":"זכרון שלוניקי-80"},{"i":20231,"n":"חנן מגיד מישרים מלכוביץ","b":"תלמיד ר שלמה מקרלין ור מרדכי מלכוביץ. מקובל והשתמש בקבלה מעשית עד שהניאו ר מרדכי מלכוביץ. הוא ואחיו ר חיים עשו \"שאלת חלום\" האם להצצרף לעדת החסידים ונענו \"כאיל תערוג על אפיקי מים כן נפשם תערוג אל האלקים\". בנו ר לייב-תלמיד ר חיים חייקא מאמדור.","s":"אלפסי"},{"i":20232,"n":"חנן ן, שלום ממרוקו","k":"בעל ברית שלום","dt":"תרצח","dp":"מרוקו - ישראל","b":"רב בנטיפה שבהרי האטלס-מרוקו, עם חביריו ר רפאל אנקווא, ור משה חליווא ממראקש.","s":"ארזי הלבנון"},{"i":20233,"n":"חנן, יעקב משלוניקי","b":"רופא בשלוניקי-תרו.","s":"זכרון שלוניקי-121"},{"i":20234,"n":"חנן, יצחק משה משלוניקי","dt":"תקיד","dp":"שלוניקי","b":"גביר בשלוניקי.","s":"זכרון שלוניקי-93"},{"i":20235,"n":"חנן, יצחק משלוניקי","k":"בעל בני יצחק","dt":"תמה-ז","dp":"שלוניקי","b":"ממשפחת הרב חנן דוד. גביר עשיר מחכמי שלוניקי-תמא, אחיו ר יעקב ור יוסף שעסקו במסחר פרנסוהו. נפטר ללא ילדים. נכד אחיו ר יעקב הו\"ל את ספרו \"בני יצחק\", וחיבר עוד \"מקנת כסף\", בארות חמר\" ועוד ונדפסו ביחד עם \"בני יצחק\". תלמיד נתן העזתי ואף אירחו בביתו - לאחר התאסלמות ש\"ץ, ויסד ישיבה ללימוד קבלה עבור נתן העזתי והיה מתלמידיה בשלוניקי.","s":"אוצר הרבנים 10668; ארזי הלבנון; זכרון שלוניקי-42; פין-כנסת ישראל; רוזניס-תורכיה-ד"},{"i":20236,"n":"חנן, שמעון משלוניקי","f":"ירמיה","dt":"תקפב - ח אדר","dp":"שלוניקי","b":"רופא בשלוניקי.","s":"זכרון שלוניקי-100; רוזניס-תורכיה-ו"},{"i":20237,"n":"חננאל איש רומי מקירואן","f":"רבינו חושיאל","bt":"ד'תשנב - בערך","b":"מגדולי חכמי ישראל בסוף תקופת הגאונים, מפרש התלמוד הבבלי, אביו רבינו חושיאל בא מאיטליה לאפריקה הצפונית, לאחר פטירת אביו שימש כראש ישיבת קירואן, מלבד הפירוש לתלמוד שהוא מן הפירושים הכוללים הראשונים, יש בידינו מקצת פירושו לתורה.","s":"אוצר הרבנים 6708; ארזי הלבנון; מלכי רבנן; פין-כנסת ישראל"},{"i":20238,"n":"חננאל הלוי מפדובה","dt":"שצא","dp":"פדובה","b":"גביר בעל חסד מחכמי פדובה.","s":"איטליה גירונדי-ח יג"},{"i":20239,"n":"חננאל מארץ ישראל","f":"אסקרא","b":"עלה לארץ ישראל ונפטר בגיל צעיר","s":"גליס; ירושלים ה"},{"i":20240,"n":"חננאל מביראת","f":"שלמה","bp":"שלוניקי","b":"רב בביראת(=ארנאוט בלגרד)-אלבניה-שנות ה-ת'. בנו - ר שלמה.","s":"רוזניס-תורכיה-ד"},{"i":20241,"n":"חננאל מלוטימורסק","dt":"תקעט - לפני","b":"מחכמי לאסק, רב בלוטימורסק-תקפ. חתן ר יוסף בן ר שמעון בן ר יצחק גולדעס, וגיסו של ר אברהם אליעזר דמשק מלאסק. מתלמידיו - ר סיני מברעזין בעל \"מנחת עני\" ומזכירו בספרו. הסכים על \"אבני קודש\" לגיסו ר אברהם אליעזר דמשק.","s":"אוצר הרבנים 6709; עיר לאסק וחכמיה"},{"i":20242,"n":"חננאל מפוסטאט","f":"שמואל","b":"ראש ישיבה בפוסטט-ד'תתקעה, ותלמיד ר פרחיה בן נסים על מקומו אחריו. חיבר פירוש על מסכת עירובין.","s":"אוצר הרבנים 6714; פין-כנסת ישראל"},{"i":20243,"n":"חננאל, משה מירושלים","f":"אברהם","dt":"תרכה - יג אדר","dp":"ירושלים","b":"מחכמי ירושלים.","s":"ארזי הלבנון; פרומקין-תח\"י"},{"i":20244,"n":"חנניה","f":"יצחק","b":"תרגום מערבית \"מוסרי הפילוסופים\".","s":"איטליה גירונדי-ח י"},{"i":20245,"n":"חנניה אלחנן חי הכהן מריגייו","k":"בעל חנוך לנער","bt":"תקיא","bp":"ריגיו","dt":"תקצג","b":"תלמיד ר שמשון נחמני ור ישעיה חי קרמי. רב ומלמד תורה בריגייו, ופירנצה. מדקדק,משורר,דרשן,חיבר ספרים רבים \"חנוך לנער\" דיני תפילה ועוד.","s":"איטליה גירונדי-ח ז; ארזי הלבנון; פין-כנסת ישראל"},{"i":20246,"n":"חנניה גבריאל משלוניקי וירושלים","dt":"תרמח","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים-תרך.","s":"זכרון שלוניקי-152"},{"i":20247,"n":"חנניה הכהן מוילקוביסק","b":"דיין בוילקוביסק.","s":"אוצר הרבנים 6693; ליטא"},{"i":20248,"n":"חנניה הכהן ממרוקו וארץ ישראל","k":"ר' אמיניה הכהן","dp":"מראקש","b":"כנראה בא מא\"י למרוקו, נחשב לקדוש העיקרי במראקש, גם מוסלמים משתטחים על קברו.","s":"ארזי הלבנון; מלכי רבנן"},{"i":20249,"n":"חנניה הכהן מפאס","f":"משה","b":"מחכמי פאס, חתם-רפו בענין הנפיחה.","s":"טולדנו-נר המערב"},{"i":20250,"n":"חנניה הפייטן","f":"שלחיה","b":"חיבר פיוטים לסליחות, ומהם במחזור רומניה, אפריקה, ופרובנס.","s":"פין-כנסת ישראל"},{"i":20251,"n":"חנניה מירושלים","k":"ח' החסיד איש ירושלים","b":"מגדולי חכמי ירושלים הקדמונים-ד'תש\"ל","s":"אוצר הרבנים 6684"},{"i":20252,"n":"חנניה מירושלים","f":"ברקון","b":"מחכמי ירושלים, חתם על התקנה נגד הפירוש בשנת שפג.","s":"גליס; ירושלים ג"},{"i":20253,"n":"חנניה מסעלץ ובריסק","b":"מחכמי סעלץ, ר\"מ בבריסק-תרך. המליץ לבני סעלץ לקבל את הגדול ממינסק לרב.","s":"הגדול ממינסק"},{"i":20254,"n":"חנניה נחום ליפמן","dt":"תשג","b":"רב בפלאטל","s":"אוצר הרבנים 6701"},{"i":20255,"n":"חנקין, יהושע","bt":"1864","dt":"1945","b":"עסקן ציוני, גואל קרקעות","s":"מתוך קטלוג"},{"i":20256,"n":"חסא, שמעון בנימין מכורדיסטן","b":"רב בעמדיא-כורדיסטן, אביו של ר עילואן אבידני.","s":"ארזי הלבנון"},{"i":20257,"n":"חסאן מקורדובה","k":"בעל חשבון העיבור","b":"דיין בקורדובה-ד'תשלב, תוכן, חיבר ספר בחשבון ועיבור.","s":"אוצר הרבנים 6716; ארזי הלבנון; פין-כנסת ישראל"},{"i":20258,"n":"חסאן, אברהם הלוי","k":"בעל תריג מצוות","b":"מחכמי טורקיה, חיבר תרי\"ג מצוות מסודרים לפני מנין ימות השבוע.","s":"ארזי הלבנון; אלופי יעקב א-צט"},{"i":20259,"n":"חסאן, אברהם מטיטואן","b":"מחכמי טיטואן, חתם על פס\"ד-תכט.","s":"מלכי רבנן"},{"i":20260,"n":"חסאן, אברהם מלוב","dt":"תשמב","b":"רב בלוב, עלה לארץ וכיהן כרב במושב שדה עוזיהו.","s":"מלכי חי\"ל-מרציאנו"},{"i":20261,"n":"חסאן, אברהם משלוניקי","f":"משה","b":"מחכמי שלוניקי-שנות הר'.","s":"זכרון שלוניקי"},{"i":20262,"n":"חסאן, אפרים מסאלי","b":"רבה של סאלי","s":"ארזי הלבנון"},{"i":20263,"n":"חסאן, דוד (שמואל) מירושלים","b":"מחכמי ישיבת \"כנסת ישראל\" בירושלים-תקיח.","s":"רוזניס-תורכיה-ה"},{"i":20264,"n":"חסאן, יהודה ממצרים","b":"מגדולי רבני מצרים-שנה.","s":"אוצר הרבנים 6939; ארזי הלבנון"},{"i":20265,"n":"חסאן, יהודה ממצרים","b":"רב במצרים-סוף שנות ה-ש'.","s":"רוזניס-תורכיה-ג"},{"i":20266,"n":"חסאן, יצחק מלוב","bt":"תם","dt":"תקי - בערך","b":"רב בחבל ג'ריאן-לוב. עליו ב\"מחניים\"-צג ת\"א תשכד.","s":"מלכי חי\"ל-מרציאנו"},{"i":20267,"n":"חסאן, יצחק מספרד ושלוניקי","b":"חזן בספרד, לאחר הגירוש חזן בשלוניקי.","s":"רוזניס-תורכיה-א,ב"},{"i":20268,"n":"חסאן, מאיר מאזמיר","dt":"תקיא - כג ניסן","dp":"אזמיר","b":"רב באזמיר-שנות ה-ת'.","s":"רוזניס-תורכיה-ה"},{"i":20269,"n":"חסאן, מרדכי מטיטואן","b":"רב בטיטואן-תנז, וחתם עם ר חסדאי אלמושנינו.","s":"ארזי הלבנון; מלכי רבנן"},{"i":20270,"n":"חסאן, משה מטריפולי","bt":"תקס","dt":"תרל - בערך","b":"מחכמי טריפולי. העתיק מסורות קדומות של יהודי טריפולי. נזכר ב\"הגיד מרדכי\" - ירושלים תשלט לר מרדכי הכהן.","s":"מלכי חי\"ל-מרציאנו"},{"i":20271,"n":"חסאן, רפאל מאיר מאזמיר","k":"בעל מנת חלקי","dt":"תרד - כה סיון","b":"רב באזמיר. חיבר \"מנת חלקי\" והדפיסו עם \"עושה חיל\" לר חיים יוסף ליג'י.","s":"ארזי הלבנון"},{"i":20272,"n":"חסאן, רפאל ממוגאדור-מרוקו","k":"בעל לחם עוני","b":"מחכמי מוגאדור-מרוקו, התישב בלונדון - בסוף שנות ה-תק'.","s":"ארזי הלבנון; מלכי רבנן"},{"i":20273,"n":"חסאן, שבתי משלוניקי","f":"עמנואל חסן","k":"בעל חוסן ישועות","dt":"תן","dp":"שלוניקי","b":"מחכמי שלוניקי, תלמיד ר דניאל אישטרושה בישיבת ק\"ק פורטוגל יחייא. למד גם בישיבת נתן העזתי-תלז. חיבר \"חוסן ישועות\" והוא מראה מקומות על הטור ונדפס בחלקו.","s":"אוצר הרבנים 18060; ארזי הלבנון; זכרון שלוניקי; רוזניס-תורכיה-ד"},{"i":20274,"n":"חסאן, שלמה מטיטואן","dt":"תקן - בערך","dp":"טיטואן","b":"ציר ספרד בטיטואן-תק'. נהרג בידי המושל אליזיד בזמן הפרעות בטיטואן.","s":"טולדנו-נר המערב"},{"i":20275,"n":"חסאן, שלמה מירושלים","f":"דוד","dt":"תקנה - ז אלול","dp":"ירושלים","b":"רב בירושלים. בשליחות צפת באיטליה. חתן ר יום טוב אלגזי, מתורתו בספרי אביו.","s":"איטליה גירונדי-ש נב; רוזניס-תורכיה-ה"},{"i":20276,"n":"חסאן, שמעון כליפא מלוב","f":"ג'רמון","bt":"תרטז","bp":"ג'ריאן-לוב","dt":"תשז","dp":"מצראתה-לוב","b":"רב בתאג'ורה-לוב, זאויה-לוב, מצראתה-לוב. לתולדותיו ב\"גשר חסון\" נתניה תשנח - בעריכת משה ג'יאן.","s":"מלכי חי\"ל-מרציאנו"},{"i":20277,"n":"חסד לאברהם - ישיבה בירושלים","b":"ישיבה בירושלים, נוסדה-תקז בידי ר אברהם בן נתן ור דוד פארדו. הישיבה התאחדה עם ישיבת \"בנין שלמה\".","s":"רוזניס-תורכיה-ה"},{"i":20278,"n":"חסדאי הכהן מקושטא","b":"מגדולי חכמי דורו,פוסק,מרביץ תורה בקושטא-ש\"פ","s":"אוצר הרבנים 6719"},{"i":20279,"n":"חסדאי הלוי ממצרים","b":"מחכמי מצרים בתקופת הרמב\"ם,רב באלכסנדריה,שאלותיו לרמב\"ם מופיעות בשו\"ת הרמב\"ם","s":"ארזי הלבנון"},{"i":20280,"n":"חסדאי מספרד","dt":"קנא","b":"חריף ובקי,מיוחד שבעדה,רב בטודילו,ולנסיה","s":"אוצר הרבנים 6717"},{"i":20281,"n":"חסדאי מספרד","f":"נסים","b":"מחכמי ספרד בדור הריב\"ש,בנו ותלמידו של הר\"נ","s":"ארזי הלבנון"},{"i":20282,"n":"חסדאי מפטרץ","b":"רב בפטרץ-שנות ה-ש' לצד ר צדיק פירמון.","s":"רוזניס-תורכיה-ג"},{"i":20283,"n":"חסדאי ן, אברהם מברצלונה","f":"שמואל","k":"בעל מאזני צדק","b":"אחיו של ר יהודה. רב ופייטן בברצלונה בזמן הרד\"ק. תרגם מערבית \"ספר התפוח\" לאריסטו ו\"בן המלך והנזיר\". חיבר \"מאזני צדק\" שהעתיק מפילוסוף קדמון, ועוד. כתב לר יהודה אלפאכר בענין מחלוקת על ספרי הרמב\"ם, ותומך ברד\"ק.","s":"איטליה גירונדי-א סז; אלופי יעקב א-צח"},{"i":20284,"n":"חסדאי ן, אברהם משלוניקי","b":"רב בשלוניקי-שמ.","s":"זכרון שלוניקי; רוזניס-תורכיה-ג"},{"i":20285,"n":"חסדאי ן, יהודה מספרד","f":"שמואל","k":"מתרגם ספר המצוות","b":"משורר ופייטן מחכמי ספרד, מתרגם ומליץ, תמך ברמב\"ם, תרגם את \"ספר המצוות\" ואת \"אגרת תימן\", וכן ספר של אריסטו, חי בדורו של הרמ\"ה","s":"ארזי הלבנון"},{"i":20286,"n":"חסדאי ן, יהודה מפאס","f":"מרדכי","b":"תלמיד ר חיים דוד סירירו. מחכמי פאס-תקפו ונזכר באגרת רבו לר ישועה אביטבול.","s":"מלכי רבנן"},{"i":20287,"n":"חסדאי ן, יוסף מספרד","k":"אבו עמר","b":"משורר מחכמי ספרד-שנות ה-ד'תש בזמן ר שמואל הנגיד וחיבר שיר לכבודו.","s":"פין-כנסת ישראל"},{"i":20288,"n":"חסדאי ן, שמואל מספרד","f":"אברהם","dt":"ד'תתקעו","b":"מחכמי ספרד, נזכר אצל ר יהודה אלחריזי.","s":"ארזי הלבנון"},{"i":20289,"n":"חסדאי, אבו אלידד","b":"פייטן, מגדולי ספרד אליסאנא(אולי בנו של ר' יוסף בן חסדאי)","s":"ארזי הלבנון"},{"i":20290,"n":"חסדו, מרדכי מארבאט","f":"שלמה","b":"מחכמי ארבאט, וסופר בי\"ד-שנות ה-תק'.","s":"מלכי רבנן"},{"i":20291,"n":"חסדן, חיים ניסן מלישינעוויטש","f":"מרדכי","bt":"תרמ","b":"רב ביאריסלוב-תרסה, לישינעוויטש-פלך חרסון. נסמך מאת: ר צבי דב מהומל, ר הלל מסטרדוב, ר משה הורביץ בעל \"ידי משה\".","s":"אוצר הרבנים 6526; אהלי שם"},{"i":20292,"n":"חסון, אברהם מחברון וצפת","b":"מצאצאי ר שלמה ן חסון בעל \"משפטים ישרים\". רב בחברון, עבר לצפת. בשנת תקם חתום על קבלת כספים מר יהודה אסיאו בקהילת חברון-תקם, בשליחות צפת-תקע באירופה.","s":"גליס; ארזי הלבנון; ירושלים לזכר לונץ, ספונות ספר ז מאמר א.י. כץ ועוד"},{"i":20293,"n":"חסון, אברהם משלוניקי","dt":"תצט","dp":"שלוניקי","b":"גביר בשלוניקי.","s":"זכרון שלוניקי-70"},{"i":20294,"n":"חסון, אברהם משלוניקי","b":"דיין בשלוניקי-תקפב. חתם-תקפד עם ר משה ברכה ור מנחם גטניו.","s":"זכרון שלוניקי-117; רוזניס-תורכיה-ו"},{"i":20295,"n":"חסון, אהרן ממרוקו","b":"מחכמי מרוקו, מכתב ממנו לר שלמה ן צור-תרכא.","s":"מלכי רבנן"},{"i":20296,"n":"חסון, אהרן משלוניקי","f":"שלמה","dt":"שסב או שעב-שעז","b":"רב וראש ישיבה ופוסק בשלוניקי-שסא, עבר לקושטא, וחזר לשלוניקי. אחרי פטירת ר דוד ן שושן, התיר לאנשי ק\"ק שלום את שבועותם שלא למנות רב על מקומו עשר שנים, ומינו את ר שמואל פלורנטין בעל \"מעיל שמואל\". מתלמידיו: ר יעקב הכלוי מזנטי בעל שו\"ת מהר\"י הלוי, ר מרדכי קלעי משלוניקי ואחיו ר ברוך קלעי מסדרקוסי, ר מאיר מלמד בן שם טוב בעל \"משפט צדק\", ר יוסף ן עזרא בעל \"עצמות יוסף\". בנו - ר שלמה הבחור.","s":"ארזי הלבנון; אלופי יעקב א-תפח; זכרון שלוניקי; רוזניס-תורכיה-ג"},{"i":20297,"n":"חסון, אהרן משלוניקי וירושלים","dt":"תקי - ב אלול","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לחברון, ירושלים, התיר לאנשי ק\"ק שלום בשלוניקי את שבועתם שלא למנות רב על מקום ר דוד ן שושן, ומינו את ר שמואל פלורנטין בעל \"מעיל שמואל\". בנו - ר יוסף מירושלים.","s":"גליס; אוצר הרבנים1571; ארזי הלבנון; זכרון שלוניקי-85; פרומקין-תח\"י; רוזניס-תורכיה-ה; שא\"י,"},{"i":20298,"n":"חסון, אליהו משלוניקי","b":"מנהל בביה\"ס ת\"ת בשלוניקי-לפני השואה.","s":"זכרון שלוניקי-137"},{"i":20299,"n":"חסון, אליהו משלוניקי","b":"מחכמי שלוניקי, מנהל ת\"ת לפני הד\"ר אפשטין.","s":"זכרון שלוניקי-213"},{"i":20300,"n":"חסון, אפרים נתן מחברון","b":"מחכמי חברון-תר, בשנת תקץ חתם על יסוד ישיבת \"מגן אבות\" וכן בשנת תריד על בקשת עזרה.","s":"גליס; ארזי הלבנון"},{"i":20301,"n":"חסון, דוד (פלוכרון) מחברון","b":"מראשי קהלת חברון, חתם-תרלב עם ר אליהו מני ור משה קמחי.","s":"מתוך קטלוג"},{"i":20302,"n":"חסון, דוד אהרן","b":"מגדולי חכמי חברון-תקצ\"ט","s":"אוצר הרבנים 5083"},{"i":20303,"n":"חסון, דוד חיים שמואל מירושלים","f":"שמואל","k":"בעל קדשי דוד","bp":"סאלי או אלגיר","dt":"תקפד? - יב אב","dp":"ירושלים או ליוורנו","b":"מחכמי אלגיר ופגש את ר חיים ן עטר בעל \"אור החיים\" ועלה אתו לירושלים-תקב. מחכמי ישיבת \"כנסת ישראל\". חתם על הקדמה לספר רבו \"ראשון לציון\". נתמנה לדיין, בשליחות בצפון אפריקה-תקיח, בדרכו חזרה נתקבל כרב באלכסנדריה-תקכה - תקלא, לאחר מכן עבר עם בנו ר שלמה לליוורנו-תקלב - תקמד והתגוררו בבית הגביר ר יוסף פראנקו ושם הנהיג ישיבה \"בית יוסף\", חתם שם \"איש ירושלים\", חיבר ספר \"קדשי דוד וחסדי דוד\" ליוורנו תקנב, \"מכתם לדוד\" על הרמב\"ם. הספרים נדפסו על ידי בנו ר שלמה חסאן שהיה חתנו של ר יום טוב אלגזי. חזר לירושלים וכיהן כדיין, (בשליחות בליוורנו ונשאר שם כרב בת\"ת \"יפאר ענוים\" שבנה הגביר ר יוסף פרנקו - האם שליחות נוספת?). יש אומרים שנפטר בירושלים (לדעת שא\"י נפטר בליוורנו בשנת תקמה). חתנו - ר יוסף אזוביב-ראב\"ד אלגיר. (לפי מלכי ישורון נפטר בליוורנו תקמה). הסכים על \"עוללות הבצר\", \"דברי שירה\"-תקס, \"עץ החיים\"-תקמב, \"מאמר מרדכי\"-תקמד, ועוד.","s":"אוצר הרבנים 5116; גליס; איטליה גירונדי-ד ד; פין-כנסת ישראל; מלכי ישורון-חכמי אלגיר; ארזי הלבנון; פרומקין-תח\"י; גאון-יהודי המזרח; רוזניס-תורכיה-ה; י. מאן תרביץ ט,"},{"i":20304,"n":"חסון, חיים יוסף מחברון - א","b":"מחכמי חברון, בשנת שעו חתם על מכתב בקשת עזרה עם רבני הקהלה.","s":"גליס; ירושלים י."},{"i":20305,"n":"חסון, חיים יוסף מחברון - ב","b":"מחכמי חברון, בשנת תקכג חתם על כתב שליחות ר רחמי באגאיו, ור יצחק זאבי.","s":"גליס"},{"i":20306,"n":"חסון, חיים ישכר מחברון","b":"מחכמי חברון, בשנת תקמח חתם על מכתב, בשנת תקנב ותקנח חתם עם גדולי חברון על בקשת עזרה. הסכים על \"שמן המור\" בשנת תקן. בשנת תקנב חתם על כתב שליחות ר אפרים נבון ור יהודה ליאון. בתקפב חתם על כתב שליחות ר יוסף עייאש.","s":"גליס; ירושלים לזכר לונץ, ריבקינד ציון ה-ו."},{"i":20307,"n":"חסון, חיים שושנה (שמואל) מחברו","b":"מחכמי חברון, חתום על אגרת רבני חברון משנת תקפח, ועל כתב שליחות ר יוסף דוד עייאש בשנת תקץ. כנראה הוא ר חיים שמואל שחתם על אגרת שליחות של ר נתן עמרם. מחמי חברון, בשנת תרס בשליחות הקהלה, היה יד ימינו של ר חזקיהו חיים מדיני שמסר בידיו את ההגהה וההדפסה של חלקיו האחרונים של \"שדי חמד\", לאחר פטירתו של ר חזקיהו מדיני נתמנה לרב הקהלה. נרצח בטבח בחברון וכתביו נשרפו גם הם. (יש כאן בלבול בשנים - שני רבנים שונים?)","s":"גליס; ירושלים לזכר לונץ"},{"i":20308,"n":"חסון, חנוך מחברון","f":"מרדכי מחברון","bt":"תרכז","bp":"חברון","dt":"תרפט - יח אייר","dp":"חברון","b":"חתן ר רחמים יוסף פרנקו מחברון. מחכמי חברון, בשנת תרס בשליחות הקהלה, דיין ויד ימינו של ר חזקיהו חיים מדיני שמסר בידיו את ההגהה וההדפסה של חלקיו האחרונים של \"שדי חמד\", לאחר פטירתו של ר חזקיהו מדיני ור אליהו מני נתמנה לאב\"ד הקהלה. נהרג עק\"ה בטבח בחברון וכתביו נשרפו גם הם.","s":"גליס; אוצר הרבנים 6644; גאון-יהודי המזרח; ארזי הלבנון; תדהר א, יהבי, יזכור לקדושי חברון."},{"i":20309,"n":"חסון, יהודה מצפת","b":"מחכמי צפת, בשנת תקנב חתם על בקשת עזרה של הקהלה והיה בשליחות באירופה.","s":"גליס; שא\"י"},{"i":20310,"n":"חסון, יוסף משלוניקי","f":"יעקב","dt":"תקי - אחרי","dp":"שלוניקי","b":"מחכמי שלוניקי. בנו של הגביר ר יעקב ן חסון.","s":"זכרון שלוניקי-85"},{"i":20311,"n":"חסון, יוסף משלוניקי וירושלים","f":"אהרן","k":"בעל בית המלך","bp":"שלוניקי?","dt":"תקכ-ג -כג תשרי","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים וכיהן כרב בירושלים עם ר יוסף חזקיה קובו. בשנת תקיד חתם על הסכמה שנשים תלכנה עם רעלות ברחוב. הסכים על \"שלחן גבוה\" לר יוסף מולכו, וכן על ספר \"שער יוסף\" לחידא. בשנת תקיח חתם על כתב שליחות ר אליהו צבי. מגיה בבית הדפוס, דיין בבית דינו של ר יונה נבון וכן בבית דינו של רפאל בן שמואל מיוחס. חיבר \"בית המלך\" שלוניקי תקסד (נדפסו עם \"סוכת דוד\", למרות שבספר יחסו לאביו מסתבר שהוא המחבר). גיסיו: ר חנניה שאול, ור אשר שלם - והביאו מחדושיו בספריהם (\"מגן שאול\" ו\"מטה אשר\"). הסכים על \"שלחן גבוה\", \"שער יוסף\" - תקיד. תלמידו - ר אברהם קובו. (בחכמי ירושלים - פרומקין - תאריך פטירתו יד ניסן תקך).","s":"גליס; אוצר הרבנים 8319; זכרון שלוניקי-85; פרומקין-תח\"י; רוזניס-תורכיה-ה"},{"i":20312,"n":"חסון, יעקב חי משלוניקי","b":"מגיה בדפוס קלעי ומרדכי נחמן בשלוניקי-שנות ה-תק'.","s":"רוזניס-תורכיה-ה"},{"i":20313,"n":"חסון, יעקב יוסף משלוניקי","b":"גביר בשלוניקי-תקיז, סייע לבן דודו - ר יעקב שאול בהדפסת ספר אביו \"מגן שאול\".","s":"רוזניס-תורכיה-ה"},{"i":20314,"n":"חסון, יעקב מירושלים","b":"מגדולי רבני ירושלים-תקי\"ד","s":"אוצר הרבנים 9635"},{"i":20315,"n":"חסון, יעקב משלוניקי","dt":"תקא","dp":"שלוניקי","b":"גביר בשלוניקי. נפטר במגיפה-תקא.","s":"זכרון שלוניקי-93"},{"i":20316,"n":"חסון, יעקב משלוניקי","dt":"תקד","dp":"שלוניקי","b":"גביר בשלוניקי. חתניו: ר חנניה שאול, ור אשר שלם.","s":"זכרון שלוניקי-93"},{"i":20317,"n":"חסון, יעקב משלוניקי","b":"מחכמי שלוניקי-רע. חתן דון שלמה ן חיון.","s":"עמנואל-שלוניקי"},{"i":20318,"n":"חסון, יעקב משלוניקי - ג","dt":"תקל","dp":"שלוניקי","b":"גביר בשלוניקי. סייע עם אחיו יצחק בהדפסת \"בית הראה\" לר שמואל פלורנטין-תקיח.","s":"זכרון שלוניקי-93"},{"i":20319,"n":"חסון, יצחק","f":"אהרן","k":"בעל אהל יצחק","s":"ארזי הלבנון"},{"i":20320,"n":"חסון, יצחק מקאשטוריאה","b":"רב בקאשטוריאה-תעח.","s":"רוזניס-תורכיה-ד"},{"i":20321,"n":"חסון, יצחק מקושטא","b":"רב בקושטא-תקמז.","s":"רוזניס-תורכיה-ו"},{"i":20322,"n":"חסון, יצחק משלוניקי","dt":"תצה","dp":"שלוניקי","b":"דיין-תנז, ורב הכולל בשלוניקי ועוזרו של הראב\"ד-ר יוסף דוד-מהרי\"ד. חתם על הסכמת ר יוסף קובו-תפה - בענין פטור תלמידי חכמים ממס, ועל הסכמה נוספת-תפט.","s":"זכרון שלוניקי-70,65"},{"i":20323,"n":"חסון, יצחק משלוניקי","dt":"תקיח - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי. סייע עם אחיו יעקב בהדפסת \"בית הראה\" לר שמואל פלורנטין-תקיח.","s":"זכרון שלוניקי-93"},{"i":20324,"n":"חסון, ישכר מחברון","b":"מחכמי חברון-תקן, חתם עם חכמי חברון.","s":"רוזניס-תורכיה-ה"},{"i":20325,"n":"חסון, כלפא מאלגיר","dt":"תקסו - לפני","b":"רב בקצמטינא. נזכר ב\"אשכבתא דרבנן\".","s":"מלכי ישורון-חכמי אלגיר"},{"i":20326,"n":"חסון, מרדכי מחברון","b":"מחכמי חברון ומראשי העדה. חתם עם ר אליהו מני-תרנה, ועם ר חיים חזקיה מדיני. בנו - ר חנוך.","s":"גאון-יהודי המזרח"},{"i":20327,"n":"חסון, משה מחברון","b":"מגדולי חכמי חברון-תרנ\"ט","s":"אוצר הרבנים 14707"},{"i":20328,"n":"חסון, עמנואל","f":"מנחם","k":"בעל כללי הגמרא","b":"חיבר כללי הגמרא ונדפס בתוך \"מהררי נמרים\".","s":"איטליה גירונדי-ע ב"},{"i":20329,"n":"חסון, רפאל משלוניקי","b":"מחכמי שלוניקי. הגיה את \"חיי אברהם\" לר אברהם קובו-תקסד, \"נר מצוה\" לר יהודה מנוח סיד, ועוד. פסק ממנו ב\"ידי דוד\" לר דוד קראסו.","s":"זכרון שלוניקי-112"},{"i":20330,"n":"חסון, רפאל משלוניקי","b":"מחכמי שלוניקי-תרם. מתומכי חברת \"עץ החיים\"","s":"זכרון שלוניקי-152"},{"i":20331,"n":"חסון, שלמה מאיטליה","f":"דוד חיים שמואל","k":"בעל מכתם לדוד","dt":"תקנה - ז אלול","dp":"ירושלים","b":"אביו היה מתלמידי ר חיים בן עטר, מחכמי ירושלים. חתן ר יום טוב אלגזי - מהרי\"ט. תלמיד החיד\"א בשנים תקיז-תקכד, בשנת תקמד בשליחות באיטליה וכיהן שם כרב-תקנב, חזר לירושלים וכיהן כראש ישיבת \"יפאר ענוים\". חיבר \"מכתם לדוד\" וכן הוציא לאור את ספרי אביו. אשתו - אסתר נפטרה בתקסז.","s":"גליס; אוצר 18450; ארזי הלבנון; פרומקין-תח\"י; רוזניס-תורכיה-ה; שא\"י"},{"i":20332,"n":"חסון, שלמה משלוניקי","dt":"תקמג","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"מנחת בכורים\" לר מיוחס בן שמואל-תקיב.","s":"זכרון שלוניקי-94"},{"i":20333,"n":"חסון, שלמה משלוניקי","f":"אהרן","b":"דיין בשלוניקי-ראשית שנות ה-תר'.","s":"זכרון שלוניקי-141"},{"i":20334,"n":"חסון, שלמה משלוניקי - הבחור","f":"אהרן בן שלמה","k":"בעל משפטים צדיקים","dt":"שפא - יא אלול","dp":"שלוניקי","b":"חתן ר אליהו רוסאנו(=רוסני). רב בשלוניקי, תלמיד ישיבת יחייא. חברם של ר חיים שבתי ור יצחק בן שלמה הלוי. מחדושיו והגהותיו ב\"בית שלמה\"-לאביו, \"מורה צדק\", ו\"דורש משפט\" וצויינו - רשב\"ח - ר\"ת של שמו. בנו - ר אהרן. יש בלבול בין חכמים שונים באותו השם, ובנוסף - לפי אוצר הרבנים - בנו - ר אהרן ן חיים וגם אביו ר אהרן ן חיים - יש שם בלבול.","s":"אוצר הרבנים 18449; גאון-יהודי המזרח; איטליה גירונדי-ש כ; ארזי הלבנון; מלכי רבנן; רוזניס-תורכיה-ג"},{"i":20335,"n":"חסון, שלמה משלוניקי - הזקן","dt":"של - כז תשרי","b":"מגדולי רבני שאלוניקי-ש\"ל","s":"אוצר הרבנים 18449 א'; מלכי רבנן"},{"i":20336,"n":"חסון, שלמה משלוניקי הזקן","dt":"שיט - אחרי","b":"רב בשלוניקי, היה במחלוקת עם ר יוסף ן לב. חתם על \"הסכמות הקהל\" בשלוניקי. בנו - ר אהרן ן חיים. יש בלבול בין חכמים שונים באותו השם (יש דיין בצפת באותו השם).","s":"זכרון שלוניקי; אוצר הרבנים 18326,18449 א'; מלכי רבנן; רוזניס-תורכיה-ב"},{"i":20337,"n":"חסון, שמואל משלוניקי ושירון","b":"מחכמי שלוניקי, דיין בשירון-שנות התק'.","s":"זכרון שלוניקי-92"},{"i":20338,"n":"חסון, שמעון","b":"מחכמי חברון, בשנת תרכו בשליחות באדרינופול.","s":"גליס"},{"i":20339,"n":"חסיד - משפחה","b":"משפחה בשלוניקי, מצאצאי קרובי רבי יהודה החסיד.","s":"רוזניס-תורכיה-ד"},{"i":20340,"n":"חסיד, אהרן","dt":"תקמד - יז ניסן","b":"דיין בקרקא","s":"אוצר הרבנים 1573"},{"i":20341,"n":"חסיד, אליעזר משלוניקי","b":"מחכמי שלוניקי-תרס.","s":"זכרון שלוניקי-191"},{"i":20342,"n":"חסיד, דוד בכור משלוניקי","dt":"תרכג","dp":"ירושלים","b":"מחכמי שלוניקי, דרש מהרבנים שיוכיחו את הגבירים כמו את העניים ללא משוא פנים.","s":"זכרון שלוניקי-141"},{"i":20343,"n":"חסיד, דוד הלוי משלוניקי","b":"תלמיד ר דניאל אישטרושא, מחכמי שלוניקי-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":20344,"n":"חסיד, חננאל חיים משלוניקי","k":"בעל הלל וזמרה","b":"מנהל ביה\"ס ת\"ת בשלוניקי-אחרי תרע, וחבר באגודת הפייטנים בשלוניקי. הו\"ל עם צדיק נחמה גרשון קובץ פיוטים בשם \"הלל וזמרה\" שלוניקי תרפח.","s":"זכרון שלוניקי-136,191,220"},{"i":20345,"n":"חסיד, יוסף הכהן מקושטא","b":"תלמיד מהרימ\"ט. מחכמי קושטא-שנות ה-ת'.","s":"רוזניס-תורכיה-ד"},{"i":20346,"n":"חסיד, יוסף שמואל משלוניקי","dt":"תרמט","dp":"שלוניקי","b":"גביר בשלוניקי.","s":"זכרון שלוניקי-152"},{"i":20347,"n":"חסיד, יוסף שמואל משלוניקי","dt":"תרעו","dp":"שלוניקי","b":"מחכמי שלוניקי.","s":"זכרון שלוניקי-213"},{"i":20348,"n":"חסיד, יעקב יצחק משלוניקי","dt":"תש..","b":"מחכמי שלוניקי. נספה בשואה.","s":"זכרון שלוניקי-214"},{"i":20349,"n":"חסיד, יעקב קופל מטיסמניץ","dt":"תקמז - יז אלול","b":"תלמיד הבעש\"ט,בקולומייא,טיסמניץ","s":"אוצר הרבנים 10302"},{"i":20350,"n":"חסיד, יצחק חננאל משלוניקי","dt":"תש..","b":"אב\"ד בשלוניקי, ראש ישיבת ג'ינילייו. נספה בשואה.","s":"זכרון שלוניקי-213"},{"i":20351,"n":"חסיד, יצחק שמואל משלוניקי","dt":"תרמז","dp":"שלוניקי","b":"גביר בשלוניקי.","s":"זכרון שלוניקי-145"},{"i":20352,"n":"חסיד, משה יהודה משלוניקי","dt":"תרעו","dp":"שלוניקי","b":"מחכמי שלוניקי, ראש ה\"שמאים\" (מעריך נדוניות), ורב ביכ\"נ.","s":"זכרון שלוניקי-213"},{"i":20353,"n":"חסיד, נחמן מסטפניץ","f":"יודל","bt":"תרכ","b":"רב בסטעפניץ-פלך קיוב-תרמז. פרסם מאמרים בכתבי עת שונים, ובהם ב\"אהל יצחק\" סטמר - תרסג - תרעד, \"שערי תורה\" - וארשא, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"קול תורה\" - וארשא תרסח, \"תורה מציון\" - ירושלים תרנה-תרסה. נסמך מאת: ר ישראל איזנשטין בעל \"עמודי אש\".","s":"אוצר הרבנים 15985; דור וחכמיו-א\"ש-ו; אוצר כתבי עת-לוין; אהלי שם"},{"i":20354,"n":"חסיד, שבתי משלוניקי","b":"גביר בשלוניקי-תרם. יסד ישיבה בשם \"לה ישיבה די ח\"ם(חכם) שבתי חסיד\".","s":"זכרון שלוניקי-157"},{"i":20355,"n":"חסיד, שמחה","b":"מחבורת ר יהודה החסיד, עלה לירושלים-תנח, חזר לאירופה, השתמד בבומברג.","s":"רוזניס-תורכיה-ד"},{"i":20356,"n":"חסידא-בוטשאן, מנחם זאב","bt":"תרמה","dt":"תשכה","b":"חסיד האדמור מאלכסנדר בעל \"ישמח ישראל\", עלה לירושלים-תרפה. עסק בהעתקת והדרת כתבי יד עתיקים, הו\"ל כתב עת \"הסגולה\".","s":"מתוך קטלוג"},{"i":20357,"n":"חסידה ישראל יצחק בן מנחם זאב","k":"יש\"י חסידה","bt":"כז אלול תרע","dt":"ערב פסח תשסג","s":"המודיע גליון 18666 עמוד ו'; היברובוקס","bk":[["אוצר אישי התנ\"ך",""],["אוצר מאמרי הלכה",""],["ביאורי החסידות לנ\"ך",""],["ביאורי החסידות לש\"ס",""],["ביאורי המקובלים לנגלה",""],["זכרון לבני ישראל",""],["זקני ישראל – תפילות לימי הזקנה",""],["חמישים שערי חסידות",""],["כרמי ישראל – נ\"ך וסידור",""],["משפחתנו – תולדות",""],["נס חנוכה – שו\"ת לנוער",""],["רב האיי גאון – רשויות לפרשיות התורה",""],["רבי חיים פאלג'י וספריו",""],["תהלות ישראל – תפילות לימי הולדת ועוד",""]]},{"i":20358,"n":"חסין ן, אברהם ממכנאס","f":"דוד","dt":"תצח - אחרי","b":"מו\"ץ ודיין במכנאס, חתם על פס\"ד-תצב עם ר שלום אדרעי, ר אברהם ן עלאל, ועוד. נזכר בשו\"ת \"משפט וצבי\".","s":"ארזי הלבנון; מלכי רבנן; טולדנו-נר המערב"},{"i":20359,"n":"חסין ן, אברהם ממרוקו","k":"בעל שמע אברהם","bt":"תקץ","dt":"תרסב - אב","b":"רב ומו\"ץ במכנאס, כתב \"שמע אברהם\"","s":"ארזי הלבנון"},{"i":20360,"n":"חסין ן, דוד ממכנאס","f":"אהרן","k":"בעל מגדל דוד","bt":"תפז","dt":"תקנב","b":"משורר מחכמי מכנאס. חתן ר' מרדכי בירדוגו, חיבר \"מגדל דוד\" ספר דרשות. היו לו 9 בנות, מחתניו: ר יעקב בירדוגו בעל \"שופריה דיעקב\".","s":"ארזי הלבנון; מלכי רבנן"},{"i":20361,"n":"חסין, שמואל ממרוקו","b":"מחכמי מרוקו-שנות ה-ת', בזמן ר יהודה ן צור.","s":"מלכי רבנן"},{"i":20362,"n":"חסמן, יהודה ליב מליטא ירושלים","f":"רפאל","k":"בעל אור יהל","bt":"תרכז-ט","bp":"איוויה-פלך וילנא","dt":"תרצו","dp":"ירושלים","b":"חבר של ר חיים עוזר גרודזינסקי, למד בסלובודקה אצל ר יצחק בלזר ור נתן פינקל. וכן אצל ר שמחה זיסל זיו בקעלם, ואחר כך בישיבת וולוזין. היה משגיח בישיבת טלז, רב בלודיבינובה(=לודווינאווא)-פלך סובאלק-תרסג, שטוצין(=שטוצ'ין)-פלך וילנא ושם הקים ישיבה-תרסח בשם \"ענף כנסת ישראל\". גלה לרוסיה-במלחה\"ע ה-I, וחזר לשטוצין-תרפא. בשנת תרפו עלה לחברון לבקשת הסבא מסלובודקה ומונה למנהל הרוחני של הישיבה. חיבר \"אור יהל\" ירושלים תרצח, \"מחנה יהודה\" תל אביב תשכה, וכן הוציא לאור חוברות \"מקבציאל\" בסלובודקה.","s":"גליס; אוצר הרבנים 7280; ליטא; אהלי שם; יומא דהילולא","bk":[["אור יהל",""],["מחנה יהודה (מהרי\"ל חסמן)",""]],"e":"תרכ\"ט-תרצ\"ו"},{"i":20363,"n":"חסמן, רפאל","f":"יהודה ליב","bt":"1895","bp":"קאלם","b":"תלמיד בישיבת שטוצ'ין, ראדין. בזמן מלחמ\"ה ה-I שימש מזכירו של ר חיים עוזר גרודזנסקי ביקטרינוסלב (לשם גלו). התישב בקובנא ופרסם מאמרים בעותנות היהודית. סופר של עתוני אדיש בניו יורק. ביקר בארץ-1928 ופרסם על כך סדרת מאמרים. עלה לארץ-1935 והיה חבר מערכת \"הצופה\", וכן עורך שבועונים והוצאות שונות. תרגם ספרים לעברית. חיבר \"ליטא העצמאית בזריחתה ושקיעתה\" בתוך \"אלבום יהודות ליטא\".","s":"ליטא"},{"i":20364,"n":"חסקין, משה מקראקינובה","f":"אפרים","k":"בעל כלכלת שביעית","bt":"תרלד","bp":"צ'רניגוב","dt":"תשי - ל סיון","dp":"ירושלים","b":"תלמיד בקלויז הגאון בוילנא, ותלמיד ר יצחק אלחנן ספקטור בקובנא והיה משמשו בסוף ימיו. רב בקראקינובה-פלך קובנא-תרס, פרילוקי-תרעה, נשאר כרב תחת שלטון הקומוניסטים תוך סכנת נפשות. עלה לירושלים-תרצג. חיבר גם \"אהל משה\"-כת\"י, ועוד. פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\", פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו.","s":"אוצר הרבנים 14708; ליטא; אוצר כתבי עת-לוין; אהלי שם"},{"i":20365,"n":"חסקינד, שלום מנ\"י","b":"תלמיד בישיבת \"תומכי תמימים\" - נ\"י תשד. פרסם מאמרים ב\"חידושי תורה\" - נ\"י תשד.","s":"אוצר כתבי עת-לוין"},{"i":20366,"n":"חפני","f":"כהן צדק","b":"גאון,מחכמי בבל,אב\"ד בישיבת פומבדיתא,זמן קצר לאחר רס\"ג","s":"ארזי הלבנון"},{"i":20367,"n":"חפני, עזרא מבבל","f":"ישראל","b":"ממשפחת גאוני סורא, נכד ר שמואל בן חפני, בן דורו של רבינו חננאל ומקרובי רב האי גאון.","s":"ארזי הלבנון"},{"i":20368,"n":"חפץ - משפחה","b":"משפחת רבנים, מבניהם גם ר משה ריבקש בעל באר הגולה.","s":"פין-קריה נאמנה"},{"i":20369,"n":"חפץ האשורי","f":"יצליח","k":"בעל ספר המצוות","bp":"מוסול","b":"מחכמי בבל לאחר תקופת הגאונים, מראשוני הפוסקים, מדקדק, סגי נהור, חיבר \"ספר המצוות\".","s":"ארזי הלבנון; פין-כנסת ישראל"},{"i":20370,"n":"חפץ זהב, חיים מקולניא","k":"בעל חפץ זהב","b":"מגדולי חכמי אשכנז, רב בקולוניא(=קלן)-שנת כ', נשא ונתן עם ר שמואל בן מנחם (רבו של ר מאיר בן ברוך).","s":"אוצר הרבנים 6001; פין-כנסת ישראל"},{"i":20371,"n":"חפץ, אלחנן מפוזנא","f":"בצלאל אורי ליפמן","k":"בעל קרית חנה (מנה)","b":"רב בפוזנא-ש\"ע. חיבר \"קרית מנה או חנה? על פרקי אבות, ונדפס עם הגהות מבעל \"עוללות אפרים\".","s":"אוצר הרבנים 2014 א'; אלופי יעקב א-תקנט"},{"i":20372,"n":"חפץ, אליהו חסיד מוילנא","dt":"תקנ - ח אלול","b":"דיין בוילנא. בניו - ר שבתי (אצל אובצינסקי), יש מחליפים בינו לבין ר אליהו חסיד בן ר משה קרמר.","s":"אוצר הרבנים 2117"},{"i":20373,"n":"חפץ, אליהו ישעיה מואלינצא","f":"יחזקאל","bt":"תרה","b":"רב בעבר נהר דיסנא, ווילינדי(=ואלניצא)-פלך ויטבסק. נסמך מאת: ר שבתי דון יחיא מדריסא.","s":"אוצר הרבנים 2279; אהלי שם"},{"i":20374,"n":"חפץ, אליהו מוילנא","f":"שבתי","dt":"תקן - ה אלול","dp":"וילנא","b":"דיין בוילנא.","s":"פין-קריה נאמנה"},{"i":20375,"n":"חפץ, אליהו מקושטא","b":"דיין בקושטא-תקסח עם ר שמואל חיים ור עובדיה נתן.","s":"רוזניס-תורכיה-ו"},{"i":20376,"n":"חפץ, אליעזר","f":"גרשון","b":"שיר ממנו בספר \"קול עוגב\".","s":"איטליה גירונדי-א נג"},{"i":20377,"n":"חפץ, אליעזר מירושלים","f":"יחיאל","k":"בעל מדעי הטבע","bp":"ירושלים","b":"תלמיד ביהמ\"ד למורים, מורה בכי\"ח. חיבר ספר \"מדעי הטבע\" ירושלים תרץ.","s":"גאון-יהודי המזרח"},{"i":20378,"n":"חפץ, אריה ליב וולף וערחודנפרוב","f":"משה יעקב","k":"בעל הלכתא בטעמא","bt":"תרד","b":"ר\"מ ורב בווערחודניפרובסק-פלך יקטרינסלב-תרסח. חיבר גם \"מדרש אבות\", \"מדרש ימי קדם\" - לתולדות ישראל, ועוד.","s":"אוצר הרבנים 3294; אהלי שם"},{"i":20379,"n":"חפץ, גרשום","f":"משה-מלאכת מחשבת","k":"בעל יד חרוזים","b":"חיבר \"יד חרוזים\". תלמיד ר שלמה בן ישעיה שהספדיו בסוף \"יד חרוזים\". נפטר בגיל 17. אביו בספרו \"מלאכת מחשבת\" מביא מתורת בנו.","s":"איטליה גירונדי-ג ד; פין-כנסת ישראל"},{"i":20380,"n":"חפץ, דוד מלמד מבוכרה","dt":"תרנח - ג אב","dp":"ירושלים","b":"גביר מחכמי בוכרה. עלה לארץ-תרלא, הו\"ל \"ברכת האילנות\" ירושלים תרמא. נכדו - צבי חפץ.","s":"גאון-יהודי המזרח"},{"i":20381,"n":"חפץ, זאב מירושלים","b":"תלמיד ר יוסף יוזל הורביץ מנוברדוק. ממיסדי \"בית יוסף\" נוברדוק בירושלים-תרצז עם ר בן ציון ברוק.","s":"אנשי שם"},{"i":20382,"n":"חפץ, יחזקאל מוארנאוי","k":"בעל מלאכת חרש","bt":"תקפח","dt":"תרמח","b":"מגדולי התורה בליטא. מחכמי הקיבוץ באיישישוק. רב בווראנאווי-תרך. דודו של ר מאיר שמחה בעל \"אור שמח\".","s":"אוצר הרבנים 9040"},{"i":20383,"n":"חפץ, יעקב הזקן","dt":"תנד","b":"אביו של ר מנשה וזקנו של ר יעקב חי מגורוציאה. תשובה ממנו ב\"דבר שמואל\" (ולא מנכדו).","s":"איטליה גירונדי-י סג"},{"i":20384,"n":"חפץ, יעקב חי מגוריציאה - הנכד","f":"מנשה","dt":"תקט","dp":"גוריציאה","b":"נכד לר יעקב חפץ הראשון. רב בגוריציאה בזמן בעל \"פחד יצחק\". מתלמידיו מוהר\"ם נאוורה הרופא.","s":"איטליה גירונדי-י סג"},{"i":20385,"n":"חפץ, ישראל","b":"רב-שנת תק\"ס","s":"אוצר הרבנים 11928"},{"i":20386,"n":"חפץ, ליב","b":"דיין בירושלים-תר\"נ","s":"אוצר הרבנים 12566"},{"i":20387,"n":"חפץ, מנשה מוירונה","f":"יעקב","b":"רב בוירונה-תס בזמן ר יצחק למפרונטי בעל \"פחד יצחק\". גיסו של הרב חגיז שהביא ממנו בספרו \"שתי הלחם\". הסכים על פס\"ד רבני אנקונה, חתם כנגד אנשי ריגייו - שהטילו מס על אנשי מנטובה. הסכים על \"ראשית בכורי קציר\". פרסם מאמרים ב\"ראשית בכורי קציר\" - ונציה-פיררה תעה.","s":"איטליה גירונדי-מ יא; אוצר הרבנים 13628; ארזי הלבנון; אוצר כתבי עת-לוין"},{"i":20388,"n":"חפץ, מרדכי מריגא","b":"שו\"ב בריגא. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד.","s":"אוצר כתבי עת-לוין"},{"i":20389,"n":"חפץ, מרדכי משלוניקי","b":"משורר בשלוניקי-שנות ה-ש', מחברי ר גדליה ן יחיא המשורר משלוניקי.","s":"רוזניס-תורכיה-ג"},{"i":20390,"n":"חפץ, משה חי מגוריציאה-איטליה","f":"יעקב חי","b":"רב בגוריציאה. שאלה ממנו לר ישמעאל הכהן-תקמז."},{"i":20391,"n":"חפץ, משה מטריאסט","f":"גרשום","k":"בעל מלאכת מחשבת","r":"מרבני אטליה","bt":"תכד","bp":"טריאסט","dt":"תעב - א כסלו","b":"תלמיד ר שלמה ניצה. רב בונציה. חיבר \"מלאכת מחשבת\", \"חנוכת הבית\" ובתוכו גם חדושים מבנו ר גרשום - (חיבר \"יד חרוזים\" - ונפטר בחיי אביו).","s":"איטליה גירונדי-מ יד; אוצר הרבנים 14709; מבשר ואומר א' כסליו תשעג","bk":[["חנוכת הבית – צורת הבית ותבניתו",""],["מלאכת מחשבת – תורה",""],["מלאכת מחשבת",""]]},{"i":20392,"n":"חפץ, משה מסיציליה","b":"מחכמי סיציליה ומקורב למלכות בזמן הרשב\"ץ, בשנת קפא הצליח להשפיע על המלך לבטל גזרות נגד היהודים ומאז התמנה לנגיד.","s":"ארזי הלבנון"},{"i":20393,"n":"חפץ, נפתלי צבי הרש","f":"ישראל חפץ","k":"בעל גן צבי","bt":"תקנז","dt":"תרלב","s":"אוצר הרבנים 16258"},{"i":20394,"n":"חפץ, נתן","b":"מחכמי ארץ ישראל, בשנת תו חתם על תקנת המסים.","s":"גליס"},{"i":20395,"n":"חפץ, עזריאל מגוריציאה","b":"תשובה אליו ב\"באר שבע\" לר ישכר בער.","s":"איטליה גירונדי-ע א"},{"i":20396,"n":"חפץ, צבי מירושלים","f":"ישראל","bt":"תרמה","bp":"ירושלים","dt":"תרעט - יד טבת","dp":"בומבי","b":"עסק במסחר בקוקנד-טורקיסטן, חזר לארץ-תרעב ועסק בעניני צבור, וגאולת קרקעות עבור עשירי בוכרה, במלחה\"ע ה-I גלה לרוסיה ופעל למען הציונות בטורקיסטן, מנהל בי\"ס עברי בסמרקנד, נפטר בדרכו חזרה לארץ בשיירת עולם מבוכרה.","s":"גאון-יהודי המזרח"},{"i":20397,"n":"חפץ, רפאל יצחק יהודה מירושלים","b":"דיין בירושלים-תרנב בבית דינו של המהרי\"ל דיסקין."},{"i":20398,"n":"חפץ, שאלתיאל משלוניקי - א","b":"משורר מחכמי שלוניקי-שנות ה-ש'. תלמידו - בן אחותו - ר דוד קונפורטי הזקן.","s":"זכרון שלוניקי; רוזניס-תורכיה-ג"},{"i":20399,"n":"חפץ, שאלתיאל משלוניקי - ב","b":"מקובל, משורר, בקי במדעים מחכמי שלוניקי-תמ או תקם.","s":"אוצר הרבנים 18900; ארזי הלבנון"},{"i":20400,"n":"חפץ, שבתי","f":"אליהו חסיד מוילנא","b":"נכד ר משה קרמר. בנו - ר אלחנן. חתנו - ר צבי הירש, ונכדו - ר שמואל מרדכי רשקס משניפישוק.","s":"אווצינסקי - קורלנד; ברוורמן-אנשי שם"},{"i":20401,"n":"חפץ, שמעיה מירושלים","dt":"תרצב - כו כסלו","dp":"ירושלים","b":"פעיל ציבור מהעדה הבוכרית בירושלים, וחוקר תולדות העדה.","s":"גאון-יהודי המזרח"},{"i":20402,"n":"חצור, שמואל ממירוסלאוו","b":"רב במירוסלאוו-ליטא.","s":"ליטא"},{"i":20403,"n":"חצקביץ, ישראל נח","bt":"תרמט","dt":"תשא - אב","b":"רב בפאנומבקה,באבעל,רבה האחרון של קופישאק","s":"אוצר הרבנים 12294 א'"},{"i":20404,"n":"חצר, שמואל מסלאבאדא","f":"אברהם","bp":"ראסיין","b":"אב\"ד סלובודה(סלאבאדא)-פלך סובאלק.","s":"מרקוביץ-ראסיין"},{"i":20405,"n":"חקאן, משה הלוי ממצרים","b":"מקורב לשלטון במצרים-רפד בזמן אחמד פחה, וסייע ליהודים מגזרות שמד.","s":"רוזניס-תורכיה-ב"},{"i":20406,"n":"חקאן, שמואל הלוי מספרד וירושל","k":"שמואל חכאן","bp":"ספרד","b":"מחכמי ספרד, עבר לקושטא ולימד תורה, עבר לקהיר-מצרים-רפ וכיהן כדיין אצל הרדב\"ז, רופא בירושלים-שנת ש'. היה במחלוקת כנגד ר יוסף טאיטצק משלוניקי. הדפיס את שו\"ת הריב\"ש-שו. חתם על הסכם השלום שעשה הרדב\"ז בין ק\"ק מסתערב וק\"ק מערבים. נזכר בספרי חכמי דורו ובהם גם ב\"בית יוסף\". החיד\"א מזהה אותו עם מהר\"ש חקאן הלוי, ויש שחולקים עליו ואומרים שהוא חכם אחר בן זמנו.","s":"אוצר הרבנים 19182,19171; רוזניס-תורכיה-א,ב; פרומקין-תח\"י; ארזי הלבנון"},{"i":20407,"n":"חקון, אברהם מאלגיר","f":"סעדיה","bt":"קי - בערך","dt":"קץ - בערך","b":"מחכמי תלמסאן, שאלות ממנו לריב\"ש ולרשב\"ץ.","s":"מלכי ישורון-חכמי אלגיר"},{"i":20408,"n":"חקון, דוד","b":"מחכמי מראקש","s":"ארזי הלבנון"},{"i":20409,"n":"חקון, סעדיה מאלגיר","f":"אברהם","bt":"קס - בערך","dt":"רכ - בערך","b":"רב בתלמסאן. היה מהקהילה הותיקה שהחזיקה בדעת הרמב\"ם, נזכר בשו\"ת רשב\"ש והסכים עם דעת הרמב\"ם כנגד דעתו של הרשב\"ץ.","s":"ארזי הלבנון; מלכי ישורון-חכמי אלגיר"},{"i":20410,"n":"חקק, רפאל מבגדד","k":"בעל ליקוטי רפאל","dt":"תשלו - ה כסלו","b":"עלה לארץ מבגדד.","s":"ארזי הלבנון","bk":[["ליקוטי רפאל",""]]},{"i":20411,"n":"חראזי, שלמה מתימן","k":"בעל בית תפילה","dt":"תנה - אחרי","dp":"תימן","b":"מחכמי תימן, משורר וסופר.","s":"ארזי הלבנון"},{"i":20412,"n":"חראץ, יהודה מתימן","f":"משה","k":"בעל מנחת יהודה","b":"רב בתימן-תרטו, חיבר 'מנחת יהודה' בדיני שחיטה. סופר שחתם שמו על כתב יד 'שעי קדושה' - תימן תריד.","s":"מתוך קטלוג"},{"i":20413,"n":"חראש, ישראל מפולין","k":"בעל קהלת ישורון","b":"חיבר \"קהילת ישורון\"","s":"איטליה גירונדי-י קכח"},{"i":20414,"n":"חרבון, אברהם מאבולוניא","b":"מגולי ספרד מחכמי אבולוניא(=אבילונא)-רן עם חבריו ר אברהם קולייר ור אברהם צרפתי. היה במחלוקת עם ר דוד מסיר ליאון באבילונא.","s":"אלופי יעקב א-רמח,שנה; פין-כנסת ישראל"},{"i":20415,"n":"חרבון, יוסף מירושלים","b":"מחכמי ירושלים, בשנת תו חתם על התקנה לשחרור תלמידי חכמים ממס.","s":"גליס"},{"i":20416,"n":"חרבון, יצחק משלוניקי","b":"מחכמי שלוניקי-של.","s":"עמנואל-שלוניקי"},{"i":20417,"n":"חרבון, יצחק שמואל מקיוסטנדיל","b":"תלמיד ר שמואל קונפורטי, ורב על מקומו אחריו-תקנו (כשעלה לארץ), דיינים אצלו ר ציון קובו ור חיים ן משה, ר יעקב בן יהודה אלעזר, ר דוד אוליבירו.","s":"רוזניס-תורכיה-ה,ו"},{"i":20418,"n":"חרברג, אלתר דוד יוסף ברוך מקיע","f":"יצחק בצלאל מקיעלץ","bt":"תרלה","b":"רב בפיעטקוביץ-פלך קיעלץ, מו\"צ בקיעלץ-תרסז על מקום אביו.","s":"אוצר הרבנים 2960"},{"i":20419,"n":"חרברג, יצחק בצלאל מקיעלץ","dt":"תרסז - בערך","b":"רב בקיעלץ-תרס.","s":"אוצר הרבנים 11276; אהלי שם"},{"i":20420,"n":"חרג, יצחק מזלאזיץ","dt":"תרס - כ סיון","b":"רב בזאלאזיץ חדש","s":"אוצר הרבנים 10670"},{"i":20421,"n":"חרובי, יצחק מפאס","b":"מחכמי פאס-שנות ה-ת'.","s":"מלכי רבנן"},{"i":20422,"n":"חרוץ, אריה מירושלים","b":"תלמיד ישיבת וולוזין, תלמיד ר אברהם קלמנוביץ מראקוב, ר אליהו שחור. עלה לארץ-תרפו במסגרת קבוצת חלוצים דתיים.","s":"מתוך קטלוג"},{"i":20423,"n":"חרוש, חיים שמעון מירושלים","dt":"תרנז - כ אב","dp":"ירושלים","b":"מורה ועסקן צבור בירושלים.","s":"גאון-יהודי המזרח"},{"i":20424,"n":"חרוש, יצחק ממראקש","b":"רב ודיין במראקש-תקמד יחד עם ר משה ן עטר, ור אברהם פינטו, ור שלמה אסבאג. חתם על הסכמה ל\"תהלה לדוד\" לר דוד חסין. בנו - הדיין ר יוסף - נפטר תקעז.","s":"ארזי הלבנון; מלכי רבנן; טולדנו-נר המערב"},{"i":20425,"n":"חרוש, מרדכי מאלגיר","bt":"תקס","dt":"תרל - בערך","b":"רב בווהראן, עלה לארץ-תקצח והתישב בצפת. חתם על אגרות בצפת.","s":"מלכי ישורון-חכמי אלגיר"},{"i":20426,"n":"חרוש, רפאל יוסף ממראקש","dt":"תרנח","b":"מו\"ץ במראקש, חתם-תריט עם ר רפאל מסעוד ן מוחא, ר שמואל יעקב בטאן, ור ברוך אסבאג.","s":"מלכי רבנן"},{"i":20427,"n":"חרוש, שמעון","b":"חדושי תורה ממנו ב\"המאסף\" בענין שבועה.","s":"ארזי הלבנון"},{"i":20428,"n":"חר\"ז, דוד מוילנא","f":"משה חר\"ז(=חתן ר זלקי","k":"בעל מצודת דוד","b":"חתן הגביר ר יצחק-חתן ר נטע גינצבורג. דיין בווילנה-תמ, הדפיס את ספרו \"מצודות דוד\" באלטונא-תצו.","s":"אוצר הרבנים 4820; פין-כנסת ישראל"},{"i":20429,"n":"חר\"ז, משה מוילנא","dt":"תצו - אחרי","dp":"וילנא","b":"חר\"ז(=חתן ר זלקינד). דיין בוילנא-תכ. אביו של ר דוד בעל \"מצודת דוד\"-אלטונא תצו, וזקנו של ר שאול שיסקעס בעל \"שביל הישר\".","s":"אוצר הרבנים 14711; בית העלמין בוילנא-קלויזנר"},{"i":20430,"n":"חרטינר, מאיר","bt":"תרמא","bp":"גליציה","dt":"תשלב - ח אלול","dp":"ישראל","b":"מלמד בבי\"ס בטרנופול, סופר ומתרגם. עלה לארץ-תרצח.","s":"מתוך קטלוג"},{"i":20431,"n":"חריזי יהודה בן שלמה","bt":"1170","dt":"ד'תתקצה 1235","s":"היברובוקס","bk":[["תחכמוני",""]]},{"i":20432,"n":"חריך, משה ראובן מנ\"י","f":"מרדכי דב","bt":"תרסב","bp":"קובנא","b":"תלמיד ישיבת מיר, נסמך מאת: ר אליעזר יהודה פינקל, ר שלמה ממיצעט, הרב גוטמן-דיין בקובנא. חתן ר אברהם נחמן שורץ מבולטימור. רב בקהלת \"ריגער קודלענדער\" בבולטימור-תרפה, קהלת \"שומרי משמרת\", \"כתר תורה\". חבר אגודת הרבנים באמריקה. פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן.","s":"אוצר כתבי עת-לוין; אנשי שם-אמריקה"},{"i":20433,"n":"חריף, איזיק","s":"אוצר הרבנים 1950"},{"i":20434,"n":"חריף, אליעזר הכהן מזסלב","f":"משלם פייבל מגריידינג","bt":"תרה","b":"נכד ר חיים חריף מדינוביץ. רב בליפקין-בסרביה, קופיל-ווהלין, זסלב-ווהלין. חבר בועדת הרבנים בפטרבורג. חיבר חדושים לשו\"ע ולש\"ס. בנו - ר חיים מגריידינג, חתנו - ר שלמה לוין מואלינשיסק.","s":"אוצר הרבנים 2504; אהלי שם"},{"i":20435,"n":"חריף, ברוך","f":"יוסף יוזפא הורביץ","s":"אוצר הרבנים 4089"},{"i":20436,"n":"חריף, דב בריש מסטרי","f":"צבי הירש חריף","b":"רב בסטריא-ת\"ע","s":"אוצר הרבנים 4539"},{"i":20437,"n":"חריף, דוד מסטנוב","f":"ישראל חריף","b":"רב בסטאנוב,סמטריטש,זוואניץ","s":"אוצר הרבנים 4661"},{"i":20438,"n":"חריף, זאב וולף הכהן","bt":"תקח","dt":"תקצח - יד שבט","b":"מרביץ תורה,רב בלאסק","s":"אוצר הרבנים 5486"},{"i":20439,"n":"חריף, חיים הכהן מגריידינג","f":"אליעזר מזסלב","bt":"תרכה","dt":"תרצב - טז ניסן","b":"נכד ותלמיד ר פיבל חריף. רב בטשימישליע-בסרביה, גריידינג-פודוליה-תרע על מקום זקנו - ר משלם פיבל, ניו יורק.","s":"אוצר הרבנים 6004; אהלי שם"},{"i":20440,"n":"חריף, חיים הכהן מדינוביץ","f":"שלמה מזברוזא","b":"נכד ר ישראל חריף מסטנוב. רב בדינוביץ. השתתף בועד הרבנים בפטרבורג-תריב. בנו - ר משלם פיבל ונכדו ר אליעזר מזסלב.","s":"אהלי שם"},{"i":20441,"n":"חריף, יהודה","k":"בעל פני יהודה","b":"רב-שנת תר\"ס","s":"אוצר הרבנים 6942"},{"i":20442,"n":"חריף, יהודה ליב","s":"אוצר הרבנים 7282"},{"i":20443,"n":"חריף, יהודה ליב מוילנא","f":"ישראל חריף","b":"חתן ר הלל מוילנא (בעל בית הלל?). רב בוילנא, חתם-תסה עם ר מרדכי בן ישראל, ר אהרן בן אברהם, ר שמואל זנויל מייזלש. חתנו - היסו\"ד.","s":"אוצר הרבנים 7281; פין-קריה נאמנה"},{"i":20444,"n":"חריף, יהושע מסוקולוב","f":"ישראל מסנוק","dt":"תרנה","b":"רב בסוקולוב על מקום אביו.","s":"וונדר-גליציה ח\"ו"},{"i":20445,"n":"חריף, יוסף סגל מלבוב ופרמישלא","f":"משה חריף מלבוב","dt":"תסב - ל ניסן","b":"חתן ר יהודה ליב חסיד מלבוב ופרמישלא. ר\"מ בלבוב, רב בפרמישלא.","s":"אוצר הרבנים 8322; בובר-לבוב"},{"i":20446,"n":"חריף, יעקב מלעשנוב","f":"משה פנחס מלבוב","dt":"תקנה - ל תשרי","b":"נכד-אבי אמו ה\"חכם צבי\". חתן ר יעקב מרדכי באבד. רב בלעשנוב, מראשי ועד ארבע ארצות, רב המדינה בפודוליה. חתם-תנט בפנקס זולקוא בענין המדפיסים שהיו בועד ירוסלב. חתנו - ר אליעזר ליפמן מרסטיצקי. בנו - ר משה אשכנזי מלבוב.","s":"אוצר הרבנים 9638; בובר-זולקוא; מוריה 24-א-ב"},{"i":20447,"n":"חריף, יצחק","f":"חיים ברודא","b":"סגי נהור,רב במוצ\"ד-תק\"מ","s":"אוצר הרבנים 10675"},{"i":20448,"n":"חריף, יצחק מסמבור","f":"משה מדראגיטשין","k":"בעל זרע יצחק","dt":"תקעג - כז תמוז","b":"מגדולי חכמי דורו בנגלה ונסתר,רב בסאמבור","s":"אוצר הרבנים 10673"},{"i":20449,"n":"חריף, ישראל מאליק","f":"ישראל חריף","bt":"שצא","b":"רב באליק-תע, נולד לאחר פטירת אביו.","s":"אוצר הרבנים 11929; בובר-לבוב"},{"i":20450,"n":"חריף, ישראל מלבוב ואוליינוב","f":"משה פנחס חריף מלבוב","dt":"שץ-תצ - כג אב","dp":"לבוב","b":"מחכמי לבוב. אחיו - ר צבי הירש מלבוב. בניו - ר ישראל חריף מאוסטרהא, ר צבי הירש מיברוב ולפי בובר גם ר משה חריף השני מאוליינוב ולבוב. (יש שרשמו תאריך פטירתו - שמים שהוא שץ, ויש שרשמו תאריך תצח).","s":"אוצר הרבנים 11932; אוסטרהא סב; אנשי שם שלז; בובר-לבוב; אוצר הרבנים 11931"},{"i":20451,"n":"חריף, ליב מונגרוב","f":"משה חריף","b":"רב בוונגרובה-תק\"פ","s":"אוצר הרבנים 12572"},{"i":20452,"n":"חריף, משה","b":"רב-שנת תק\"מ","s":"אוצר הרבנים 14719"},{"i":20453,"n":"חריף, משלם פיבל הכהן מגריידינג","f":"חיים מדינוביץ","b":"רב בגריידינג-תי.","s":"אוצר הרבנים 15764; אהלי שם"},{"i":20454,"n":"חריף, נפתלי הרץ מירוסלב","f":"שאול מאלסק","bt":"תץ","bp":"ברודי","dt":"תקף","b":"חתן ר מאיר מאוסטרהא בעל \"מאיר נתיבים\"-המזכירו בספרו, ובזיוו\"ש חתן ר זכריה מנדל פרנקל מירוסלב. רב בשריגרד, ירוסלב-תקס על מקום ר משה יהושע הורביץ - שעבר להורדנא (כך במוריה - אך הוא עבר להורדנא בשנת תקיז) ועל מקום גיסו ר יהודה ליב הלר ולרשטין. מתורתו בספרי חכמי דורו ובהם \"בית אפרים\" ל אלכסנדר מסטאנוב, ועוד. חיבר ספר דרשות וחדושים בשם \"קדש נפתלי\" - בכת\"י. תלמידו - ר אברהם בעריש פלאם מלובלין סיפר בשם ר יעקב אורנשטין בעל \"ישועות יעקב\" (בן אחותו של ר נפתלי חריף) שסיפר שר נפתלי סירב להצעת הרבנות בירוסלב ואז פנו אליו והסכים - אולם אשת ר נפתלי לא הסכימה ור יעקב ששמע על כך ויתר על הרבנות - משלחת רבנים הגיעה אל ר נפתלי לפייסו וביניהם המגיד מדובנא ואז נתרצה לכהן כרב.","s":"וונדר-גליציה ח\"ב; אוצר הרבנים 16211; מוריה 24-א-ב"},{"i":20455,"n":"חריף, צבי הירש חריף מלבוב","f":"משה פנחס מלבוב","dt":"תצז - כו תמוז","dp":"לבוב","b":"רב ביברוב-תפו, ראב\"ד בלבוב-תצו. אחיו - ר ישראל חריף. הסכים על \"זרע ברוך\" ואנזבק תץ עם בעל פני יהושע, הסכים על \"בית שמואל\", חתם-תסז על תקנה בלבוב.","s":"אוצר הרבנים 17291; פין-כנסת ישראל; מצבות קדש-לבוב; בובר-לבוב"},{"i":20456,"n":"חריף, שאול מאלסק","f":"יעקב מלעשנוב","b":"רב באלעסק-תק\"כ","s":"אוצר הרבנים 17960"},{"i":20457,"n":"חריף, שלמה הכהן מזברוזא","f":"ישראל מסטנוב","b":"רב בזבארז-תף.","s":"אוצר הרבנים 18455; אהלי שם"},{"i":20458,"n":"חריף-הבנשטריט, ישראל מסאנוק","f":"מרדכי אריה מסוקולוב","k":"ישראל חריף","b":"רב בסוקולוב-תקפב ובנו ר יהושע על מקומו אחריו, רבה של סנוק.","s":"וונדר-גליציה ח\"ב"},{"i":20459,"n":"חרי\"ק, שמואל מוילנא","b":"גביר מראשי קהלת וילנא יחד עם ר אריה ליב פעסעלעס.","s":"פרומקין-תח\"י"},{"i":20460,"n":"חרירי, אברהם מכורדיסטן","f":"פנחס","k":"בעל ספר המטעמים","b":"מרבני כורדיסטאן, בעל \"ספר המטעמים\"","s":"ארזי הלבנון"},{"i":20461,"n":"חרירי, יצחק מחריר (כורדיסטן)","f":"משה","k":"בעל נחלת ה'","b":"רב בחריר-כורדיסטן. אולי זהה עם הפייטן והמחבר של \"נחלת ה'\" ומחבר פיוט \"אצלי צלותא\" לנשמת כל חי ובנו ר פנחס.","s":"ארזי הלבנון"},{"i":20462,"n":"חרירי, משה מכורדיסטן","f":"אברהם","k":"בעל ויבחר משה","b":"מחמכי כוי סנג'ק-כורדיסטן.","s":"ארזי הלבנון"},{"i":20463,"n":"חרירי, פנחס מכורדיסטן","f":"יצחק","k":"בעל דרכי נועם","b":"מחכמי חריר-כורדיסטן-תכד, פייטן ומקובל. שלח אגרת לרבנית אסנת בת ר שמואל ברזני. בנו ר חיים. חיבר גם \"נתיבות שלום\" ועוד.","s":"ארזי הלבנון"},{"i":20464,"n":"חרלה, דב מירושלים","b":"פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו.","s":"אוצר כתבי עת-לוין"},{"i":20465,"n":"חרל\"פ, א' אליעזר צבי","k":"בעל עטרת צבי","dt":"תרט - ה אלול","b":"רב בשצוצין,גאנידז,ביזון,סאכטשוב,מזריטש,ספריו נשרפו בדליקה","s":"אוצר הרבנים 3083"},{"i":20466,"n":"חרל\"פ, אברהם חיים מארה\"ב","f":"יוסף","bp":"וישטיניץ","b":"היגר לארה\"ב, וכיהן כמנהל הת\"ת בסירקוז-ניו יורק, מלמד בניו יורק. פרסם מאמרים, סידר והגיה סידורי תפלה, חיבר ספרי לימוד.","s":"אנשי השם בארהב-איזנשטט"},{"i":20467,"n":"חרל\"פ, אפרים אליעזר צבי ממזריט","k":"בעל הוד תהלה","dp":"מזריטש","b":"אב\"ד במזריטש ועוד."},{"i":20468,"n":"חרל\"פ, זאב יהודה","f":"אפרים אליעזר צבי","b":"רב-שנת תר\"ל","s":"אוצר הרבנים 5560"},{"i":20469,"n":"חרל\"פ, זבולון מירושלים","f":"נפתלי או יצחק","k":"בעל מאורי חיים","bt":"תר","bp":"וילקוביסק (פולין)","dt":"תרנח (תרנה)","dp":"ירושלים","b":", מצאצאי רבנים ראשי גולה ותנאים מגזע דוד המלך. ראשי התיבות חרל\"פ הם חייא ראש לגולי פולין, אמו נכדת ר חיים משרשוב בעל \"שירה לחיים\". בשנת תריא-טו עלה לארץ עם משפחתו. תלמיד ישיבת \"עץ חיים\", ואצל ר נחום משאדיק ור מאיר אוירבך מקליש. היה דיין בבית דינו של המהרי\"ל דיסקין, וממונה על כוללות סובאלק ולומז'ה. השאיר הרבה חדושי תורה חלקם פורסם בחוברות \"אור תורה\" ו\"תורה מציון\" - ירושלים תרנה-תרסה. חיבר ספר \"מאורי חיים\". בנו היה ר יעקב משה חרלפ.","s":"גליס; אוצר הרבנים 5566; ליטא; אוצר כתבי עת-לוין; פרומקין-תח\"י"},{"i":20470,"n":"חרל\"פ, חיים זבולון מראשון לציו","f":"יעקב משה","k":"בעל נחלי חיים","bt":"תרסב","bp":"ירושלים","dt":"תשכה","b":"תלמיד ישיבות עץ חיים, מרכז הרב בירושלים. נסמך מאת הראי\"ה קוק, ר איסר זלמן מלצר. רב בראשון לציון-תרפו. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו, \"בית מדרש\" - תל אביב תשא, \"ועד חכמים\" - ירושלים תרפג, \"הפוסק\" - תל אביב תש-תשיד, \"תלפיות\" - טרנוב תרצח. מכתביו נדפס - \"נחלי חיים\", \"עין החיים\".","s":"אוצר הרבנים 6313; אוצר כתבי עת-לוין"},{"i":20471,"n":"חרל\"פ, יהודה לייב ממאריאמפול","b":"חתן ר חיים שרשובר-פרלמוטר ממאריאמפול. רב במריאמפול על מקום חותנו.","s":"אוצר הרבנים 7284; ליטא"},{"i":20472,"n":"חרל\"פ, יחיאל מיכל מניו יורק","f":"יעקב משה חרל\"פ","k":"בעל חוף ימים","r":"רב בית הכנסת המרכז היהודי בברונקס","bt":"תרס","dt":"תשלה - יב חשון","b":"רב בניו יורק. פרסם מאמר ב\"קונטרס מיוחד\" - נ\"י תשא - דברי תורה מועידת המזרחי.","s":"אוצר הרבנים 9281 א'; אמריקה; אוצר כתבי עת-לוין; הקדמת הספר על מכות שיצא לאור לאחר פטירתו, מוריה קובץ קז שנה יט גליונות ג - ד עמוד נ","bk":[["חוף ימים - עבודה זרה סב ע\"א",""]]},{"i":20473,"n":"חרל\"פ, יעקב משה מירושלים","f":"זבולון חרל\"פ","k":"בעל בית זבול","bt":"תרמג","bp":"ירושלים","dt":"תשיב - ז כסלו","b":"תלמיד ישיבות \"עץ חיים\", תורת חיים\" בירושלים, ותלמיד ר יהושע צבי מיכל בעל \"ציץ הקדש\", ר יצחק ירוחם דיסקין, הראי\"ה קוק. חתן ר שלמה נתן קוטלר. ראש ישיבת מרכז הרב בירושלים, רב שכונת שערי חסד, ומייסד ביהמ\"ד \"בית זבול\" בירושלים. מחבר \"בית זבול\" ו\"מי מרום\". בנו ר יצחק אליעזר. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, \"כרם ציון\" - ירושלים תשכג - קובץ \"מדרש בני ציון\", \"קול תורה\" - ירושלים תרץ, \"קול תורה\" - ירושלים תרץ-תשז, \"שערי ציון\" - ירושלים תרפא.","s":"אוצר הרבנים 10240; ליטא; אוצר כתבי עת-לוין; אגרות לראי\"ה עמוד נו","bk":[["בית זבול [שו\"ת]",""],["מי מרום",""],["בית זבול - הלכה",""],["מי מרום - הלכה",""],["מכתבי מרום - מכתבי חיזוק לבנו בעל 'חוף ימים'",""]]},{"i":20474,"n":"חרל\"פ, יצחק אליעזר מירושלים","f":"יעקב משה מירושלים","bp":"ירושלים","dt":"תרעד - אחרי","dp":"ירושלים","b":"עסקן ציבורי וממונה על כוללות סובאלק ולומז'ה בירושלים על מקום זקנו ר זבולון. נפטר בזמן מלחה\"ע ה-I.","s":"ליטא"},{"i":20475,"n":"חרל\"פ, מעשל מירושלים","b":"רב שכונה בירושלים-תר\"ל","s":"אוצר הרבנים 14721"},{"i":20476,"n":"חרל\"פ, ניסן יהודה ליב מירושלים","b":"רב בירושלים. פרסם מאמרים ב\"המאסף\", \"תורה מציון\" - ירושלים תרנה-תרסה.","s":"דור וחכמיו-א\"ש-ו; אוצר כתבי עת-לוין"},{"i":20477,"n":"חרפ, שלמה מיזירנה","k":"אדמור מיזירנה","bt":"תקע","bp":"יזירנה","dt":"תרם","b":"רב ביזירנה, הוסמך כאדמור על ידי ר מאיר מפרמישלן.","s":"וונדר-גליציה ח\"ב"},{"i":20478,"n":"חרצן-שקד, יוסף מאוסטרובה","b":"פרסם מאמרים ב\"אור המאיר\" - וארשא תרצו.","s":"אוצר כתבי עת-לוין"},{"i":20479,"n":"חרק, חנוך הניך","b":"תשובה אליו בשו\"מ.","s":"וונדר-גליציה ח\"ב"},{"i":20480,"n":"חרק, יצחק מזלוזיץ","dt":"תרס","b":"חתן ר שלמה לנגרמן מטרוקא-תרנח.","s":"וונדר-גליציה ח\"ב"},{"i":20481,"n":"חרק, צבי הירש ממוסט","dt":"תרצט","b":"רב במוסט.","s":"וונדר-גליציה ח\"ב"},{"i":20482,"n":"חרש, פייש מריגא","dt":"תשג","b":"רב בריגא","s":"אוצר הרבנים 16846"},{"i":20483,"n":"חר\"ת רפפורט, משה מזאמושט","b":"עשיר,מגדולי זאמוטשט","s":"אוצר הרבנים 15166"},{"i":20484,"n":"חשין, בנימין זאב מירושלים","b":"פרסם מאמרים ב\"שערי תורה\" - ירושלים תשה.","s":"אוצר כתבי עת-לוין"},{"i":20485,"n":"חשין, יצחק מירושלים","f":"משה","dt":"תרמב - ז שבט","dp":"ירושלים","b":"גבאי \"ביקור חולים\" בירושלים.","s":"פרומקין-תח\"י"},{"i":20486,"n":"חשין, משה יוסף מירושלים","f":"יצחק חסלביצר","dt":"תרלב - יב אייר","b":"עלה עם אביו לצפת, עבר לירושלים-אחרי תקץ, בתקצד היה בצפת וסייע לקהלה כשתדלן בזמן הפרעות, וחזר לירושלים. מראשי קהלת האשכנזים בירושלים, בשליחות ברוסיה, ממיסדי כולל מינסק, וחברת \"שלום ירושלים\", ועוד. חתם על שטר חזקה-תקצב, ותקצח, על עניני החורבה-תריא. בנו - ר יצחק. אבי משפחת חשין בירושלים.","s":"אוצר הרבנים 14722; פרומקין-תח\"י"},{"i":20487,"n":"חשין, שלום בר מפטרוביץ","b":"חתן ר יואל מחאסלביץ(=חסלביץ). גביר תלמיד חכם בפטרוביץ(=פעטראוויטש). חתנו - ר עקיבא בן ר שלמה זלמן מטשאווס.","s":"אהלי שם"},{"i":20488,"n":"חשמון, יצחק מאלגיר","bt":"תק","dt":"תקף - בערך","b":"רב בתלמסאן, מלמד תורה.","s":"מלכי ישורון-חכמי אלגיר"},{"i":20489,"n":"חשסמן, יהודה מארה\"ב","f":"ישראל אשר","bt":"תרלו","bp":"הרודישץ-פלך מינסק","b":"תלמיד ישיבת ראדין, קבוץ קרליץ, מינסק שאלודאק, קאפוליע אצל ר אברהם אהרן יודלביץ מקאפוליע, ונסמך ממנו ומאת ר מנדל אסטרינסקי משטוצין, ר משה בצלאל מסייני, ר דוד טביל קצנלנבוגן מסובאלק. חתן הגביר ר משה יודא מישינסקי מברעזניקי. רב בבאקלעראווא-פלך סובאלק-תרסד, קרעווא-פלך וילנא, היגר לארה\"ב וכיהן כרב קהלת אנשי טיקטין בשיקגו-תרפה. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט, \"תורה מציון\" - ירושלים תרנה-תרסה.","s":"אוצר הרבנים 6943; אוצר כתבי עת-לוין; אנשי שם-אמריקה"},{"i":20490,"n":"חשקיטו, ברוך","b":"מגדולי חכמי איטליה,רב בפירארו-שנת ש'","s":"אוצר הרבנים 4087"},{"i":20491,"n":"חשקס (דנציג), משה ליב","f":"יוסף","k":"בעל נטעי נאמנים","bt":"1848","bp":"וילנא","dt":"1908","dp":"פטרבורג","b":"תלמיד ישיבות ליטא, וביהמ\"ד לרבנים בזיטומיר. חיבר שירים וספורים בשפות שונות ובהם אידיש ועברית.","s":"ליטא"},{"i":20492,"n":"חת","b":"מו\"צ באויבן ישן-ת\"ק","s":"אוצר הרבנים 6726"},{"i":20493,"n":"חתאתו חדוק, דוד","k":"בעל דגן בחורים","dt":"תרפז","b":"מחכמי ג'רבא, חיבר \"דגן בחורים\"","s":"ארזי הלבנון","bk":[["דגן בחורים",""]]},{"i":20494,"n":"חתוכא, שלום מתימן","dt":"תרעג","dp":"רדאע-תימן","b":"ראב\"ד ברדאע-תימן-תרסד.","s":"ארזי הלבנון"},{"i":20495,"n":"חתון ן","b":"מגדולי חכמי קושטא-ש\"פ","s":"אוצר הרבנים 1574"}];
